/* =========================================================
   AUTHENTICATION TOKEN RESOLUTION
========================================================= */

function getStoredAuthenticationToken(){

  const keys = [

    AIFT_TEACHER_CONFIG
      .storageKeys
      .teacherToken,

    AIFT_TEACHER_CONFIG
      .storageKeys
      .schoolToken,

    AIFT_TEACHER_CONFIG
      .storageKeys
      .adminToken,

    AIFT_TEACHER_CONFIG
      .storageKeys
      .genericToken

  ];


  for (
    const key of keys
  ){

    const value =
      String(
        localStorage.getItem(
          key
        ) ||
        sessionStorage.getItem(
          key
        ) ||
        ""
      ).trim();


    if (
      value
    ){

      return value;

    }

  }


  return "";

}


/* =========================================================
   STORED ROLE RESOLUTION
========================================================= */

function getStoredRole(){

  return normalizeRole(
    localStorage.getItem(
      AIFT_TEACHER_CONFIG
        .storageKeys
        .role
    ) ||
    sessionStorage.getItem(
      AIFT_TEACHER_CONFIG
        .storageKeys
        .role
    ) ||
    ""
  );

}


