/* =========================================================
   DOM HELPER
========================================================= */

function $(
  id
){

  return document.getElementById(
    id
  );

}


/* =========================================================
   QUERY SELECTOR HELPERS
========================================================= */

function $one(
  selector,
  root = document
){

  if (
    !selector ||
    !root
  ){

    return null;

  }


  return root.querySelector(
    selector
  );

}


function $all(
  selector,
  root = document
){

  if (
    !selector ||
    !root
  ){

    return [];

  }


  return Array.from(
    root.querySelectorAll(
      selector
    )
  );

}


/* =========================================================
   ROLE NORMALIZATION
========================================================= */

function normalizeRole(
  value
){

  const normalized =
    String(
      value ||
      ""
    )
      .trim()
      .toLowerCase();


  const aliases = {

    instructor:
      "teacher",

    faculty:
      "teacher",

    learner:
      "student",

    administrator:
      "admin"

  };


  return (
    aliases[
      normalized
    ] ||
    normalized
  );

}


/* =========================================================
   ID NORMALIZATION
========================================================= */

function normalizeId(
  value
){

  if (
    value === null ||
    value === undefined
  ){

    return "";

  }


  if (
    typeof value ===
    "string"
  ){

    return value.trim();

  }


  if (
    typeof value ===
    "number"
  ){

    return String(
      value
    );

  }


  if (
    typeof value ===
      "object" &&
    value._id !==
      undefined
  ){

    return normalizeId(
      value._id
    );

  }


  if (
    typeof value ===
      "object" &&
    value.id !==
      undefined
  ){

    return normalizeId(
      value.id
    );

  }


  return String(
    value
  ).trim();

}


/* =========================================================
   ID COMPARISON
========================================================= */

function sameId(
  first,
  second
){

  const firstId =
    normalizeId(
      first
    );

  const secondId =
    normalizeId(
      second
    );


  return Boolean(
    firstId &&
    secondId &&
    firstId ===
      secondId
  );

}


/* =========================================================
   ARRAY NORMALIZATION

   Existing AIFT endpoints do not all use exactly the same
   envelope shape. This function intentionally understands
   the response shapes currently used around the platform.
========================================================= */

function asArray(
  value
){

  if (
    Array.isArray(
      value
    )
  ){

    return value;

  }


  if (
    !value ||
    typeof value !==
      "object"
  ){

    return [];

  }


  const candidates = [

    value.data,
    value.items,
    value.users,
    value.students,
    value.teachers,
    value.classes,
    value.assignments,
    value.submissions,
    value.schedules,
    value.attendance,
    value.quizzes,
    value.quizSubmissions,
    value.questions,
    value.questionBank,
    value.posts,
    value.resources,
    value.notifications,
    value.results

  ];


  for (
    const candidate of candidates
  ){

    if (
      Array.isArray(
        candidate
      )
    ){

      return candidate;

    }

  }


  return [];

}


/* =========================================================
   SAFE OBJECT
========================================================= */

function asObject(
  value
){

  if (
    value &&
    typeof value ===
      "object" &&
    !Array.isArray(
      value
    )
  ){

    return value;

  }


  return {};

}


/* =========================================================
   HTML ESCAPING
========================================================= */

function escapeHtml(
  value
){

  return String(
    value ??
    ""
  )
    .replace(
      /&/g,
      "&amp;"
    )
    .replace(
      /</g,
      "&lt;"
    )
    .replace(
      />/g,
      "&gt;"
    )
    .replace(
      /"/g,
      "&quot;"
    )
    .replace(
      /'/g,
      "&#039;"
    );

}


/* =========================================================
   ATTRIBUTE ESCAPING
========================================================= */

function escapeAttribute(
  value
){

  return escapeHtml(
    value
  );

}


/* =========================================================
   SAFE TEXT SETTER
========================================================= */

function setText(
  id,
  value
){

  const element =
    $(
      id
    );


  if (
    !element
  ){

    return false;

  }


  element.textContent =
    value ===
      null ||
    value ===
      undefined
      ? ""
      : String(
          value
        );


  return true;

}


/* =========================================================
   SAFE HTML SETTER

   Only use this when the caller has constructed sanitized
   markup. User-provided fields must pass through escapeHtml.
========================================================= */

function setHtml(
  id,
  html
){

  const element =
    $(
      id
    );


  if (
    !element
  ){

    return false;

  }


  element.innerHTML =
    String(
      html ||
      ""
    );


  return true;

}


/* =========================================================
   SAFE STRING
========================================================= */

function safeString(
  value,
  fallback = ""
){

  if (
    value ===
      null ||
    value ===
      undefined
  ){

    return fallback;

  }


  const normalized =
    String(
      value
    ).trim();


  return (
    normalized ||
    fallback
  );

}


/* =========================================================
   SAFE NUMBER
========================================================= */

function safeNumber(
  value,
  fallback = 0
){

  const number =
    Number(
      value
    );


  return Number.isFinite(
    number
  )
    ? number
    : fallback;

}


/* =========================================================
   INTEGER NORMALIZATION
========================================================= */

function safeInteger(
  value,
  fallback = 0
){

  const number =
    Number.parseInt(
      value,
      10
    );


  return Number.isFinite(
    number
  )
    ? number
    : fallback;

}


/* =========================================================
   PERCENTAGE NORMALIZATION
========================================================= */

function clampPercentage(
  value
){

  return Math.max(
    0,
    Math.min(
      100,
      Math.round(
        safeNumber(
          value,
          0
        )
      )
    )
  );

}


/* =========================================================
   BOOLEAN NORMALIZATION
========================================================= */

function normalizeBoolean(
  value,
  fallback = false
){

  if (
    typeof value ===
    "boolean"
  ){

    return value;

  }


  if (
    typeof value ===
    "number"
  ){

    return value !==
      0;

  }


  const normalized =
    String(
      value ??
      ""
    )
      .trim()
      .toLowerCase();


  if (
    [
      "true",
      "1",
      "yes",
      "on"
    ].includes(
      normalized
    )
  ){

    return true;

  }


  if (
    [
      "false",
      "0",
      "no",
      "off"
    ].includes(
      normalized
    )
  ){

    return false;

  }


  return fallback;

}


/* =========================================================
   VALID DATE
========================================================= */

function toValidDate(
  value
){

  if (
    !value
  ){

    return null;

  }


  const date =
    value instanceof Date
      ? new Date(
          value.getTime()
        )
      : new Date(
          value
        );


  if (
    Number.isNaN(
      date.getTime()
    )
  ){

    return null;

  }


  return date;

}


/* =========================================================
   DATE FORMATTER
========================================================= */

function formatDate(
  value,
  fallback = "No date"
){

  const date =
    toValidDate(
      value
    );


  if (
    !date
  ){

    return fallback;

  }


  return date.toLocaleDateString(
    [],
    {
      month:
        "short",

      day:
        "numeric",

      year:
        "numeric"
    }
  );

}


/* =========================================================
   DATE + TIME FORMATTER
========================================================= */

function formatDateTime(
  value,
  fallback = "No date"
){

  const date =
    toValidDate(
      value
    );


  if (
    !date
  ){

    return fallback;

  }


  return date.toLocaleString(
    [],
    {
      month:
        "short",

      day:
        "numeric",

      year:
        "numeric",

      hour:
        "2-digit",

      minute:
        "2-digit"
    }
  );

}


/* =========================================================
   TIME FORMATTER
========================================================= */

function formatTime(
  value,
  fallback = ""
){

  if (
    !value
  ){

    return fallback;

  }


  if (
    typeof value ===
      "string" &&
    !value.includes(
      "T"
    ) &&
    /^\d{1,2}:\d{2}/.test(
      value
    )
  ){

    return value;

  }


  const date =
    toValidDate(
      value
    );


  if (
    !date
  ){

    return String(
      value
    );

  }


  return date.toLocaleTimeString(
    [],
    {
      hour:
        "2-digit",

      minute:
        "2-digit"
    }
  );

}


/* =========================================================
   RELATIVE DATE LABEL
========================================================= */

function formatRelativeDate(
  value
){

  const date =
    toValidDate(
      value
    );


  if (
    !date
  ){

    return "";

  }


  const now =
    Date.now();

  const difference =
    now -
    date.getTime();

  const absoluteDifference =
    Math.abs(
      difference
    );

  const minute =
    60 * 1000;

  const hour =
    60 * minute;

  const day =
    24 * hour;


  if (
    absoluteDifference <
    minute
  ){

    return difference >=
      0
      ? "Just now"
      : "Soon";

  }


  if (
    absoluteDifference <
    hour
  ){

    const minutes =
      Math.max(
        1,
        Math.round(
          absoluteDifference /
          minute
        )
      );


    return difference >=
      0
      ? `${minutes}m ago`
      : `In ${minutes}m`;

  }


  if (
    absoluteDifference <
    day
  ){

    const hours =
      Math.max(
        1,
        Math.round(
          absoluteDifference /
          hour
        )
      );


    return difference >=
      0
      ? `${hours}h ago`
      : `In ${hours}h`;

  }


  const days =
    Math.max(
      1,
      Math.round(
        absoluteDifference /
        day
      )
    );


  if (
    days <
    7
  ){

    return difference >=
      0
      ? `${days}d ago`
      : `In ${days}d`;

  }


  return formatDate(
    date
  );

}


/* =========================================================
   SAFE URL

   Allows HTTP(S) URLs only.
========================================================= */

function normalizeHttpUrl(
  value
){

  const raw =
    String(
      value ||
      ""
    ).trim();


  if (
    !raw
  ){

    return "";

  }


  try{

    const url =
      new URL(
        raw,
        window.location.origin
      );


    if (
      ![
        "http:",
        "https:"
      ].includes(
        url.protocol
      )
    ){

      return "";

    }


    return url.href;

  }catch{

    return "";

  }

}


/* =========================================================
   SAFE IMAGE SOURCE
========================================================= */

function getSafeImageUrl(
  value,
  fallback = FALLBACK_AVATAR
){

  return (
    normalizeHttpUrl(
      value
    ) ||
    fallback
  );

}


/* =========================================================
   UNIQUE BY ID
========================================================= */

function uniqueById(
  items
){

  const map =
    new Map();


  asArray(
    items
  ).forEach(
    item => {

      const id =
        normalizeId(
          item?._id ||
          item?.id ||
          item
        );


      if (
        !id ||
        map.has(
          id
        )
      ){

        return;

      }


      map.set(
        id,
        item
      );

    }
  );


  return Array.from(
    map.values()
  );

}


/* =========================================================
   SORT NEWEST FIRST
========================================================= */

function sortNewestFirst(
  items,
  fields = [
    "updatedAt",
    "createdAt"
  ]
){

  return [
    ...asArray(
      items
    )
  ].sort(
    (
      first,
      second
    ) => {

      const getTimestamp =
        item => {

          for (
            const field of fields
          ){

            const date =
              toValidDate(
                item?.[
                  field
                ]
              );


            if (
              date
            ){

              return date.getTime();

            }

          }


          return 0;

        };


      return (
        getTimestamp(
          second
        ) -
        getTimestamp(
          first
        )
      );

    }
  );

}


/* =========================================================
   TEACHER ID

   IMPORTANT:
   selectedTeacherId is accepted for school/admin inspection.
   A normal teacher session will later be validated against
   the authenticated identity during boot.
========================================================= */

function getTeacherId(){

  return normalizeId(

    state.session
      .teacherId ||

    selectedTeacherId ||

    state.me?._id ||
    state.me?.id ||

    state.loggedUser?._id ||
    state.loggedUser?.id ||

    localStorage.getItem(
      AIFT_TEACHER_CONFIG
        .storageKeys
        .userId
    )

  );

}


/* =========================================================
   SCHOOL ID
========================================================= */

function getSchoolId(){

  const sessionSchoolId =
    normalizeId(
      state.session
        .schoolId
    );


  if (
    sessionSchoolId
  ){

    return sessionSchoolId;

  }


  const profileSchoolId =
    normalizeId(

      state.me
        ?.schoolId
        ?._id ||

      state.me
        ?.schoolId ||

      state.me
        ?.linkedSchoolId
        ?._id ||

      state.me
        ?.linkedSchoolId

    );


  if (
    profileSchoolId
  ){

    return profileSchoolId;

  }


  const authenticatedSchoolId =
    normalizeId(

      state.loggedUser
        ?.schoolId
        ?._id ||

      state.loggedUser
        ?.schoolId ||

      state.loggedUser
        ?.linkedSchoolId
        ?._id ||

      state.loggedUser
        ?.linkedSchoolId

    );


  if (
    authenticatedSchoolId
  ){

    return authenticatedSchoolId;

  }


  const classWithSchool =
    asArray(
      state.classes
    ).find(
      classItem =>
        normalizeId(
          classItem
            ?.schoolId
            ?._id ||
          classItem
            ?.schoolId
        )
    );


  return normalizeId(
    classWithSchool
      ?.schoolId
      ?._id ||
    classWithSchool
      ?.schoolId
  );

}


/* =========================================================
   AUTHENTICATED USER ID
========================================================= */

function getAuthenticatedUserId(){

  return normalizeId(

    state.loggedUser
      ?._id ||

    state.loggedUser
      ?.id ||

    state.session
      .userId ||

    localStorage.getItem(
      AIFT_TEACHER_CONFIG
        .storageKeys
        .userId
    )

  );

}


/* =========================================================
   AUTHENTICATED ROLE
========================================================= */

function getAuthenticatedRole(){

  return normalizeRole(

    state.loggedUser
      ?.role ||

    state.me
      ?.role ||

    state.session
      .role ||

    role

  );

}


/* =========================================================
   ROLE CHECKS
========================================================= */

function isTeacherSession(){

  return (
    getAuthenticatedRole() ===
    "teacher"
  );

}


function isSchoolSession(){

  return (
    getAuthenticatedRole() ===
    "school"
  );

}


function isAdminSession(){

  return (
    getAuthenticatedRole() ===
    "admin"
  );

}


/* =========================================================
   GET ASSIGNED TEACHER CLASSES

   SECURITY MODEL:
   Frontend filtering is UX only.

   Backend permissions remain authoritative.

   For a teacher session, only classes whose teacherId
   matches that authenticated teacher are returned.

   School/admin sessions may inspect broader class data,
   but Teacher Studio's teacher-scoped workspaces still use
   the selected teacher when one is explicitly selected.
========================================================= */

function getTeacherClasses(){

  const teacherId =
    getTeacherId();


  if (
    !teacherId
  ){

    return [];

  }


  return asArray(
    state.classes
  ).filter(
    classItem => {

      const classTeacherId =
        normalizeId(

          classItem
            ?.teacherId
            ?._id ||

          classItem
            ?.teacherId

        );


      return (
        classTeacherId &&
        sameId(
          classTeacherId,
          teacherId
        )
      );

    }
  );

}


/* =========================================================
   GET TEACHER CLASS IDS
========================================================= */

function getTeacherClassIds(){

  return getTeacherClasses()
    .map(
      classItem =>
        normalizeId(
          classItem?._id ||
          classItem?.id
        )
    )
    .filter(
      Boolean
    );

}


/* =========================================================
   ASSIGNMENT STATUS
========================================================= */

function normalizeAssignmentStatus(
  value
){

  const status =
    String(
      value ||
      ""
    )
      .trim()
      .toLowerCase();


  const validStatuses =
    new Set([
      "draft",
      "published",
      "active",
      "closed",
      "archived"
    ]);


  if (
    validStatuses.has(
      status
    )
  ){

    return status;

  }


  return (
    status ||
    "active"
  );

}


/* =========================================================
   SUBMISSION STATUS
========================================================= */

function normalizeSubmissionStatus(
  value
){

  const status =
    String(
      value ||
      "submitted"
    )
      .trim()
      .toLowerCase();


  return (
    status ||
    "submitted"
  );

}


/* =========================================================
   GET TEACHER ASSIGNMENTS
========================================================= */

function getTeacherAssignments(){

  const classIds =
    new Set(
      getTeacherClassIds()
    );

  const teacherId =
    getTeacherId();


  return asArray(
    state.assignments
  ).filter(
    assignment => {

      const classId =
        normalizeId(
          assignment
            ?.classId
            ?._id ||
          assignment
            ?.classId
        );

      const assignmentTeacherId =
        normalizeId(
          assignment
            ?.teacherId
            ?._id ||
          assignment
            ?.teacherId
        );


      /*
        Modern assignment:
        belongs to one of this teacher's assigned classes.

        Legacy assignment without a class:
        preserve only if explicitly owned by this teacher.
      */

      if (
        classId
      ){

        return classIds.has(
          classId
        );

      }


      return (
        assignmentTeacherId &&
        sameId(
          assignmentTeacherId,
          teacherId
        )
      );

    }
  );

}


