/* =========================================================
   UNIQUE STUDENTS FROM ASSIGNED CLASSES
========================================================= */

function getTeacherStudents(){

  const studentMap =
    new Map();


  getTeacherClasses()
    .forEach(
      classItem => {

        const classId =
          normalizeId(
            classItem?._id ||
            classItem?.id
          );

        const classTitle =
          safeString(
            classItem?.title ||
            classItem?.subject,
            "Class"
          );


        asArray(
          classItem?.studentIds
        ).forEach(
          student => {

            const studentId =
              normalizeId(
                student?._id ||
                student?.id ||
                student
              );


            if (
              !studentId
            ){

              return;

            }


            if (
              !studentMap.has(
                studentId
              )
            ){

              studentMap.set(
                studentId,
                {

                  id:
                    studentId,

                  student:
                    typeof student ===
                      "object"
                      ? student
                      : {
                          _id:
                            studentId
                        },

                  classes:
                    []

                }
              );

            }


            const record =
              studentMap.get(
                studentId
              );


            if (
              !record.classes.some(
                existingClass =>
                  sameId(
                    existingClass.id,
                    classId
                  )
              )
            ){

              record.classes.push({

                id:
                  classId,

                title:
                  classTitle

              });

            }

          }
        );

      }
    );


  return Array.from(
    studentMap.values()
  );

}


/* =========================================================
   PENDING TEACHER SUBMISSIONS
========================================================= */

function getPendingTeacherSubmissions(){

  return getTeacherSubmissions()
    .filter(
      submission => {

        const status =
          normalizeSubmissionStatus(
            submission?.status
          );


        return [
          "submitted",
          "pending"
        ].includes(
          status
        );

      }
    );

}


