/* =========================================================
   LEGACY API SEND COMPATIBILITY

   Older Teacher Studio modules still use:

     apiSend(path, method)
     apiSend(path, method, body)
     apiSend(path, method, body, options)

   Keep one compatibility layer instead of rewriting older
   production modules individually.

   All requests still flow through apiRequest(), therefore:
     - Bearer authentication remains centralized
     - timeout handling remains centralized
     - FormData support remains centralized
     - 401 handling remains centralized
     - AIFTApiError remains authoritative
========================================================= */

async function apiSend(
  path,
  method = "POST",
  body = undefined,
  options = {}
){

  const normalizedMethod =
    safeString(
      method,
      "POST"
    )
      .toUpperCase();


  const requestOptions = {
    ...asObject(
      options
    ),

    method:
      normalizedMethod
  };


  if (
    body !==
    undefined &&
    normalizedMethod !==
      "GET" &&
    normalizedMethod !==
      "HEAD"
  ){

    requestOptions.body =
      body;

  }


  return apiRequest(
    path,
    requestOptions
  );

}


/*
  Runtime audit checks required functions through window[].

  Explicit export avoids depending on browser behavior for
  global function declarations.
*/

window.apiSend =
  apiSend;


/* =========================================================
   LEGACY API REQUEST COMPATIBILITY

   Some existing workspace implementations use api().
   The new architecture keeps one real implementation instead
   of duplicating request logic.
========================================================= */

async function api(
  path,
  options = {}
){

  return apiRequest(
    path,
    options
  );

}


/* =========================================================
   AIFT NOTIFICATION SYSTEM
========================================================= */

const AIFT_NOTIFICATION_DEFAULT_DURATION =
  4200;

const AIFT_NOTIFICATION_MAX_VISIBLE =
  4;

const AIFT_NOTIFICATION_TYPES =
  Object.freeze({

    success:{

      title:
        "Completed",

      icon:
        "fa-solid fa-circle-check"

    },

    error:{

      title:
        "Something went wrong",

      icon:
        "fa-solid fa-circle-exclamation"

    },

    warning:{

      title:
        "Attention needed",

      icon:
        "fa-solid fa-triangle-exclamation"

    },

    info:{

      title:
        "AIFT update",

      icon:
        "fa-solid fa-circle-info"

    }

  });


let aiftNotificationSequence =
  0;


/* =========================================================
   NOTIFICATION REGION
========================================================= */

function getAIFTNotificationRegion(){

  let region =
    $(
      "aiftNotificationRegion"
    );


  if (
    region
  ){

    return region;

  }


  region =
    document.createElement(
      "div"
    );


  region.id =
    "aiftNotificationRegion";

  region.className =
    "aift-notification-region";

  region.setAttribute(
    "role",
    "region"
  );

  region.setAttribute(
    "aria-label",
    "AIFT notifications"
  );

  region.setAttribute(
    "aria-live",
    "polite"
  );

  region.setAttribute(
    "aria-relevant",
    "additions removals"
  );


  document.body.appendChild(
    region
  );


  return region;

}


/* =========================================================
   NORMALIZE NOTIFICATION TYPE
========================================================= */

function normalizeAIFTNotificationType(
  type
){

  const normalized =
    String(
      type ||
      "info"
    )
      .trim()
      .toLowerCase();


  return Object.prototype
    .hasOwnProperty
    .call(
      AIFT_NOTIFICATION_TYPES,
      normalized
    )
      ? normalized
      : "info";

}


/* =========================================================
   REMOVE NOTIFICATION
========================================================= */

function removeAIFTNotification(
  notification,
  immediate = false
){

  if (
    !notification
  ){

    return;

  }


  const timer =
    safeInteger(
      notification.dataset
        .notificationTimer,
      0
    );


  if (
    timer
  ){

    window.clearTimeout(
      timer
    );

  }


  if (
    immediate
  ){

    notification.remove();
    return;

  }


  if (
    notification.classList.contains(
      "is-leaving"
    )
  ){

    return;

  }


  notification.classList.remove(
    "is-visible"
  );

  notification.classList.add(
    "is-leaving"
  );


  window.setTimeout(
    () => {

      notification.remove();

    },
    290
  );

}


/* =========================================================
   NOTIFICATION VISIBILITY LIMIT
========================================================= */

function enforceAIFTNotificationLimit(
  region
){

  const notifications =
    Array.from(
      region.querySelectorAll(
        ".aift-notification"
      )
    );


  while (
    notifications.length >=
    AIFT_NOTIFICATION_MAX_VISIBLE
  ){

    const oldest =
      notifications.shift();


    removeAIFTNotification(
      oldest,
      true
    );

  }

}


/* =========================================================
   SHOW NOTIFICATION
========================================================= */

function showAlert(
  type,
  message,
  options = {}
){

  const normalizedType =
    normalizeAIFTNotificationType(
      type
    );

  const configuration =
    AIFT_NOTIFICATION_TYPES[
      normalizedType
    ];

  const safeMessage =
    safeString(
      message,
      "An update is available."
    );

  const title =
    safeString(
      options.title,
      configuration.title
    );

  const duration =
    Math.max(
      1500,
      safeInteger(
        options.duration,
        AIFT_NOTIFICATION_DEFAULT_DURATION
      )
    );

  const region =
    getAIFTNotificationRegion();


  enforceAIFTNotificationLimit(
    region
  );


  const notification =
    document.createElement(
      "article"
    );

  const notificationId =
    `aift-notification-${++aiftNotificationSequence}`;


  notification.id =
    notificationId;

  notification.className =
    `aift-notification ${normalizedType}`;

  notification.setAttribute(
    "role",
    normalizedType ===
      "error"
      ? "alert"
      : "status"
  );

  notification.setAttribute(
    "aria-atomic",
    "true"
  );

  notification.style.setProperty(
    "--aift-notification-duration",
    `${duration}ms`
  );


  notification.innerHTML = `
    <div
      class="aift-notification-icon"
      aria-hidden="true"
    >
      <i
        class="${escapeAttribute(configuration.icon)}"
        aria-hidden="true"
      ></i>
    </div>

    <div
      class="aift-notification-copy"
    >
      <span
        class="aift-notification-brand"
      >
        AIFT
      </span>

      <strong>
        ${escapeHtml(title)}
      </strong>

      <p>
        ${escapeHtml(safeMessage)}
      </p>
    </div>

    <button
      class="aift-notification-close"
      type="button"
      aria-label="Dismiss notification"
    >
      <i
        class="fa-solid fa-xmark"
        aria-hidden="true"
      ></i>
    </button>

    <div
      class="aift-notification-progress"
      aria-hidden="true"
    ></div>
  `;


  region.appendChild(
    notification
  );


  window.requestAnimationFrame(
    () => {

      window.requestAnimationFrame(
        () => {

          notification.classList.add(
            "is-visible"
          );

        }
      );

    }
  );


  let remaining =
    duration;

  let startedAt =
    Date.now();


  const startTimer =
    () => {

      startedAt =
        Date.now();


      const timer =
        window.setTimeout(
          () => {

            removeAIFTNotification(
              notification
            );

          },
          remaining
        );


      notification.dataset
        .notificationTimer =
        String(
          timer
        );

    };


  const pauseTimer =
    () => {

      const timer =
        safeInteger(
          notification.dataset
            .notificationTimer,
          0
        );


      if (
        timer
      ){

        window.clearTimeout(
          timer
        );

      }


      remaining =
        Math.max(
          0,
          remaining -
          (
            Date.now() -
            startedAt
          )
        );


      notification.classList.add(
        "is-paused"
      );

    };


  const resumeTimer =
    () => {

      if (
        remaining <=
        0
      ){

        removeAIFTNotification(
          notification
        );

        return;

      }


      notification.classList.remove(
        "is-paused"
      );


      startTimer();

    };


  notification
    .querySelector(
      ".aift-notification-close"
    )
    ?.addEventListener(
      "click",
      () => {

        removeAIFTNotification(
          notification
        );

      }
    );


  notification.addEventListener(
    "mouseenter",
    pauseTimer
  );

  notification.addEventListener(
    "mouseleave",
    resumeTimer
  );

  notification.addEventListener(
    "focusin",
    pauseTimer
  );

  notification.addEventListener(
    "focusout",
    resumeTimer
  );


  startTimer();


  return {

    id:
      notificationId,

    close(){

      removeAIFTNotification(
        notification
      );

    },

    element:
      notification

  };

}


