/* =========================================================
   BUILD GRADING STATE
========================================================= */

function rebuildTeacherGradingState(){

  const pending =
    getPendingTeacherSubmissions();

  const reviewed =
    getReviewedTeacherSubmissions();

  const returned =
    getReturnedTeacherSubmissions();


  state.grading.pending =
    pending;

  state.grading.reviewed =
    reviewed;

  state.grading.returned =
    returned;

  state.grading.total =
    getTeacherSubmissions()
      .length;


  return state.grading;

}


/* =========================================================
   ATTENDANCE RATE
========================================================= */

function calculateTeacherAttendanceRate(){

  const attendance =
    getTeacherAttendance();


  if (
    !attendance.length
  ){

    return 0;

  }


  const attended =
    attendance.filter(
      record => {

        const status =
          String(
            record?.status ||
            ""
          )
            .trim()
            .toLowerCase();


        return [
          "present",
          "late"
        ].includes(
          status
        );

      }
    ).length;


  return clampPercentage(
    (
      attended /
      attendance.length
    ) *
    100
  );

}


/* =========================================================
   SUBMISSION ENGAGEMENT RATE

   This is a Teacher Studio operational metric.

   It measures unique students represented in submissions
   against the teacher's unique assigned students.

   It is NOT presented as an academic grade.
========================================================= */

function calculateTeacherEngagementRate(){

  const students =
    getTeacherStudents();

  const submissions =
    getTeacherSubmissions();


  if (
    !students.length
  ){

    return 0;

  }


  const submittingStudentIds =
    new Set();


  submissions.forEach(
    submission => {

      const studentId =
        normalizeId(
          submission
            ?.studentId
            ?._id ||
          submission
            ?.studentId
        );


      if (
        studentId
      ){

        submittingStudentIds.add(
          studentId
        );

      }

    }
  );


  return clampPercentage(
    (
      submittingStudentIds.size /
      students.length
    ) *
    100
  );

}


/* =========================================================
   PERFORMANCE METRIC

   Uses reviewed numeric grades only.

   It does not allow Kabezya to publish or modify grades.
========================================================= */

function calculateTeacherPerformanceRate(){

  const reviewedSubmissions =
    getReviewedTeacherSubmissions()
      .filter(
        submission =>
          Number.isFinite(
            Number(
              submission?.grade
            )
          )
      );


  if (
    !reviewedSubmissions.length
  ){

    return 0;

  }


  const total =
    reviewedSubmissions.reduce(
      (
        sum,
        submission
      ) =>
        sum +
        safeNumber(
          submission?.grade,
          0
        ),
      0
    );


  return clampPercentage(
    total /
    reviewedSubmissions.length
  );

}


/* =========================================================
   CALCULATE TEACHER METRICS
========================================================= */

function calculateTeacherMetrics(){

  const classes =
    getTeacherClasses();

  const students =
    getTeacherStudents();

  const assignments =
    getTeacherAssignments();

  const submissions =
    getTeacherSubmissions();

  const pendingGrading =
    getPendingTeacherSubmissions();


  state.metrics.classes =
    classes.length;

  state.metrics.students =
    students.length;

  state.metrics.assignments =
    assignments.length;

  state.metrics.submissions =
    submissions.length;

  state.metrics.pendingGrading =
    pendingGrading.length;

  state.metrics.attendance =
    calculateTeacherAttendanceRate();

  state.metrics.engagement =
    calculateTeacherEngagementRate();

  state.metrics.performance =
    calculateTeacherPerformanceRate();


  return state.metrics;

}


/* =========================================================
   CREATE EMPTY CLASS CACHE RECORD
========================================================= */

function createTeacherClassCacheRecord(
  classItem
){

  return {

    classId:
      normalizeId(
        classItem?._id ||
        classItem?.id
      ),

    classItem,

    students:
      [],

    assignments:
      [],

    submissions:
      [],

    schedules:
      [],

    attendance:
      [],

    quizzes:
      [],

    quizSubmissions:
      [],

    modules:
      [],

    lessons:
      [],

    analytics:
      {}

  };

}


/* =========================================================
   REBUILD PER-CLASS DATA CACHE
========================================================= */

function rebuildTeacherClassDataCache(){

  state.classDataById.clear();


  getTeacherClasses()
    .forEach(
      classItem => {

        const classId =
          normalizeId(
            classItem?._id ||
            classItem?.id
          );


        if (
          !classId
        ){

          return;

        }


        const record =
          createTeacherClassCacheRecord(
            classItem
          );


        record.students =
          asArray(
            classItem?.studentIds
          );


        record.assignments =
          getTeacherAssignments()
            .filter(
              assignment =>
                sameId(
                  assignment
                    ?.classId
                    ?._id ||
                  assignment
                    ?.classId,
                  classId
                )
            );


        record.submissions =
          getTeacherSubmissions()
            .filter(
              submission =>
                sameId(
                  submission
                    ?.classId
                    ?._id ||
                  submission
                    ?.classId,
                  classId
                )
            );


        record.schedules =
          getTeacherSchedules()
            .filter(
              schedule =>
                sameId(
                  schedule
                    ?.classId
                    ?._id ||
                  schedule
                    ?.classId,
                  classId
                )
            );


        record.attendance =
          getTeacherAttendance()
            .filter(
              attendanceRecord =>
                sameId(
                  attendanceRecord
                    ?.classId
                    ?._id ||
                  attendanceRecord
                    ?.classId,
                  classId
                )
            );


        record.quizzes =
          getTeacherQuizzes()
            .filter(
              quiz =>
                sameId(
                  quiz
                    ?.classId
                    ?._id ||
                  quiz
                    ?.classId,
                  classId
                )
            );


        record.quizSubmissions =
          asArray(
            state.quizSubmissions
          )
            .filter(
              submission =>
                sameId(
                  submission
                    ?.classId
                    ?._id ||
                  submission
                    ?.classId,
                  classId
                )
            );


        state.classDataById.set(
          classId,
          record
        );

      }
    );


  return state.classDataById;

}


/* =========================================================
   GET CLASS CACHE
========================================================= */

function getTeacherClassData(
  classId
){

  return (
    state.classDataById.get(
      normalizeId(
        classId
      )
    ) ||
    null
  );

}


/* =========================================================
   FINALIZE LOADED TEACHER DATA
========================================================= */

function finalizeTeacherLoadedData(){

  rebuildTeacherStudents();

  rebuildTeacherGradingState();

  calculateTeacherMetrics();

  rebuildTeacherClassDataCache();


  return state;

}


/* =========================================================
   CRITICAL DATA LOAD

   Critical means:
   - authenticated account
   - authorization
   - teacher identity
   - assigned classes

   If these fail, Teacher Studio cannot safely continue.
========================================================= */

async function loadTeacherCriticalData(){

  const authenticatedUser =
    await loadAuthenticatedTeacherStudioUser();


  validateSelectedTeacherIdentity();


  await loadTeacherClasses();


  state.boot.criticalDataLoaded =
    true;


  return {
    authenticatedUser,

    classes:
      getTeacherClasses(),

    teacherId:
      getTeacherId(),

    schoolId:
      getSchoolId()
  };

}


/* =========================================================
   PRIMARY WORKSPACE DATA

   Assignments/submissions/schedules directly drive the
   Teacher Studio's primary workspaces.

   They are loaded together after assigned classes exist.
========================================================= */

async function loadTeacherPrimaryWorkspaceData(){

  const results =
    await Promise.allSettled([

      loadTeacherAssignments(),

      loadTeacherSubmissions(),

      loadTeacherSchedules()

    ]);


  const labels = [
    "Assignments",
    "Submissions",
    "Schedules"
  ];


  const failures =
    [];


  results.forEach(
    (
      result,
      index
    ) => {

      if (
        result.status ===
        "rejected"
      ){

        failures.push({
          label:
            labels[index],

          error:
            result.reason
        });

      }

    }
  );


  /*
    Authentication failures have already been handled by the
    API client.

    A single workspace endpoint failure does not leave the
    entire page permanently disabled. The failed workspace can
    present a recoverable state later.
  */

  failures.forEach(
    failure => {

      reportOptionalRequestError(
        failure.label,
        failure.error
      );

    }
  );


  return {
    assignments:
      getTeacherAssignments(),

    submissions:
      getTeacherSubmissions(),

    schedules:
      getTeacherSchedules(),

    failures
  };

}


/* =========================================================
   SECONDARY / OPTIONAL DATA LOAD

   These datasets enrich Teacher Studio but must not make the
   complete dashboard unusable if one request fails.
========================================================= */

async function loadTeacherOptionalData(){

  const tasks = [

    {
      name:
        "Attendance",

      run:
        loadTeacherAttendance
    },

    {
      name:
        "Quizzes",

      run:
        loadTeacherQuizzes
    },

    {
      name:
        "Quiz submissions",

      run:
        loadTeacherQuizSubmissions
    },

    {
      name:
        "Unread notifications",

      run:
        loadTeacherUnreadNotifications
    },

    {
      name:
        "Resources",

      run:
        loadTeacherResources
    },

    {
      name:
        "Question Bank",

      run:
        loadTeacherQuestionBankWhenAvailable
    }

  ];


  const results =
    await Promise.allSettled(
      tasks.map(
        task =>
          task.run()
      )
    );


  const failures =
    [];


  results.forEach(
    (
      result,
      index
    ) => {

      if (
        result.status ===
        "rejected"
      ){

        const failure = {
          name:
            tasks[index].name,

          error:
            result.reason
        };


        failures.push(
          failure
        );


        reportOptionalRequestError(
          failure.name,
          failure.error
        );

      }

    }
  );


  state.boot.optionalDataLoaded =
    true;


  return {
    results,
    failures
  };

}


/* =========================================================
   CENTRALIZED DATA BOOT

   This replaces the missing old loadAll() architecture.

   IMPORTANT:
   It intentionally does not render workspaces yet.

   Rendering/router/controller initialization will be added
   after those functions have been rebuilt in later parts.

   That prevents startup from referencing functions that have
   not yet been defined.
========================================================= */

async function loadTeacherStudioData(){

  if (
    state.boot.started
  ){

    return state;

  }


  state.boot.started =
    true;

  state.boot.failed =
    false;

  state.boot.error =
    null;


  try{

    await loadTeacherCriticalData();


    await loadTeacherPrimaryWorkspaceData();


    await loadTeacherOptionalData();


    finalizeTeacherLoadedData();


    document.dispatchEvent(
      new CustomEvent(
        AIFT_TEACHER_CONFIG
          .events
          .dataRefresh,
        {
          detail:{

            teacherId:
              getTeacherId(),

            schoolId:
              getSchoolId(),

            metrics:{
              ...state.metrics
            }

          }
        }
      )
    );


    return state;

  }catch(
    error
  ){

    state.boot.failed =
      true;

    state.boot.error =
      error;


    throw error;

  }

}


/* =========================================================
   RELOAD TEACHER STUDIO DATA

   Used later by manual refresh, focus refresh and Socket.IO.

   Unlike the initial boot, this may be called repeatedly.
========================================================= */

async function refreshTeacherStudioData(
  options = {}
){

  const includeAttendance =
    options.includeAttendance !==
    false;

  const includeQuizzes =
    options.includeQuizzes !==
    false;

  const includeSchedules =
    options.includeSchedules !==
    false;

  const includeAssignments =
    options.includeAssignments !==
    false;

  const includeSubmissions =
    options.includeSubmissions !==
    false;


  const tasks =
    [];


  if (
    includeAssignments
  ){

    tasks.push({
      name:
        "Assignments",

      run:
        loadTeacherAssignments
    });

  }


  if (
    includeSubmissions
  ){

    tasks.push({
      name:
        "Submissions",

      run:
        loadTeacherSubmissions
    });

  }


  if (
    includeSchedules
  ){

    tasks.push({
      name:
        "Schedules",

      run:
        loadTeacherSchedules
    });

  }


  if (
    includeAttendance
  ){

    tasks.push({
      name:
        "Attendance",

      run:
        loadTeacherAttendance
    });

  }


  if (
    includeQuizzes
  ){

    tasks.push({
      name:
        "Quizzes",

      run:
        loadTeacherQuizzes
    });

    tasks.push({
      name:
        "Quiz submissions",

      run:
        loadTeacherQuizSubmissions
    });

  }


  const results =
    await Promise.allSettled(
      tasks.map(
        task =>
          task.run()
      )
    );


  const failures =
    [];


  results.forEach(
    (
      result,
      index
    ) => {

      if (
        result.status ===
        "rejected"
      ){

        failures.push({
          name:
            tasks[index].name,

          error:
            result.reason
        });


        reportOptionalRequestError(
          tasks[index].name,
          result.reason
        );

      }

    }
  );


  finalizeTeacherLoadedData();


  document.dispatchEvent(
    new CustomEvent(
      AIFT_TEACHER_CONFIG
        .events
        .dataRefresh,
      {
        detail:{

          teacherId:
            getTeacherId(),

          metrics:{
            ...state.metrics
          },

          failures
        }
      }
    )
  );


  return {
    state,
    failures
  };

}


