/* =========================================================
   CLASS TITLE
========================================================= */

function getTeacherClassTitle(
  classItem
){

  return safeString(

    classItem?.title ||
    classItem?.name ||
    classItem?.subject,

    "Untitled class"

  );

}


/* =========================================================
   CLASS SUBJECT
========================================================= */

function getTeacherClassSubject(
  classItem
){

  return safeString(

    classItem?.subject ||
    classItem?.category ||
    classItem?.course,

    "Class"

  );

}


/* =========================================================
   CLASS CODE
========================================================= */

function getTeacherClassCode(
  classItem
){

  return safeString(

    classItem?.classCode ||
    classItem?.code ||
    classItem?.joinCode

  );

}


/* =========================================================
   CLASS STATUS
========================================================= */

function getTeacherClassStatus(
  classItem
){

  const status =
    safeString(
      classItem?.status,
      "active"
    )
      .toLowerCase();


  if (
    [
      "published",
      "open",
      "ongoing"
    ].includes(
      status
    )
  ){

    return "active";

  }


  if (
    [
      "completed",
      "closed",
      "finished"
    ].includes(
      status
    )
  ){

    return "completed";

  }


  return status;

}


/* =========================================================
   CLASS STUDENT COUNT
========================================================= */

function getTeacherClassStudentCount(
  classItem
){

  return asArray(
    classItem?.studentIds
  ).length;

}


/* =========================================================
   CLASS COVER
========================================================= */

function getTeacherClassCover(
  classItem
){

  return getSafeImageUrl(

    classItem?.coverImage ||
    classItem?.coverUrl ||
    classItem?.bannerImage ||
    classItem?.banner ||
    classItem?.image,

    CLASS_FALLBACK

  );

}


/* =========================================================
   MOST RECENT CLASS ACTIVITY
========================================================= */

function getTeacherClassLastActivity(
  classItem
){

  const classId =
    normalizeId(
      classItem?._id ||
      classItem?.id
    );

  const classData =
    getTeacherClassData(
      classId
    );


  const candidates = [

    classItem?.updatedAt,

    ...asArray(
      classData?.assignments
    ).map(
      item =>
        item.updatedAt ||
        item.createdAt
    ),

    ...asArray(
      classData?.submissions
    ).map(
      item =>
        item.submittedAt ||
        item.updatedAt ||
        item.createdAt
    ),

    ...asArray(
      classData?.schedules
    ).map(
      item =>
        item.updatedAt ||
        item.createdAt ||
        item.date
    )

  ]
    .map(
      toValidDate
    )
    .filter(
      Boolean
    )
    .sort(
      (
        first,
        second
      ) =>
        second.getTime() -
        first.getTime()
    );


  return candidates[0] ||
    null;

}


/* =========================================================
   OVERVIEW CLASS CARD
========================================================= */

function createTeacherOverviewClassCard(
  classItem
){

  const classId =
    normalizeId(
      classItem?._id ||
      classItem?.id
    );

  const title =
    getTeacherClassTitle(
      classItem
    );

  const subject =
    getTeacherClassSubject(
      classItem
    );

  const code =
    getTeacherClassCode(
      classItem
    );

  const students =
    getTeacherClassStudentCount(
      classItem
    );

  const cover =
    getTeacherClassCover(
      classItem
    );

  const activityDate =
    getTeacherClassLastActivity(
      classItem
    );

  const activityLabel =
    activityDate
      ? formatRelativeDate(
          activityDate
        )
      : "No recent activity";


  return `
    <article
      class="teacher-dashboard-class-item"
      data-teacher-class-id="${escapeAttribute(classId)}"
    >

      <button
        type="button"
        class="teacher-dashboard-class-main"
        data-teacher-action="open-class"
        data-class-id="${escapeAttribute(classId)}"
        aria-label="Open ${escapeAttribute(title)}"
      >

        <span
          class="teacher-dashboard-class-cover"
        >
          <img
            src="${escapeAttribute(cover)}"
            alt=""
            loading="lazy"
            referrerpolicy="no-referrer"
          />
        </span>

        <span
          class="teacher-dashboard-class-copy"
        >

          <strong>
            ${escapeHtml(title)}
          </strong>

          <span>
            ${escapeHtml(subject)}
            ${
              code
                ? ` · ${escapeHtml(code)}`
                : ""
            }
          </span>

          <small>
            ${students}
            ${
              students === 1
                ? "student"
                : "students"
            }
            · ${escapeHtml(activityLabel)}
          </small>

        </span>

        <span
          class="teacher-dashboard-class-arrow"
          aria-hidden="true"
        >
          <i
            class="fa-solid fa-chevron-right"
          ></i>
        </span>

      </button>

    </article>
  `;

}


/* =========================================================
   OVERVIEW CLASSES
========================================================= */

function renderTeacherOverviewClasses(){

  const container =
    $(
      "teacherDashboardClasses"
    );


  if (
    !container
  ){

    return;

  }


  const classes =
    getTeacherClasses()
      .filter(
        classItem =>
          ![
            "archived",
            "completed",
            "closed"
          ].includes(
            getTeacherClassStatus(
              classItem
            )
          )
      )
      .slice(
        0,
        5
      );


  if (
    !classes.length
  ){

    container.innerHTML = `
      <div
        class="teacher-inline-empty"
      >
        No active classes assigned yet.
      </div>
    `;


    return;

  }


  container.innerHTML =
    classes
      .map(
        createTeacherOverviewClassCard
      )
      .join(
        ""
      );


  container
    .querySelectorAll(
      "img"
    )
    .forEach(
      image => {

        image.onerror =
          () => {

            image.onerror =
              null;

            image.src =
              CLASS_FALLBACK;

          };

      }
    );

}


/* =========================================================
   SCHEDULE DATE RESOLUTION
========================================================= */

function getTeacherScheduleDate(
  schedule
){

  const directDate =
    schedule?.startDateTime ||
    schedule?.startAt ||
    schedule?.dateTime;


  if (
    directDate
  ){

    return toValidDate(
      directDate
    );

  }


  const datePart =
    safeString(
      schedule?.date
    );

  const timePart =
    safeString(
      schedule?.startTime ||
      schedule?.time
    );


  if (
    datePart &&
    timePart
  ){

    const combined =
      toValidDate(
        `${datePart}T${timePart}`
      );


    if (
      combined
    ){

      return combined;

    }

  }


  return toValidDate(
    datePart
  );

}


/* =========================================================
   SCHEDULE TITLE
========================================================= */

function getTeacherScheduleTitle(
  schedule
){

  const classTitle =
    safeString(

      schedule
        ?.classId
        ?.title ||

      schedule
        ?.classId
        ?.subject

    );


  return safeString(

    schedule?.title ||
    classTitle,

    "Scheduled class"

  );

}


/* =========================================================
   SCHEDULE TIME LABEL
========================================================= */

function getTeacherScheduleTimeLabel(
  schedule
){

  const start =
    safeString(
      schedule?.startTime ||
      schedule?.time
    );

  const end =
    safeString(
      schedule?.endTime
    );


  if (
    start &&
    end
  ){

    return `${start} – ${end}`;

  }


  if (
    start
  ){

    return start;

  }


  const date =
    getTeacherScheduleDate(
      schedule
    );


  return date
    ? formatTime(
        date
      )
    : "";

}


/* =========================================================
   OVERVIEW SCHEDULE ITEM
========================================================= */

function createTeacherOverviewScheduleItem(
  schedule
){

  const scheduleId =
    normalizeId(
      schedule?._id ||
      schedule?.id
    );

  const classId =
    normalizeId(
      schedule
        ?.classId
        ?._id ||
      schedule
        ?.classId
    );

  const title =
    getTeacherScheduleTitle(
      schedule
    );

  const scheduleDate =
    getTeacherScheduleDate(
      schedule
    );

  const time =
    getTeacherScheduleTimeLabel(
      schedule
    );

  const meetingLink =
    normalizeHttpUrl(
      schedule?.meetingLink
    );


  return `
    <div
      class="teacher-dashboard-schedule-item"
      data-schedule-id="${escapeAttribute(scheduleId)}"
    >

      <div
        class="teacher-dashboard-schedule-date"
      >
        <strong>
          ${
            scheduleDate
              ? escapeHtml(
                  scheduleDate.toLocaleDateString(
                    [],
                    {
                      day:
                        "2-digit"
                    }
                  )
                )
              : "—"
          }
        </strong>

        <span>
          ${
            scheduleDate
              ? escapeHtml(
                  scheduleDate.toLocaleDateString(
                    [],
                    {
                      month:
                        "short"
                    }
                  )
                )
              : ""
          }
        </span>
      </div>

      <div
        class="teacher-dashboard-schedule-copy"
      >

        <strong>
          ${escapeHtml(title)}
        </strong>

        <span>
          ${escapeHtml(time || "Time not set")}
        </span>

      </div>

      ${
        meetingLink
          ? `
            <a
              class="teacher-icon-button"
              href="${escapeAttribute(meetingLink)}"
              target="_blank"
              rel="noopener noreferrer"
              aria-label="Join ${escapeAttribute(title)}"
              title="Join class"
            >
              <i
                class="fa-solid fa-video"
              ></i>
            </a>
          `
          : `
            <button
              type="button"
              class="teacher-icon-button"
              data-teacher-action="open-schedule"
              data-schedule-id="${escapeAttribute(scheduleId)}"
              data-class-id="${escapeAttribute(classId)}"
              aria-label="View schedule"
              title="View schedule"
            >
              <i
                class="fa-regular fa-calendar"
              ></i>
            </button>
          `
      }

    </div>
  `;

}


/* =========================================================
   OVERVIEW SCHEDULE
========================================================= */

function renderTeacherOverviewSchedule(){

  const container =
    $(
      "teacherDashboardSchedule"
    );


  if (
    !container
  ){

    return;

  }


  const now =
    Date.now();


  const upcoming =
    getTeacherSchedules()
      .map(
        schedule => ({
          schedule,
          date:
            getTeacherScheduleDate(
              schedule
            )
        })
      )
      .filter(
        item =>
          item.date &&
          item.date.getTime() >=
            (
              now -
              60 * 60 * 1000
            )
      )
      .sort(
        (
          first,
          second
        ) =>
          first.date.getTime() -
          second.date.getTime()
      )
      .slice(
        0,
        5
      )
      .map(
        item =>
          item.schedule
      );


  if (
    !upcoming.length
  ){

    container.innerHTML = `
      <div
        class="teacher-inline-empty"
      >
        No upcoming classes.
      </div>
    `;


    return;

  }


  container.innerHTML =
    upcoming
      .map(
        createTeacherOverviewScheduleItem
      )
      .join(
        ""
      );

}


/* =========================================================
   ASSIGNMENT TITLE
========================================================= */

function getTeacherAssignmentTitle(
  assignment
){

  return safeString(
    assignment?.title,
    "Untitled assignment"
  );

}


/* =========================================================
   ASSIGNMENT CLASS TITLE
========================================================= */

function getTeacherAssignmentClassTitle(
  assignment
){

  const populatedClass =
    assignment?.classId;


  if (
    populatedClass &&
    typeof populatedClass ===
      "object"
  ){

    return safeString(

      populatedClass.title ||
      populatedClass.subject,

      "Class"

    );

  }


  const classId =
    normalizeId(
      populatedClass
    );


  const classRecord =
    getTeacherClassData(
      classId
    );


  return getTeacherClassTitle(
    classRecord?.classItem ||
    {}
  );

}


/* =========================================================
   ASSIGNMENT DUE DATE
========================================================= */

function getTeacherAssignmentDueDate(
  assignment
){

  if (
    !assignment
  ){

    return null;

  }


  return (
    assignment.dueDate ||
    assignment.deadline ||
    null
  );

}

/* =========================================================
   RECENT ASSIGNMENT ROW
========================================================= */

function createTeacherOverviewAssignmentRow(
  assignment
){

  const assignmentId =
    normalizeId(
      assignment?._id ||
      assignment?.id
    );

  const title =
    getTeacherAssignmentTitle(
      assignment
    );

  const classTitle =
    getTeacherAssignmentClassTitle(
      assignment
    );

  const dueDate =
    getTeacherAssignmentDueDate(
      assignment
    );

  const status =
    normalizeAssignmentStatus(
      assignment?.status
    );


  const relatedSubmissions =
    getTeacherSubmissions()
      .filter(
        submission =>
          sameId(
            submission
              ?.assignmentId
              ?._id ||
            submission
              ?.assignmentId,
            assignmentId
          )
      );


  const pending =
    relatedSubmissions
      .filter(
        submission =>
          [
            "submitted",
            "pending"
          ].includes(
            normalizeSubmissionStatus(
              submission?.status
            )
          )
      )
      .length;


  return `
    <button
      type="button"
      class="teacher-dashboard-assignment-item"
      data-teacher-action="open-assignment"
      data-assignment-id="${escapeAttribute(assignmentId)}"
    >

      <span
        class="teacher-dashboard-assignment-icon"
        aria-hidden="true"
      >
        <i
          class="fa-regular fa-file-lines"
        ></i>
      </span>

      <span
        class="teacher-dashboard-assignment-copy"
      >

        <strong>
          ${escapeHtml(title)}
        </strong>

        <span>
          ${escapeHtml(classTitle)}
          ${
            dueDate
              ? ` · Due ${escapeHtml(formatDate(dueDate))}`
              : ""
          }
        </span>

      </span>

      <span
        class="teacher-dashboard-assignment-meta"
      >

        ${
          pending
            ? `
              <span
                class="teacher-status-badge warning"
              >
                ${pending}
                ${
                  pending === 1
                    ? "to review"
                    : "to review"
                }
              </span>
            `
            : `
              <span
                class="teacher-status-badge"
              >
                ${escapeHtml(status)}
              </span>
            `
        }

        <i
          class="fa-solid fa-chevron-right"
          aria-hidden="true"
        ></i>

      </span>

    </button>
  `;

}


/* =========================================================
   OVERVIEW ASSIGNMENTS
========================================================= */

function renderTeacherOverviewAssignments(){

  const container =
    $(
      "teacherDashboardAssignments"
    );


  if (
    !container
  ){

    return;

  }


  const assignments =
    sortNewestFirst(
      getTeacherAssignments(),
      [
        "updatedAt",
        "createdAt",
        "dueDate"
      ]
    )
      .slice(
        0,
        6
      );


  if (
    !assignments.length
  ){

    container.innerHTML = `
      <div
        class="teacher-inline-empty"
      >
        No assignments yet.
      </div>
    `;


    return;

  }


  container.innerHTML =
    assignments
      .map(
        createTeacherOverviewAssignmentRow
      )
      .join(
        ""
      );

}


