/* =========================================================
   STUDENT WORKSPACE STATE
========================================================= */

const teacherStudentWorkspaceState = {

  search:
    "",

  classId:
    "",

  progress:
    "",

  selectedStudentId:
    "",

  refreshing:
    false,

  initialized:
    false

};


/* =========================================================
   NORMALIZE TEACHER STUDENT RECORD

   Part 2 deliberately stores student records as:

   {
     id,
     student:{...},
     classes:[...]
   }

   because one student may belong to multiple assigned
   classes.

   This helper gives the rest of the workspace one canonical
   interface while preserving that richer structure.
========================================================= */

function normalizeTeacherStudentRecord(
  value
){

  if (
    !value
  ){

    return null;

  }


  if (
    value.student &&
    typeof value.student ===
      "object"
  ){

    const studentId =
      normalizeId(

        value.id ||

        value.student._id ||
        value.student.id

      );


    if (
      !studentId
    ){

      return null;

    }


    return {

      id:
        studentId,

      student:
        value.student,

      classes:
        asArray(
          value.classes
        )

    };

  }


  const studentId =
    normalizeId(
      value._id ||
      value.id
    );


  if (
    !studentId
  ){

    return null;

  }


  return {

    id:
      studentId,

    student:
      value,

    classes:
      []

  };

}


/* =========================================================
   GET ALL STUDENT RECORDS
========================================================= */

function getTeacherStudentRecords(){

  return asArray(
    state.students
  )
    .map(
      normalizeTeacherStudentRecord
    )
    .filter(
      Boolean
    );

}


/* =========================================================
   STUDENT BY ID
========================================================= */

function getTeacherStudentById(
  studentId
){

  const normalizedStudentId =
    normalizeId(
      studentId
    );


  if (
    !normalizedStudentId
  ){

    return null;

  }


  return (
    getTeacherStudentRecords()
      .find(
        record =>
          sameId(
            record.id,
            normalizedStudentId
          )
      ) ||
    null
  );

}


/* =========================================================
   RAW STUDENT OBJECT
========================================================= */

function getTeacherStudentObject(
  value
){

  const record =
    normalizeTeacherStudentRecord(
      value
    );


  return (
    record?.student ||
    {}
  );

}


/* =========================================================
   STUDENT NAME
========================================================= */

function getTeacherStudentDisplayName(
  value
){

  const student =
    getTeacherStudentObject(
      value
    );


  return safeString(

    student.name ||
    student.fullName ||
    student.displayName,

    "Student"

  );

}


/* =========================================================
   STUDENT EMAIL
========================================================= */

function getTeacherStudentEmail(
  value
){

  const student =
    getTeacherStudentObject(
      value
    );


  return safeString(
    student.email
  );

}


/* =========================================================
   STUDENT COURSE / PROGRAM
========================================================= */

function getTeacherStudentCourse(
  value
){

  const student =
    getTeacherStudentObject(
      value
    );


  return safeString(

    student.course ||
    student.program ||
    student.department ||
    student.gradeLevel,

    ""

  );

}


/* =========================================================
   STUDENT AVATAR
========================================================= */

function getTeacherStudentAvatar(
  value
){

  const student =
    getTeacherStudentObject(
      value
    );


  return getSafeImageUrl(

    student.profileImage ||
    student.avatar ||
    student.photoURL ||
    student.image,

    FALLBACK_AVATAR

  );

}


/* =========================================================
   STUDENT INITIALS
========================================================= */

function getTeacherStudentInitials(
  value
){

  const name =
    getTeacherStudentDisplayName(
      value
    );


  const parts =
    name
      .split(
        /\s+/
      )
      .filter(
        Boolean
      )
      .slice(
        0,
        2
      );


  return (
    parts
      .map(
        part =>
          part.charAt(
            0
          )
            .toUpperCase()
      )
      .join(
        ""
      ) ||
    "S"
  );

}


/* =========================================================
   STUDENT CLASSES
========================================================= */

function getTeacherStudentClasses(
  value
){

  const record =
    normalizeTeacherStudentRecord(
      value
    );


  if (
    !record
  ){

    return [];

  }


  /*
    Prefer the normalized class membership built from
    assigned classes.
  */

  if (
    record.classes.length
  ){

    return record.classes;

  }


  /*
    Defensive recovery:
    derive membership from currently assigned classes if a
    record was supplied in flat form.
  */

  return getTeacherClasses()
    .filter(
      classItem =>
        asArray(
          classItem?.studentIds
        )
          .some(
            student =>
              sameId(
                student?._id ||
                student?.id ||
                student,
                record.id
              )
          )
    )
    .map(
      classItem => ({

        id:
          normalizeId(
            classItem?._id ||
            classItem?.id
          ),

        title:
          getTeacherClassTitle(
            classItem
          )

      })
    );

}


/* =========================================================
   STUDENT CLASS TITLES
========================================================= */

function getTeacherStudentClassTitles(
  value
){

  return getTeacherStudentClasses(
    value
  )
    .map(
      classItem =>
        safeString(

          classItem.title ||
          classItem.subject ||
          classItem.name,

          "Class"

        )
    )
    .filter(
      Boolean
    );

}


/* =========================================================
   STUDENT SUBMISSIONS
========================================================= */

function getTeacherStudentSubmissions(
  studentId
){

  const normalizedStudentId =
    normalizeId(
      studentId
    );


  if (
    !normalizedStudentId
  ){

    return [];

  }


  return getTeacherSubmissions()
    .filter(
      submission =>
        sameId(
          submission
            ?.studentId
            ?._id ||
          submission
            ?.studentId,
          normalizedStudentId
        )
    );

}


/* =========================================================
   STUDENT ATTENDANCE
========================================================= */

function getTeacherStudentAttendance(
  studentId
){

  const normalizedStudentId =
    normalizeId(
      studentId
    );


  if (
    !normalizedStudentId
  ){

    return [];

  }


  return getTeacherAttendance()
    .filter(
      record =>
        sameId(
          record
            ?.studentId
            ?._id ||
          record
            ?.studentId,
          normalizedStudentId
        )
    );

}


/* =========================================================
   STUDENT ATTENDANCE RATE
========================================================= */

function getTeacherStudentAttendanceRate(
  studentId
){

  const records =
    getTeacherStudentAttendance(
      studentId
    )
      .filter(
        record =>
          [
            "present",
            "late",
            "absent",
            "excused"
          ].includes(
            String(
              record?.status ||
              ""
            )
              .trim()
              .toLowerCase()
          )
      );


  if (
    !records.length
  ){

    return 0;

  }


  const attended =
    records
      .filter(
        record =>
          [
            "present",
            "late"
          ].includes(
            String(
              record?.status ||
              ""
            )
              .trim()
              .toLowerCase()
          )
      )
      .length;


  return clampPercentage(
    (
      attended /
      records.length
    ) *
    100
  );

}


/* =========================================================
   REVIEWED STUDENT SUBMISSIONS
========================================================= */

function getTeacherStudentReviewedSubmissions(
  studentId
){

  return getTeacherStudentSubmissions(
    studentId
  )
    .filter(
      submission =>
        [
          "reviewed",
          "graded",
          "returned"
        ].includes(
          normalizeSubmissionStatus(
            submission?.status
          )
        )
    );

}


/* =========================================================
   PENDING STUDENT SUBMISSIONS
========================================================= */

function getTeacherStudentPendingSubmissions(
  studentId
){

  return getTeacherStudentSubmissions(
    studentId
  )
    .filter(
      submission =>
        [
          "submitted",
          "pending"
        ].includes(
          normalizeSubmissionStatus(
            submission?.status
          )
        )
    );

}


/* =========================================================
   STUDENT ASSIGNMENTS

   A student is considered assigned work from every teacher
   class in which that student is enrolled.
========================================================= */

function getTeacherStudentAssignments(
  studentId
){

  const studentRecord =
    getTeacherStudentById(
      studentId
    );


  if (
    !studentRecord
  ){

    return [];

  }


  const classIds =
    new Set(
      getTeacherStudentClasses(
        studentRecord
      )
        .map(
          classItem =>
            normalizeId(
              classItem?._id ||
              classItem?.id
            )
        )
        .filter(
          Boolean
        )
    );


  return getTeacherAssignments()
    .filter(
      assignment => {

        const classId =
          normalizeId(
            assignment
              ?.classId
              ?._id ||
            assignment
              ?.classId
          );


        return (
          classId &&
          classIds.has(
            classId
          )
        );

      }
    );

}


/* =========================================================
   MISSING / OVERDUE ASSIGNMENTS

   We only mark an assignment missing when:
   - it belongs to one of the student's classes
   - no submission exists
   - it has a valid due date
   - that due date has passed

   An assignment with no deadline is NOT assumed missing.
========================================================= */

function getTeacherStudentMissingAssignments(
  studentId
){

  const assignments =
    getTeacherStudentAssignments(
      studentId
    );

  const submissions =
    getTeacherStudentSubmissions(
      studentId
    );


  const submittedAssignmentIds =
    new Set(
      submissions
        .map(
          submission =>
            normalizeId(
              submission
                ?.assignmentId
                ?._id ||
              submission
                ?.assignmentId
            )
        )
        .filter(
          Boolean
        )
    );


  return assignments.filter(
    assignment => {

      const assignmentId =
        normalizeId(
          assignment?._id ||
          assignment?.id
        );


      if (
        !assignmentId ||
        submittedAssignmentIds.has(
          assignmentId
        )
      ){

        return false;

      }


      const dueDate =
        toValidDate(
          assignment?.dueDate
        );


      if (
        !dueDate
      ){

        return false;

      }


      return (
        dueDate.getTime() <
        Date.now()
      );

    }
  );

}


/* =========================================================
   STUDENT REVIEW COMPLETION RATE
========================================================= */

function getTeacherStudentReviewRate(
  studentId
){

  const submissions =
    getTeacherStudentSubmissions(
      studentId
    );


  if (
    !submissions.length
  ){

    return 0;

  }


  const reviewed =
    getTeacherStudentReviewedSubmissions(
      studentId
    ).length;


  return clampPercentage(
    (
      reviewed /
      submissions.length
    ) *
    100
  );

}


/* =========================================================
   STUDENT NUMERIC GRADE AVERAGE
========================================================= */

function getTeacherStudentGradeAverage(
  studentId
){

  const graded =
    getTeacherStudentReviewedSubmissions(
      studentId
    )
      .filter(
        submission =>
          Number.isFinite(
            Number(
              submission?.grade
            )
          )
      );


  if (
    !graded.length
  ){

    return null;

  }


  const total =
    graded.reduce(
      (
        sum,
        submission
      ) =>
        sum +
        safeNumber(
          submission?.grade,
          0
        ),
      0
    );


  return clampPercentage(
    total /
    graded.length
  );

}


/* =========================================================
   STUDENT PROGRESS SCORE

   This is a dashboard indication, NOT a published grade.

   Priority:
   1. Reviewed grade average when available.
   2. Submission completion when assignments exist.
   3. Attendance when attendance data exists.
   4. Otherwise no measurable score.

   Kabezya is not used to invent this number.
========================================================= */

function getTeacherStudentProgressScore(
  studentId
){

  const gradeAverage =
    getTeacherStudentGradeAverage(
      studentId
    );


  if (
    gradeAverage !==
    null
  ){

    return gradeAverage;

  }


  const assignments =
    getTeacherStudentAssignments(
      studentId
    );

  const submissions =
    getTeacherStudentSubmissions(
      studentId
    );


  if (
    assignments.length
  ){

    const submittedAssignmentIds =
      new Set(
        submissions
          .map(
            submission =>
              normalizeId(
                submission
                  ?.assignmentId
                  ?._id ||
                submission
                  ?.assignmentId
              )
          )
          .filter(
            Boolean
          )
      );


    return clampPercentage(
      (
        submittedAssignmentIds.size /
        assignments.length
      ) *
      100
    );

  }


  const attendanceRecords =
    getTeacherStudentAttendance(
      studentId
    );


  if (
    attendanceRecords.length
  ){

    return getTeacherStudentAttendanceRate(
      studentId
    );

  }


  return null;

}


/* =========================================================
   PROGRESS CATEGORY

   These categories correspond to teacher.html options:

   excellent
   good
   needs-attention
========================================================= */

function getTeacherStudentProgressCategory(
  studentId
){

  const missing =
    getTeacherStudentMissingAssignments(
      studentId
    ).length;

  const attendanceRecords =
    getTeacherStudentAttendance(
      studentId
    );

  const attendanceRate =
    getTeacherStudentAttendanceRate(
      studentId
    );

  const score =
    getTeacherStudentProgressScore(
      studentId
    );


  /*
    Strong warning signals take priority.
  */

  if (
    missing >=
      2 ||
    (
      attendanceRecords.length &&
      attendanceRate <
        60
    ) ||
    (
      score !==
        null &&
      score <
        60
    )
  ){

    return "needs-attention";

  }


  if (
    score !==
      null &&
    score >=
      85 &&
    (
      !attendanceRecords.length ||
      attendanceRate >=
        80
    ) &&
    missing ===
      0
  ){

    return "excellent";

  }


  return "good";

}


/* =========================================================
   STUDENT STATUS LABEL
========================================================= */

function getTeacherStudentProgressLabel(
  studentId
){

  switch(
    getTeacherStudentProgressCategory(
      studentId
    )
  ){

    case "excellent":

      return "Excellent";

    case "needs-attention":

      return "Needs attention";

    default:

      return "Good";

  }

}


/* =========================================================
   STUDENT CARD STATUS CLASS

   Existing CSS defines active/inactive.

   We retain those classes instead of inventing new badge CSS.
========================================================= */

function getTeacherStudentStatusClass(
  studentId
){

  return (
    getTeacherStudentProgressCategory(
      studentId
    ) ===
    "needs-attention"
      ? "inactive"
      : "active"
  );

}


/* =========================================================
   PROGRESS BAR CLASS

   Existing CSS:
     good
     warning
     danger
========================================================= */

function getTeacherStudentProgressBarClass(
  score
){

  if (
    score ===
    null
  ){

    return "";

  }


  if (
    score >=
    80
  ){

    return "good";

  }


  if (
    score >=
    60
  ){

    return "warning";

  }


  return "danger";

}


/* =========================================================
   STUDENT LATEST ACTIVITY
========================================================= */

function getTeacherStudentLatestActivity(
  studentId
){

  return (
    sortNewestFirst(
      getTeacherStudentSubmissions(
        studentId
      ),
      [
        "submittedAt",
        "reviewedAt",
        "updatedAt",
        "createdAt"
      ]
    )[0] ||
    null
  );

}


/* =========================================================
   FILTER STUDENTS
========================================================= */

function getFilteredTeacherStudents(){

  const search =
    safeString(
      teacherStudentWorkspaceState
        .search
    )
      .toLowerCase();

  const classId =
    normalizeId(
      teacherStudentWorkspaceState
        .classId
    );

  const progress =
    safeString(
      teacherStudentWorkspaceState
        .progress
    )
      .toLowerCase();


  let students = [
    ...getTeacherStudentRecords()
  ];


  /* -------------------------------------------------------
     SEARCH
  ------------------------------------------------------- */

  if (
    search
  ){

    students =
      students.filter(
        record => {

          const haystack =
            [

              getTeacherStudentDisplayName(
                record
              ),

              getTeacherStudentEmail(
                record
              ),

              getTeacherStudentCourse(
                record
              ),

              ...getTeacherStudentClassTitles(
                record
              )

            ]
              .filter(
                Boolean
              )
              .join(
                " "
              )
              .toLowerCase();


          return haystack.includes(
            search
          );

        }
      );

  }


  /* -------------------------------------------------------
     CLASS
  ------------------------------------------------------- */

  if (
    classId
  ){

    students =
      students.filter(
        record =>
          getTeacherStudentClasses(
            record
          )
            .some(
              classItem =>
                sameId(
                  classItem?._id ||
                  classItem?.id,
                  classId
                )
            )
      );

  }


  /* -------------------------------------------------------
     PROGRESS
  ------------------------------------------------------- */

  if (
    progress
  ){

    students =
      students.filter(
        record =>
          getTeacherStudentProgressCategory(
            record.id
          ) ===
          progress
      );

  }


  /* -------------------------------------------------------
     CURRENT HTML DOES NOT HAVE A SORT CONTROL.

     Stable alphabetical ordering keeps the current design
     unchanged.
  ------------------------------------------------------- */

  students.sort(
    (
      first,
      second
    ) =>
      getTeacherStudentDisplayName(
        first
      )
        .localeCompare(
          getTeacherStudentDisplayName(
            second
          )
        )
  );


  return students;

}


/* =========================================================
   HYDRATE STUDENT CLASS FILTER
========================================================= */

function renderTeacherStudentClassFilter(){

  const select =
    $(
      "teacherStudentClassFilter"
    );


  if (
    !select
  ){

    return;

  }


  const selectedValue =
    teacherStudentWorkspaceState
      .classId;


  select.innerHTML = `
    <option value="">
      All classes
    </option>

    ${
      getTeacherClasses()
        .map(
          classItem => {

            const classId =
              normalizeId(
                classItem?._id ||
                classItem?.id
              );


            return `
              <option
                value="${escapeAttribute(classId)}"
              >
                ${escapeHtml(
                  getTeacherClassTitle(
                    classItem
                  )
                )}
              </option>
            `;

          }
        )
        .join(
          ""
        )
    }
  `;


  select.value =
    selectedValue;


  if (
    select.value !==
    selectedValue
  ){

    teacherStudentWorkspaceState
      .classId =
      "";

    select.value =
      "";

  }

}


/* =========================================================
   HYDRATE PROGRESS FILTER

   Options already exist in teacher.html.
   Only its selected value is synchronized.
========================================================= */

function renderTeacherStudentProgressFilter(){

  const select =
    $(
      "teacherStudentProgressFilter"
    );


  if (
    !select
  ){

    return;

  }


  select.value =
    teacherStudentWorkspaceState
      .progress;


  if (
    select.value !==
    teacherStudentWorkspaceState
      .progress
  ){

    teacherStudentWorkspaceState
      .progress =
      "";

    select.value =
      "";

  }

}


/* =========================================================
   STUDENT COUNT
========================================================= */

function renderTeacherStudentsCount(){

  const allStudents =
    getTeacherStudentRecords();

  const filteredStudents =
    getFilteredTeacherStudents();

  const hasFilters =
    Boolean(

      teacherStudentWorkspaceState
        .search ||

      teacherStudentWorkspaceState
        .classId ||

      teacherStudentWorkspaceState
        .progress

    );


  if (
    hasFilters
  ){

    setText(
      "teacherStudentsCount",
      `${filteredStudents.length} of ${allStudents.length} ${
        allStudents.length === 1
          ? "student"
          : "students"
      }`
    );


    return;

  }


  setText(
    "teacherStudentsCount",
    `${allStudents.length} ${
      allStudents.length === 1
        ? "student"
        : "students"
    }`
  );

}


/* =========================================================
   STUDENT EMPTY STATE
========================================================= */

function renderTeacherStudentsEmptyState(
  students
){

  const empty =
    $(
      "teacherStudentsEmpty"
    );


  if (
    !empty
  ){

    return;

  }


  const hasStudents =
    getTeacherStudentRecords()
      .length >
    0;

  const hasResults =
    asArray(
      students
    ).length >
    0;

  const hasFilters =
    Boolean(

      teacherStudentWorkspaceState
        .search ||

      teacherStudentWorkspaceState
        .classId ||

      teacherStudentWorkspaceState
        .progress

    );


  empty.hidden =
    hasResults;


  if (
    hasResults
  ){

    return;

  }


  const heading =
    empty.querySelector(
      "h2"
    );

  const description =
    empty.querySelector(
      "p"
    );

  const clearButton =
    empty.querySelector(
      '[data-teacher-action="clear-student-filters"]'
    );


  if (
    !hasStudents
  ){

    if (
      heading
    ){

      heading.textContent =
        "No students assigned yet";

    }


    if (
      description
    ){

      description.textContent =
        "Students enrolled in your assigned classes will appear here.";

    }


    if (
      clearButton
    ){

      clearButton.hidden =
        true;

    }


    return;

  }


  if (
    hasFilters
  ){

    if (
      heading
    ){

      heading.textContent =
        "No students found";

    }


    if (
      description
    ){

      description.textContent =
        "No students match the selected filters.";

    }


    if (
      clearButton
    ){

      clearButton.hidden =
        false;

    }

  }

}


/* =========================================================
   STUDENT PRIMARY CLASS LABEL
========================================================= */

function getTeacherStudentPrimaryClassLabel(
  record
){

  const titles =
    getTeacherStudentClassTitles(
      record
    );


  if (
    !titles.length
  ){

    return "No assigned class";

  }


  if (
    titles.length ===
    1
  ){

    return titles[0];

  }


  return `${titles[0]} +${titles.length - 1}`;

}


/* =========================================================
   STUDENT CARD
========================================================= */

function createTeacherStudentCard(
  record
){

  const studentId =
    record.id;

  const name =
    getTeacherStudentDisplayName(
      record
    );

  const email =
    getTeacherStudentEmail(
      record
    );

  const avatar =
    getTeacherStudentAvatar(
      record
    );

  const initials =
    getTeacherStudentInitials(
      record
    );

  const classLabel =
    getTeacherStudentPrimaryClassLabel(
      record
    );

  const progressScore =
    getTeacherStudentProgressScore(
      studentId
    );

  const progressCategory =
    getTeacherStudentProgressCategory(
      studentId
    );

  const progressLabel =
    getTeacherStudentProgressLabel(
      studentId
    );

  const progressClass =
    getTeacherStudentProgressBarClass(
      progressScore
    );

  const statusClass =
    getTeacherStudentStatusClass(
      studentId
    );

  const submissions =
    getTeacherStudentSubmissions(
      studentId
    ).length;

  const pending =
    getTeacherStudentPendingSubmissions(
      studentId
    ).length;

  const missing =
    getTeacherStudentMissingAssignments(
      studentId
    ).length;

  const attendanceRecords =
    getTeacherStudentAttendance(
      studentId
    );

  const attendanceRate =
    getTeacherStudentAttendanceRate(
      studentId
    );

  const latestActivity =
    getTeacherStudentLatestActivity(
      studentId
    );


  return `
    <article
      class="teacher-student-card"
      data-student-id="${escapeAttribute(studentId)}"
    >

      <!-- ===============================================
           STUDENT HEADER
      ================================================ -->

      <div
        class="teacher-student-card-top"
      >

        <div
          class="teacher-student-avatar"
          aria-hidden="true"
        >
          <span>
            ${escapeHtml(initials)}
          </span>

          <img
            src="${escapeAttribute(avatar)}"
            alt=""
            loading="lazy"
            referrerpolicy="no-referrer"
          />
        </div>


        <div
          class="teacher-student-info"
        >

          <h3
            class="teacher-student-name"
            title="${escapeAttribute(name)}"
          >
            ${escapeHtml(name)}
          </h3>

          <p
            class="teacher-student-email"
            title="${escapeAttribute(email)}"
          >
            ${escapeHtml(
              email ||
              "No email available"
            )}
          </p>

        </div>


        <span
          class="teacher-student-status ${escapeAttribute(statusClass)}"
          title="${escapeAttribute(progressLabel)}"
        >
          ${escapeHtml(progressLabel)}
        </span>

      </div>


      <!-- ===============================================
           CLASS
      ================================================ -->

      <div
        class="teacher-student-class"
        title="${escapeAttribute(
          getTeacherStudentClassTitles(
            record
          ).join(", ")
        )}"
      >
        <i
          class="fa-solid fa-chalkboard-user"
          aria-hidden="true"
        ></i>

        <span>
          ${escapeHtml(classLabel)}
        </span>
      </div>


      <!-- ===============================================
           PROGRESS
      ================================================ -->

      <div
        class="teacher-student-progress"
      >

        <div
          class="teacher-student-progress-header"
        >
          <span>
            Learning progress
          </span>

          <strong>
            ${
              progressScore ===
              null
                ? "—"
                : `${progressScore}%`
            }
          </strong>
        </div>


        <div
          class="teacher-student-progress-track"
          ${
            progressScore !==
            null
              ? `
                role="progressbar"
                aria-valuemin="0"
                aria-valuemax="100"
                aria-valuenow="${progressScore}"
              `
              : ""
          }
        >
          <div
            class="teacher-student-progress-fill ${escapeAttribute(progressClass)}"
            style="width:${
              progressScore ===
              null
                ? 0
                : progressScore
            }%"
          ></div>
        </div>

      </div>


      <!-- ===============================================
           ACTIVITY METRICS
      ================================================ -->

      <div
        class="teacher-student-activity"
      >

        <div
          class="teacher-student-activity-item"
        >
          <strong>
            ${submissions}
          </strong>

          <span>
            Submitted
          </span>
        </div>


        <div
          class="teacher-student-activity-item"
        >
          <strong>
            ${pending}
          </strong>

          <span>
            To review
          </span>
        </div>


        <div
          class="teacher-student-activity-item"
        >
          <strong>
            ${
              attendanceRecords.length
                ? `${attendanceRate}%`
                : "—"
            }
          </strong>

          <span>
            Attendance
          </span>
        </div>

      </div>


      <!-- ===============================================
           SECONDARY CONTEXT
      ================================================ -->

      <div
        class="teacher-student-card-context"
      >

        ${
          missing
            ? `
              <span
                class="teacher-student-context-warning"
              >
                <i
                  class="fa-solid fa-triangle-exclamation"
                  aria-hidden="true"
                ></i>

                ${missing}
                ${
                  missing === 1
                    ? "overdue assignment"
                    : "overdue assignments"
                }
              </span>
            `
            : `
              <span>
                ${
                  latestActivity
                    ? `Last activity ${escapeHtml(
                        formatRelativeDate(
                          latestActivity.submittedAt ||
                          latestActivity.updatedAt ||
                          latestActivity.createdAt
                        )
                      )}`
                    : "No recent submission activity"
                }
              </span>
            `
        }

      </div>


      <!-- ===============================================
           ACTIONS

           The authoritative Studio action controller will
           bind these in one location later.
      ================================================ -->

      <div
        class="teacher-student-card-actions"
      >

        <button
          type="button"
          class="teacher-secondary-button"
          data-teacher-action="student-work"
          data-student-id="${escapeAttribute(studentId)}"
        >
          <i
            class="fa-regular fa-file-lines"
            aria-hidden="true"
          ></i>

          <span>
            Student Work
          </span>
        </button>


        <button
          type="button"
          class="teacher-primary-button"
          data-teacher-action="open-student"
          data-student-id="${escapeAttribute(studentId)}"
        >
          <span>
            View Student
          </span>

          <i
            class="fa-solid fa-arrow-right"
            aria-hidden="true"
          ></i>
        </button>

      </div>

    </article>
  `;

}


/* =========================================================
   STUDENT IMAGE FALLBACKS
========================================================= */

function bindTeacherStudentImageFallbacks(){

  const grid =
    $(
      "teacherStudentsGrid"
    );


  if (
    !grid
  ){

    return;

  }


  grid
    .querySelectorAll(
      ".teacher-student-avatar img"
    )
    .forEach(
      image => {

        image.onerror =
          () => {

            /*
              Hide the failed image rather than loading another
              broken asset. The initials beneath remain visible.
            */

            image.onerror =
              null;

            image.hidden =
              true;

          };

      }
    );

}


/* =========================================================
   RENDER STUDENT GRID
========================================================= */

function renderTeacherStudentsGrid(){

  const grid =
    $(
      "teacherStudentsGrid"
    );


  if (
    !grid
  ){

    return;

  }


  const students =
    getFilteredTeacherStudents();


  renderTeacherStudentsCount();

  renderTeacherStudentsEmptyState(
    students
  );


  if (
    !students.length
  ){

    grid.innerHTML =
      "";

    grid.hidden =
      true;

    return;

  }


  grid.hidden =
    false;


  grid.innerHTML =
    students
      .map(
        createTeacherStudentCard
      )
      .join(
        ""
      );


  bindTeacherStudentImageFallbacks();

}


