/* =========================================================
   REFRESH ASSIGNMENTS
========================================================= */

async function refreshTeacherAssignmentsWorkspace(){

  if (
    teacherAssignmentWorkspaceState
      .refreshing
  ){

    return false;

  }


  teacherAssignmentWorkspaceState
    .refreshing =
    true;


  const buttons =
    $all(
      '[data-teacher-action="refresh-assignments"]'
    );


  buttons.forEach(
    button => {

      button.disabled =
        true;

      button.setAttribute(
        "aria-busy",
        "true"
      );

    }
  );


  try{

    const results =
      await Promise.allSettled([

        loadTeacherAssignments(),

        loadTeacherSubmissions()

      ]);


    results.forEach(
      (
        result,
        index
      ) => {

        if (
          result.status ===
          "rejected"
        ){

          reportOptionalRequestError(
            [
              "Assignments",
              "Submissions"
            ][index],
            result.reason
          );

        }

      }
    );


    finalizeTeacherLoadedData();


    renderTeacherAssignmentsWorkspace();

    renderTeacherOverviewAssignments();

    renderTeacherDashboardStats();


    notifyAIFTSuccess(
      "Assignments are up to date.",
      {
        title:
          "Assignments refreshed"
      }
    );


    return true;

  }catch(
    error
  ){

    notifyAIFTError(
      getErrorMessage(
        error,
        "Assignments could not be refreshed."
      ),
      {
        title:
          "Refresh failed"
      }
    );


    return false;

  }finally{

    teacherAssignmentWorkspaceState
      .refreshing =
      false;


    buttons.forEach(
      button => {

        button.disabled =
          false;

        button.setAttribute(
          "aria-busy",
          "false"
        );

      }
    );

  }

}


/* =========================================================
   INITIALIZE ASSIGNMENTS WORKSPACE
========================================================= */

function initializeTeacherAssignmentsWorkspace(){

  if (
    teacherAssignmentWorkspaceState
      .initialized
  ){

    renderTeacherAssignmentsWorkspace();

    return;

  }


  teacherAssignmentWorkspaceState
    .initialized =
    true;


  const search =
    $(
      "teacherAssignmentSearch"
    );

  const classFilter =
    $(
      "teacherAssignmentClassFilter"
    );

  const statusFilter =
    $(
      "teacherAssignmentStatusFilter"
    );


  if (
    search
  ){

    search.oninput =
      handleTeacherAssignmentSearchInput;

  }


  if (
    classFilter
  ){

    classFilter.onchange =
      handleTeacherAssignmentClassChange;

  }


  if (
    statusFilter
  ){

    statusFilter.onchange =
      handleTeacherAssignmentStatusChange;

  }


  renderTeacherAssignmentsWorkspace();

}


/* =========================================================
   ASSIGNMENT EDITOR / CRUD
   DEVICE FILE UPLOAD ENABLED
========================================================= */


/* =========================================================
   ASSIGNMENT FILE CONFIG
========================================================= */

const TEACHER_ASSIGNMENT_FILE_LIMIT =
  100 * 1024 * 1024;


const TEACHER_ASSIGNMENT_ALLOWED_EXTENSIONS =
  new Set([
    "jpg",
    "jpeg",
    "png",
    "gif",
    "webp",

    "mp4",
    "webm",
    "mov",
    "m4v",

    "mp3",
    "wav",
    "m4a",
    "ogg",

    "pdf",

    "doc",
    "docx",

    "ppt",
    "pptx",

    "xls",
    "xlsx",

    "csv",
    "txt",
    "rtf",

    "zip"
  ]);


/* =========================================================
   FILE EXTENSION
========================================================= */

function getTeacherAssignmentFileExtension(
  fileName
){

  const value =
    safeString(
      fileName
    )
      .toLowerCase();


  if (
    !value.includes(
      "."
    )
  ){

    return "";

  }


  return value
    .split(
      "."
    )
    .pop()
    .trim();

}


/* =========================================================
   VALIDATE ASSIGNMENT FILE
========================================================= */

function validateTeacherAssignmentFile(
  file
){

  if (
    !file
  ){

    return true;

  }


  if (
    file.size >
    TEACHER_ASSIGNMENT_FILE_LIMIT
  ){

    throw new AIFTApiError(
      "The attachment is too large. The maximum file size is 100 MB.",
      {
        code:
          "ASSIGNMENT_FILE_TOO_LARGE"
      }
    );

  }


  const extension =
    getTeacherAssignmentFileExtension(
      file.name
    );


  if (
    !TEACHER_ASSIGNMENT_ALLOWED_EXTENSIONS
      .has(
        extension
      )
  ){

    throw new AIFTApiError(
      "This file type is not supported for assignments.",
      {
        code:
          "ASSIGNMENT_FILE_TYPE_NOT_SUPPORTED"
      }
    );

  }


  return true;

}


/* =========================================================
   HUMAN FILE SIZE
========================================================= */

function formatTeacherAssignmentFileSize(
  bytes
){

  const size =
    Number(
      bytes
    ) ||
    0;


  if (
    size <
    1024
  ){

    return `${size} B`;

  }


  if (
    size <
    1024 * 1024
  ){

    return `${
      (
        size /
        1024
      ).toFixed(
        1
      )
    } KB`;

  }


  return `${
    (
      size /
      (
        1024 *
        1024
      )
    ).toFixed(
      1
    )
  } MB`;

}


/* =========================================================
   ASSIGNMENT ATTACHMENT NAME
========================================================= */

function getTeacherAssignmentAttachmentName(
  assignment
){

  const url =
    safeString(
      assignment?.attachmentUrl
    );


  if (
    !url
  ){

    return "";

  }


  try{

    const pathname =
      new URL(
        url
      )
        .pathname;


    return decodeURIComponent(
      pathname
        .split(
          "/"
        )
        .filter(
          Boolean
        )
        .pop() ||
      "Current attachment"
    );

  }catch{

    return "Current attachment";

  }

}


/* =========================================================
   OPEN ASSIGNMENT EDITOR
========================================================= */

function openTeacherAssignmentEditor(
  assignmentId =
    ""
){

  const normalizedId =
    normalizeId(
      assignmentId
    );


  const assignment =
    normalizedId
      ? getTeacherAssignments()
          .find(
            item =>
              sameId(
                item?._id ||
                item?.id,
                normalizedId
              )
          ) ||
        null
      : null;


  if (
    normalizedId &&
    !assignment
  ){

    notifyAIFTError(
      "The selected assignment is no longer available.",
      {
        title:
          "Assignment unavailable"
      }
    );


    return false;

  }


  renderTeacherAssignmentEditor(
    assignment
  );


  window.requestAnimationFrame(
    () => {

      $(
        "teacherAssignmentEditor"
      )
        ?.scrollIntoView({
          behavior:
            "smooth",

          block:
            "start"
        });

    }
  );


  return true;

}


/* =========================================================
   RENDER ASSIGNMENT EDITOR
========================================================= */

function renderTeacherAssignmentEditor(
  assignment =
    null
){

  const container =
    $(
      "teacherAssignmentEditor"
    );


  if (
    !container
  ){

    throw new Error(
      "teacherAssignmentEditor host is missing from teacher.html."
    );

  }


  const editing =
    Boolean(
      assignment
    );


  const assignmentId =
    normalizeId(
      assignment?._id ||
      assignment?.id
    );


  const classes =
    getTeacherClasses();


  const selectedClassId =
    normalizeId(

      assignment
        ?.classId
        ?._id ||

      assignment
        ?.classId ||

      teacherAssignmentWorkspaceState
        .classId ||

      state.selectedClassId

    );


  const rawStatus =
    normalizeAssignmentStatus(
      assignment?.status ||
      "draft"
    );


  const status =
    rawStatus ===
      "active"
      ? "published"
      : rawStatus;


const dueDate =
  getTeacherAssignmentDueDate(
    assignment
  );


const dueInputValue =
  dueDate
    ? String(
        dueDate
      )
        .slice(
          0,
          10
        )
    : "";


  const attachmentUrl =
    safeString(
      assignment?.attachmentUrl
    );


  const attachmentName =
    getTeacherAssignmentAttachmentName(
      assignment
    );


  teacherAssignmentWorkspaceState
    .editingAssignmentId =
    assignmentId ||
    "";


  container.hidden =
    false;


  container.innerHTML = `
    <section
      class="teacher-assignment-editor-panel"
    >

      <header
        class="teacher-assignment-editor-header"
      >

        <div>

          <span>
            ${
              editing
                ? "Edit assignment"
                : "New assignment"
            }
          </span>

          <h2>
            ${
              editing
                ? escapeHtml(
                    getTeacherAssignmentTitle(
                      assignment
                    )
                  )
                : "Create assignment"
            }
          </h2>

        </div>


        <button
          type="button"
          class="teacher-icon-button"
          data-teacher-action="close-assignment-editor"
          aria-label="Close assignment editor"
        >

          <i
            class="fa-solid fa-xmark"
            aria-hidden="true"
          ></i>

        </button>

      </header>


      <form
        id="teacherAssignmentForm"
        class="teacher-assignment-form"
        enctype="multipart/form-data"
      >

        <input
          type="hidden"
          id="teacherAssignmentId"
          value="${escapeAttribute(
            assignmentId
          )}"
        />


        <!-- ===============================================
             CLASS
        ================================================ -->

        <label
          class="teacher-form-field"
        >

          <span>
            Class
          </span>


          <select
            id="teacherAssignmentClassId"
            required
          >

            <option value="">
              Select class
            </option>

            ${
              classes
                .map(
                  classItem => {

                    const classId =
                      normalizeId(
                        classItem?._id ||
                        classItem?.id
                      );


                    return `
                      <option
                        value="${escapeAttribute(
                          classId
                        )}"
                        ${
                          sameId(
                            classId,
                            selectedClassId
                          )
                            ? "selected"
                            : ""
                        }
                      >
                        ${escapeHtml(
                          getTeacherClassTitle(
                            classItem
                          )
                        )}
                      </option>
                    `;

                  }
                )
                .join(
                  ""
                )
            }

          </select>

        </label>


        <!-- ===============================================
             TITLE
        ================================================ -->

        <label
          class="teacher-form-field"
        >

          <span>
            Assignment title
          </span>


          <input
            id="teacherAssignmentTitle"
            type="text"
            maxlength="160"
            required
            autocomplete="off"
            placeholder="Enter assignment title"
            value="${escapeAttribute(
              assignment?.title ||
              ""
            )}"
          />

        </label>


        <!-- ===============================================
             INSTRUCTIONS
        ================================================ -->

        <label
          class="teacher-form-field"
        >

          <span>
            Instructions
          </span>


          <textarea
            id="teacherAssignmentInstructions"
            rows="8"
            maxlength="12000"
            placeholder="Explain what students need to complete..."
          >${escapeHtml(
            assignment?.instructions ||
            assignment?.description ||
            ""
          )}</textarea>

        </label>


        <!-- ===============================================
             DATE + STATUS
        ================================================ -->

        <div
          class="teacher-form-grid"
        >

          <label
            class="teacher-form-field"
          >

            <span>
              Due date
            </span>


<input
  id="teacherAssignmentDueDate"
  type="date"
  value="${escapeAttribute(
    dueInputValue
  )}"
/>

          </label>


          <label
            class="teacher-form-field"
          >

            <span>
              Status
            </span>


            <select
              id="teacherAssignmentStatus"
            >

              <option
                value="draft"
                ${
                  status ===
                  "draft"
                    ? "selected"
                    : ""
                }
              >
                Draft
              </option>


              <option
                value="published"
                ${
                  status ===
                  "published"
                    ? "selected"
                    : ""
                }
              >
                Published
              </option>


              <option
                value="closed"
                ${
                  status ===
                  "closed"
                    ? "selected"
                    : ""
                }
              >
                Closed
              </option>

            </select>

          </label>

        </div>


        <!-- ===============================================
             DEVICE ATTACHMENT
        ================================================ -->

        <div
          class="teacher-form-field"
        >

          <span>
            Assignment attachment
          </span>


          <div
            class="teacher-assignment-file-upload"
          >

            <input
              id="teacherAssignmentAttachment"
              type="file"
              hidden
              accept="
                image/*,
                video/*,
                audio/*,
                application/pdf,
                .doc,
                .docx,
                .ppt,
                .pptx,
                .xls,
                .xlsx,
                .csv,
                .txt,
                .rtf,
                .zip
              "
            />


            <button
              id="teacherAssignmentChooseFile"
              type="button"
              class="teacher-assignment-file-picker"
            >

              <span
                class="teacher-assignment-file-picker-icon"
              >
                <i
                  class="fa-solid fa-cloud-arrow-up"
                  aria-hidden="true"
                ></i>
              </span>


              <span
                class="teacher-assignment-file-picker-copy"
              >

                <strong>
                  Choose a file from your device
                </strong>

                <small>
                  Photos, video, audio, PDF, Word, PowerPoint,
                  Excel, text or ZIP · maximum 100 MB
                </small>

              </span>

            </button>


            <div
              id="teacherAssignmentSelectedFile"
              class="teacher-assignment-selected-file"
              hidden
            ></div>


            ${
              attachmentUrl
                ? `
                  <div
                    id="teacherAssignmentExistingAttachment"
                    class="teacher-assignment-existing-file"
                  >

                    <span
                      class="teacher-assignment-existing-file-icon"
                    >
                      <i
                        class="fa-solid fa-paperclip"
                        aria-hidden="true"
                      ></i>
                    </span>


                    <span
                      class="teacher-assignment-existing-file-copy"
                    >

                      <strong>
                        ${escapeHtml(
                          attachmentName ||
                          "Current attachment"
                        )}
                      </strong>

                      <small>
                        Existing assignment attachment
                      </small>

                    </span>


                    <a
                      href="${escapeAttribute(
                        attachmentUrl
                      )}"
                      target="_blank"
                      rel="noopener noreferrer"
                      class="teacher-icon-button"
                      aria-label="Open current attachment"
                    >
                      <i
                        class="fa-solid fa-up-right-from-square"
                        aria-hidden="true"
                      ></i>
                    </a>


                    <button
                      type="button"
                      id="teacherAssignmentRemoveExistingFile"
                      class="teacher-icon-button"
                      aria-label="Remove current attachment"
                    >
                      <i
                        class="fa-regular fa-trash-can"
                        aria-hidden="true"
                      ></i>
                    </button>

                  </div>


                  <input
                    id="teacherAssignmentRemoveAttachment"
                    type="hidden"
                    value="false"
                  />
                `
                : `
                  <input
                    id="teacherAssignmentRemoveAttachment"
                    type="hidden"
                    value="false"
                  />
                `
            }

          </div>

        </div>


        <!-- ===============================================
             ACTIONS
        ================================================ -->

        <div
          class="teacher-assignment-editor-actions"
        >

          ${
            editing
              ? `
                <button
                  type="button"
                  class="
                    teacher-secondary-button
                    teacher-assignment-editor-delete
                  "
                  data-teacher-action="delete-assignment"
                  data-assignment-id="${escapeAttribute(
                    assignmentId
                  )}"
                >

                  <i
                    class="fa-regular fa-trash-can"
                    aria-hidden="true"
                  ></i>

                  Delete

                </button>
              `
              : ""
          }


          <button
            type="button"
            class="teacher-secondary-button"
            data-teacher-action="close-assignment-editor"
          >
            Cancel
          </button>


          <button
            type="submit"
            class="teacher-primary-button"
            id="teacherAssignmentSaveButton"
          >

            <i
              class="fa-solid fa-floppy-disk"
              aria-hidden="true"
            ></i>

            <span>
              ${
                editing
                  ? "Save Changes"
                  : "Create Assignment"
              }
            </span>

          </button>

        </div>

      </form>

    </section>
  `;


  bindTeacherAssignmentEditorControls();


  return true;

}


/* =========================================================
   ASSIGNMENT EDITOR CONTROLS
========================================================= */

function bindTeacherAssignmentEditorControls(){

  const form =
    $(
      "teacherAssignmentForm"
    );


  const fileInput =
    $(
      "teacherAssignmentAttachment"
    );


  const chooseButton =
    $(
      "teacherAssignmentChooseFile"
    );


  const removeExistingButton =
    $(
      "teacherAssignmentRemoveExistingFile"
    );


  chooseButton?.addEventListener(
    "click",
    () => {

      fileInput?.click();

    }
  );


  fileInput?.addEventListener(
    "change",
    () => {

      renderTeacherAssignmentSelectedFile();

    }
  );


  removeExistingButton?.addEventListener(
    "click",
    () => {

      const removeField =
        $(
          "teacherAssignmentRemoveAttachment"
        );


      const existing =
        $(
          "teacherAssignmentExistingAttachment"
        );


      if (
        removeField
      ){

        removeField.value =
          "true";

      }


      if (
        existing
      ){

        existing.hidden =
          true;

      }

    }
  );


  form?.addEventListener(
    "submit",
    event => {

      event.preventDefault();

      saveTeacherAssignment();

    }
  );

}


/* =========================================================
   SELECTED FILE PREVIEW
========================================================= */

function renderTeacherAssignmentSelectedFile(){

  const input =
    $(
      "teacherAssignmentAttachment"
    );


  const container =
    $(
      "teacherAssignmentSelectedFile"
    );


  if (
    !container
  ){

    return;

  }


  const file =
    input?.files?.[0] ||
    null;


  if (
    !file
  ){

    container.hidden =
      true;

    container.innerHTML =
      "";

    return;

  }


  try{

    validateTeacherAssignmentFile(
      file
    );

  }catch(
    error
  ){

    if (
      input
    ){

      input.value =
        "";

    }


    container.hidden =
      true;

    container.innerHTML =
      "";


    notifyAIFTError(
      getErrorMessage(
        error,
        "This file cannot be attached."
      ),
      {
        title:
          "Attachment not accepted"
      }
    );


    return;

  }


  const extension =
    getTeacherAssignmentFileExtension(
      file.name
    );


  let icon =
    "fa-solid fa-file";


  if (
    file.type.startsWith(
      "image/"
    )
  ){

    icon =
      "fa-solid fa-image";

  }else if (
    file.type.startsWith(
      "video/"
    )
  ){

    icon =
      "fa-solid fa-circle-play";

  }else if (
    file.type.startsWith(
      "audio/"
    )
  ){

    icon =
      "fa-solid fa-headphones";

  }else if (
    extension ===
    "pdf"
  ){

    icon =
      "fa-solid fa-file-pdf";

  }else if (
    [
      "doc",
      "docx",
      "rtf",
      "txt"
    ].includes(
      extension
    )
  ){

    icon =
      "fa-solid fa-file-lines";

  }else if (
    [
      "xls",
      "xlsx",
      "csv"
    ].includes(
      extension
    )
  ){

    icon =
      "fa-solid fa-file-excel";

  }else if (
    [
      "ppt",
      "pptx"
    ].includes(
      extension
    )
  ){

    icon =
      "fa-solid fa-file-powerpoint";

  }


  container.hidden =
    false;


  container.innerHTML = `
    <span
      class="teacher-assignment-selected-file-icon"
    >
      <i
        class="${escapeAttribute(
          icon
        )}"
        aria-hidden="true"
      ></i>
    </span>


    <span
      class="teacher-assignment-selected-file-copy"
    >
      <strong>
        ${escapeHtml(
          file.name
        )}
      </strong>

      <small>
        ${escapeHtml(
          formatTeacherAssignmentFileSize(
            file.size
          )
        )}
      </small>
    </span>


    <button
      type="button"
      id="teacherAssignmentClearSelectedFile"
      class="teacher-icon-button"
      aria-label="Remove selected file"
    >
      <i
        class="fa-solid fa-xmark"
        aria-hidden="true"
      ></i>
    </button>
  `;


  $(
    "teacherAssignmentClearSelectedFile"
  )
    ?.addEventListener(
      "click",
      () => {

        if (
          input
        ){

          input.value =
            "";

        }


        renderTeacherAssignmentSelectedFile();

      }
    );

}


/* =========================================================
   CLOSE ASSIGNMENT EDITOR
========================================================= */

function closeTeacherAssignmentEditor(){

  teacherAssignmentWorkspaceState
    .editingAssignmentId =
    "";


  teacherAssignmentWorkspaceState
    .saving =
    false;


  const container =
    $(
      "teacherAssignmentEditor"
    );


  if (
    container
  ){

    container.hidden =
      true;

    container.innerHTML =
      "";

  }


  return true;

}


/* =========================================================
   BUILD ASSIGNMENT FORM DATA
========================================================= */

function buildTeacherAssignmentFormData(){

  const classId =
    normalizeId(
      $(
        "teacherAssignmentClassId"
      )?.value
    );


  const title =
    safeString(
      $(
        "teacherAssignmentTitle"
      )?.value
    );


  const instructions =
    safeString(
      $(
        "teacherAssignmentInstructions"
      )?.value
    );


  const dueValue =
    safeString(
      $(
        "teacherAssignmentDueDate"
      )?.value
    );


  const status =
    safeString(
      $(
        "teacherAssignmentStatus"
      )?.value,
      "draft"
    );


  const file =
    $(
      "teacherAssignmentAttachment"
    )
      ?.files
      ?.[0] ||
    null;


  const removeAttachment =
    $(
      "teacherAssignmentRemoveAttachment"
    )?.value ===
    "true";


  if (
    !classId
  ){

    throw new AIFTApiError(
      "Please select a class.",
      {
        code:
          "ASSIGNMENT_CLASS_REQUIRED"
      }
    );

  }


  if (
    !title
  ){

    throw new AIFTApiError(
      "Assignment title is required.",
      {
        code:
          "ASSIGNMENT_TITLE_REQUIRED"
      }
    );

  }


  if (
    !getTeacherClassById(
      classId
    )
  ){

    throw new AIFTApiError(
      "You do not have access to the selected class.",
      {
        code:
          "ASSIGNMENT_CLASS_FORBIDDEN"
      }
    );

  }


  if (
    file
  ){

    validateTeacherAssignmentFile(
      file
    );

  }


let dueDate =
  "";


if (
  dueValue
){

  /*
    Keep assignment deadlines consistent with school.html.

    The School dashboard sends YYYY-MM-DD directly to the
    Assignment API and that is the established working
    contract for assignment deadlines.
  */

  if (
    !/^\d{4}-\d{2}-\d{2}$/.test(
      dueValue
    )
  ){

    throw new AIFTApiError(
      "Please enter a valid assignment due date.",
      {
        code:
          "ASSIGNMENT_DUE_DATE_INVALID"
      }
    );

  }


  dueDate =
    dueValue;

}


  const formData =
    new FormData();


  formData.append(
    "classId",
    classId
  );


  formData.append(
    "title",
    title
  );


  formData.append(
    "instructions",
    instructions
  );


  formData.append(
    "description",
    instructions
  );


  formData.append(
    "dueDate",
    dueDate
  );


  formData.append(
    "status",
    status
  );


  formData.append(
    "removeAttachment",
    removeAttachment
      ? "true"
      : "false"
  );


  if (
    file
  ){

    formData.append(
      "attachment",
      file,
      file.name
    );

  }


  return formData;

}


/* =========================================================
   SET ASSIGNMENT SAVE BUTTON
========================================================= */

function setTeacherAssignmentSaveButtonState(
  saving
){

  const button =
    $(
      "teacherAssignmentSaveButton"
    );


  if (
    !button
  ){

    return;

  }


  const editing =
    Boolean(
      teacherAssignmentWorkspaceState
        .editingAssignmentId
    );


  button.disabled =
    Boolean(
      saving
    );


  button.setAttribute(
    "aria-busy",
    saving
      ? "true"
      : "false"
  );


  button.innerHTML =
    saving
      ? `
          <i
            class="fa-solid fa-spinner fa-spin"
            aria-hidden="true"
          ></i>

          <span>
            Uploading & Saving...
          </span>
        `
      : `
          <i
            class="fa-solid fa-floppy-disk"
            aria-hidden="true"
          ></i>

          <span>
            ${
              editing
                ? "Save Changes"
                : "Create Assignment"
            }
          </span>
        `;

}


/* =========================================================
   SAVE ASSIGNMENT
========================================================= */

async function saveTeacherAssignment(){

  if (
    teacherAssignmentWorkspaceState
      .saving
  ){

    return false;

  }


  /* =====================================================
     BUILD FORM DATA
  ===================================================== */

  let formData;


  try{

    formData =
      buildTeacherAssignmentFormData();

  }catch(
    error
  ){

    notifyAIFTError(
      getErrorMessage(
        error,
        "Please check the assignment details."
      ),
      {
        title:
          "Assignment incomplete"
      }
    );


    return false;

  }


  /* =====================================================
     CURRENT EDITING ID
  ===================================================== */

  const assignmentId =
    normalizeId(
      teacherAssignmentWorkspaceState
        .editingAssignmentId
    );


  /*
    Keep the exact submitted values.

    We use these for immediate local reconciliation while the
    authoritative GET request refreshes the collection.
  */

  const submittedDueDate =
    safeString(
      formData.get(
        "dueDate"
      )
    );


  const submittedTitle =
    safeString(
      formData.get(
        "title"
      )
    );


  const submittedInstructions =
    safeString(
      formData.get(
        "instructions"
      )
    );


  const submittedStatus =
    safeString(
      formData.get(
        "status"
      )
    );


  const submittedClassId =
    normalizeId(
      formData.get(
        "classId"
      )
    );


  /* =====================================================
     SAVING STATE
  ===================================================== */

  teacherAssignmentWorkspaceState
    .saving =
    true;


  setTeacherAssignmentSaveButtonState(
    true
  );


  try{

    /* ===================================================
       SAVE TO BACKEND
    =================================================== */

    const response =
      assignmentId
        ? await apiPatch(
            `/api/assignments/${
              encodeURIComponent(
                assignmentId
              )
            }`,
            formData,
            {
              timeout:
                120000
            }
          )
        : await apiPost(
            "/api/assignments",
            formData,
            {
              timeout:
                120000
            }
          );


    const responseAssignment =
      response?.assignment ||
      response?.data ||
      response;


    const responseId =
      normalizeId(
        responseAssignment?._id ||
        responseAssignment?.id
      );


    const savedAssignmentId =
      responseId ||
      assignmentId;


    /* ===================================================
       IMMEDIATE LOCAL RECONCILIATION

       This prevents an old card from remaining red while
       the authoritative collection reload is happening.
    =================================================== */

    if (
      savedAssignmentId
    ){

      const existingIndex =
        state.assignments
          .findIndex(
            item =>
              sameId(
                item?._id ||
                item?.id,
                savedAssignmentId
              )
          );


      const currentAssignment =
        existingIndex >=
          0
          ? state.assignments[
              existingIndex
            ]
          : null;


      /*
        IMPORTANT:

        Do not blindly trust only the PATCH response for the
        editable fields.

        The submitted values are known to be what the teacher
        just saved.
      */

      const reconciledAssignment = {

        ...(
          currentAssignment ||
          {}
        ),

        ...(
          responseAssignment &&
          typeof responseAssignment ===
            "object"
            ? responseAssignment
            : {}
        ),

        _id:
          responseId ||
          normalizeId(
            currentAssignment?._id ||
            currentAssignment?.id
          ) ||
          savedAssignmentId,

        title:
          submittedTitle ||
          responseAssignment?.title ||
          currentAssignment?.title ||
          "",

        instructions:
          submittedInstructions,

        description:
          submittedInstructions,

        dueDate:
          submittedDueDate ||
          null,

        status:
          submittedStatus ||
          responseAssignment?.status ||
          currentAssignment?.status ||
          "draft",

        classId:
          responseAssignment?.classId ||
          getTeacherClassById(
            submittedClassId
          ) ||
          submittedClassId

      };


      if (
        existingIndex >=
        0
      ){

        state.assignments[
          existingIndex
        ] =
          reconciledAssignment;

      }else{

        state.assignments.unshift(
          reconciledAssignment
        );

      }


      /*
        Render immediately so the teacher does not continue
        seeing the old due date.
      */

      finalizeTeacherLoadedData();

      renderTeacherAssignmentsWorkspace();

      renderTeacherOverviewAssignments();

      renderTeacherDashboardStats();

    }


    /* ===================================================
       AUTHORITATIVE DATABASE REFRESH

       THIS IS THE IMPORTANT FIX.

       Always reload after POST/PATCH instead of trusting the
       mutation response as the final Teacher Studio state.
    =================================================== */

    await loadTeacherAssignments();


    finalizeTeacherLoadedData();


    /* ===================================================
       VERIFY UPDATED RECORD EXISTS
    =================================================== */

    if (
      savedAssignmentId
    ){

      const canonicalAssignment =
        getTeacherAssignments()
          .find(
            item =>
              sameId(
                item?._id ||
                item?.id,
                savedAssignmentId
              )
          );


      if (
        !canonicalAssignment
      ){

        console.warn(
          "Saved assignment was not found after refresh:",
          savedAssignmentId
        );

      }else{

        /*
          Helpful production diagnostic.

          If the backend ever accepts the PATCH but fails to
          persist the due date, this makes the mismatch visible
          immediately in the console.
        */

        const canonicalDueDate =
          getTeacherAssignmentDueDate(
            canonicalAssignment
          );


        if (
          submittedDueDate
        ){

          const submittedDate =
            toValidDate(
              submittedDueDate
            );


          if (
            submittedDate &&
            canonicalDueDate &&
            submittedDate.getTime() !==
              canonicalDueDate.getTime()
          ){

            console.warn(
              "Assignment due-date mismatch after save:",
              {
                assignmentId:
                  savedAssignmentId,

                submitted:
                  submittedDate
                    .toISOString(),

                backend:
                  canonicalDueDate
                    .toISOString()
              }
            );

          }

        }

      }

    }


    /* ===================================================
       FINAL RENDER FROM DATABASE STATE
    =================================================== */

    closeTeacherAssignmentEditor();


    renderTeacherAssignmentsWorkspace();

    renderTeacherOverviewAssignments();

    renderTeacherDashboardStats();


    /*
      Due dates also affect late/submission calculations.

      Refresh dependent UI from the newly loaded assignment
      collection.
    */

    if (
      typeof renderTeacherSubmissionsWorkspace ===
        "function"
    ){

      renderTeacherSubmissionsWorkspace();

    }


    if (
      typeof renderTeacherGradingWorkspace ===
        "function" &&
      isTeacherStudioPageActive(
        "grading"
      )
    ){

      renderTeacherGradingWorkspace();

    }


    /* ===================================================
       SUCCESS
    =================================================== */

    notifyAIFTSuccess(
      assignmentId
        ? "Assignment updated successfully."
        : "Assignment created successfully.",
      {
        title:
          assignmentId
            ? "Assignment updated"
            : "Assignment created"
      }
    );


    return true;

  }catch(
    error
  ){

    console.error(
      "saveTeacherAssignment failed:",
      error
    );


    notifyAIFTError(
      getErrorMessage(
        error,
        "AIFT could not save this assignment."
      ),
      {
        title:
          "Assignment not saved"
      }
    );


    return false;

  }finally{

    teacherAssignmentWorkspaceState
      .saving =
      false;


    if (
      $(
        "teacherAssignmentSaveButton"
      )
    ){

      setTeacherAssignmentSaveButtonState(
        false
      );

    }

  }

}

/* =========================================================
   DELETE ASSIGNMENT
========================================================= */

async function deleteTeacherAssignment(
  assignmentId
){

  const normalizedId =
    normalizeId(
      assignmentId
    );


  if (
    !normalizedId
  ){

    return false;

  }


  const assignment =
    getTeacherAssignments()
      .find(
        item =>
          sameId(
            item?._id ||
            item?.id,
            normalizedId
          )
      );


  if (
    !assignment
  ){

    notifyAIFTError(
      "The assignment is no longer available.",
      {
        title:
          "Assignment unavailable"
      }
    );


    return false;

  }


  const confirmed =
    window.confirm(
      `Delete "${getTeacherAssignmentTitle(
        assignment
      )}"?\n\nIts dependent student submissions may also be removed by the backend. This cannot be undone.`
    );


  if (
    !confirmed
  ){

    return false;

  }


  try{

    await apiSend(
      `/api/assignments/${
        encodeURIComponent(
          normalizedId
        )
      }`,
      "DELETE"
    );


    state.assignments =
      getTeacherAssignments()
        .filter(
          item =>
            !sameId(
              item?._id ||
              item?.id,
              normalizedId
            )
        );


    /*
      The backend currently deletes dependent submissions when
      an assignment is deleted, so refresh submission state too.
    */

    await Promise.allSettled([

      loadTeacherAssignments(),

      loadTeacherSubmissions()

    ]);


    finalizeTeacherLoadedData();


    closeTeacherAssignmentEditor();


    renderTeacherAssignmentsWorkspace();

    renderTeacherOverviewAssignments();

    renderTeacherOverviewActivity();

    renderTeacherDashboardStats();

    renderTeacherGradingBadge();


    notifyAIFTSuccess(
      "Assignment deleted.",
      {
        title:
          "Assignment removed"
      }
    );


    return true;

  }catch(
    error
  ){

    console.error(
      "deleteTeacherAssignment failed:",
      error
    );


    notifyAIFTError(
      getErrorMessage(
        error,
        "The assignment could not be deleted."
      ),
      {
        title:
          "Delete failed"
      }
    );


    return false;

  }

}



/* =========================================================
   SUBMISSION ID
========================================================= */

function getTeacherSubmissionId(
  submission
){

  return normalizeId(
    submission?._id ||
    submission?.id
  );

}


/* =========================================================
   SUBMISSION STUDENT
========================================================= */

function getTeacherSubmissionStudent(
  submission
){

  const value =
    submission?.studentId;


  if (
    value &&
    typeof value ===
      "object"
  ){

    return value;

  }


  const studentRecord =
    getTeacherStudentById(
      value
    );


  return (
    studentRecord?.student ||
    null
  );

}


/* =========================================================
   SUBMISSION ASSIGNMENT
========================================================= */

function getTeacherSubmissionAssignment(
  submission
){

  const value =
    submission?.assignmentId;


  if (
    value &&
    typeof value ===
      "object" &&
    (
      value.title ||
      value.dueDate
    )
  ){

    const assignmentId =
      normalizeId(
        value._id ||
        value.id
      );


    return (
      getTeacherAssignments()
        .find(
          assignment =>
            sameId(
              assignment?._id ||
              assignment?.id,
              assignmentId
            )
        ) ||
      value
    );

  }


  return (
    getTeacherAssignments()
      .find(
        assignment =>
          sameId(
            assignment?._id ||
            assignment?.id,
            value
          )
      ) ||
    null
  );

}


/* =========================================================
   SUBMISSION CLASS
========================================================= */

function getTeacherSubmissionClass(
  submission
){

  const classValue =
    submission?.classId;


  if (
    classValue &&
    typeof classValue ===
      "object"
  ){

    return (
      getTeacherClassById(
        classValue._id ||
        classValue.id
      ) ||
      classValue
    );

  }


  return (
    getTeacherClassById(
      classValue
    ) ||
    null
  );

}


/* =========================================================
   SUBMISSION DATE
========================================================= */

function getTeacherSubmissionDate(
  submission
){

  return toValidDate(

    submission?.submittedAt ||
    submission?.createdAt

  );

}


/* =========================================================
   SUBMISSION LATE STATUS

   Calculated from actual assignment due date and submission
   timestamp.

   No database status is modified.
========================================================= */

function isTeacherSubmissionLate(
  submission
){

  const assignment =
    getTeacherSubmissionAssignment(
      submission
    );


  if (
    !assignment
  ){

    return false;

  }


  const dueDate =
    toValidDate(
      getTeacherAssignmentDueDate(
        assignment
      )
    );

  const submittedAt =
    getTeacherSubmissionDate(
      submission
    );


  if (
    !dueDate ||
    !submittedAt
  ){

    return false;

  }


  return (
    submittedAt.getTime() >
    dueDate.getTime()
  );

}


/* =========================================================
   SUBMISSION DISPLAY STATUS

   HTML supports:
   submitted
   reviewed
   needs-review
   late

   "needs-review" is a UI classification for pending review;
   it does not mutate submission.status.
========================================================= */

function getTeacherSubmissionDisplayStatus(
  submission
){

  const status =
    normalizeSubmissionStatus(
      submission?.status
    );


  if (
    isTeacherSubmissionLate(
      submission
    ) &&
    ![
      "reviewed",
      "graded",
      "returned"
    ].includes(
      status
    )
  ){

    return "late";

  }


  if (
    [
      "reviewed",
      "graded",
      "returned"
    ].includes(
      status
    )
  ){

    return "reviewed";

  }


  if (
    status ===
    "pending"
  ){

    return "needs-review";

  }


  return "submitted";

}


/* =========================================================
   SUBMISSION DISPLAY LABEL
========================================================= */

function getTeacherSubmissionStatusLabel(
  submission
){

  switch(
    getTeacherSubmissionDisplayStatus(
      submission
    )
  ){

    case "reviewed":

      return "Reviewed";

    case "needs-review":

      return "Needs review";

    case "late":

      return "Late";

    default:

      return "Submitted";

  }

}


/* =========================================================
   FILTER SUBMISSIONS
========================================================= */

function getFilteredTeacherSubmissions(){

  const search =
    safeString(
      teacherSubmissionWorkspaceState
        .search
    )
      .toLowerCase();

  const classId =
    normalizeId(
      teacherSubmissionWorkspaceState
        .classId
    );

  const status =
    safeString(
      teacherSubmissionWorkspaceState
        .status
    )
      .toLowerCase();


  let submissions = [
    ...getTeacherSubmissions()
  ];


  if (
    search
  ){

    submissions =
      submissions.filter(
        submission => {

          const student =
            getTeacherSubmissionStudent(
              submission
            );

          const assignment =
            getTeacherSubmissionAssignment(
              submission
            );

          const classItem =
            getTeacherSubmissionClass(
              submission
            );


          const haystack =
            [

              student?.name,
              student?.fullName,
              student?.email,

              assignment?.title,

              getTeacherClassTitle(
                classItem ||
                {}
              )

            ]
              .filter(
                Boolean
              )
              .join(
                " "
              )
              .toLowerCase();


          return haystack.includes(
            search
          );

        }
      );

  }


  if (
    classId
  ){

    submissions =
      submissions.filter(
        submission =>
          sameId(
            submission
              ?.classId
              ?._id ||
            submission
              ?.classId,
            classId
          )
      );

  }


  if (
    status
  ){

    submissions =
      submissions.filter(
        submission => {

          const displayStatus =
            getTeacherSubmissionDisplayStatus(
              submission
            );

          const rawStatus =
            normalizeSubmissionStatus(
              submission?.status
            );


          /*
            "Submitted" means the actual submitted state.
            "Needs review" includes any unresolved submission.
            This intentionally allows a submitted record to
            appear under Needs review when appropriate.
          */

          if (
            status ===
            "needs-review"
          ){

            return [
              "submitted",
              "pending"
            ].includes(
              rawStatus
            );

          }


          if (
            status ===
            "submitted"
          ){

            return rawStatus ===
              "submitted";

          }


          return displayStatus ===
            status;

        }
      );

  }


  submissions.sort(
    (
      first,
      second
    ) =>
      (
        getTeacherSubmissionDate(
          second
        )?.getTime() ||
        0
      ) -
      (
        getTeacherSubmissionDate(
          first
        )?.getTime() ||
        0
      )
  );


  return submissions;

}


/* =========================================================
   SUBMISSION CLASS FILTER
========================================================= */

function renderTeacherSubmissionClassFilter(){

  const select =
    $(
      "teacherSubmissionClassFilter"
    );


  if (
    !select
  ){

    return;

  }


  const selectedValue =
    teacherSubmissionWorkspaceState
      .classId;


  select.innerHTML = `
    <option value="">
      All classes
    </option>

    ${
      getTeacherClasses()
        .map(
          classItem => {

            const classId =
              normalizeId(
                classItem?._id ||
                classItem?.id
              );


            return `
              <option
                value="${escapeAttribute(classId)}"
              >
                ${escapeHtml(
                  getTeacherClassTitle(
                    classItem
                  )
                )}
              </option>
            `;

          }
        )
        .join(
          ""
        )
    }
  `;


  select.value =
    selectedValue;


  if (
    select.value !==
    selectedValue
  ){

    teacherSubmissionWorkspaceState
      .classId =
      "";

    select.value =
      "";

  }

}


/* =========================================================
   SUBMISSION STATUS FILTER
========================================================= */

function renderTeacherSubmissionStatusFilter(){

  const select =
    $(
      "teacherSubmissionStatusFilter"
    );


  if (
    !select
  ){

    return;

  }


  select.value =
    teacherSubmissionWorkspaceState
      .status;


  if (
    select.value !==
    teacherSubmissionWorkspaceState
      .status
  ){

    teacherSubmissionWorkspaceState
      .status =
      "";

    select.value =
      "";

  }

}


/* =========================================================
   SUBMISSION FILTER STATE
========================================================= */

function renderTeacherSubmissionFilters(){

  const search =
    $(
      "teacherSubmissionSearch"
    );


  if (
    search &&
    search.value !==
      teacherSubmissionWorkspaceState
        .search
  ){

    search.value =
      teacherSubmissionWorkspaceState
        .search;

  }


  renderTeacherSubmissionClassFilter();

  renderTeacherSubmissionStatusFilter();

}


/* =========================================================
   SUBMISSIONS COUNT
========================================================= */

function renderTeacherSubmissionsCount(){

  const allSubmissions =
    getTeacherSubmissions();

  const filteredSubmissions =
    getFilteredTeacherSubmissions();

  const hasFilters =
    Boolean(

      teacherSubmissionWorkspaceState
        .search ||

      teacherSubmissionWorkspaceState
        .classId ||

      teacherSubmissionWorkspaceState
        .status

    );


  setText(

    "teacherSubmissionsCount",

    hasFilters
      ? `${filteredSubmissions.length} of ${allSubmissions.length} ${
          allSubmissions.length === 1
            ? "submission"
            : "submissions"
        }`
      : `${allSubmissions.length} ${
          allSubmissions.length === 1
            ? "submission"
            : "submissions"
        }`

  );

}


/* =========================================================
   SUBMISSION EMPTY STATE
========================================================= */

function renderTeacherSubmissionsEmptyState(
  submissions
){

  const empty =
    $(
      "teacherSubmissionsEmpty"
    );


  if (
    !empty
  ){

    return;

  }


  const hasSubmissions =
    getTeacherSubmissions()
      .length >
    0;

  const hasResults =
    submissions.length >
    0;


  empty.hidden =
    hasResults;


  if (
    hasResults
  ){

    return;

  }


  const heading =
    empty.querySelector(
      "h2"
    );

  const description =
    empty.querySelector(
      "p"
    );


  if (
    !hasSubmissions
  ){

    if (
      heading
    ){

      heading.textContent =
        "No submissions yet";

    }


    if (
      description
    ){

      description.textContent =
        "Student submissions will appear here when work is submitted.";

    }


    return;

  }


  if (
    heading
  ){

    heading.textContent =
      "No submissions found";

  }


  if (
    description
  ){

    description.textContent =
      "No student work matches the current search or filters.";

  }

}


/* =========================================================
   SUBMISSION STUDENT NAME
========================================================= */

function getTeacherSubmissionStudentName(
  submission
){

  const student =
    getTeacherSubmissionStudent(
      submission
    );


  return safeString(

    student?.name ||
    student?.fullName ||
    student?.displayName,

    "Student"

  );

}


/* =========================================================
   SUBMISSION STUDENT AVATAR
========================================================= */

function getTeacherSubmissionStudentAvatar(
  submission
){

  const student =
    getTeacherSubmissionStudent(
      submission
    );


  return getSafeImageUrl(

    student?.profileImage ||
    student?.avatar ||
    student?.photoURL,

    FALLBACK_AVATAR

  );

}


/* =========================================================
   SUBMISSION INITIALS
========================================================= */

function getTeacherSubmissionStudentInitials(
  submission
){

  const name =
    getTeacherSubmissionStudentName(
      submission
    );


  return (
    name
      .split(
        /\s+/
      )
      .filter(
        Boolean
      )
      .slice(
        0,
        2
      )
      .map(
        part =>
          part.charAt(
            0
          ).toUpperCase()
      )
      .join(
        ""
      ) ||
    "S"
  );

}


/* =========================================================
   SUBMISSION CARD
========================================================= */

function createTeacherSubmissionCard(
  submission
){

  const submissionId =
    getTeacherSubmissionId(
      submission
    );

  const studentName =
    getTeacherSubmissionStudentName(
      submission
    );

  const studentAvatar =
    getTeacherSubmissionStudentAvatar(
      submission
    );

  const initials =
    getTeacherSubmissionStudentInitials(
      submission
    );

  const assignment =
    getTeacherSubmissionAssignment(
      submission
    );

  const classItem =
    getTeacherSubmissionClass(
      submission
    );

  const assignmentTitle =
    safeString(
      assignment?.title,
      "Assignment"
    );

  const classTitle =
    getTeacherClassTitle(
      classItem ||
      {}
    );

  const submissionDate =
    getTeacherSubmissionDate(
      submission
    );

  const status =
    getTeacherSubmissionDisplayStatus(
      submission
    );

  const statusLabel =
    getTeacherSubmissionStatusLabel(
      submission
    );

  const grade =
    Number.isFinite(
      Number(
        submission?.grade
      )
    )
      ? Number(
          submission.grade
        )
      : null;


  return `
    <article
      class="teacher-submission-card"
      data-submission-id="${escapeAttribute(submissionId)}"
    >

      <div
        class="teacher-submission-avatar"
        aria-hidden="true"
      >
        <span>
          ${escapeHtml(initials)}
        </span>

        <img
          src="${escapeAttribute(studentAvatar)}"
          alt=""
          loading="lazy"
          referrerpolicy="no-referrer"
        />
      </div>


      <div
        class="teacher-submission-main"
      >

        <h3
          class="teacher-submission-title"
          title="${escapeAttribute(assignmentTitle)}"
        >
          ${escapeHtml(assignmentTitle)}
        </h3>


        <p
          class="teacher-submission-student"
        >
          ${escapeHtml(studentName)}
        </p>


        <p
          class="teacher-submission-class"
        >
          ${escapeHtml(classTitle)}
        </p>


        <div
          class="teacher-submission-meta"
        >

          <span
            class="teacher-submission-meta-item"
          >
            <i
              class="fa-regular fa-clock"
              aria-hidden="true"
            ></i>

            ${
              submissionDate
                ? escapeHtml(
                    formatDateTime(
                      submissionDate
                    )
                  )
                : "No submission time"
            }
          </span>


          ${
            grade !==
            null
              ? `
                <span
                  class="teacher-submission-meta-item"
                >
                  <i
                    class="fa-solid fa-graduation-cap"
                    aria-hidden="true"
                  ></i>

                  Grade:
                  ${escapeHtml(grade)}
                </span>
              `
              : ""
          }


          <span
            class="teacher-submission-status ${escapeAttribute(status)}"
          >
            ${escapeHtml(statusLabel)}
          </span>

        </div>

      </div>


      <div
        class="teacher-submission-actions"
      >

        <button
          type="button"
          class="teacher-submission-action ai"
          data-teacher-action="kabezya-review-submission"
          data-submission-id="${escapeAttribute(submissionId)}"
          title="Inspect with Kabezya AI"
        >
          <i
            class="fa-solid fa-wand-magic-sparkles"
            aria-hidden="true"
          ></i>

          AI Review
        </button>


        <button
          type="button"
          class="teacher-submission-action primary"
          data-teacher-action="review-submission"
          data-submission-id="${escapeAttribute(submissionId)}"
        >
          <i
            class="fa-solid fa-pen-to-square"
            aria-hidden="true"
          ></i>

          ${
            status ===
            "reviewed"
              ? "View"
              : "Review"
          }
        </button>

      </div>

    </article>
  `;

}


/* =========================================================
   SUBMISSION IMAGE FALLBACKS
========================================================= */

function bindTeacherSubmissionImageFallbacks(){

  const list =
    $(
      "teacherSubmissionsList"
    );


  if (
    !list
  ){

    return;

  }


  list
    .querySelectorAll(
      ".teacher-submission-avatar img"
    )
    .forEach(
      image => {

        image.onerror =
          () => {

            image.onerror =
              null;

            image.hidden =
              true;

          };

      }
    );

}


/* =========================================================
   RENDER SUBMISSIONS LIST
========================================================= */

function renderTeacherSubmissionsList(){

  const list =
    $(
      "teacherSubmissionsList"
    );


  if (
    !list
  ){

    return;

  }


  const submissions =
    getFilteredTeacherSubmissions();


  renderTeacherSubmissionsCount();

  renderTeacherSubmissionsEmptyState(
    submissions
  );


  if (
    !submissions.length
  ){

    list.innerHTML =
      "";

    list.hidden =
      true;

    return;

  }


  list.hidden =
    false;


  list.innerHTML =
    submissions
      .map(
        createTeacherSubmissionCard
      )
      .join(
        ""
      );


  bindTeacherSubmissionImageFallbacks();

}


/* =========================================================
   RENDER SUBMISSIONS WORKSPACE
========================================================= */

function renderTeacherSubmissionsWorkspace(){

  renderTeacherSubmissionFilters();

  renderTeacherSubmissionsList();

}


