/* =========================================================
   GRADING WORKSPACE STATE
========================================================= */

const teacherGradingWorkspaceState = {

  classId:
    "",

  assignmentId:
    "",

  status:
    "submitted",

  search:
    "",

  selectedSubmissionId:
    "",

  saving:
    false,

  refreshing:
    false,

  initialized:
    false,

  kabezyaLoading:
    false,

  kabezyaSuggestion:
    null

};


/* =========================================================
   GET SUBMISSION BY ID
========================================================= */

function getTeacherSubmissionById(
  submissionId
){

  const normalizedSubmissionId =
    normalizeId(
      submissionId
    );


  if (
    !normalizedSubmissionId
  ){

    return null;

  }


  return (
    getTeacherSubmissions()
      .find(
        submission =>
          sameId(
            getTeacherSubmissionId(
              submission
            ),
            normalizedSubmissionId
          )
      ) ||
    null
  );

}


/* =========================================================
   SUBMISSION STUDENT ID
========================================================= */

function getTeacherSubmissionStudentId(
  submission
){

  return normalizeId(
    submission
      ?.studentId
      ?._id ||
    submission
      ?.studentId
  );

}


/* =========================================================
   SUBMISSION ASSIGNMENT ID
========================================================= */

function getTeacherSubmissionAssignmentId(
  submission
){

  return normalizeId(
    submission
      ?.assignmentId
      ?._id ||
    submission
      ?.assignmentId
  );

}


/* =========================================================
   SUBMISSION CLASS ID
========================================================= */

function getTeacherSubmissionClassId(
  submission
){

  return normalizeId(
    submission
      ?.classId
      ?._id ||
    submission
      ?.classId
  );

}


/* =========================================================
   GRADING NORMALIZED STATUS

   This is intentionally separate from the Submission page's
   visual status classification.

   Grading cares about actual review lifecycle:
     submitted
     reviewed
     returned
========================================================= */

function getTeacherGradingSubmissionStatus(
  submission
){

  const status =
    normalizeSubmissionStatus(
      submission?.status
    );


  if (
    [
      "reviewed",
      "graded"
    ].includes(
      status
    )
  ){

    return "reviewed";

  }


  if (
    status ===
    "returned"
  ){

    return "returned";

  }


  return "submitted";

}


/* =========================================================
   GRADING STATUS LABEL
========================================================= */

function getTeacherGradingStatusLabel(
  submission
){

  switch(
    getTeacherGradingSubmissionStatus(
      submission
    )
  ){

    case "reviewed":

      return "Reviewed";

    case "returned":

      return "Returned";

    default:

      return "Needs review";

  }

}


/* =========================================================
   GRADING ASSIGNMENTS FOR CURRENT CLASS
========================================================= */

function getTeacherGradingAssignments(){

  const classId =
    normalizeId(
      teacherGradingWorkspaceState
        .classId
    );


  let assignments = [
    ...getTeacherAssignments()
  ];


  if (
    classId
  ){

    assignments =
      assignments.filter(
        assignment =>
          sameId(
            assignment
              ?.classId
              ?._id ||
            assignment
              ?.classId,
            classId
          )
      );

  }


  return assignments.sort(
    (
      first,
      second
    ) =>
      getTeacherAssignmentTitle(
        first
      )
        .localeCompare(
          getTeacherAssignmentTitle(
            second
          )
        )
  );

}

/* =========================================================
   GRADING SUBMISSION FILTER ENGINE
========================================================= */


/* =========================================================
   GET GRADING SCOPE SUBMISSIONS

   Scope filters:
   - class
   - assignment

   Status/search are intentionally applied separately so the
   summary can still show meaningful lifecycle counts.
========================================================= */

function getTeacherGradingScopeSubmissions(){

  const classId =
    normalizeId(
      teacherGradingWorkspaceState
        .classId
    );


  const assignmentId =
    normalizeId(
      teacherGradingWorkspaceState
        .assignmentId
    );


  let submissions =
    [
      ...getTeacherSubmissions()
    ];


  /* =====================================================
     CLASS SCOPE
  ===================================================== */

  if (
    classId
  ){

    submissions =
      submissions.filter(
        submission =>
          sameId(
            getTeacherSubmissionClassId(
              submission
            ),
            classId
          )
      );

  }


  /* =====================================================
     ASSIGNMENT SCOPE
  ===================================================== */

  if (
    assignmentId
  ){

    submissions =
      submissions.filter(
        submission =>
          sameId(
            getTeacherSubmissionAssignmentId(
              submission
            ),
            assignmentId
          )
      );

  }


  return submissions;

}


/* =========================================================
   SEARCH MATCH
========================================================= */

function teacherGradingSubmissionMatchesSearch(
  submission,
  searchValue
){

  const search =
    safeString(
      searchValue
    )
      .toLowerCase();


  if (
    !search
  ){

    return true;

  }


  const student =
    getTeacherSubmissionStudent(
      submission
    );


  const assignment =
    getTeacherSubmissionAssignment(
      submission
    );


  const classItem =
    getTeacherSubmissionClass(
      submission
    );


  const studentName =
    safeString(

      student?.name ||
      student?.fullName ||
      student?.displayName

    );


  const studentEmail =
    safeString(
      student?.email
    );


  const assignmentTitle =
    getTeacherAssignmentTitle(
      assignment ||
      {}
    );


  const classTitle =
    getTeacherClassTitle(
      classItem ||
      {}
    );


  const submissionText =
    safeString(

      submission?.text ||
      submission?.answer ||
      submission?.response

    );


  const haystack =
    [
      studentName,
      studentEmail,
      assignmentTitle,
      classTitle,
      submissionText
    ]
      .filter(
        Boolean
      )
      .join(
        " "
      )
      .toLowerCase();


  return haystack.includes(
    search
  );

}


/* =========================================================
   FILTER GRADING SUBMISSIONS
========================================================= */

function getTeacherFilteredGradingSubmissions(){

  const status =
    safeString(
      teacherGradingWorkspaceState
        .status,
      "submitted"
    )
      .toLowerCase();


  const search =
    safeString(
      teacherGradingWorkspaceState
        .search
    );


  let submissions =
    getTeacherGradingScopeSubmissions();


  /* =====================================================
     STATUS
  ===================================================== */

  if (
    status &&
    status !==
      "all"
  ){

    submissions =
      submissions.filter(
        submission =>
          getTeacherGradingSubmissionStatus(
            submission
          ) ===
          status
      );

  }


  /* =====================================================
     SEARCH
  ===================================================== */

  if (
    search
  ){

    submissions =
      submissions.filter(
        submission =>
          teacherGradingSubmissionMatchesSearch(
            submission,
            search
          )
      );

  }


  /* =====================================================
     ORDER

     Needs review:
       oldest first — teacher works through queue.

     Reviewed / returned / all:
       newest first.
  ===================================================== */

  submissions.sort(
    (
      first,
      second
    ) => {

      const firstTime =
        getTeacherSubmissionDate(
          first
        )?.getTime() ||
        0;


      const secondTime =
        getTeacherSubmissionDate(
          second
        )?.getTime() ||
        0;


      if (
        status ===
        "submitted"
      ){

        return (
          firstTime -
          secondTime
        );

      }


      return (
        secondTime -
        firstTime
      );

    }
  );


  return submissions;

}


/* =========================================================
   GRADING SUMMARY

   IMPORTANT:
   Summary respects class + assignment scope,
   but intentionally does NOT respect the selected status.

   Example:
   selecting one class still shows:
     total
     needs review
     reviewed
     returned
========================================================= */

function getTeacherGradingSummary(){

  const submissions =
    getTeacherGradingScopeSubmissions();


  const submitted =
    submissions.filter(
      submission =>
        getTeacherGradingSubmissionStatus(
          submission
        ) ===
        "submitted"
    ).length;


  const reviewed =
    submissions.filter(
      submission =>
        getTeacherGradingSubmissionStatus(
          submission
        ) ===
        "reviewed"
    ).length;


  const returned =
    submissions.filter(
      submission =>
        getTeacherGradingSubmissionStatus(
          submission
        ) ===
        "returned"
    ).length;


  return {

    total:
      submissions.length,

    submitted,

    reviewed,

    returned

  };

}


/* =========================================================
   FIRST AVAILABLE GRADING SUBMISSION
========================================================= */

function getFirstTeacherGradingSubmission(){

  return (
    getTeacherFilteredGradingSubmissions()[
      0
    ] ||
    null
  );

}


/* =========================================================
   ENSURE VALID GRADING SELECTION

   Automatically selects the first matching submission.

   This prevents the right-side viewer from appearing blank
   every time a filter changes.
========================================================= */

function ensureTeacherGradingSelection(){

  const submissions =
    getTeacherFilteredGradingSubmissions();


  if (
    !submissions.length
  ){

    teacherGradingWorkspaceState
      .selectedSubmissionId =
      "";


    state.selectedSubmissionId =
      "";


    return null;

  }


  const selectedId =
    normalizeId(
      teacherGradingWorkspaceState
        .selectedSubmissionId
    );


  const selectedStillVisible =
    submissions.some(
      submission =>
        sameId(
          getTeacherSubmissionId(
            submission
          ),
          selectedId
        )
    );


  if (
    selectedStillVisible
  ){

    return getTeacherSubmissionById(
      selectedId
    );

  }


  const firstSubmission =
    submissions[
      0
    ];


  const firstId =
    getTeacherSubmissionId(
      firstSubmission
    );


  teacherGradingWorkspaceState
    .selectedSubmissionId =
    firstId;


  state.selectedSubmissionId =
    firstId;


  teacherGradingWorkspaceState
    .kabezyaSuggestion =
    null;


  teacherGradingWorkspaceState
    .kabezyaLoading =
    false;


  return firstSubmission;

}

