/* =========================================================
   GRADING QUEUE ITEM
========================================================= */

function createTeacherGradingQueueItem(
  submission
){

  const submissionId =
    getTeacherSubmissionId(
      submission
    );

  const student =
    getTeacherSubmissionStudent(
      submission
    );

  const assignment =
    getTeacherSubmissionAssignment(
      submission
    );

  const classItem =
    getTeacherSubmissionClass(
      submission
    );

  const selected =
    sameId(
      teacherGradingWorkspaceState
        .selectedSubmissionId,
      submissionId
    );

  const studentName =
    safeString(

      student?.name ||
      student?.fullName ||
      student?.displayName,

      "Student"

    );

  const studentAvatar =
    getSafeImageUrl(

      student?.profileImage ||
      student?.avatar ||
      student?.photoURL,

      FALLBACK_AVATAR

    );

  const submittedAt =
    getTeacherSubmissionDate(
      submission
    );

  const status =
    getTeacherGradingSubmissionStatus(
      submission
    );


  return `
    <button
      type="button"
      class="
        teacher-submission-list-item
        ${
          selected
            ? "active"
            : ""
        }
      "
      data-teacher-action="select-grading-submission"
      data-submission-id="${escapeAttribute(submissionId)}"
    >

      <img
        src="${escapeAttribute(studentAvatar)}"
        alt=""
        loading="lazy"
        referrerpolicy="no-referrer"
      />


      <span
        class="teacher-submission-list-copy"
      >

        <span
          class="teacher-submission-list-top"
        >

          <strong>
            ${escapeHtml(studentName)}
          </strong>

          <small>
            ${escapeHtml(
              formatRelativeDate(
                submittedAt
              )
            )}
          </small>

        </span>


        <span
          class="teacher-submission-assignment"
        >
          ${escapeHtml(
            getTeacherAssignmentTitle(
              assignment ||
              {}
            )
          )}
        </span>


        <span
          class="teacher-submission-class"
        >
          ${escapeHtml(
            getTeacherClassTitle(
              classItem ||
              {}
            )
          )}
        </span>


        <span
          class="teacher-submission-status is-${escapeAttribute(status)}"
        >
          ${escapeHtml(
            getTeacherGradingStatusLabel(
              submission
            )
          )}
        </span>

      </span>

    </button>
  `;

}


/* =========================================================
   RENDER GRADING QUEUE
========================================================= */

function renderTeacherGradingSubmissionList(){

  const container =
    $(
      "teacherSubmissionList"
    );


  if (
    !container
  ){

    return false;

  }


  const submissions =
    getTeacherFilteredGradingSubmissions();


  /* =====================================================
     EMPTY
  ===================================================== */

  if (
    !submissions.length
  ){

    teacherGradingWorkspaceState
      .selectedSubmissionId =
      "";


    state.selectedSubmissionId =
      "";


    container.innerHTML = `
      <div
        class="teacher-workspace-empty teacher-grading-queue-empty"
      >

        <div
          class="teacher-workspace-empty-icon"
        >
          <i
            class="fa-solid fa-inbox"
            aria-hidden="true"
          ></i>
        </div>


        <h3>
          No submissions found
        </h3>


        <p>
          ${
            teacherGradingWorkspaceState
              .status ===
            "submitted"

              ? "There is currently no student work waiting for review."

              : "No student submissions match the current filters."
          }
        </p>


        ${
          teacherGradingWorkspaceState
            .status ===
          "submitted"

            ? `
                <button
                  type="button"
                  class="teacher-secondary-button"
                  data-teacher-action="grading-show-all"
                >
                  <i
                    class="fa-solid fa-list"
                    aria-hidden="true"
                  ></i>

                  View all submissions
                </button>
              `

            : ""
        }

      </div>
    `;


    return true;

  }


  /* =====================================================
     VALID SELECTION
  ===================================================== */

  ensureTeacherGradingSelection();


  /* =====================================================
     QUEUE ITEMS
  ===================================================== */

  container.innerHTML =
    submissions
      .map(
        createTeacherGradingQueueItem
      )
      .join(
        ""
      );


  /* =====================================================
     FALLBACK AVATARS
  ===================================================== */

  container
    .querySelectorAll(
      ".teacher-submission-list-item img"
    )
    .forEach(
      image => {

        image.onerror =
          () => {

            image.onerror =
              null;


            image.src =
              FALLBACK_AVATAR;

          };

      }
    );


  return true;

}


