/* =========================================================
   SELECT GRADING SUBMISSION
========================================================= */

function selectTeacherGradingSubmission(
  submissionId
){

  const submission =
    getTeacherSubmissionById(
      submissionId
    );


  if (
    !submission
  ){

    notifyAIFTError(
      "The selected submission is no longer available.",
      {
        title:
          "Submission unavailable"
      }
    );


    return false;

  }


  const normalizedId =
    getTeacherSubmissionId(
      submission
    );


  teacherGradingWorkspaceState
    .selectedSubmissionId =
    normalizedId;


  state.selectedSubmissionId =
    normalizedId;


  teacherGradingWorkspaceState
    .kabezyaSuggestion =
    null;


  teacherGradingWorkspaceState
    .kabezyaLoading =
    false;


  renderTeacherGradingSubmissionList();

  renderTeacherSubmissionViewer();


  /*
    On smaller screens the queue and viewer stack vertically.
    Move the teacher directly to the selected work.
  */

  if (
    window.innerWidth <=
    860
  ){

    window.requestAnimationFrame(
      () => {

        $(
          "teacherSubmissionViewer"
        )
          ?.scrollIntoView({
            behavior:
              "smooth",

            block:
              "start"
          });

      }
    );

  }


  return true;

}


/* =========================================================
   REVIEW PAYLOAD VALIDATION
========================================================= */

function buildTeacherSubmissionReviewPayload(
  submission
){

  const gradeInput =
    $(
      "teacherSubmissionGrade"
    );

  const feedbackInput =
    $(
      "teacherSubmissionFeedback"
    );

  const statusInput =
    $(
      "teacherSubmissionReviewStatus"
    );


  const rawGrade =
    safeString(
      gradeInput?.value
    );


  let grade =
    null;


  if (
    rawGrade !==
    ""
  ){

    grade =
      Number(
        rawGrade
      );


    if (
      !Number.isFinite(
        grade
      ) ||
      grade <
      0
    ){

      throw new AIFTApiError(
        "Please enter a valid non-negative grade.",
        {
          code:
            "INVALID_GRADE"
        }
      );

    }


    const assignment =
      getTeacherSubmissionAssignment(
        submission
      );

    const maximumScore =
      getTeacherAssignmentMaximumScore(
        assignment
      );


    if (
      maximumScore !==
        null &&
      grade >
        maximumScore
    ){

      throw new AIFTApiError(
        `The grade cannot be higher than ${maximumScore}.`,
        {
          code:
            "GRADE_EXCEEDS_MAXIMUM"
        }
      );

    }

  }


  const feedback =
    safeString(
      feedbackInput?.value
    );


  const status =
    safeString(
      statusInput?.value,
      "reviewed"
    )
      .toLowerCase();


  if (
    ![
      "reviewed",
      "returned"
    ].includes(
      status
    )
  ){

    throw new AIFTApiError(
      "Please select a valid review status.",
      {
        code:
          "INVALID_REVIEW_STATUS"
      }
    );

  }


  return {
    grade,
    feedback,
    status
  };

}


/* =========================================================
   REPLACE SUBMISSION IN STATE
========================================================= */

function replaceTeacherSubmissionInState(
  updatedSubmission
){

  const updatedId =
    getTeacherSubmissionId(
      updatedSubmission
    );


  if (
    !updatedId
  ){

    return false;

  }


  const index =
    state.submissions
      .findIndex(
        submission =>
          sameId(
            getTeacherSubmissionId(
              submission
            ),
            updatedId
          )
      );


  if (
    index <
    0
  ){

    state.submissions.unshift(
      updatedSubmission
    );

  }else{

    state.submissions[
      index
    ] =
      updatedSubmission;

  }


  return true;

}


/* =========================================================
   SAVE REAL SUBMISSION REVIEW

   BACKEND CONTRACT SUPPLIED FOR THIS PROJECT:

   PATCH
   /api/submissions/:id/review

   Body:
   {
     grade,
     feedback,
     status
   }

   Valid final statuses:
     reviewed
     returned

   Server-side canGrade() remains authoritative.
========================================================= */

async function saveTeacherSubmissionReview(){

  if (
    teacherGradingWorkspaceState
      .saving
  ){

    return false;

  }


  const submission =
    getTeacherSubmissionById(
      teacherGradingWorkspaceState
        .selectedSubmissionId
    );


  if (
    !submission
  ){

    notifyAIFTError(
      "Please select a submission first.",
      {
        title:
          "Nothing selected"
      }
    );


    return false;

  }


  let payload;


  try{

    payload =
      buildTeacherSubmissionReviewPayload(
        submission
      );

  }catch(
    error
  ){

    notifyAIFTError(
      getErrorMessage(
        error,
        "Please review the assessment fields."
      ),
      {
        title:
          "Assessment incomplete"
      }
    );


    return false;

  }


  teacherGradingWorkspaceState
    .saving =
    true;


  renderTeacherSubmissionViewer();


  try{

    const submissionId =
      getTeacherSubmissionId(
        submission
      );


    const response =
      await apiPatch(
        `/api/submissions/${encodeURIComponent(submissionId)}/review`,
        payload
      );


    const updatedSubmission =
      response?.submission ||
      response?.data ||
      response;


    /*
      Preferred path:
      backend returns the updated submission.
    */

    if (
      updatedSubmission &&
      getTeacherSubmissionId(
        updatedSubmission
      )
    ){

      replaceTeacherSubmissionInState(
        updatedSubmission
      );

    }else{

      /*
        Safe fallback:
        reload from authoritative backend.
      */

      await loadTeacherSubmissions();

    }


    finalizeTeacherLoadedData();


    /*
      Keep selection on the same submission after save.
    */

    teacherGradingWorkspaceState
      .selectedSubmissionId =
      submissionId;


    renderTeacherGradingSummary();

    renderTeacherGradingSubmissionList();

    renderTeacherSubmissionViewer();

    renderTeacherSubmissionsWorkspace();

    renderTeacherAssignmentsGrid();

    renderTeacherDashboardStats();

    renderTeacherGradingBadge();

    renderTeacherOverviewAssignments();

    renderTeacherOverviewActivity();


    notifyAIFTSuccess(

      payload.status ===
        "returned"
        ? "The submission was returned to the student."
        : "The student assessment was saved.",

      {
        title:
          payload.status ===
            "returned"
            ? "Work returned"
            : "Assessment saved"
      }

    );


    return true;

  }catch(
    error
  ){

    notifyAIFTError(
      getErrorMessage(
        error,
        "AIFT could not save this assessment."
      ),
      {
        title:
          "Assessment not saved"
      }
    );


    return false;

  }finally{

    teacherGradingWorkspaceState
      .saving =
      false;


    renderTeacherSubmissionViewer();

  }

}


/* =========================================================
   GRADING FILTER CONTROL BINDINGS

   Toolbar markup is dynamic, so bindings are applied after
   each toolbar render.

   Property handlers ensure one listener per element.
========================================================= */

function bindTeacherGradingFilterControls(){

  const classFilter =
    $(
      "teacherGradingClassFilter"
    );


  const assignmentFilter =
    $(
      "teacherGradingAssignmentFilter"
    );


  const statusFilter =
    $(
      "teacherGradingStatusFilter"
    );


  const search =
    $(
      "teacherGradingSearch"
    );


  /* =====================================================
     SHARED REFRESH AFTER FILTER
  ===================================================== */

  const refreshFilteredGradingView =
    ({
      toolbar =
        false,

      summary =
        true
    } = {}) => {


      /*
        If class changes, assignment choices also change.
      */

      if (
        toolbar
      ){

        renderTeacherGradingToolbar();

      }


      ensureTeacherGradingSelection();


      if (
        summary
      ){

        renderTeacherGradingSummary();

      }


      renderTeacherGradingSubmissionList();

      renderTeacherSubmissionViewer();

  };


  /* =====================================================
     CLASS
  ===================================================== */

  if (
    classFilter
  ){

    classFilter.onchange =
      event => {

        teacherGradingWorkspaceState
          .classId =
          normalizeId(
            event.target.value
          );


        /*
          Assignment must reset because its previous value may
          not belong to the newly selected class.
        */

        teacherGradingWorkspaceState
          .assignmentId =
          "";


        teacherGradingWorkspaceState
          .selectedSubmissionId =
          "";


        teacherGradingWorkspaceState
          .kabezyaSuggestion =
          null;


        refreshFilteredGradingView({
          toolbar:
            true,

          summary:
            true
        });

      };

  }


  /* =====================================================
     ASSIGNMENT
  ===================================================== */

  if (
    assignmentFilter
  ){

    assignmentFilter.onchange =
      event => {

        teacherGradingWorkspaceState
          .assignmentId =
          normalizeId(
            event.target.value
          );


        teacherGradingWorkspaceState
          .selectedSubmissionId =
          "";


        teacherGradingWorkspaceState
          .kabezyaSuggestion =
          null;


        refreshFilteredGradingView({
          summary:
            true
        });

      };

  }


  /* =====================================================
     STATUS
  ===================================================== */

  if (
    statusFilter
  ){

    statusFilter.onchange =
      event => {

        const requested =
          safeString(
            event.target.value,
            "submitted"
          )
            .toLowerCase();


        teacherGradingWorkspaceState
          .status =
          [
            "all",
            "submitted",
            "reviewed",
            "returned"
          ].includes(
            requested
          )
            ? requested
            : "submitted";


        teacherGradingWorkspaceState
          .selectedSubmissionId =
          "";


        teacherGradingWorkspaceState
          .kabezyaSuggestion =
          null;


        refreshFilteredGradingView({
          summary:
            false
        });

      };

  }


  /* =====================================================
     SEARCH
  ===================================================== */

  if (
    search
  ){

    search.oninput =
      event => {

        teacherGradingWorkspaceState
          .search =
          safeString(
            event.target.value
          );


        /*
          Do not force-clear the selected submission.

          ensureTeacherGradingSelection() retains it if it still
          matches, otherwise moves to the first matching result.
        */

        ensureTeacherGradingSelection();

        renderTeacherGradingSubmissionList();

        renderTeacherSubmissionViewer();

      };

  }

}


/* =========================================================
   OPEN GRADING FOR A SUBMISSION

   Used by the central action controller when the teacher
   clicks Review from the Submissions page.
========================================================= */

function prepareTeacherGradingSubmission(
  submissionId
){

  const submission =
    getTeacherSubmissionById(
      submissionId
    );


  if (
    !submission
  ){

    return false;

  }


  teacherGradingWorkspaceState
    .classId =
    getTeacherSubmissionClassId(
      submission
    );

  teacherGradingWorkspaceState
    .assignmentId =
    getTeacherSubmissionAssignmentId(
      submission
    );

  teacherGradingWorkspaceState
    .status =
    "all";

  teacherGradingWorkspaceState
    .selectedSubmissionId =
    getTeacherSubmissionId(
      submission
    );


  return true;

}


/* =========================================================
   OPEN GRADING FOR AN ASSIGNMENT
========================================================= */

function prepareTeacherGradingAssignment(
  assignmentId
){

  const assignment =
    getTeacherAssignments()
      .find(
        item =>
          sameId(
            item?._id ||
            item?.id,
            assignmentId
          )
      );


  if (
    !assignment
  ){

    return false;

  }


  teacherGradingWorkspaceState
    .classId =
    normalizeId(
      assignment
        ?.classId
        ?._id ||
      assignment
        ?.classId
    );

  teacherGradingWorkspaceState
    .assignmentId =
    normalizeId(
      assignment?._id ||
      assignment?.id
    );

  teacherGradingWorkspaceState
    .status =
    "submitted";

  teacherGradingWorkspaceState
    .selectedSubmissionId =
    "";


  return true;

}


/* =========================================================
   OPEN GRADING FOR CLASS
========================================================= */

function prepareTeacherGradingClass(
  classId
){

  if (
    !getTeacherClassById(
      classId
    )
  ){

    return false;

  }


  teacherGradingWorkspaceState
    .classId =
    normalizeId(
      classId
    );

  teacherGradingWorkspaceState
    .assignmentId =
    "";

  teacherGradingWorkspaceState
    .status =
    "submitted";

  teacherGradingWorkspaceState
    .selectedSubmissionId =
    "";


  return true;

}


/* =========================================================
   REFRESH GRADING
========================================================= */

async function refreshTeacherGradingWorkspace(){

  if (
    teacherGradingWorkspaceState
      .refreshing
  ){

    return false;

  }


  teacherGradingWorkspaceState
    .refreshing =
    true;


  renderTeacherGradingHeader();


  try{

    const results =
      await Promise.allSettled([

        loadTeacherAssignments(),

        loadTeacherSubmissions()

      ]);


    results.forEach(
      (
        result,
        index
      ) => {

        if (
          result.status ===
          "rejected"
        ){

          reportOptionalRequestError(
            [
              "Assignments",
              "Submissions"
            ][index],
            result.reason
          );

        }

      }
    );


    finalizeTeacherLoadedData();


    /*
      If selected submission no longer exists, clear it.
    */

    if (
      teacherGradingWorkspaceState
        .selectedSubmissionId &&
      !getTeacherSubmissionById(
        teacherGradingWorkspaceState
          .selectedSubmissionId
      )
    ){

      teacherGradingWorkspaceState
        .selectedSubmissionId =
        "";

    }


    renderTeacherGradingWorkspace();

    renderTeacherDashboardStats();

    renderTeacherGradingBadge();


    notifyAIFTSuccess(
      "The grading queue is up to date.",
      {
        title:
          "Grading refreshed"
      }
    );


    return true;

  }catch(
    error
  ){

    notifyAIFTError(
      getErrorMessage(
        error,
        "The grading queue could not be refreshed."
      ),
      {
        title:
          "Refresh failed"
      }
    );


    return false;

  }finally{

    teacherGradingWorkspaceState
      .refreshing =
      false;


    renderTeacherGradingHeader();

  }

}


/* =========================================================
   RENDER COMPLETE GRADING WORKSPACE
========================================================= */

function renderTeacherGradingWorkspace(){

  renderTeacherGradingHeader();

  renderTeacherGradingToolbar();

  renderTeacherGradingSummary();


  /*
    Keep a real submission selected whenever the current
    filters contain work.
  */

  ensureTeacherGradingSelection();


  renderTeacherGradingSubmissionList();

  renderTeacherSubmissionViewer();


  return true;

}


/* =========================================================
   INITIALIZE GRADING WORKSPACE
========================================================= */

function initializeTeacherGradingWorkspace(){

  if (
    teacherGradingWorkspaceState
      .initialized
  ){

    renderTeacherGradingWorkspace();

    return;

  }


  teacherGradingWorkspaceState
    .initialized =
    true;


  /*
    Default to work that needs teacher attention.
  */

  if (
    !teacherGradingWorkspaceState
      .status
  ){

    teacherGradingWorkspaceState
      .status =
      "submitted";

  }


  renderTeacherGradingWorkspace();

}


/* =========================================================
   UPDATE GRADING UI FROM CURRENT STATE
========================================================= */

function refreshTeacherGradingFromCurrentState(){

  renderTeacherGradingSummary();

  renderTeacherGradingSubmissionList();

  renderTeacherSubmissionViewer();

  renderTeacherGradingBadge();

}


/* =========================================================
   PART 7 COMPLETE

   REAL MUTATION PATH:
   PATCH /api/submissions/:id/review

   No separate grading API helper exists.

   No client-side authorization is treated as security.

   No AI suggestion is automatically saved.

   No Kabezya endpoint has been invented.

   The authoritative Studio action controller will later map:

     select-grading-submission
       -> selectTeacherGradingSubmission()

     save-submission-review
       -> saveTeacherSubmissionReview()

     refresh-grading
       -> refreshTeacherGradingWorkspace()

     review-submission
       -> prepareTeacherGradingSubmission()
          + navigate to grading

     assignment-submissions
       -> prepareTeacherGradingAssignment()
          + navigate to grading

     class-grading
       -> prepareTeacherGradingClass()
          + navigate to grading

     kabezya-review-submission
       -> verified Kabezya review lifecycle
          in the dedicated AI part
========================================================= */
/* =========================================================
   AIFT TEACHER STUDIO
   PRODUCTION REPLACEMENT
   PART 8

   ATTENDANCE WORKSPACE
   ---------------------------------------------------------
   1. Attendance workspace state
   2. Date/status normalization
   3. Selected-class roster
   4. Record lookup
   5. Attendance summary
   6. Dynamic header
   7. Dynamic toolbar
   8. Existing bulk-action design
   9. Existing roster design
   10. Student history
   11. Real POST /api/attendance upsert
   12. Single-status updates
   13. Bulk attendance
   14. Refresh lifecycle
   15. Attendance initialization

   SECURITY MODEL
   ---------------------------------------------------------
   Frontend checks improve UX only.

   routes/attendance.js remains authoritative.

   The server:
   - authenticates the user
   - loads the real class
   - confirms assigned-teacher permission
   - confirms student enrollment
   - derives schoolId from the class
   - derives teacherId from the class
========================================================= */


/* =========================================================
   ATTENDANCE WORKSPACE STATE
   PRODUCTION SESSION-AWARE VERSION

   classId
     identifies the authorized Teacher class.

   date
     remains useful for manual/non-scheduled attendance.

   scheduleId
     identifies one exact scheduled teaching session.

   When scheduleId exists:
     Attendance identity = schedule + student.

   When scheduleId is empty:
     Attendance identity = class + student + date.
========================================================= */

const teacherAttendanceWorkspaceState = {

  classId:
    "",


  scheduleId:
    "",


  date:
    getTeacherLocalDateInputValue(),


  search:
    "",


  selectedStudentId:
    "",


  savingStudentIds:
    new Set(),


  bulkSaving:
    false,


  loading:
    false,


  initialized:
    false

};


/* =========================================================
   ACTIVE ATTENDANCE SCHEDULE
========================================================= */

function getTeacherAttendanceSelectedSchedule(){

  const scheduleId =
    normalizeId(
      teacherAttendanceWorkspaceState
        .scheduleId
    );


  if (
    !scheduleId
  ){

    return null;

  }


  return (
    getTeacherScheduleById(
      scheduleId
    ) ||
    null
  );

}


/* =========================================================
   ATTENDANCE IS SCHEDULE-BOUND
========================================================= */

function isTeacherScheduledAttendance(){

  return Boolean(
    normalizeId(
      teacherAttendanceWorkspaceState
        .scheduleId
    )
  );

}


/* =========================================================
   CLEAR SCHEDULE CONTEXT

   Used when Teacher manually switches to another class/date.
========================================================= */

function clearTeacherAttendanceScheduleContext(){

  teacherAttendanceWorkspaceState
    .scheduleId =
    "";

}

/* =========================================================
   ATTENDANCE SESSION LOCK STATE

   Scheduled Attendance remains editable only while the
   authoritative Schedule is actively started.

   Completed / missed / cancelled sessions are review-only.
========================================================= */

function isTeacherAttendanceFinalized(){

  const schedule =
    getTeacherAttendanceSelectedSchedule();


  if (
    !schedule
  ){

    return false;

  }


  const status =
    getTeacherScheduleStatus(
      schedule
    );


  return (
    schedule.attendanceFinalized ===
      true ||
    status ===
      "completed"
  );

}


/* =========================================================
   ATTENDANCE READ-ONLY STATE
========================================================= */

function isTeacherAttendanceReadOnly(){

  const schedule =
    getTeacherAttendanceSelectedSchedule();


  if (
    !schedule
  ){

    return false;

  }


  const status =
    getTeacherScheduleStatus(
      schedule
    );


  return (
    schedule.attendanceFinalized ===
      true ||
    [
      "completed",
      "missed",
      "cancelled"
    ].includes(
      status
    )
  );

}


/* =========================================================
   LOCAL DATE FOR <input type="date">

   Do not use new Date().toISOString().slice(0,10) here.

   ISO date is UTC and can show the wrong calendar date near
   midnight in the teacher's local timezone.
========================================================= */

function getTeacherLocalDateInputValue(
  value = new Date()
){

  const date =
    value instanceof Date
      ? value
      : toValidDate(
          value
        );


  if (
    !date
  ){

    return "";

  }


  const year =
    date.getFullYear();

  const month =
    String(
      date.getMonth() +
      1
    ).padStart(
      2,
      "0"
    );

  const day =
    String(
      date.getDate()
    ).padStart(
      2,
      "0"
    );


  return `${year}-${month}-${day}`;

}


/* =========================================================
   VALID DATE INPUT VALUE
========================================================= */

function normalizeTeacherAttendanceDate(
  value
){

  const normalized =
    safeString(
      value
    );


  if (
    !/^\d{4}-\d{2}-\d{2}$/.test(
      normalized
    )
  ){

    return "";

  }


  const [
    year,
    month,
    day
  ] =
    normalized
      .split(
        "-"
      )
      .map(
        Number
      );


  const date =
    new Date(
      year,
      month - 1,
      day
    );


  if (
    Number.isNaN(
      date.getTime()
    ) ||
    date.getFullYear() !==
      year ||
    date.getMonth() !==
      month - 1 ||
    date.getDate() !==
      day
  ){

    return "";

  }


  return normalized;

}


/* =========================================================
   DATE FOR ATTENDANCE API

   Backend normalizes attendance dates to the start of day.

   Use one stable ISO representation for the selected calendar
   day rather than allowing browser-specific date parsing.
========================================================= */

function getTeacherAttendanceApiDate(
  value
){

  const normalized =
    normalizeTeacherAttendanceDate(
      value
    );


  if (
    !normalized
  ){

    return "";

  }


  return `${normalized}T00:00:00.000Z`;

}


/* =========================================================
   NORMALIZE ATTENDANCE STATUS
========================================================= */

function normalizeTeacherAttendanceStatus(
  value
){

  const status =
    safeString(
      value
    )
      .toLowerCase();


  if (
    [
      "present",
      "late",
      "absent",
      "excused"
    ].includes(
      status
    )
  ){

    return status;

  }


  return "";

}


/* =========================================================
   ATTENDANCE STATUS LABEL
========================================================= */

function getTeacherAttendanceStatusLabel(
  value
){

  switch(
    normalizeTeacherAttendanceStatus(
      value
    )
  ){

    case "present":

      return "Present";

    case "late":

      return "Late";

    case "absent":

      return "Absent";

    case "excused":

      return "Excused";

    default:

      return "Not marked";

  }

}


/* =========================================================
   ATTENDANCE STATUS ICON
========================================================= */

function getTeacherAttendanceStatusIcon(
  value
){

  switch(
    normalizeTeacherAttendanceStatus(
      value
    )
  ){

    case "present":

      return "fa-solid fa-check";

    case "late":

      return "fa-regular fa-clock";

    case "absent":

      return "fa-solid fa-xmark";

    case "excused":

      return "fa-solid fa-circle-info";

    default:

      return "fa-regular fa-circle";

  }

}


/* =========================================================
   SELECTED ATTENDANCE CLASS
========================================================= */

function getTeacherAttendanceSelectedClass(){

  const classId =
    normalizeId(
      teacherAttendanceWorkspaceState
        .classId
    );


  if (
    !classId
  ){

    return null;

  }


  return getTeacherClassById(
    classId
  );

}


/* =========================================================
   STUDENTS IN ONE TEACHER CLASS

   Class.studentIds is populated by the current classes route.
========================================================= */

function getTeacherAttendanceClassStudents(
  classId
){

  const classItem =
    getTeacherClassById(
      classId
    );


  if (
    !classItem
  ){

    return [];

  }


  const students =
    [];


  asArray(
    classItem.studentIds
  )
    .forEach(
      value => {

        const studentId =
          normalizeId(
            value?._id ||
            value?.id ||
            value
          );


        if (
          !studentId
        ){

          return;

        }


        let student =
          value;


        if (
          typeof value !==
          "object"
        ){

          const normalizedRecord =
            getTeacherStudentById(
              studentId
            );


          student =
            normalizedRecord
              ?.student ||
            {
              _id:
                studentId
            };

        }


        students.push({
          ...student,

          _id:
            studentId
        });

      }
    );


  return uniqueById(
    students
  );

}


/* =========================================================
   FILTERED ATTENDANCE ROSTER
========================================================= */

function getTeacherAttendanceRoster(){

  const classId =
    normalizeId(
      teacherAttendanceWorkspaceState
        .classId
    );


  if (
    !classId
  ){

    return [];

  }


  const search =
    safeString(
      teacherAttendanceWorkspaceState
        .search
    )
      .toLowerCase();


  let students =
    getTeacherAttendanceClassStudents(
      classId
    );


  if (
    search
  ){

    students =
      students.filter(
        student => {

          const haystack =
            [

              student?.name,
              student?.fullName,
              student?.displayName,
              student?.email,
              student?.course,
              student?.program

            ]
              .filter(
                Boolean
              )
              .join(
                " "
              )
              .toLowerCase();


          return haystack.includes(
            search
          );

        }
      );

  }


  students.sort(
    (
      first,
      second
    ) =>
      safeString(
        first?.name ||
        first?.fullName ||
        first?.displayName,
        "Student"
      )
        .localeCompare(
          safeString(
            second?.name ||
            second?.fullName ||
            second?.displayName,
            "Student"
          )
        )
  );


  return students;

}


/* =========================================================
   ATTENDANCE RECORD DATE KEY
========================================================= */

function getTeacherAttendanceRecordDateKey(
  record
){

  const date =
    toValidDate(
      record?.date
    );


  if (
    !date
  ){

    return "";

  }


  /*
    Attendance backend dates are normalized to day boundaries.

    Build the key from UTC components because POST uses the
    corresponding UTC-midnight representation.
  */

  const year =
    date.getUTCFullYear();

  const month =
    String(
      date.getUTCMonth() +
      1
    ).padStart(
      2,
      "0"
    );

  const day =
    String(
      date.getUTCDate()
    ).padStart(
      2,
      "0"
    );


  return `${year}-${month}-${day}`;

}

/* =========================================================
   GET ATTENDANCE RECORD
   SESSION-AWARE IDENTITY

   Scheduled:
     scheduleId + studentId

   Manual:
     classId + studentId + date
========================================================= */

function getTeacherAttendanceRecord(
  classId,
  studentId,
  date,
  scheduleId =
    teacherAttendanceWorkspaceState
      .scheduleId
){

  const normalizedClassId =
    normalizeId(
      classId
    );


  const normalizedStudentId =
    normalizeId(
      studentId
    );


  const normalizedDate =
    normalizeTeacherAttendanceDate(
      date
    );


  const normalizedScheduleId =
    normalizeId(
      scheduleId
    );


  if (
    !normalizedClassId ||
    !normalizedStudentId
  ){

    return null;

  }


  /* =====================================================
     SCHEDULED ATTENDANCE
  ===================================================== */

  if (
    normalizedScheduleId
  ){

    return (
      getTeacherAttendance()
        .find(
          record => {

            const recordClassId =
              normalizeId(
                record
                  ?.classId
                  ?._id ||
                record
                  ?.classId
              );


            const recordStudentId =
              normalizeId(
                record
                  ?.studentId
                  ?._id ||
                record
                  ?.studentId
              );


            const recordScheduleId =
              normalizeId(
                record
                  ?.scheduleId
                  ?._id ||
                record
                  ?.scheduleId
              );


            return (
              sameId(
                recordClassId,
                normalizedClassId
              ) &&
              sameId(
                recordStudentId,
                normalizedStudentId
              ) &&
              sameId(
                recordScheduleId,
                normalizedScheduleId
              )
            );

          }
        ) ||
      null
    );

  }


  /* =====================================================
     MANUAL ATTENDANCE
  ===================================================== */

  if (
    !normalizedDate
  ){

    return null;

  }


  return (
    getTeacherAttendance()
      .find(
        record => {

          const recordClassId =
            normalizeId(
              record
                ?.classId
                ?._id ||
              record
                ?.classId
            );


          const recordStudentId =
            normalizeId(
              record
                ?.studentId
                ?._id ||
              record
                ?.studentId
            );


          const recordScheduleId =
            normalizeId(
              record
                ?.scheduleId
                ?._id ||
              record
                ?.scheduleId
            );


          /*
            Manual mode must not accidentally grab an Attendance
            record belonging to a scheduled session.
          */

          return (
            sameId(
              recordClassId,
              normalizedClassId
            ) &&
            sameId(
              recordStudentId,
              normalizedStudentId
            ) &&
            !recordScheduleId &&
            getTeacherAttendanceRecordDateKey(
              record
            ) ===
              normalizedDate
          );

        }
      ) ||
    null
  );

}


/* =========================================================
   RECORDS FOR STUDENT
========================================================= */

function getTeacherAttendanceStudentRecords(
  studentId
){

  const normalizedStudentId =
    normalizeId(
      studentId
    );


  if (
    !normalizedStudentId
  ){

    return [];

  }


  return getTeacherAttendance()
    .filter(
      record => {

        const recordStudentId =
          normalizeId(
            record
              ?.studentId
              ?._id ||
            record
              ?.studentId
          );


        return sameId(
          recordStudentId,
          normalizedStudentId
        );

      }
    )
    .sort(
      (
        first,
        second
      ) =>
        (
          toValidDate(
            second?.date
          )?.getTime() ||
          0
        ) -
        (
          toValidDate(
            first?.date
          )?.getTime() ||
          0
        )
    );

}


/* =========================================================
   ATTENDANCE UI ENGINE
   PRODUCTION RESTORATION

   IMPORTANT
   ---------------------------------------------------------

   This block restores the renderer functions required by:

     renderTeacherAttendanceWorkspace()

   It uses the Attendance state/helpers that already exist
   above this block.

   It does NOT introduce another Attendance state system.
========================================================= */


/* =========================================================
   STUDENT DISPLAY NAME
========================================================= */

function getTeacherAttendanceStudentName(
  student
){

  return safeString(

    student?.name ||
    student?.fullName ||
    student?.displayName ||
    student?.email,

    "Student"

  );

}


/* =========================================================
   STUDENT AVATAR
========================================================= */

function getTeacherAttendanceStudentAvatar(
  student
){

  return getSafeImageUrl(

    student?.profileImage ||
    student?.avatar ||
    student?.photoURL ||
    student?.image,

    FALLBACK_AVATAR

  );

}


/* =========================================================
   ATTENDANCE SUMMARY DATA
========================================================= */

function getTeacherAttendanceSummary(){

  const classId =
    normalizeId(
      teacherAttendanceWorkspaceState
        .classId
    );


  const scheduleId =
    normalizeId(
      teacherAttendanceWorkspaceState
        .scheduleId
    );


  const date =
    normalizeTeacherAttendanceDate(
      teacherAttendanceWorkspaceState
        .date
    );


  const students =
    getTeacherAttendanceClassStudents(
      classId
    );


  const summary = {

    total:
      students.length,

    present:
      0,

    late:
      0,

    absent:
      0,

    excused:
      0,

    pending:
      0,

    unmarked:
      0,

    recorded:
      0,

    attendanceRate:
      0

  };


  if (
    !classId ||
    !students.length
  ){

    return summary;

  }


  students.forEach(
    student => {

      const studentId =
        normalizeId(
          student?._id ||
          student?.id
        );


      if (
        !studentId
      ){

        return;

      }


      const record =
        getTeacherAttendanceRecord(
          classId,
          studentId,
          date,
          scheduleId
        );


      if (
        !record
      ){

        summary.unmarked +=
          1;

        return;

      }


      const rawStatus =
        safeString(
          record.status
        )
          .toLowerCase();


      if (
        rawStatus ===
        "pending"
      ){

        summary.pending +=
          1;

        return;

      }


      const status =
        normalizeTeacherAttendanceStatus(
          rawStatus
        );


      if (
        !status
      ){

        summary.unmarked +=
          1;

        return;

      }


      summary.recorded +=
        1;


      if (
        Object.prototype
          .hasOwnProperty
          .call(
            summary,
            status
          )
      ){

        summary[
          status
        ] +=
          1;

      }

    }
  );


  const positiveAttendance =
    summary.present +
    summary.late +
    summary.excused;


  summary.attendanceRate =
    summary.recorded
      ? Math.round(
          (
            positiveAttendance /
            summary.recorded
          ) *
          100
        )
      : 0;


  return summary;

}


