/* =========================================================
   ATTENDANCE STATUS BUTTON
========================================================= */

function createTeacherAttendanceStatusButton(
  {
    studentId,
    status,
    activeStatus,
    saving
  }
){

  const active =
    status ===
    activeStatus;


  const readOnly =
    isTeacherAttendanceReadOnly();


  const disabled =
    Boolean(
      saving ||
      readOnly
    );


  return `

    <button
      type="button"
      class="
        teacher-attendance-status-button
        is-${escapeAttribute(status)}

        ${
          active
            ? "active"
            : ""
        }

        ${
          readOnly
            ? "is-readonly"
            : ""
        }
      "
      data-teacher-action="set-attendance-status"
      data-student-id="${escapeAttribute(studentId)}"
      data-attendance-status="${escapeAttribute(status)}"
      aria-pressed="${active ? "true" : "false"}"
      ${
        disabled
          ? "disabled"
          : ""
      }
    >

      <i
        class="${escapeAttribute(
          getTeacherAttendanceStatusIcon(
            status
          )
        )}"
        aria-hidden="true"
      ></i>


      ${escapeHtml(
        getTeacherAttendanceStatusLabel(
          status
        )
      )}

    </button>

  `;

}


/* =========================================================
   ATTENDANCE STUDENT ROW
========================================================= */

function createTeacherAttendanceStudentRow(
  student
){

  const classId =
    normalizeId(
      teacherAttendanceWorkspaceState
        .classId
    );


  const scheduleId =
    normalizeId(
      teacherAttendanceWorkspaceState
        .scheduleId
    );


  const studentId =
    normalizeId(
      student?._id ||
      student?.id
    );


  const date =
    teacherAttendanceWorkspaceState
      .date;


  const record =
    getTeacherAttendanceRecord(
      classId,
      studentId,
      date,
      scheduleId
    );


  const rawStatus =
    safeString(
      record?.status
    )
      .toLowerCase();


  const currentStatus =
    normalizeTeacherAttendanceStatus(
      rawStatus
    );


  const pending =
    rawStatus ===
    "pending";


  const saving =
    teacherAttendanceWorkspaceState
      .savingStudentIds
      .has(
        studentId
      );


  const readOnly =
    isTeacherAttendanceReadOnly();


  const studentName =
    getTeacherAttendanceStudentName(
      student
    );


  const email =
    safeString(
      student?.email,
      "Student"
    );


  const avatar =
    getTeacherAttendanceStudentAvatar(
      student
    );


  return `

    <div
      class="
        teacher-attendance-student-row
        ${
          readOnly
            ? "is-readonly"
            : ""
        }
      "
      data-student-id="${escapeAttribute(studentId)}"
    >

      <button
        type="button"
        class="teacher-attendance-student-main"
        data-teacher-action="attendance-student-history"
        data-student-id="${escapeAttribute(studentId)}"
      >

        <img
          src="${escapeAttribute(avatar)}"
          alt=""
          loading="lazy"
          referrerpolicy="no-referrer"
          onerror="this.onerror=null;this.src='${escapeAttribute(FALLBACK_AVATAR)}';"
        />


        <span>

          <strong>
            ${escapeHtml(studentName)}
          </strong>

          <small>
            ${escapeHtml(email)}
          </small>

        </span>

      </button>


      <div
        class="teacher-attendance-status-options"
      >

        ${
          [
            "present",
            "late",
            "absent",
            "excused"
          ]
            .map(
              status =>
                createTeacherAttendanceStatusButton({
                  studentId,
                  status,
                  activeStatus:
                    currentStatus,
                  saving
                })
            )
            .join(
              ""
            )
        }

      </div>


      <div
        class="teacher-attendance-record-meta"
      >

        <span
          class="${
            pending
              ? "is-pending"
              : ""
          }"
        >

          ${
            pending
              ? "Pending"
              : currentStatus
                ? escapeHtml(
                    getTeacherAttendanceStatusLabel(
                      currentStatus
                    )
                  )
                : "Not marked"
          }

        </span>


        <small>

          ${
            record?.updatedAt ||
            record?.createdAt
              ? escapeHtml(
                  formatRelativeDate(
                    record.updatedAt ||
                    record.createdAt
                  )
                )
              : "No record"
          }

        </small>

      </div>

    </div>

  `;

}


/* =========================================================
   ATTENDANCE ROSTER
========================================================= */

function renderTeacherAttendanceRoster(){

  const container =
    $(
      "teacherAttendanceRoster"
    );


  if (
    !container
  ){

    return false;

  }


  const classItem =
    getTeacherAttendanceSelectedClass();


  if (
    !classItem
  ){

    container.innerHTML = `

      <div
        class="teacher-empty-state"
      >

        <i
          class="fa-solid fa-user-check"
          aria-hidden="true"
        ></i>


        <strong>
          Select a class
        </strong>


        <p>
          Choose one of your assigned classes to view its attendance roster.
        </p>

      </div>

    `;


    return true;

  }


  if (
    teacherAttendanceWorkspaceState
      .loading
  ){

    container.innerHTML = `

      <div
        class="teacher-empty-state"
      >

        <i
          class="fa-solid fa-spinner fa-spin"
          aria-hidden="true"
        ></i>

        <strong>
          Loading attendance
        </strong>

        <p>
          Retrieving the latest attendance records.
        </p>

      </div>

    `;


    return true;

  }


  const students =
    getTeacherAttendanceRoster();


  if (
    !students.length
  ){

    container.innerHTML = `

      <div
        class="teacher-empty-state"
      >

        <i
          class="fa-solid fa-users"
          aria-hidden="true"
        ></i>


        <strong>
          No students found
        </strong>


        <p>
          ${
            teacherAttendanceWorkspaceState
              .search
              ? "No students match the current search."
              : "No students are currently enrolled in this class."
          }
        </p>

      </div>

    `;


    return true;

  }


  container.innerHTML =
    students
      .map(
        student =>
          createTeacherAttendanceStudentRow(
            student
          )
      )
      .join(
        ""
      );


  return true;

}


/* =========================================================
   ATTENDANCE STUDENT HISTORY
========================================================= */

function renderTeacherAttendanceStudentHistory(
  studentId =
    teacherAttendanceWorkspaceState
      .selectedStudentId
){

  const container =
    $(
      "teacherAttendanceStudentHistory"
    );


  if (
    !container
  ){

    return false;

  }


  const normalizedStudentId =
    normalizeId(
      studentId
    );


  if (
    !normalizedStudentId
  ){

    container.innerHTML =
      "";

    container.hidden =
      true;


    return true;

  }


  teacherAttendanceWorkspaceState
    .selectedStudentId =
    normalizedStudentId;


  const studentRecord =
    getTeacherStudentById(
      normalizedStudentId
    );


  const student =
    studentRecord?.student ||
    getTeacherAttendanceClassStudents(
      teacherAttendanceWorkspaceState
        .classId
    )
      .find(
        candidate =>
          sameId(
            candidate?._id ||
            candidate?.id,
            normalizedStudentId
          )
      ) ||
    {
      _id:
        normalizedStudentId
    };


  const records =
    getTeacherAttendanceStudentRecords(
      normalizedStudentId
    );


  const name =
    getTeacherAttendanceStudentName(
      student
    );


  const avatar =
    getTeacherAttendanceStudentAvatar(
      student
    );


  container.hidden =
    false;


  container.innerHTML = `

    <div
      class="teacher-attendance-history-card"
    >

      <div
        class="teacher-attendance-history-head"
      >

        <div
          class="teacher-attendance-history-student"
        >

          <img
            src="${escapeAttribute(avatar)}"
            alt=""
            onerror="this.onerror=null;this.src='${escapeAttribute(FALLBACK_AVATAR)}';"
          />


          <div>

            <strong>
              ${escapeHtml(name)}
            </strong>

            <span>
              Attendance history
            </span>

          </div>

        </div>


        <button
          type="button"
          class="teacher-icon-button"
          data-teacher-action="close-attendance-history"
          aria-label="Close attendance history"
        >

          <i
            class="fa-solid fa-xmark"
            aria-hidden="true"
          ></i>

        </button>

      </div>


      <div
        class="teacher-attendance-history-list"
      >

        ${
          records.length
            ? records
                .slice(
                  0,
                  30
                )
                .map(
                  record => {

                    const rawStatus =
                      safeString(
                        record?.status
                      )
                        .toLowerCase();


                    const status =
                      rawStatus ===
                      "pending"
                        ? "pending"
                        : normalizeTeacherAttendanceStatus(
                            rawStatus
                          );


                    return `

                      <div
                        class="teacher-attendance-history-item"
                      >

                        <span>

                          <strong>
                            ${escapeHtml(
                              formatDate(
                                record?.date,
                                "No date"
                              )
                            )}
                          </strong>

                          <small>
                            ${
                              record?.scheduleId
                                ? "Scheduled session"
                                : "Manual attendance"
                            }
                          </small>

                        </span>


                        <span
                          class="
                            teacher-attendance-history-status
                            is-${escapeAttribute(
                              status ||
                              "unmarked"
                            )}
                          "
                        >

                          ${
                            status ===
                            "pending"
                              ? "Pending"
                              : escapeHtml(
                                  getTeacherAttendanceStatusLabel(
                                    status
                                  )
                                )
                          }

                        </span>

                      </div>

                    `;

                  }
                )
                .join(
                  ""
                )
            : `

              <div
                class="teacher-empty-state compact"
              >

                <span>
                  No attendance history is available yet.
                </span>

              </div>

            `
        }

      </div>

    </div>

  `;


  return true;

}


/* =========================================================
   BUILD ATTENDANCE WRITE PAYLOAD

   SECURITY
   ---------------------------------------------------------

   Frontend DOES NOT send:

     schoolId
     teacherId
     markedBy

   Backend derives them from authenticated Teacher + Class.

   SESSION MODE
   ---------------------------------------------------------

   We DO send scheduleId because it identifies which authorized
   class session the attendance belongs to.

   Backend validates the Schedule/Class relationship.
========================================================= */

function buildTeacherAttendancePayload(
  studentId,
  status
){

  const classId =
    normalizeId(
      teacherAttendanceWorkspaceState
        .classId
    );


  const scheduleId =
    normalizeId(
      teacherAttendanceWorkspaceState
        .scheduleId
    );


  const normalizedStudentId =
    normalizeId(
      studentId
    );


  const normalizedStatus =
    normalizeTeacherAttendanceStatus(
      status
    );


  const date =
    getTeacherAttendanceApiDate(
      teacherAttendanceWorkspaceState
        .date
    );


  if (
    !classId
  ){

    throw new AIFTApiError(
      "Please select a class first.",
      {
        code:
          "ATTENDANCE_CLASS_REQUIRED"
      }
    );

  }


  const classItem =
    getTeacherClassById(
      classId
    );


  if (
    !classItem
  ){

    throw new AIFTApiError(
      "The selected class is not available to this Teacher.",
      {
        code:
          "ATTENDANCE_CLASS_UNAVAILABLE"
      }
    );

  }


  if (
    !normalizedStudentId
  ){

    throw new AIFTApiError(
      "The selected student could not be identified.",
      {
        code:
          "ATTENDANCE_STUDENT_REQUIRED"
      }
    );

  }


  const enrolled =
    getTeacherAttendanceClassStudents(
      classId
    )
      .some(
        student =>
          sameId(
            student?._id ||
            student?.id,
            normalizedStudentId
          )
      );


  if (
    !enrolled
  ){

    throw new AIFTApiError(
      "The selected student is not enrolled in this class.",
      {
        code:
          "ATTENDANCE_STUDENT_NOT_ENROLLED"
      }
    );

  }


  if (
    !date
  ){

    throw new AIFTApiError(
      "Please select a valid attendance date.",
      {
        code:
          "ATTENDANCE_DATE_REQUIRED"
      }
    );

  }


  if (
    !normalizedStatus
  ){

    throw new AIFTApiError(
      "Please select a valid attendance status.",
      {
        code:
          "ATTENDANCE_STATUS_INVALID"
      }
    );

  }


  /* =====================================================
     VALIDATE SCHEDULE CONTEXT LOCALLY
  ===================================================== */

  if (
    scheduleId
  ){

    const schedule =
      getTeacherScheduleById(
        scheduleId
      );


    if (
      !schedule
    ){

      throw new AIFTApiError(
        "The selected teaching session is no longer available.",
        {
          code:
            "ATTENDANCE_SCHEDULE_UNAVAILABLE"
        }
      );

    }


    if (
      !sameId(
        getTeacherScheduleClassId(
          schedule
        ),
        classId
      )
    ){

      throw new AIFTApiError(
        "This Schedule does not belong to the selected class.",
        {
          code:
            "ATTENDANCE_SCHEDULE_CLASS_MISMATCH"
        }
      );

    }

  }


  return {

    classId,


    studentId:
      normalizedStudentId,


    scheduleId:
      scheduleId ||
      null,


    date,


    status:
      normalizedStatus,


    source:
      scheduleId
        ? "schedule"
        : "manual"

  };

}

/* =========================================================
   REPLACE ATTENDANCE RECORD IN STATE

   Match primarily by returned _id.

   Fall back to the unique attendance identity:
     classId + studentId + date
========================================================= */

function replaceTeacherAttendanceRecordInState(
  savedRecord
){

  if (
    !savedRecord ||
    typeof savedRecord !==
      "object"
  ){

    return false;

  }


  const recordId =
    normalizeId(
      savedRecord._id ||
      savedRecord.id
    );

  const classId =
    normalizeId(
      savedRecord
        ?.classId
        ?._id ||
      savedRecord
        ?.classId
    );

  const studentId =
    normalizeId(
      savedRecord
        ?.studentId
        ?._id ||
      savedRecord
        ?.studentId
    );

  const dateKey =
    getTeacherAttendanceRecordDateKey(
      savedRecord
    );


  let index =
    -1;


  if (
    recordId
  ){

    index =
      state.attendance
        .findIndex(
          record =>
            sameId(
              record?._id ||
              record?.id,
              recordId
            )
        );

  }


  if (
    index <
    0 &&
    classId &&
    studentId &&
    dateKey
  ){

    index =
      state.attendance
        .findIndex(
          record =>
            sameId(
              record
                ?.classId
                ?._id ||
              record
                ?.classId,
              classId
            ) &&
            sameId(
              record
                ?.studentId
                ?._id ||
              record
                ?.studentId,
              studentId
            ) &&
            getTeacherAttendanceRecordDateKey(
              record
            ) ===
            dateKey
        );

  }


  if (
    index >=
    0
  ){

    state.attendance[
      index
    ] =
      savedRecord;

  }else{

    state.attendance.unshift(
      savedRecord
    );

  }


  return true;

}


/* =========================================================
   SAVE ONE ATTENDANCE RECORD

   CURRENT BACKEND POST IS ALREADY AN UPSERT.

   This is important.

   The backend uses findOneAndUpdate() keyed by:
     schoolId
     classId
     studentId
     date

   Therefore Teacher Studio does NOT need to decide between
   POST and PATCH simply to change the daily status.

   One POST path removes a race condition and lets the server
   retain authority over the attendance identity.
========================================================= */

async function saveTeacherAttendanceRecord(
  studentId,
  status
){

  const payload =
    buildTeacherAttendancePayload(
      studentId,
      status
    );


  const response =
    await apiPost(
      "/api/attendance",
      payload
    );


  const savedRecord =
    response?.attendance ||
    response?.data ||
    response;


  if (
    savedRecord &&
    typeof savedRecord ===
      "object"
  ){

    replaceTeacherAttendanceRecordInState(
      savedRecord
    );

  }else{

    /*
      If backend response format changes, reload authoritative
      attendance rather than fabricating a local record.
    */

    await loadTeacherAttendance();

  }


  finalizeTeacherLoadedData();


  return savedRecord;

}


/* =========================================================
   UPDATE ONE STUDENT STATUS
========================================================= */

async function updateTeacherAttendanceStatus(
  studentId,
  status
){

  const normalizedStudentId =
    normalizeId(
      studentId
    );

  const normalizedStatus =
    normalizeTeacherAttendanceStatus(
      status
    );


  if (
    !normalizedStudentId ||
    !normalizedStatus
  ){

    return false;

  }


  if (
    teacherAttendanceWorkspaceState
      .savingStudentIds
      .has(
        normalizedStudentId
      )
  ){

    return false;

  }


  teacherAttendanceWorkspaceState
    .savingStudentIds
    .add(
      normalizedStudentId
    );


  renderTeacherAttendanceRoster();


  try{

    await saveTeacherAttendanceRecord(
      normalizedStudentId,
      normalizedStatus
    );


    renderTeacherAttendanceSummary();

    renderTeacherAttendanceRoster();

    renderTeacherDashboardStats();


    if (
      sameId(
        teacherAttendanceWorkspaceState
          .selectedStudentId,
        normalizedStudentId
      )
    ){

      renderTeacherAttendanceStudentHistory(
        normalizedStudentId
      );

    }


    return true;

  }catch(
    error
  ){

    notifyAIFTError(
      getErrorMessage(
        error,
        "AIFT could not save attendance."
      ),
      {
        title:
          "Attendance not saved"
      }
    );


    return false;

  }finally{

    teacherAttendanceWorkspaceState
      .savingStudentIds
      .delete(
        normalizedStudentId
      );


    renderTeacherAttendanceRoster();

  }

}


/* =========================================================
   BULK ATTENDANCE

   Bulk updates only the CURRENTLY VISIBLE roster.

   That means the search box can intentionally limit who is
   affected.

   Each record still goes through the authenticated backend.
========================================================= */

async function saveTeacherBulkAttendance(
  status
){

  if (
    teacherAttendanceWorkspaceState
      .bulkSaving
  ){

    return false;

  }


  const normalizedStatus =
    normalizeTeacherAttendanceStatus(
      status
    );


  const classId =
    normalizeId(
      teacherAttendanceWorkspaceState
        .classId
    );


  const date =
    normalizeTeacherAttendanceDate(
      teacherAttendanceWorkspaceState
        .date
    );


  if (
    !normalizedStatus ||
    !classId ||
    !date
  ){

    notifyAIFTWarning(
      "Select a class and attendance date before using bulk attendance.",
      {
        title:
          "Attendance context required"
      }
    );


    return false;

  }


  /*
    Preserve your current useful behavior:

    Bulk attendance affects the currently visible roster,
    so search can intentionally narrow the target students.
  */

  const students =
    getTeacherAttendanceRoster();


  if (
    !students.length
  ){

    notifyAIFTInfo(
      "There are no visible students to update.",
      {
        title:
          "No attendance changes"
      }
    );


    return false;

  }


  const records =
    students
      .map(
        student => {

          const studentId =
            normalizeId(
              student?._id ||
              student?.id
            );


          if (
            !studentId
          ){

            return null;

          }


          return {

            studentId,

            status:
              normalizedStatus,

            participationScore:
              0,

            notes:
              ""

          };

        }
      )
      .filter(
        Boolean
      );


  if (
    !records.length
  ){

    return false;

  }


  teacherAttendanceWorkspaceState
    .bulkSaving =
    true;


  renderTeacherAttendanceBulkActions();

  renderTeacherAttendanceRoster();


  try{

    const response =
      await apiPost(
        "/api/attendance/bulk",
{
  classId,

  scheduleId:
    normalizeId(
      teacherAttendanceWorkspaceState
        .scheduleId
    ) ||
    null,

  date,

  records
},
        {
          timeout:
            120000
        }
      );


    const savedRecords =
      asArray(
        response?.records
      );


    /*
      Merge authoritative saved records immediately.
    */

    savedRecords
      .forEach(
        record => {

          replaceTeacherAttendanceRecordInState(
            record
          );

        }
      );


    /*
      Then reload this date once from the server so there is
      no possibility of stale local state.
    */

    await loadTeacherSelectedClassAttendance();


    finalizeTeacherLoadedData();


    renderTeacherAttendanceSummary();

    renderTeacherAttendanceRoster();

    renderTeacherDashboardStats();


    if (
      teacherAttendanceWorkspaceState
        .selectedStudentId
    ){

      renderTeacherAttendanceStudentHistory(
        teacherAttendanceWorkspaceState
          .selectedStudentId
      );

    }


    notifyAIFTSuccess(
      `${records.length} student${
        records.length ===
          1
          ? ""
          : "s"
      } marked ${getTeacherAttendanceStatusLabel(
        normalizedStatus
      ).toLowerCase()}.`,
      {
        title:
          "Attendance saved"
      }
    );


    return true;

  }catch(
    error
  ){

    console.error(
      "Bulk attendance failed:",
      error
    );


    notifyAIFTError(
      getErrorMessage(
        error,
        "AIFT could not save bulk attendance."
      ),
      {
        title:
          "Attendance not saved"
      }
    );


    return false;

  }finally{

    teacherAttendanceWorkspaceState
      .bulkSaving =
      false;


    renderTeacherAttendanceBulkActions();

    renderTeacherAttendanceRoster();

  }

}


/* =========================================================
   LOAD ATTENDANCE FOR SELECTED CLASS

   This uses the strongest backend authorization path:
     GET /api/attendance?classId=<assigned-class>
========================================================= */

async function loadTeacherSelectedClassAttendance(){

  const classId =
    normalizeId(
      teacherAttendanceWorkspaceState
        .classId
    );


  const date =
    normalizeTeacherAttendanceDate(
      teacherAttendanceWorkspaceState
        .date
    );


  if (
    !classId
  ){

    return [];

  }


  if (
    !date
  ){

    return [];

  }


const scheduleId =
  normalizeId(
    teacherAttendanceWorkspaceState
      .scheduleId
  );


const records =
  await loadTeacherAttendanceForClass(
    classId,
    date,
    scheduleId
  );


  /*
    Remove only records for this exact class + date.

    Do NOT wipe historical attendance for the same class.
  */

  state.attendance =
    state.attendance
      .filter(
        record => {

          const recordClassId =
            normalizeId(
              record
                ?.classId
                ?._id ||
              record
                ?.classId
            );


          const recordDate =
            getTeacherAttendanceRecordDateKey(
              record
            );


          return !(
            sameId(
              recordClassId,
              classId
            ) &&
            recordDate ===
              date
          );

        }
      );


  state.attendance.push(
    ...asArray(
      records
    )
  );


  state.attendance =
    uniqueById(
      state.attendance
    );


  finalizeTeacherLoadedData();


  return records;

}

/* =========================================================
   ATTENDANCE TOOLBAR CONTROLS

   Toolbar is dynamic, so handlers are applied immediately
   after every render.

   These are local form controls only.

   Global action buttons still use the authoritative Studio
   action controller later.
========================================================= */

function bindTeacherAttendanceToolbarControls(){

  const classFilter =
    $(
      "teacherAttendanceClassFilter"
    );


  const dateInput =
    $(
      "teacherAttendanceDate"
    );


  const searchInput =
    $(
      "teacherAttendanceSearch"
    );


  /* =====================================================
     CLASS
  ===================================================== */

  if (
    classFilter
  ){

    classFilter.onchange =
      async event => {

        const classId =
          normalizeId(
            event.target.value
          );


        teacherAttendanceWorkspaceState
          .classId =
          classId;


        teacherAttendanceWorkspaceState
          .selectedStudentId =
          "";


        teacherAttendanceWorkspaceState
          .search =
          "";


        renderTeacherAttendanceHeader();

        renderTeacherAttendanceBulkActions();

        renderTeacherAttendanceStudentHistory(
          ""
        );


        if (
          !classId
        ){

          renderTeacherAttendanceSummary();

          renderTeacherAttendanceRoster();

          return;

        }


        teacherAttendanceWorkspaceState
          .loading =
          true;


        renderTeacherAttendanceToolbar();

        renderTeacherAttendanceRoster();


        try{

          await loadTeacherSelectedClassAttendance();


          renderTeacherAttendanceSummary();

          renderTeacherAttendanceRoster();

          renderTeacherDashboardStats();

        }catch(
          error
        ){

          console.error(
            "Attendance class load failed:",
            error
          );


          notifyAIFTError(
            getErrorMessage(
              error,
              "Attendance for this class could not be loaded."
            ),
            {
              title:
                "Attendance unavailable"
            }
          );

        }finally{

          teacherAttendanceWorkspaceState
            .loading =
            false;


          renderTeacherAttendanceToolbar();

        }

      };

  }


  /* =====================================================
     DATE
  ===================================================== */

  if (
    dateInput
  ){

    dateInput.onchange =
      async event => {

        const date =
          normalizeTeacherAttendanceDate(
            event.target.value
          );


        if (
          !date
        ){

          notifyAIFTError(
            "Please select a valid attendance date.",
            {
              title:
                "Invalid date"
            }
          );


          event.target.value =
            teacherAttendanceWorkspaceState
              .date;


          return;

        }


        teacherAttendanceWorkspaceState
          .date =
          date;


        teacherAttendanceWorkspaceState
          .selectedStudentId =
          "";


        renderTeacherAttendanceStudentHistory(
          ""
        );


        /*
          No class = nothing authoritative to load yet.
        */

        if (
          !teacherAttendanceWorkspaceState
            .classId
        ){

          renderTeacherAttendanceSummary();

          renderTeacherAttendanceRoster();

          return;

        }


        teacherAttendanceWorkspaceState
          .loading =
          true;


        renderTeacherAttendanceToolbar();

        renderTeacherAttendanceRoster();


        try{

          await loadTeacherSelectedClassAttendance();


          renderTeacherAttendanceSummary();

          renderTeacherAttendanceRoster();

        }catch(
          error
        ){

          console.error(
            "Attendance date load failed:",
            error
          );


          notifyAIFTError(
            getErrorMessage(
              error,
              "Attendance for this date could not be loaded."
            ),
            {
              title:
                "Attendance unavailable"
            }
          );

        }finally{

          teacherAttendanceWorkspaceState
            .loading =
            false;


          renderTeacherAttendanceToolbar();

        }

      };

  }


  /* =====================================================
     SEARCH
  ===================================================== */

  if (
    searchInput
  ){

    searchInput.oninput =
      event => {

        teacherAttendanceWorkspaceState
          .search =
          safeString(
            event.target.value
          );


        renderTeacherAttendanceRoster();

      };

  }

}


/* =========================================================
   ATTENDANCE TODAY
========================================================= */

async function setTeacherAttendanceToToday(){

  const today =
    getTeacherLocalDateInputValue();


  teacherAttendanceWorkspaceState
    .date =
    today;


  teacherAttendanceWorkspaceState
    .selectedStudentId =
    "";


  renderTeacherAttendanceStudentHistory(
    ""
  );


  renderTeacherAttendanceToolbar();


  if (
    !teacherAttendanceWorkspaceState
      .classId
  ){

    renderTeacherAttendanceSummary();

    renderTeacherAttendanceRoster();

    return true;

  }


  teacherAttendanceWorkspaceState
    .loading =
    true;


  renderTeacherAttendanceToolbar();

  renderTeacherAttendanceRoster();


  try{

    await loadTeacherSelectedClassAttendance();


    renderTeacherAttendanceSummary();

    renderTeacherAttendanceRoster();


    return true;

  }catch(
    error
  ){

    notifyAIFTError(
      getErrorMessage(
        error,
        "Today's attendance could not be loaded."
      ),
      {
        title:
          "Attendance unavailable"
      }
    );


    return false;

  }finally{

    teacherAttendanceWorkspaceState
      .loading =
      false;


    renderTeacherAttendanceToolbar();

  }

}


/* =========================================================
   PREPARE ATTENDANCE CLASS

   Used when Attendance is opened from a specific class card.
========================================================= */

function prepareTeacherAttendanceClass(
  classId
){

  const classItem =
    getTeacherClassById(
      classId
    );


  if (
    !classItem
  ){

    return false;

  }


  teacherAttendanceWorkspaceState
    .classId =
    normalizeId(
      classId
    );

  teacherAttendanceWorkspaceState
    .date =
    getTeacherLocalDateInputValue();

  teacherAttendanceWorkspaceState
    .search =
    "";

  teacherAttendanceWorkspaceState
    .selectedStudentId =
    "";


  return true;

}


/* =========================================================
   REFRESH ATTENDANCE
========================================================= */

async function refreshTeacherAttendanceWorkspace(){

  if (
    teacherAttendanceWorkspaceState
      .loading
  ){

    return false;

  }


  teacherAttendanceWorkspaceState
    .loading =
    true;


  renderTeacherAttendanceToolbar();


  try{

    if (
      teacherAttendanceWorkspaceState
        .classId
    ){

      await loadTeacherSelectedClassAttendance();

    }else{

      await loadTeacherAttendance();

      finalizeTeacherLoadedData();

    }


    renderTeacherAttendanceWorkspace();

    renderTeacherDashboardStats();


    notifyAIFTSuccess(
      "Attendance records are up to date.",
      {
        title:
          "Attendance refreshed"
      }
    );


    return true;

  }catch(
    error
  ){

    notifyAIFTError(
      getErrorMessage(
        error,
        "Attendance could not be refreshed."
      ),
      {
        title:
          "Refresh failed"
      }
    );


    return false;

  }finally{

    teacherAttendanceWorkspaceState
      .loading =
      false;


    renderTeacherAttendanceToolbar();

  }

}


/* =========================================================
   COMPLETE ATTENDANCE WORKSPACE
========================================================= */

function renderTeacherAttendanceWorkspace(){

  renderTeacherAttendanceHeader();

  renderTeacherAttendanceToolbar();

  renderTeacherAttendanceSummary();

  renderTeacherAttendanceBulkActions();

  renderTeacherAttendanceRoster();


  if (
    teacherAttendanceWorkspaceState
      .selectedStudentId
  ){

    renderTeacherAttendanceStudentHistory();

  }else{

    renderTeacherAttendanceStudentHistory(
      ""
    );

  }

}


/* =========================================================
   INITIALIZE ATTENDANCE WORKSPACE
========================================================= */

function initializeTeacherAttendanceWorkspace(){

  if (
    teacherAttendanceWorkspaceState
      .initialized
  ){

    renderTeacherAttendanceWorkspace();

    return;

  }


  teacherAttendanceWorkspaceState
    .initialized =
    true;


  /*
    If the teacher only has one class, automatically selecting
    it is useful and unambiguous.

    With multiple classes, preserve the explicit selection
    requirement to prevent marking the wrong roster.
  */

  const classes =
    getTeacherClasses();


  if (
    classes.length ===
      1 &&
    !teacherAttendanceWorkspaceState
      .classId
  ){

    teacherAttendanceWorkspaceState
      .classId =
      normalizeId(
        classes[0]?._id ||
        classes[0]?.id
      );

  }


  renderTeacherAttendanceWorkspace();

}


/* =========================================================
   REFRESH ATTENDANCE UI FROM CURRENT STATE
========================================================= */

function refreshTeacherAttendanceFromCurrentState(){

  renderTeacherAttendanceSummary();

  renderTeacherAttendanceBulkActions();

  renderTeacherAttendanceRoster();


  if (
    teacherAttendanceWorkspaceState
      .selectedStudentId
  ){

    renderTeacherAttendanceStudentHistory();

  }

}


/* =========================================================
   PART 8 COMPLETE

   CURRENT DESIGN PRESERVED.

   AUTHORITATIVE BACKEND WRITE:
     POST /api/attendance

   CURRENT BACKEND POST IS AN UPSERT, SO A TEACHER CAN CHANGE
   A STUDENT'S STATUS WITHOUT THE FRONTEND HAVING TO CHOOSE
   BETWEEN CREATE AND PATCH.

   THE BROWSER DOES NOT SEND:
     schoolId
     teacherId
     markedBy

   because the backend now derives those values from the
   authenticated user and real class.

   THE CENTRAL ACTION CONTROLLER WILL LATER HANDLE:

     set-attendance-status
       -> updateTeacherAttendanceStatus()

     bulk-attendance
       -> saveTeacherBulkAttendance()

     attendance-student-history
       -> renderTeacherAttendanceStudentHistory()

     close-attendance-history
       -> clear selectedStudentId

     attendance-today
       -> setTeacherAttendanceToToday()

     refresh-attendance
       -> refreshTeacherAttendanceWorkspace()

     class attendance shortcut
       -> prepareTeacherAttendanceClass()
          + navigate to attendance
========================================================= */
/* =========================================================
   AIFT TEACHER STUDIO
   PRODUCTION REPLACEMENT
   PART 9

   SCHEDULE WORKSPACE
   ---------------------------------------------------------
   1. Workspace state
   2. Schedule identity helpers
   3. Date/time normalization
   4. Status calculation
   5. Filtering
   6. Existing class filter
   7. Existing list design
   8. Existing calendar design
   9. Month navigation
   10. View switching
   11. Refresh
   12. Class shortcut preparation
   13. Schedule state reconciliation
   14. Workspace initialization

   DESIGN CONTRACT
   ---------------------------------------------------------
   Uses current teacher.html:

   #teacherScheduleClassFilter
   #teacherScheduleList
   #teacherScheduleCalendar
   #teacherScheduleEmpty
   #teacherCalendarMonth
   #teacherCalendarGrid

   Uses existing:
   [data-teacher-schedule-view="list"]
   [data-teacher-schedule-view="calendar"]

   No new Schedule page is generated.
========================================================= */


/* =========================================================
   SCHEDULE WORKSPACE STATE
========================================================= */

const teacherScheduleWorkspaceState = {

  classId:
    "",

  view:
    "list",

  calendarDate:
    new Date(
      new Date().getFullYear(),
      new Date().getMonth(),
      1
    ),

  selectedScheduleId:
    "",

  refreshing:
    false,

  initialized:
    false

};


/* =========================================================
   SCHEDULE ID
========================================================= */

function getTeacherScheduleId(
  schedule
){

  return normalizeId(
    schedule?._id ||
    schedule?.id
  );

}


/* =========================================================
   SCHEDULE CLASS ID
========================================================= */

function getTeacherScheduleClassId(
  schedule
){

  return normalizeId(
    schedule
      ?.classId
      ?._id ||
    schedule
      ?.classId
  );

}


/* =========================================================
   SCHEDULE CLASS RECORD
========================================================= */

function getTeacherScheduleClass(
  schedule
){

  const value =
    schedule?.classId;


  if (
    value &&
    typeof value ===
      "object"
  ){

    return (
      getTeacherClassById(
        value._id ||
        value.id
      ) ||
      value
    );

  }


  return (
    getTeacherClassById(
      value
    ) ||
    null
  );

}


/* =========================================================
   SCHEDULE BY ID
========================================================= */

function getTeacherScheduleById(
  scheduleId
){

  const normalizedScheduleId =
    normalizeId(
      scheduleId
    );


  if (
    !normalizedScheduleId
  ){

    return null;

  }


  return (
    getTeacherSchedules()
      .find(
        schedule =>
          sameId(
            getTeacherScheduleId(
              schedule
            ),
            normalizedScheduleId
          )
      ) ||
    null
  );

}


/* =========================================================
   SCHEDULE DATE STRING

   Return YYYY-MM-DD.

   Preserve a native backend date string when possible rather
   than needlessly round-tripping it through UTC.
========================================================= */

function getTeacherScheduleDateString(
  schedule
){

  const value =

    schedule?.date ||

    schedule?.startDate ||

    schedule?.scheduledAt ||

    schedule?.startDateTime ||

    null;


  if (
    !value
  ){

    return "";

  }


  if (
    typeof value ===
      "string"
  ){

    const dateMatch =
      value.match(
        /^(\d{4}-\d{2}-\d{2})/
      );


    if (
      dateMatch
    ){

      return dateMatch[1];

    }

  }


  const date =
    toValidDate(
      value
    );


  if (
    !date
  ){

    return "";

  }


  return getTeacherLocalDateInputValue(
    date
  );

}


/* =========================================================
   START TIME

   Supports the actual schedule fields used across the
   existing frontend/backend evolution.
========================================================= */

function getTeacherScheduleStartTime(
  schedule
){

  return safeString(

    schedule?.startTime ||

    schedule?.time

  );

}


/* =========================================================
   END TIME
========================================================= */

function getTeacherScheduleEndTime(
  schedule
){

  return safeString(
    schedule?.endTime
  );

}


/* =========================================================
   LOCAL DATE + TIME

   Schedule dates represent teaching calendar dates, so this
   uses local browser time instead of forcing UTC.
========================================================= */

function getTeacherScheduleLocalDateTime(
  schedule,
  {
    useEndTime = false
  } = {}
){

  const date =
    getTeacherScheduleDateString(
      schedule
    );


  if (
    !date
  ){

    return null;

  }


  const time =
    useEndTime
      ? (
          getTeacherScheduleEndTime(
            schedule
          ) ||
          getTeacherScheduleStartTime(
            schedule
          ) ||
          "00:00"
        )
      : (
          getTeacherScheduleStartTime(
            schedule
          ) ||
          "00:00"
        );


  const parsed =
    new Date(
      `${date}T${time}`
    );


  return Number.isNaN(
    parsed.getTime()
  )
    ? null
    : parsed;

}



/* =========================================================
   TEACHER SCHEDULE OPERATIONAL ENGINE

   AUTHORITATIVE STATUS
   ---------------------------------------------------------

   sessionStatus:
     scheduled
     started
     completed
     missed
     cancelled
     rescheduled

   Legacy schedule.status is fallback only.

   IMPORTANT
   ---------------------------------------------------------

   The frontend does NOT invent "completed" simply because
   the scheduled time has passed.

   Backend /api/schedules now determines whether an expired
   session is actually:

     completed
     missed
     cancelled

   This prevents missed classes from appearing completed.
========================================================= */


/* =========================================================
   SCHEDULE STATUS
========================================================= */

function getTeacherScheduleStatus(
  schedule
){

  if (
    !schedule ||
    typeof schedule !==
      "object"
  ){

    return "scheduled";

  }


  const sessionStatus =
    safeString(
      schedule.sessionStatus
    )
      .toLowerCase();


  const allowedSessionStatuses =
    new Set([
      "scheduled",
      "started",
      "completed",
      "missed",
      "cancelled",
      "rescheduled"
    ]);


  if (
    allowedSessionStatuses.has(
      sessionStatus
    )
  ){

    return sessionStatus;

  }


  /* =====================================================
     LEGACY BACKEND COMPATIBILITY
  ===================================================== */

  const legacyStatus =
    safeString(
      schedule.status
    )
      .toLowerCase();


  if (
    [
      "cancelled",
      "canceled"
    ].includes(
      legacyStatus
    )
  ){

    return "cancelled";

  }


  if (
    [
      "completed",
      "closed"
    ].includes(
      legacyStatus
    )
  ){

    return "completed";

  }


  return "scheduled";

}


/* =========================================================
   SCHEDULE STATUS LABEL
========================================================= */

function getTeacherScheduleStatusLabel(
  schedule
){

  switch (
    getTeacherScheduleStatus(
      schedule
    )
  ){

    case "started":

      return "In progress";


    case "completed":

      return "Completed";


    case "missed":

      return "Missed";


    case "cancelled":

      return "Cancelled";


    case "rescheduled":

      return "Rescheduled";


    case "scheduled":
    default:

      return "Scheduled";

  }

}


/* =========================================================
   SCHEDULE STATUS ICON
========================================================= */

function getTeacherScheduleStatusIcon(
  schedule
){

  switch (
    getTeacherScheduleStatus(
      schedule
    )
  ){

    case "started":

      return "fa-solid fa-circle-play";


    case "completed":

      return "fa-solid fa-circle-check";


    case "missed":

      return "fa-solid fa-circle-exclamation";


    case "cancelled":

      return "fa-solid fa-ban";


    case "rescheduled":

      return "fa-solid fa-calendar-arrow-down";


    case "scheduled":
    default:

      return "fa-regular fa-clock";

  }

}


/* =========================================================
   TEACHER ATTENDANCE STATUS
========================================================= */

function getTeacherScheduleAttendanceStatus(
  schedule
){

  const status =
    safeString(
      schedule?.teacherAttendanceStatus,
      "pending"
    )
      .toLowerCase();


  const allowed =
    new Set([
      "pending",
      "present",
      "late",
      "missed",
      "excused"
    ]);


  return allowed.has(
    status
  )
    ? status
    : "pending";

}


/* =========================================================
   TEACHER ATTENDANCE LABEL
========================================================= */

function getTeacherScheduleAttendanceLabel(
  schedule
){

  switch (
    getTeacherScheduleAttendanceStatus(
      schedule
    )
  ){

    case "present":

      return "Teacher present";


    case "late":

      return "Teacher started late";


    case "missed":

      return "Teacher missed session";


    case "excused":

      return "Teacher excused";


    case "pending":
    default:

      return "Awaiting session";

  }

}


/* =========================================================
   LATE MINUTES
========================================================= */

function getTeacherScheduleLateMinutes(
  schedule
){

  const value =
    Number(
      schedule?.teacherLateMinutes ||
      0
    );


  if (
    !Number.isFinite(
      value
    )
  ){

    return 0;

  }


  return Math.max(
    0,
    Math.round(
      value
    )
  );

}


/* =========================================================
   SCHEDULE REVIEW FLAG
========================================================= */

function teacherScheduleRequiresReview(
  schedule
){

  return Boolean(
    schedule?.requiresReview
  );

}


/* =========================================================
   MISSED REASON
========================================================= */

function getTeacherScheduleMissedReason(
  schedule
){

  return safeString(
    schedule?.missedReason
  );

}


/* =========================================================
   CANCELLATION REASON
========================================================= */

function getTeacherScheduleCancelReason(
  schedule
){

  return safeString(
    schedule?.cancelReason
  );

}


/* =========================================================
   RESCHEDULE REASON
========================================================= */

function getTeacherScheduleRescheduleReason(
  schedule
){

  return safeString(
    schedule?.rescheduleReason
  );

}


/* =========================================================
   SESSION CAN JOIN
========================================================= */

function canTeacherJoinSchedule(
  schedule
){

  const status =
    getTeacherScheduleStatus(
      schedule
    );


  return [
    "scheduled",
    "started",
    "rescheduled"
  ].includes(
    status
  );

}


/* =========================================================
   SESSION CAN EDIT
========================================================= */

function canTeacherEditSchedule(
  schedule
){

  const status =
    getTeacherScheduleStatus(
      schedule
    );


  /*
    Historical accountability should not be silently changed
    from the normal editor.

    Backend permissions remain authoritative.
  */

  return ![
    "missed",
    "completed"
  ].includes(
    status
  );

}


/* =========================================================
   HISTORICAL STATUS
========================================================= */

function isTeacherScheduleHistorical(
  schedule
){

  return [
    "completed",
    "missed",
    "cancelled"
  ].includes(
    getTeacherScheduleStatus(
      schedule
    )
  );

}


/* =========================================================
   FORMAT SCHEDULE TIME
========================================================= */

function formatTeacherScheduleClockTime(
  value
){

  const time =
    safeString(
      value
    );


  if (
    !time
  ){

    return "";

  }


  const match =
    time.match(
      /^(\d{1,2}):(\d{2})/
    );


  if (
    !match
  ){

    return time;

  }


  const hour =
    Number(
      match[1]
    );


  const minute =
    Number(
      match[2]
    );


  if (
    !Number.isFinite(
      hour
    ) ||
    !Number.isFinite(
      minute
    )
  ){

    return time;

  }


  const date =
    new Date();


  date.setHours(
    hour,
    minute,
    0,
    0
  );


  return date.toLocaleTimeString(
    [],
    {
      hour:
        "numeric",

      minute:
        "2-digit"
    }
  );

}


/* =========================================================
   SCHEDULE TIME RANGE
========================================================= */

function getTeacherScheduleTimeRange(
  schedule
){

  const start =
    getTeacherScheduleStartTime(
      schedule
    );


  const end =
    getTeacherScheduleEndTime(
      schedule
    );


  if (
    !start
  ){

    return "Time not set";

  }


  if (
    !end
  ){

    return formatTeacherScheduleClockTime(
      start
    );

  }


  return `${formatTeacherScheduleClockTime(
    start
  )} – ${formatTeacherScheduleClockTime(
    end
  )}`;

}


/* =========================================================
   SCHEDULE MEETING LINK
========================================================= */

function getTeacherScheduleMeetingLink(
  schedule
){

  return normalizeHttpUrl(
    schedule?.meetingLink
  );

}


/* =========================================================
   SCHEDULE NOTES
========================================================= */

function getTeacherScheduleNotes(
  schedule
){

  return safeString(
    schedule?.notes
  );

}


/* =========================================================
   FILTERED SCHEDULES
========================================================= */

function getFilteredTeacherScheduleRecords(){

  const classId =
    normalizeId(
      teacherScheduleWorkspaceState
        .classId
    );


  let schedules = [
    ...getTeacherSchedules()
  ];


  if (
    classId
  ){

    schedules =
      schedules.filter(
        schedule =>
          sameId(
            getTeacherScheduleClassId(
              schedule
            ),
            classId
          )
      );

  }


  schedules.sort(
    (
      first,
      second
    ) => {

      const firstDate =
        getTeacherScheduleLocalDateTime(
          first
        );


      const secondDate =
        getTeacherScheduleLocalDateTime(
          second
        );


      return (
        (
          firstDate?.getTime() ||
          0
        ) -
        (
          secondDate?.getTime() ||
          0
        )
      );

    }
  );


  return schedules;

}


/* =========================================================
   LIST SCHEDULES

   ACTIVE:
     started
     scheduled
     rescheduled

   HISTORY:
     missed
     cancelled
     completed

   Historical entries remain visible so Teacher accountability
   is never hidden simply because the meeting date passed.
========================================================= */

function getTeacherScheduleListRecords(){

  const schedules =
    getFilteredTeacherScheduleRecords();


  const active =
    schedules
      .filter(
        schedule =>
          [
            "started",
            "scheduled",
            "rescheduled"
          ].includes(
            getTeacherScheduleStatus(
              schedule
            )
          )
      )
      .sort(
        (
          first,
          second
        ) =>
          (
            getTeacherScheduleLocalDateTime(
              first
            )?.getTime() ||
            0
          ) -
          (
            getTeacherScheduleLocalDateTime(
              second
            )?.getTime() ||
            0
          )
      );


  const history =
    schedules
      .filter(
        schedule =>
          [
            "missed",
            "cancelled",
            "completed"
          ].includes(
            getTeacherScheduleStatus(
              schedule
            )
          )
      )
      .sort(
        (
          first,
          second
        ) =>
          (
            getTeacherScheduleLocalDateTime(
              second
            )?.getTime() ||
            0
          ) -
          (
            getTeacherScheduleLocalDateTime(
              first
            )?.getTime() ||
            0
          )
      )
      .slice(
        0,
        20
      );


  return [
    ...active,
    ...history
  ];

}


/* =========================================================
   SCHEDULE CLASS FILTER
========================================================= */

function renderTeacherScheduleClassFilter(){

  const select =
    $(
      "teacherScheduleClassFilter"
    );


  if (
    !select
  ){

    return;

  }


  const selectedValue =
    teacherScheduleWorkspaceState
      .classId;


  select.innerHTML = `
    <option value="">
      All classes
    </option>

    ${
      getTeacherClasses()
        .map(
          classItem => {

            const classId =
              normalizeId(
                classItem?._id ||
                classItem?.id
              );


            return `
              <option
                value="${escapeAttribute(classId)}"
              >
                ${escapeHtml(
                  getTeacherClassTitle(
                    classItem
                  )
                )}
              </option>
            `;

          }
        )
        .join(
          ""
        )
    }
  `;


  select.value =
    selectedValue;


  if (
    select.value !==
    selectedValue
  ){

    teacherScheduleWorkspaceState
      .classId =
      "";


    select.value =
      "";

  }


  select.onchange =
    event => {

      teacherScheduleWorkspaceState
        .classId =
        normalizeId(
          event.target.value
        );


      renderTeacherScheduleWorkspace();

    };

}


/* =========================================================
   SCHEDULE VIEW BUTTONS
========================================================= */

function renderTeacherScheduleViewButtons(){

  $all(
    "[data-teacher-schedule-view]"
  )
    .forEach(
      button => {

        const view =
          safeString(
            button.dataset
              .teacherScheduleView
          );


        const active =
          view ===
          teacherScheduleWorkspaceState
            .view;


        button.classList.toggle(
          "active",
          active
        );


        button.setAttribute(
          "aria-pressed",
          String(
            active
          )
        );

      }
    );

}


/* =========================================================
   ACCOUNTABILITY / SESSION NOTICE
========================================================= */

function renderTeacherScheduleOperationalNotice(
  schedule
){

  const status =
    getTeacherScheduleStatus(
      schedule
    );


  const teacherAttendanceStatus =
    getTeacherScheduleAttendanceStatus(
      schedule
    );


  /* =====================================================
     MISSED
  ===================================================== */

  if (
    status ===
    "missed"
  ){

    const reason =
      getTeacherScheduleMissedReason(
        schedule
      ) ||
      "The scheduled teaching session ended without a recorded Teacher start.";


    return `
      <div
        class="teacher-schedule-notice missed"
      >
        <span
          class="teacher-schedule-notice-icon"
        >
          <i
            class="fa-solid fa-circle-exclamation"
            aria-hidden="true"
          ></i>
        </span>

        <div>
          <strong>
            Missed teaching session
          </strong>

          <span>
            ${escapeHtml(reason)}
          </span>

          ${
            teacherScheduleRequiresReview(
              schedule
            )
              ? `
                <small>
                  This session has been flagged for School review.
                </small>
              `
              : ""
          }
        </div>
      </div>
    `;

  }


  /* =====================================================
     TEACHER LATE
  ===================================================== */

  if (
    teacherAttendanceStatus ===
    "late"
  ){

    const minutes =
      getTeacherScheduleLateMinutes(
        schedule
      );


    return `
      <div
        class="teacher-schedule-notice late"
      >
        <span
          class="teacher-schedule-notice-icon"
        >
          <i
            class="fa-regular fa-clock"
            aria-hidden="true"
          ></i>
        </span>

        <div>
          <strong>
            Late start recorded
          </strong>

          <span>
            ${
              minutes
                ? `Session started ${escapeHtml(
                    String(
                      minutes
                    )
                  )} minute${
                    minutes ===
                    1
                      ? ""
                      : "s"
                  } after the scheduled start.`
                : "This session was recorded as a late Teacher start."
            }
          </span>
        </div>
      </div>
    `;

  }


  /* =====================================================
     CANCELLED
  ===================================================== */

  if (
    status ===
    "cancelled"
  ){

    const reason =
      getTeacherScheduleCancelReason(
        schedule
      );


    return `
      <div
        class="teacher-schedule-notice cancelled"
      >
        <span
          class="teacher-schedule-notice-icon"
        >
          <i
            class="fa-solid fa-ban"
            aria-hidden="true"
          ></i>
        </span>

        <div>
          <strong>
            Session cancelled
          </strong>

          <span>
            ${
              escapeHtml(
                reason ||
                "This teaching session was cancelled."
              )
            }
          </span>
        </div>
      </div>
    `;

  }


  /* =====================================================
     RESCHEDULED
  ===================================================== */

  if (
    status ===
    "rescheduled"
  ){

    const reason =
      getTeacherScheduleRescheduleReason(
        schedule
      );


    return `
      <div
        class="teacher-schedule-notice rescheduled"
      >
        <span
          class="teacher-schedule-notice-icon"
        >
          <i
            class="fa-solid fa-calendar-arrow-down"
            aria-hidden="true"
          ></i>
        </span>

        <div>
          <strong>
            Session rescheduled
          </strong>

          <span>
            ${
              escapeHtml(
                reason ||
                "This teaching session has a revised schedule."
              )
            }
          </span>
        </div>
      </div>
    `;

  }


  return "";

}

/* =========================================================
   CREATE TEACHER SCHEDULE CARD
   PRODUCTION SESSION LIFECYCLE

   LIFECYCLE
   ---------------------------------------------------------

   scheduled / rescheduled
     -> Start Session

   started
     -> Join Meeting
     -> Complete Session

   completed
     -> Historical record

   missed
     -> Historical accountability record

   cancelled
     -> Historical / editable cancellation record

   IMPORTANT
   ---------------------------------------------------------

   Opening a meeting link is NOT considered a Teacher start.

   The Teacher must first trigger:
     POST /api/schedules/:id/start

   This gives the School a real backend attendance trail.
========================================================= */

function createTeacherScheduleCard(
  schedule
){

  const scheduleId =
    getTeacherScheduleId(
      schedule
    );


  const classItem =
    getTeacherScheduleClass(
      schedule
    );


  const title =
    getTeacherScheduleTitle(
      schedule
    );


  const classTitle =
    getTeacherClassTitle(
      classItem ||
      {}
    );


  const dateString =
    getTeacherScheduleDateString(
      schedule
    );


  const date =
    dateString
      ? new Date(
          `${dateString}T12:00:00`
        )
      : null;


  const status =
    getTeacherScheduleStatus(
      schedule
    );


  const statusLabel =
    getTeacherScheduleStatusLabel(
      schedule
    );


  const statusIcon =
    getTeacherScheduleStatusIcon(
      schedule
    );


  const notes =
    getTeacherScheduleNotes(
      schedule
    );


  const meetingLink =
    getTeacherScheduleMeetingLink(
      schedule
    );


  const operationalNotice =
    renderTeacherScheduleOperationalNotice(
      schedule
    );


  const startAllowed =
    [
      "scheduled",
      "rescheduled"
    ].includes(
      status
    );


  const completeAllowed =
    status ===
    "started";


  const joinAllowed =
    Boolean(
      meetingLink &&
      status ===
      "started"
    );


  const editAllowed =
    canTeacherEditSchedule(
      schedule
    );


  const historical =
    isTeacherScheduleHistorical(
      schedule
    );


  return `
    <article
      class="
        teacher-schedule-card
        teacher-schedule-card-${escapeAttribute(status)}
      "
      data-schedule-id="${escapeAttribute(scheduleId)}"
      data-schedule-status="${escapeAttribute(status)}"
    >

      <!-- ===============================================
           DATE
      ================================================ -->

      <div
        class="teacher-schedule-date"
      >

        <strong
          class="teacher-schedule-date-day"
        >
          ${
            date
              ? escapeHtml(
                  String(
                    date.getDate()
                  ).padStart(
                    2,
                    "0"
                  )
                )
              : "—"
          }
        </strong>


        <span
          class="teacher-schedule-date-month"
        >
          ${
            date
              ? escapeHtml(
                  date.toLocaleDateString(
                    [],
                    {
                      month:
                        "short"
                    }
                  )
                )
              : ""
          }
        </span>


        <span
          class="teacher-schedule-date-weekday"
        >
          ${
            date
              ? escapeHtml(
                  date.toLocaleDateString(
                    [],
                    {
                      weekday:
                        "short"
                    }
                  )
                )
              : ""
          }
        </span>

      </div>


      <!-- ===============================================
           MAIN CONTENT
      ================================================ -->

      <div
        class="teacher-schedule-main"
      >

        <div
          class="teacher-schedule-card-head"
        >

          <div
            class="teacher-schedule-heading-copy"
          >

            <h3
              class="teacher-schedule-title"
            >
              ${escapeHtml(title)}
            </h3>


            <div
              class="teacher-schedule-class"
            >
              <i
                class="fa-solid fa-chalkboard-user"
                aria-hidden="true"
              ></i>

              <span>
                ${escapeHtml(classTitle)}
              </span>
            </div>

          </div>


          <span
            class="teacher-schedule-status ${escapeAttribute(status)}"
          >
            <i
              class="${escapeAttribute(statusIcon)}"
              aria-hidden="true"
            ></i>

            ${escapeHtml(statusLabel)}
          </span>

        </div>


        <!-- =============================================
             TIME
        ============================================== -->

        <div
          class="teacher-schedule-time"
        >
          <i
            class="fa-regular fa-clock"
            aria-hidden="true"
          ></i>

          <span>
            ${escapeHtml(
              getTeacherScheduleTimeRange(
                schedule
              )
            )}
          </span>


          ${
            date
              ? `
                <span
                  class="teacher-schedule-meta-divider"
                  aria-hidden="true"
                >
                  •
                </span>

                <span>
                  ${escapeHtml(
                    formatDate(
                      date
                    )
                  )}
                </span>
              `
              : ""
          }


          ${
            status ===
            "started"
              ? `
                <span
                  class="teacher-schedule-live-indicator"
                >
                  <span
                    class="teacher-schedule-live-dot"
                    aria-hidden="true"
                  ></span>

                  Session active
                </span>
              `
              : ""
          }

        </div>


        <!-- =============================================
             NOTES
        ============================================== -->

        ${
          notes
            ? `
              <p
                class="teacher-schedule-notes"
              >
                ${escapeHtml(notes)}
              </p>
            `
            : ""
        }


        <!-- =============================================
             OPERATIONAL NOTICE
        ============================================== -->

        ${operationalNotice}

      </div>


      <!-- ===============================================
           ACTIONS
      ================================================ -->

      <div
        class="teacher-schedule-actions"
      >

        <!-- =============================================
             START SESSION
        ============================================== -->

        ${
          startAllowed
            ? `
              <button
                type="button"
                class="
                  teacher-schedule-action
                  teacher-schedule-action-start
                  primary
                "
                data-teacher-action="start-schedule"
                data-schedule-id="${escapeAttribute(scheduleId)}"
              >
                <i
                  class="fa-solid fa-play"
                  aria-hidden="true"
                ></i>

                Start Session
              </button>
            `
            : ""
        }


        <!-- =============================================
             JOIN ONLINE MEETING

             Only available AFTER session has officially
             started in the backend.
        ============================================== -->

        ${
          joinAllowed
            ? `
              <button
                type="button"
                class="
                  teacher-schedule-action
                  teacher-schedule-action-join
                "
                data-teacher-action="open-schedule-meeting"
                data-schedule-id="${escapeAttribute(scheduleId)}"
              >
                <i
                  class="fa-solid fa-video"
                  aria-hidden="true"
                ></i>

                Join Meeting
              </button>
            `
            : ""
        }


        <!-- =============================================
             COMPLETE SESSION
        ============================================== -->

        ${
          completeAllowed
            ? `
              <button
                type="button"
                class="
                  teacher-schedule-action
                  teacher-schedule-action-complete
                "
                data-teacher-action="complete-schedule"
                data-schedule-id="${escapeAttribute(scheduleId)}"
              >
                <i
                  class="fa-solid fa-check"
                  aria-hidden="true"
                ></i>

                Complete
              </button>
            `
            : ""
        }


        <!-- =============================================
             EDIT
        ============================================== -->

        ${
          editAllowed &&
          status !==
          "started"
            ? `
              <button
                type="button"
                class="teacher-schedule-action"
                data-teacher-action="edit-schedule"
                data-schedule-id="${escapeAttribute(scheduleId)}"
              >
                <i
                  class="fa-regular fa-pen-to-square"
                  aria-hidden="true"
                ></i>

                Edit
              </button>
            `
            : ""
        }


        <!-- =============================================
             HISTORY
        ============================================== -->

        ${
          historical &&
          !editAllowed
            ? `
              <span
                class="teacher-schedule-history-label"
                title="This session is retained as teaching history."
              >
                <i
                  class="fa-solid fa-lock"
                  aria-hidden="true"
                ></i>

                History
              </span>
            `
            : ""
        }

      </div>

    </article>
  `;

}


/* =========================================================
   SCHEDULE EMPTY STATE
========================================================= */

function renderTeacherScheduleEmptyState(
  schedules
){

  const empty =
    $(
      "teacherScheduleEmpty"
    );


  if (
    !empty
  ){

    return;

  }


  const hasResults =
    schedules.length >
    0;


  empty.hidden =
    hasResults;


  if (
    hasResults
  ){

    return;

  }


  const heading =
    empty.querySelector(
      "h2"
    );

  const description =
    empty.querySelector(
      "p"
    );


  if (
    heading
  ){

    heading.textContent =
      teacherScheduleWorkspaceState
        .classId
        ? "No schedule for this class"
        : "No scheduled classes";

  }


  if (
    description
  ){

    description.textContent =
      teacherScheduleWorkspaceState
        .classId
        ? "This class does not have any scheduled teaching sessions yet."
        : "You don't have any scheduled teaching sessions yet.";

  }

}


/* =========================================================
   SCHEDULE LIST
========================================================= */

function renderTeacherScheduleList(){

  const container =
    $(
      "teacherScheduleList"
    );


  if (
    !container
  ){

    return;

  }


  const schedules =
    getTeacherScheduleListRecords();


  renderTeacherScheduleEmptyState(
    schedules
  );


  if (
    !schedules.length
  ){

    container.innerHTML =
      "";

    container.hidden =
      true;

    return;

  }


  container.hidden =
    false;


  container.innerHTML =
    schedules
      .map(
        createTeacherScheduleCard
      )
      .join(
        ""
      );

}


/* =========================================================
   CALENDAR MONTH LABEL
========================================================= */

function renderTeacherCalendarMonthLabel(){

  const label =
    $(
      "teacherCalendarMonth"
    );


  if (
    !label
  ){

    return;

  }


  label.textContent =
    teacherScheduleWorkspaceState
      .calendarDate
      .toLocaleDateString(
        [],
        {
          month:
            "long",

          year:
            "numeric"
        }
      );

}


/* =========================================================
   CALENDAR SCHEDULE MAP
========================================================= */

function getTeacherCalendarScheduleMap(){

  const map =
    new Map();


  getFilteredTeacherScheduleRecords()
    .forEach(
      schedule => {

        const date =
          getTeacherScheduleDateString(
            schedule
          );


        if (
          !date
        ){

          return;

        }


        if (
          !map.has(
            date
          )
        ){

          map.set(
            date,
            []
          );

        }


        map.get(
          date
        ).push(
          schedule
        );

      }
    );


  return map;

}


/* =========================================================
   CALENDAR DATE KEY
========================================================= */

function getTeacherCalendarDateKey(
  date
){

  return getTeacherLocalDateInputValue(
    date
  );

}


/* =========================================================
   CREATE CALENDAR DAY
========================================================= */

function createTeacherCalendarDay(
  date,
  activeMonth,
  schedules
){

  const dateKey =
    getTeacherCalendarDateKey(
      date
    );

  const today =
    getTeacherLocalDateInputValue();

  const muted =
    date.getMonth() !==
    activeMonth;

  const isToday =
    dateKey ===
    today;


  const visibleEvents =
    schedules.slice(
      0,
      3
    );

  const additional =
    Math.max(
      0,
      schedules.length -
      visibleEvents.length
    );


  return `
    <button
      type="button"
      class="
        teacher-calendar-day
        ${
          muted
            ? "muted"
            : ""
        }
        ${
          isToday
            ? "today"
            : ""
        }
      "
      data-teacher-action="schedule-calendar-date"
      data-schedule-date="${escapeAttribute(dateKey)}"
    >

      <span
        class="teacher-calendar-day-number"
      >
        ${date.getDate()}
      </span>


      <span
        class="teacher-calendar-events"
      >

        ${
          visibleEvents
            .map(
              schedule => `
                <span
                  class="teacher-calendar-event"
                  title="${escapeAttribute(
                    `${getTeacherScheduleTitle(
                      schedule
                    )} · ${getTeacherScheduleTimeRange(
                      schedule
                    )}`
                  )}"
                >
                  ${escapeHtml(
                    getTeacherScheduleTitle(
                      schedule
                    )
                  )}
                </span>
              `
            )
            .join(
              ""
            )
        }


        ${
          additional
            ? `
              <span
                class="teacher-calendar-event"
              >
                +${additional} more
              </span>
            `
            : ""
        }

      </span>

    </button>
  `;

}


/* =========================================================
   CALENDAR
========================================================= */

function renderTeacherScheduleCalendar(){

  const grid =
    $(
      "teacherCalendarGrid"
    );


  if (
    !grid
  ){

    return;

  }


  renderTeacherCalendarMonthLabel();


  const reference =
    teacherScheduleWorkspaceState
      .calendarDate;

  const year =
    reference.getFullYear();

  const month =
    reference.getMonth();


  const firstOfMonth =
    new Date(
      year,
      month,
      1
    );

  const start =
    new Date(
      year,
      month,
      1 -
      firstOfMonth.getDay()
    );


  const scheduleMap =
    getTeacherCalendarScheduleMap();


  const days =
    [];


  for (
    let index = 0;
    index < 42;
    index += 1
  ){

    const date =
      new Date(
        start
      );


    date.setDate(
      start.getDate() +
      index
    );


    const key =
      getTeacherCalendarDateKey(
        date
      );


    days.push(
      createTeacherCalendarDay(
        date,
        month,
        scheduleMap.get(
          key
        ) ||
        []
      )
    );

  }


  grid.innerHTML =
    days.join(
      ""
    );

}


/* =========================================================
   SWITCH LIST / CALENDAR
========================================================= */

function setTeacherScheduleView(
  view
){

  if (
    ![
      "list",
      "calendar"
    ].includes(
      view
    )
  ){

    return false;

  }


  teacherScheduleWorkspaceState
    .view =
    view;


  renderTeacherScheduleWorkspace();


  return true;

}


/* =========================================================
   MONTH NAVIGATION
========================================================= */

function moveTeacherScheduleCalendarMonth(
  offset
){

  const amount =
    safeInteger(
      offset,
      0
    );


  const current =
    teacherScheduleWorkspaceState
      .calendarDate;


  teacherScheduleWorkspaceState
    .calendarDate =
    new Date(
      current.getFullYear(),
      current.getMonth() +
      amount,
      1
    );


  renderTeacherScheduleCalendar();

}


/* =========================================================
   PREPARE SCHEDULE CLASS

   Used when the teacher enters Schedule from a class card.
========================================================= */

function prepareTeacherScheduleClass(
  classId
){

  const classItem =
    getTeacherClassById(
      classId
    );


  if (
    !classItem
  ){

    return false;

  }


  teacherScheduleWorkspaceState
    .classId =
    normalizeId(
      classId
    );

  teacherScheduleWorkspaceState
    .view =
    "list";


  return true;

}


/* =========================================================
   OPEN CALENDAR DATE

   We keep the existing List/Calendar model.

   Clicking a calendar date with schedules switches to List
   and limits the list visually by marking that day's events
   first rather than creating a new third schedule mode.
========================================================= */

function openTeacherScheduleCalendarDate(
  date
){

  const normalizedDate =
    normalizeTeacherAttendanceDate(
      date
    );


  if (
    !normalizedDate
  ){

    return false;

  }


  const matching =
    getFilteredTeacherScheduleRecords()
      .filter(
        schedule =>
          getTeacherScheduleDateString(
            schedule
          ) ===
          normalizedDate
      );


  if (
    !matching.length
  ){

    return false;

  }


  const first =
    matching[0];


  teacherScheduleWorkspaceState
    .selectedScheduleId =
    getTeacherScheduleId(
      first
    );


  /*
    Stay in calendar.

    The central action controller can open the schedule editor
    directly for the selected event later.
  */


  return true;

}


/* =========================================================
   REPLACE SCHEDULE IN STATE

   Used later by create/edit operations.
========================================================= */

function replaceTeacherScheduleInState(
  savedSchedule
){

  const scheduleId =
    getTeacherScheduleId(
      savedSchedule
    );


  if (
    !scheduleId
  ){

    return false;

  }


  const index =
    state.schedules
      .findIndex(
        schedule =>
          sameId(
            getTeacherScheduleId(
              schedule
            ),
            scheduleId
          )
      );


  if (
    index >=
    0
  ){

    state.schedules[
      index
    ] =
      savedSchedule;

  }else{

    state.schedules.push(
      savedSchedule
    );

  }


  finalizeTeacherLoadedData();


  return true;

}


/* =========================================================
   REMOVE SCHEDULE FROM STATE
========================================================= */

function removeTeacherScheduleFromState(
  scheduleId
){

  const normalizedScheduleId =
    normalizeId(
      scheduleId
    );


  if (
    !normalizedScheduleId
  ){

    return false;

  }


  const before =
    state.schedules.length;


  state.schedules =
    state.schedules
      .filter(
        schedule =>
          !sameId(
            getTeacherScheduleId(
              schedule
            ),
            normalizedScheduleId
          )
      );


  finalizeTeacherLoadedData();


  return (
    state.schedules.length <
    before
  );

}


/* =========================================================
   REFRESH SCHEDULE
========================================================= */

async function refreshTeacherScheduleWorkspace(){

  if (
    teacherScheduleWorkspaceState
      .refreshing
  ){

    return false;

  }


  teacherScheduleWorkspaceState
    .refreshing =
    true;


  const refreshButtons =
    $all(
      '[data-teacher-action="refresh-schedule"]'
    );


  refreshButtons.forEach(
    button => {

      button.disabled =
        true;

      button.setAttribute(
        "aria-busy",
        "true"
      );


      const icon =
        button.querySelector(
          "i"
        );


      if (
        icon
      ){

        icon.classList.add(
          "fa-spin"
        );

      }

    }
  );


  try{

    await loadTeacherSchedules();


    finalizeTeacherLoadedData();


    renderTeacherScheduleWorkspace();

    renderTeacherOverviewSchedule();


    notifyAIFTSuccess(
      "Your teaching schedule is up to date.",
      {
        title:
          "Schedule refreshed"
      }
    );


    return true;

  }catch(
    error
  ){

    notifyAIFTError(
      getErrorMessage(
        error,
        "Your schedule could not be refreshed."
      ),
      {
        title:
          "Refresh failed"
      }
    );


    return false;

  }finally{

    teacherScheduleWorkspaceState
      .refreshing =
      false;


    refreshButtons.forEach(
      button => {

        button.disabled =
          false;

        button.setAttribute(
          "aria-busy",
          "false"
        );


        const icon =
          button.querySelector(
            "i"
          );


        if (
          icon
        ){

          icon.classList.remove(
            "fa-spin"
          );

        }

      }
    );

  }

}


/* =========================================================
   RENDER COMPLETE SCHEDULE WORKSPACE
========================================================= */

function renderTeacherScheduleWorkspace(){

  renderTeacherScheduleClassFilter();

  renderTeacherScheduleViewButtons();


  const list =
    $(
      "teacherScheduleList"
    );

  const calendar =
    $(
      "teacherScheduleCalendar"
    );

  const empty =
    $(
      "teacherScheduleEmpty"
    );


  if (
    teacherScheduleWorkspaceState
      .view ===
    "calendar"
  ){

    if (
      list
    ){

      list.hidden =
        true;

    }


    if (
      empty
    ){

      empty.hidden =
        true;

    }


    if (
      calendar
    ){

      calendar.hidden =
        false;

    }


    renderTeacherScheduleCalendar();


    return;

  }


  if (
    calendar
  ){

    calendar.hidden =
      true;

  }


  renderTeacherScheduleList();

}


/* =========================================================
   INITIALIZE SCHEDULE WORKSPACE
========================================================= */

function initializeTeacherScheduleWorkspace(){

  if (
    teacherScheduleWorkspaceState
      .initialized
  ){

    renderTeacherScheduleWorkspace();

    return;

  }


  teacherScheduleWorkspaceState
    .initialized =
    true;


  /*
    Current teacher.html already owns the view buttons.

    Property handlers avoid introducing another document-wide
    listener before the authoritative controller is installed.
  */

  $all(
    "[data-teacher-schedule-view]"
  )
    .forEach(
      button => {

        button.onclick =
          event => {

            event.preventDefault();


            setTeacherScheduleView(
              safeString(
                button.dataset
                  .teacherScheduleView
              )
            );

          };

      }
    );


  renderTeacherScheduleWorkspace();

}


/* =========================================================
   SCHEDULE VIEW REFRESH FROM CURRENT STATE
========================================================= */

function refreshTeacherScheduleFromCurrentState(){

  renderTeacherScheduleWorkspace();

}


/* =========================================================
   PART 9 COMPLETE

   CURRENT SCHEDULE DESIGN PRESERVED.

   THIS PART DOES NOT CREATE:
   - a second schedule page
   - a replacement calendar
   - a second router
   - guessed modal markup
   - guessed backend ownership fields

   CENTRAL ACTION CONTROLLER WILL HANDLE:

     refresh-schedule
       -> refreshTeacherScheduleWorkspace()

     create-schedule
       -> open the existing schedule editor flow

     edit-schedule
       -> selected schedule editor

     schedule-prev-month
       -> moveTeacherScheduleCalendarMonth(-1)

     schedule-next-month
       -> moveTeacherScheduleCalendarMonth(1)

     schedule-calendar-date
       -> openTeacherScheduleCalendarDate()

     class-schedule
       -> prepareTeacherScheduleClass()
          + navigate to Schedule

   Schedule CRUD will use the existing backend contract:
     POST   /api/schedules
     PATCH  /api/schedules/:id
     DELETE /api/schedules/:id

   once the editor is reconciled with the final centralized
   action/controller architecture.
========================================================= */

/* =========================================================
   AIFT TEACHER STUDIO
   PART 9B

   SCHEDULE CRUD + PRODUCTION EDITOR
   ---------------------------------------------------------

   Backend contract:

     GET
       /api/schedules

     POST
       /api/schedules

     PATCH
       /api/schedules/:id

     DELETE
       /api/schedules/:id

   SECURITY:

   Backend remains authoritative.

   Teacher:
     only schedules for explicitly assigned classes.

   School/Admin:
     broader access according to routes/schedules.js.

   The frontend never invents:
     schoolId
     teacher ownership
========================================================= */


/* =========================================================
   SCHEDULE EDITOR STATE
========================================================= */

const teacherScheduleEditorState = {

  open:
    false,

  scheduleId:
    "",

  saving:
    false,

  deleting:
    false,

  initialized:
    false

};


/* =========================================================
   SCHEDULE EDITOR HOST
========================================================= */

function getTeacherScheduleEditor(){

  return $(
    "teacherScheduleEditor"
  );

}


/* =========================================================
   CREATE EDITOR HOST
========================================================= */

function ensureTeacherScheduleEditor(){

  let editor =
    getTeacherScheduleEditor();


  if(
    editor
  ){

    return editor;

  }


  editor =
    document.createElement(
      "div"
    );


  editor.id =
    "teacherScheduleEditor";


  editor.className =
    "teacher-schedule-editor";


  editor.hidden =
    true;


  editor.setAttribute(
    "aria-hidden",
    "true"
  );


  document.body.appendChild(
    editor
  );


  return editor;

}


/* =========================================================
   SCHEDULE FORM CLASS OPTIONS
========================================================= */

function buildTeacherScheduleClassOptions(
  selectedClassId =
    ""
){

  const selected =
    normalizeId(
      selectedClassId
    );


  return getTeacherClasses()
    .map(
      classItem => {

        const classId =
          normalizeId(
            classItem?._id ||
            classItem?.id
          );


        const title =
          getTeacherClassTitle(
            classItem
          );


        const subject =
          safeString(
            classItem?.subject
          );


        return `
          <option
            value="${escapeAttribute(classId)}"
            ${
              sameId(
                classId,
                selected
              )
                ? "selected"
                : ""
            }
          >
            ${escapeHtml(title)}${
              subject
                ? ` · ${escapeHtml(subject)}`
                : ""
            }
          </option>
        `;

      }
    )
    .join(
      ""
    );

}


/* =========================================================
   EDITOR DATE
========================================================= */

function getTeacherScheduleEditorDateValue(
  schedule
){

  return getTeacherScheduleDateString(
    schedule
  );

}


