/* =========================================================
   AIFT TEACHER STUDIO
   PRODUCTION REPLACEMENT
   PART 10

   QUIZZES WORKSPACE
   ---------------------------------------------------------
   1. Quiz workspace state
   2. Quiz identity helpers
   3. Quiz questions / points
   4. Quiz submission metrics
   5. Status normalization
   6. Search / class / status / sort filtering
   7. Quiz summary
   8. Quiz toolbar
   9. Existing quiz-card design
   10. Quiz grid
   11. Quiz results/details
   12. Quiz state reconciliation
   13. Refresh lifecycle
   14. Class shortcut preparation
   15. Workspace initialization

   IMPORTANT HTML AUDIT RESULT
   ---------------------------------------------------------
   Current teacher.html has:
     - Quizzes sidebar navigation
     - complete quiz CSS

   But it does NOT currently contain:
     data-teacher-page="quizzes"

   The final teacher.html repair will add the missing host
   section using the SAME existing design.

   No alternative quiz design is introduced here.
========================================================= */


/* =========================================================
   QUIZ WORKSPACE STATE
========================================================= */

const teacherQuizWorkspaceState = {

  search:
    "",

  classId:
    "",

  status:
    "",

  sort:
    "recent",

  selectedQuizId:
    "",

  editingQuizId:
    "",

  refreshing:
    false,

  saving:
    false,

  /*
    Unsaved questions currently being edited.

    These are intentionally separate from state.quizzes so
    editing a quiz cannot mutate the saved quiz before Save.
  */

  draftQuestions:
    [],

  initialized:
    false
};


/* =========================================================
   QUIZ ID
========================================================= */

function getTeacherQuizId(
  quiz
){

  return normalizeId(
    quiz?._id ||
    quiz?.id
  );

}


/* =========================================================
   QUIZ BY ID
========================================================= */

function getTeacherQuizById(
  quizId
){

  const normalizedQuizId =
    normalizeId(
      quizId
    );


  if (
    !normalizedQuizId
  ){

    return null;

  }


  return (
    getTeacherQuizzes()
      .find(
        quiz =>
          sameId(
            getTeacherQuizId(
              quiz
            ),
            normalizedQuizId
          )
      ) ||
    null
  );

}


/* =========================================================
   QUIZ CLASS ID
========================================================= */

function getTeacherQuizClassId(
  quiz
){

  return normalizeId(
    quiz
      ?.classId
      ?._id ||
    quiz
      ?.classId
  );

}


/* =========================================================
   QUIZ CLASS
========================================================= */

function getTeacherQuizClass(
  quiz
){

  const value =
    quiz?.classId;


  if (
    value &&
    typeof value ===
      "object"
  ){

    return (
      getTeacherClassById(
        value._id ||
        value.id
      ) ||
      value
    );

  }


  return (
    getTeacherClassById(
      value
    ) ||
    null
  );

}


/* =========================================================
   QUIZ TITLE
========================================================= */

function getTeacherQuizTitle(
  quiz
){

  return safeString(
    quiz?.title,
    "Untitled quiz"
  );

}


/* =========================================================
   QUIZ INSTRUCTIONS
========================================================= */

function getTeacherQuizInstructions(
  quiz
){

  return safeString(

    quiz?.instructions ||
    quiz?.description,

    ""

  );

}


/* =========================================================
   QUIZ QUESTIONS
========================================================= */

function getTeacherQuizQuestions(
  quiz
){

  return asArray(
    quiz?.questions
  );

}


/* =========================================================
   QUESTION COUNT
========================================================= */

function getTeacherQuizQuestionCount(
  quiz
){

  return getTeacherQuizQuestions(
    quiz
  ).length;

}


/* =========================================================
   QUESTION POINTS
========================================================= */

function getTeacherQuizQuestionPoints(
  question
){

  return Math.max(
    0,
    safeNumber(
      question?.points,
      1
    )
  );

}


/* =========================================================
   QUIZ TOTAL POINTS
========================================================= */

function getTeacherQuizTotalPoints(
  quiz
){

  return getTeacherQuizQuestions(
    quiz
  )
    .reduce(
      (
        total,
        question
      ) =>
        total +
        getTeacherQuizQuestionPoints(
          question
        ),
      0
    );

}


/* =========================================================
   QUIZ PASSING SCORE
========================================================= */

function getTeacherQuizPassingScore(
  quiz
){

  return clampPercentage(
    safeNumber(
      quiz?.passingScore,
      70
    )
  );

}


/* =========================================================
   QUIZ TIME LIMIT
========================================================= */

function getTeacherQuizTimeLimit(
  quiz
){

  return Math.max(
    0,
    safeInteger(
      quiz?.timeLimitMinutes,
      0
    )
  );

}


/* =========================================================
   QUIZ ATTEMPTS ALLOWED
========================================================= */

function getTeacherQuizAttemptsAllowed(
  quiz
){

  return Math.max(
    1,
    safeInteger(
      quiz?.attemptsAllowed,
      1
    )
  );

}


/* =========================================================
   QUIZ STATUS

   Backend values:
     draft
     published
     archived

   Current quiz CSS/UI uses:
     draft
     published
     closed

   Therefore archived is displayed as closed without changing
   the backend record itself.
========================================================= */

function getTeacherQuizStatus(
  quiz
){

  const status =
    safeString(
      quiz?.status,
      "draft"
    )
      .toLowerCase();


  if (
    status ===
    "archived"
  ){

    return "closed";

  }


  if (
    [
      "draft",
      "published",
      "closed"
    ].includes(
      status
    )
  ){

    return status;

  }


  return "draft";

}


/* =========================================================
   QUIZ BACKEND STATUS

   Convert visual "closed" back to backend "archived" only
   when creating/updating a quiz.
========================================================= */

function getTeacherQuizBackendStatus(
  value
){

  const status =
    safeString(
      value,
      "draft"
    )
      .toLowerCase();


  if (
    status ===
    "closed"
  ){

    return "archived";

  }


  if (
    [
      "draft",
      "published",
      "archived"
    ].includes(
      status
    )
  ){

    return status;

  }


  return "draft";

}


/* =========================================================
   QUIZ STATUS LABEL
========================================================= */

function getTeacherQuizStatusLabel(
  quiz
){

  switch(
    getTeacherQuizStatus(
      quiz
    )
  ){

    case "published":

      return "Published";

    case "closed":

      return "Closed";

    default:

      return "Draft";

  }

}


/* =========================================================
   QUIZ SUBMISSION QUIZ ID
========================================================= */

function getTeacherQuizSubmissionQuizId(
  submission
){

  return normalizeId(
    submission
      ?.quizId
      ?._id ||
    submission
      ?.quizId
  );

}


/* =========================================================
   SUBMISSIONS FOR QUIZ
========================================================= */

function getTeacherQuizSubmissions(
  quizId
){

  const normalizedQuizId =
    normalizeId(
      quizId
    );


  if (
    !normalizedQuizId
  ){

    return [];

  }


  return asArray(
    state.quizSubmissions
  )
    .filter(
      submission =>
        sameId(
          getTeacherQuizSubmissionQuizId(
            submission
          ),
          normalizedQuizId
        )
    );

}


/* =========================================================
   UNIQUE QUIZ PARTICIPANTS
========================================================= */

function getTeacherQuizParticipantIds(
  quizId
){

  const ids =
    new Set();


  getTeacherQuizSubmissions(
    quizId
  )
    .forEach(
      submission => {

        const studentId =
          normalizeId(
            submission
              ?.studentId
              ?._id ||
            submission
              ?.studentId
          );


        if (
          studentId
        ){

          ids.add(
            studentId
          );

        }

      }
    );


  return ids;

}


/* =========================================================
   EXPECTED QUIZ STUDENTS
========================================================= */

function getTeacherQuizExpectedStudents(
  quiz
){

  const classItem =
    getTeacherQuizClass(
      quiz
    );


  return classItem
    ? getTeacherClassStudentCount(
        classItem
      )
    : 0;

}


/* =========================================================
   QUIZ COMPLETION RATE
========================================================= */

function getTeacherQuizCompletionRate(
  quiz
){

  const quizId =
    getTeacherQuizId(
      quiz
    );

  const expected =
    getTeacherQuizExpectedStudents(
      quiz
    );


  if (
    !expected
  ){

    return 0;

  }


  const completed =
    getTeacherQuizParticipantIds(
      quizId
    ).size;


  return clampPercentage(
    (
      completed /
      expected
    ) *
    100
  );

}


/* =========================================================
   QUIZ SUBMISSION PERCENTAGE

   Support the response shapes used by the existing quiz
   implementation while keeping one normalized calculation.
========================================================= */

function getTeacherQuizSubmissionPercentage(
  submission,
  quiz
){

  const directCandidates = [

    submission?.percentage,
    submission?.percentageScore,
    submission?.scorePercent

  ];


  for (
    const value of directCandidates
  ){

    const number =
      Number(
        value
      );


    if (
      Number.isFinite(
        number
      )
    ){

      return clampPercentage(
        number
      );

    }

  }


  const rawScore =
    Number(
      submission?.score
    );

  const totalPoints =
    safeNumber(

      submission?.totalPoints ||
      getTeacherQuizTotalPoints(
        quiz
      ),

      0

    );


  if (
    Number.isFinite(
      rawScore
    ) &&
    totalPoints >
    0
  ){

    return clampPercentage(
      (
        rawScore /
        totalPoints
      ) *
      100
    );

  }


  return null;

}


/* =========================================================
   QUIZ AVERAGE SCORE
========================================================= */

function getTeacherQuizAverageScore(
  quiz
){

  const scores =
    getTeacherQuizSubmissions(
      getTeacherQuizId(
        quiz
      )
    )
      .map(
        submission =>
          getTeacherQuizSubmissionPercentage(
            submission,
            quiz
          )
      )
      .filter(
        score =>
          score !==
            null
      );


  if (
    !scores.length
  ){

    return 0;

  }


  return clampPercentage(
    scores.reduce(
      (
        total,
        score
      ) =>
        total +
        score,
      0
    ) /
    scores.length
  );

}


/* =========================================================
   QUIZ PASS RATE
========================================================= */

function getTeacherQuizPassRate(
  quiz
){

  const passingScore =
    getTeacherQuizPassingScore(
      quiz
    );

  const scores =
    getTeacherQuizSubmissions(
      getTeacherQuizId(
        quiz
      )
    )
      .map(
        submission =>
          getTeacherQuizSubmissionPercentage(
            submission,
            quiz
          )
      )
      .filter(
        score =>
          score !==
            null
      );


  if (
    !scores.length
  ){

    return 0;

  }


  const passing =
    scores.filter(
      score =>
        score >=
        passingScore
    )
      .length;


  return clampPercentage(
    (
      passing /
      scores.length
    ) *
    100
  );

}


/* =========================================================
   QUIZ LAST UPDATED
========================================================= */

function getTeacherQuizUpdatedTime(
  quiz
){

  return (
    toValidDate(
      quiz?.updatedAt ||
      quiz?.createdAt
    )?.getTime() ||
    0
  );

}


/* =========================================================
   FILTER QUIZZES
========================================================= */

function getFilteredTeacherQuizzes(){

  const search =
    safeString(
      teacherQuizWorkspaceState
        .search
    )
      .toLowerCase();

  const classId =
    normalizeId(
      teacherQuizWorkspaceState
        .classId
    );

  const status =
    safeString(
      teacherQuizWorkspaceState
        .status
    )
      .toLowerCase();


  let quizzes = [
    ...getTeacherQuizzes()
  ];


  /* -------------------------------------------------------
     SEARCH
  ------------------------------------------------------- */

  if (
    search
  ){

    quizzes =
      quizzes.filter(
        quiz => {

          const classItem =
            getTeacherQuizClass(
              quiz
            );


          const haystack =
            [

              getTeacherQuizTitle(
                quiz
              ),

              getTeacherQuizInstructions(
                quiz
              ),

              getTeacherClassTitle(
                classItem ||
                {}
              )

            ]
              .filter(
                Boolean
              )
              .join(
                " "
              )
              .toLowerCase();


          return haystack.includes(
            search
          );

        }
      );

  }


  /* -------------------------------------------------------
     CLASS
  ------------------------------------------------------- */

  if (
    classId
  ){

    quizzes =
      quizzes.filter(
        quiz =>
          sameId(
            getTeacherQuizClassId(
              quiz
            ),
            classId
          )
      );

  }


  /* -------------------------------------------------------
     STATUS
  ------------------------------------------------------- */

  if (
    status
  ){

    quizzes =
      quizzes.filter(
        quiz =>
          getTeacherQuizStatus(
            quiz
          ) ===
          status
      );

  }


  /* -------------------------------------------------------
     SORT
  ------------------------------------------------------- */

  switch(
    teacherQuizWorkspaceState
      .sort
  ){

    case "name":

      quizzes.sort(
        (
          first,
          second
        ) =>
          getTeacherQuizTitle(
            first
          )
            .localeCompare(
              getTeacherQuizTitle(
                second
              )
            )
      );

      break;


    case "questions":

      quizzes.sort(
        (
          first,
          second
        ) =>
          getTeacherQuizQuestionCount(
            second
          ) -
          getTeacherQuizQuestionCount(
            first
          )
      );

      break;


    case "completion":

      quizzes.sort(
        (
          first,
          second
        ) =>
          getTeacherQuizCompletionRate(
            second
          ) -
          getTeacherQuizCompletionRate(
            first
          )
      );

      break;


    case "score":

      quizzes.sort(
        (
          first,
          second
        ) =>
          getTeacherQuizAverageScore(
            second
          ) -
          getTeacherQuizAverageScore(
            first
          )
      );

      break;


    default:

      quizzes.sort(
        (
          first,
          second
        ) =>
          getTeacherQuizUpdatedTime(
            second
          ) -
          getTeacherQuizUpdatedTime(
            first
          )
      );

      break;

  }


  return quizzes;

}


/* =========================================================
   QUIZ SUMMARY
========================================================= */

function getTeacherQuizSummary(){

  const quizzes =
    getTeacherQuizzes();


  return {

    total:
      quizzes.length,

    published:
      quizzes.filter(
        quiz =>
          getTeacherQuizStatus(
            quiz
          ) ===
          "published"
      ).length,

    draft:
      quizzes.filter(
        quiz =>
          getTeacherQuizStatus(
            quiz
          ) ===
          "draft"
      ).length,

    attempts:
      asArray(
        state.quizSubmissions
      ).length

  };

}


