/* =========================================================
   QUIZ EMPTY STATE
========================================================= */

function renderTeacherQuizEmptyState(
  quizzes
){

  const empty =
    $(
      "teacherQuizzesEmpty"
    );


  if (
    !empty
  ){

    return;

  }


  const hasResults =
    quizzes.length >
    0;


  empty.hidden =
    hasResults;


  if (
    hasResults
  ){

    return;

  }


  const heading =
    empty.querySelector(
      "h2"
    );

  const description =
    empty.querySelector(
      "p"
    );


  if (
    heading
  ){

    heading.textContent =
      getTeacherQuizzes()
        .length
        ? "No quizzes found"
        : "No quizzes yet";

  }


  if (
    description
  ){

    description.textContent =
      getTeacherQuizzes()
        .length
        ? "No quizzes match the current search or filters."
        : "Create a quiz for one of your assigned classes.";

  }

}


/* =========================================================
   QUIZ GRID
========================================================= */

function renderTeacherQuizzesGrid(){

  const container =
    $(
      "teacherQuizzesGrid"
    );


  if (
    !container
  ){

    return;

  }


  const quizzes =
    getFilteredTeacherQuizzes();


  renderTeacherQuizEmptyState(
    quizzes
  );


  if (
    !quizzes.length
  ){

    container.innerHTML =
      "";

    container.hidden =
      true;

    return;

  }


  container.hidden =
    false;


  container.innerHTML =
    quizzes
      .map(
        createTeacherQuizCard
      )
      .join(
        ""
      );

}


/* =========================================================
   QUIZ RESULT STUDENT
========================================================= */

function getTeacherQuizSubmissionStudent(
  submission
){

  const value =
    submission?.studentId;


  if (
    value &&
    typeof value ===
      "object"
  ){

    return value;

  }


  return (
    getTeacherStudentById(
      value
    )
      ?.student ||
    null
  );

}


/* =========================================================
   QUIZ RESULT STUDENT NAME
========================================================= */

function getTeacherQuizSubmissionStudentName(
  submission
){

  const student =
    getTeacherQuizSubmissionStudent(
      submission
    );


  return safeString(

    student?.name ||
    student?.fullName ||
    student?.displayName,

    "Student"

  );

}


/* =========================================================
   QUIZ RESULT STUDENT AVATAR
========================================================= */

function getTeacherQuizSubmissionStudentAvatar(
  submission
){

  const student =
    getTeacherQuizSubmissionStudent(
      submission
    );


  return getSafeImageUrl(

    student?.profileImage ||
    student?.avatar ||
    student?.photoURL,

    FALLBACK_AVATAR

  );

}


/* =========================================================
   QUIZ RESULT DATE
========================================================= */

function getTeacherQuizSubmissionDate(
  submission
){

  return toValidDate(

    submission?.submittedAt ||
    submission?.completedAt ||
    submission?.createdAt

  );

}


/* =========================================================
   RENDER ONE QUIZ ATTEMPT
========================================================= */

function createTeacherQuizAttemptRow(
  submission,
  quiz
){

  const studentName =
    getTeacherQuizSubmissionStudentName(
      submission
    );

  const avatar =
    getTeacherQuizSubmissionStudentAvatar(
      submission
    );

  const percentage =
    getTeacherQuizSubmissionPercentage(
      submission,
      quiz
    );

  const submittedAt =
    getTeacherQuizSubmissionDate(
      submission
    );

  const passing =
    percentage !==
      null &&
    percentage >=
      getTeacherQuizPassingScore(
        quiz
      );


  return `
    <article
      class="teacher-quiz-attempt-row"
    >

      <div
        class="teacher-quiz-attempt-student"
      >

        <img
          src="${escapeAttribute(avatar)}"
          alt=""
          loading="lazy"
          referrerpolicy="no-referrer"
        />

        <span>

          <strong>
            ${escapeHtml(studentName)}
          </strong>

          <small>
            ${
              submittedAt
                ? escapeHtml(
                    formatRelativeDate(
                      submittedAt
                    )
                  )
                : "Submission date unavailable"
            }
          </small>

        </span>

      </div>


      <strong
        class="teacher-quiz-attempt-score"
      >
        ${
          percentage ===
          null
            ? "—"
            : `${percentage}%`
        }
      </strong>


      <span
        class="teacher-quiz-attempt-status"
      >
        ${
          percentage ===
          null
            ? "Recorded"
            : (
                passing
                  ? "Passed"
                  : "Below passing"
              )
        }
      </span>

    </article>
  `;

}


/* =========================================================
   SELECTED QUIZ RESULTS
========================================================= */

function renderTeacherSelectedQuiz(
  quizId =
    teacherQuizWorkspaceState
      .selectedQuizId
){

  const container =
    $(
      "teacherSelectedQuiz"
    );


  if (
    !container
  ){

    return;

  }


  const normalizedQuizId =
    normalizeId(
      quizId
    );

  const quiz =
    getTeacherQuizById(
      normalizedQuizId
    );


  if (
    !quiz
  ){

    teacherQuizWorkspaceState
      .selectedQuizId =
      "";

    container.hidden =
      true;

    container.innerHTML =
      "";

    return;

  }


  teacherQuizWorkspaceState
    .selectedQuizId =
    normalizedQuizId;


  const submissions =
    getTeacherQuizSubmissions(
      normalizedQuizId
    )
      .sort(
        (
          first,
          second
        ) =>
          (
            getTeacherQuizSubmissionDate(
              second
            )?.getTime() ||
            0
          ) -
          (
            getTeacherQuizSubmissionDate(
              first
            )?.getTime() ||
            0
          )
      );

  const classItem =
    getTeacherQuizClass(
      quiz
    );

  const averageScore =
    getTeacherQuizAverageScore(
      quiz
    );

  const passRate =
    getTeacherQuizPassRate(
      quiz
    );

  const completion =
    getTeacherQuizCompletionRate(
      quiz
    );


  container.hidden =
    false;


  container.innerHTML = `
    <section
      class="teacher-selected-quiz-panel"
    >

      <header
        class="teacher-selected-quiz-header"
      >

        <div>

          <span
            class="teacher-page-eyebrow"
          >
            QUIZ RESULTS
          </span>

          <h2>
            ${escapeHtml(
              getTeacherQuizTitle(
                quiz
              )
            )}
          </h2>

          <p>
            ${escapeHtml(
              getTeacherClassTitle(
                classItem ||
                {}
              )
            )}
          </p>

        </div>


        <button
          type="button"
          class="teacher-icon-button"
          data-teacher-action="close-quiz-results"
          aria-label="Close quiz results"
        >
          <i
            class="fa-solid fa-xmark"
            aria-hidden="true"
          ></i>
        </button>

      </header>


      <div
        class="teacher-quiz-attempts-summary"
      >

        <article>
          <strong>
            ${submissions.length}
          </strong>

          <span>
            Attempts
          </span>
        </article>


        <article>
          <strong>
            ${completion}%
          </strong>

          <span>
            Completion
          </span>
        </article>


        <article>
          <strong>
            ${
              submissions.length
                ? `${averageScore}%`
                : "—"
            }
          </strong>

          <span>
            Average score
          </span>
        </article>


        <article>
          <strong>
            ${
              submissions.length
                ? `${passRate}%`
                : "—"
            }
          </strong>

          <span>
            Pass rate
          </span>
        </article>

      </div>


      <div
        class="teacher-quiz-attempts-list"
      >

        ${
          submissions.length
            ? submissions
                .map(
                  submission =>
                    createTeacherQuizAttemptRow(
                      submission,
                      quiz
                    )
                )
                .join(
                  ""
                )
            : `
                <div
                  class="teacher-inline-empty"
                >
                  No quiz attempts have been recorded yet.
                </div>
              `
        }

      </div>

    </section>
  `;


  container
    .querySelectorAll(
      ".teacher-quiz-attempt-student img"
    )
    .forEach(
      image => {

        image.onerror =
          () => {

            image.onerror =
              null;

            image.src =
              FALLBACK_AVATAR;

          };

      }
    );

}


/* =========================================================
   OPEN QUIZ RESULTS
========================================================= */

function openTeacherQuizResults(
  quizId
){

  const quiz =
    getTeacherQuizById(
      quizId
    );


  if (
    !quiz
  ){

    notifyAIFTError(
      "The selected quiz is no longer available.",
      {
        title:
          "Quiz unavailable"
      }
    );


    return false;

  }


  teacherQuizWorkspaceState
    .selectedQuizId =
    getTeacherQuizId(
      quiz
    );


  renderTeacherSelectedQuiz();


  return true;

}


/* =========================================================
   CLOSE QUIZ RESULTS
========================================================= */

function closeTeacherQuizResults(){

  teacherQuizWorkspaceState
    .selectedQuizId =
    "";


  renderTeacherSelectedQuiz();

}


/* =========================================================
   REPLACE QUIZ IN STATE

   Used by create/edit lifecycle later.
========================================================= */

function replaceTeacherQuizInState(
  savedQuiz
){

  const quizId =
    getTeacherQuizId(
      savedQuiz
    );


  if (
    !quizId
  ){

    return false;

  }


  const index =
    state.quizzes
      .findIndex(
        quiz =>
          sameId(
            getTeacherQuizId(
              quiz
            ),
            quizId
          )
      );


  if (
    index >=
    0
  ){

    state.quizzes[
      index
    ] =
      savedQuiz;

  }else{

    state.quizzes.unshift(
      savedQuiz
    );

  }


  finalizeTeacherLoadedData();


  return true;

}


/* =========================================================
   REMOVE QUIZ FROM STATE
========================================================= */

function removeTeacherQuizFromState(
  quizId
){

  const normalizedQuizId =
    normalizeId(
      quizId
    );


  if (
    !normalizedQuizId
  ){

    return false;

  }


  state.quizzes =
    state.quizzes
      .filter(
        quiz =>
          !sameId(
            getTeacherQuizId(
              quiz
            ),
            normalizedQuizId
          )
      );


  /*
    Deleting a quiz also deletes its QuizSubmission records on
    the backend, so remove those from local state too.
  */

  state.quizSubmissions =
    state.quizSubmissions
      .filter(
        submission =>
          !sameId(
            getTeacherQuizSubmissionQuizId(
              submission
            ),
            normalizedQuizId
          )
      );


  if (
    sameId(
      teacherQuizWorkspaceState
        .selectedQuizId,
      normalizedQuizId
    )
  ){

    teacherQuizWorkspaceState
      .selectedQuizId =
      "";

  }


  finalizeTeacherLoadedData();


  return true;

}

/* =========================================================
   QUIZ EDITOR
   PRODUCTION CREATE / EDIT / SAVE / DELETE
========================================================= */


/* =========================================================
   QUIZ EDITOR QUESTION SEQUENCE
========================================================= */

let teacherQuizEditorQuestionSequence =
  0;


/* =========================================================
   NORMALIZE QUIZ EDITOR QUESTION
========================================================= */

function normalizeTeacherQuizEditorQuestion(
  question = {}
){

  teacherQuizEditorQuestionSequence +=
    1;


  const type =
    safeString(
      question?.type,
      "multiple_choice"
    )
      .toLowerCase();


  const allowedTypes =
    new Set([
      "multiple_choice",
      "true_false",
      "short_answer"
    ]);


  return {

    editorId:
      safeString(
        question?.editorId
      ) ||
      `teacher-quiz-question-${Date.now()}-${teacherQuizEditorQuestionSequence}`,

    questionBankId:
      normalizeId(
        question?.questionBankId
      ),

    question:
      safeString(
        question?.question
      ),

    type:
      allowedTypes.has(
        type
      )
        ? type
        : "multiple_choice",

    options:
      Array.isArray(
        question?.options
      )
        ? question.options
            .map(
              option =>
                safeString(
                  typeof option ===
                    "object"
                    ? (
                        option?.text ||
                        option?.label ||
                        option?.value
                      )
                    : option
                )
            )
            .filter(
              Boolean
            )
        : [],

    correctAnswer:
      question?.correctAnswer ??
      "",

    explanation:
      safeString(
        question?.explanation
      ),

    points:
      Math.max(
        0,
        safeNumber(
          question?.points,
          1
        )
      )

  };

}


/* =========================================================
   EDITOR QUESTIONS
========================================================= */

function getTeacherQuizDraftQuestions(){

  return Array.isArray(
    teacherQuizWorkspaceState
      .draftQuestions
  )
    ? teacherQuizWorkspaceState
        .draftQuestions
    : [];

}


/* =========================================================
   SET EDITOR QUESTIONS
========================================================= */

function setTeacherQuizDraftQuestions(
  questions
){

  teacherQuizWorkspaceState
    .draftQuestions =
    asArray(
      questions
    )
      .map(
        question =>
          normalizeTeacherQuizEditorQuestion(
            question
          )
      );


  return teacherQuizWorkspaceState
    .draftQuestions;

}


/* =========================================================
   QUIZ EDITOR HOST
========================================================= */

function getTeacherQuizEditorHost(){

  return (
    $(
      "teacherQuizEditor"
    ) ||
    $(
      "quizEditorWorkspace"
    ) ||
    null
  );

}


/* =========================================================
   QUIZ EDITOR CLASS OPTIONS
========================================================= */

function renderTeacherQuizEditorClassOptions(
  selectedClassId =
    ""
){

  return getTeacherClasses()
    .map(
      classItem => {

        const classId =
          normalizeId(
            classItem?._id ||
            classItem?.id
          );


        return `
          <option
            value="${escapeAttribute(
              classId
            )}"
            ${
              sameId(
                classId,
                selectedClassId
              )
                ? "selected"
                : ""
            }
          >
            ${escapeHtml(
              getTeacherClassTitle(
                classItem
              )
            )}
          </option>
        `;

      }
    )
    .join(
      ""
    );

}


/* =========================================================
   CREATE QUESTION EDITOR ROW
========================================================= */

function createTeacherQuizEditorQuestionMarkup(
  question,
  index
){

  const editorId =
    safeString(
      question?.editorId
    );


  const type =
    safeString(
      question?.type,
      "multiple_choice"
    );


  const options =
    asArray(
      question?.options
    );


  return `
    <article
      class="teacher-quiz-question-editor"
      data-quiz-question-editor-id="${escapeAttribute(
        editorId
      )}"
    >

      <div
        class="teacher-quiz-question-editor-head"
      >

        <div>
          <span>
            Question ${index + 1}
          </span>

          <strong>
            ${
              safeString(
                question?.question
              )
                ? escapeHtml(
                    question.question
                  )
                : "New question"
            }
          </strong>
        </div>


        <button
          type="button"
          class="teacher-icon-button"
          data-quiz-question-remove="${escapeAttribute(
            editorId
          )}"
          aria-label="Remove question"
        >
          <i
            class="fa-regular fa-trash-can"
            aria-hidden="true"
          ></i>
        </button>

      </div>


      <div
        class="teacher-quiz-question-editor-grid"
      >

        <label
          class="teacher-form-field teacher-form-field-full"
        >

          <span>
            Question
          </span>

          <textarea
            class="teacher-quiz-question-text"
            rows="3"
            maxlength="2000"
            placeholder="Enter the question..."
          >${escapeHtml(
            question?.question ||
            ""
          )}</textarea>

        </label>


        <label
          class="teacher-form-field"
        >

          <span>
            Question type
          </span>

          <select
            class="teacher-quiz-question-type"
          >

            <option
              value="multiple_choice"
              ${
                type ===
                "multiple_choice"
                  ? "selected"
                  : ""
              }
            >
              Multiple choice
            </option>

            <option
              value="true_false"
              ${
                type ===
                "true_false"
                  ? "selected"
                  : ""
              }
            >
              True / False
            </option>

            <option
              value="short_answer"
              ${
                type ===
                "short_answer"
                  ? "selected"
                  : ""
              }
            >
              Short answer
            </option>

          </select>

        </label>


        <label
          class="teacher-form-field"
        >

          <span>
            Points
          </span>

          <input
            class="teacher-quiz-question-points"
            type="number"
            min="0"
            step="1"
            value="${escapeAttribute(
              question?.points ??
              1
            )}"
          />

        </label>


        ${
          type ===
          "multiple_choice"
            ? `
                <label
                  class="teacher-form-field teacher-form-field-full"
                >

                  <span>
                    Answer options
                  </span>

                  <textarea
                    class="teacher-quiz-question-options"
                    rows="5"
                    placeholder="Enter one option per line..."
                  >${escapeHtml(
                    options.join(
                      "\n"
                    )
                  )}</textarea>

                  <small>
                    Enter one answer option per line.
                  </small>

                </label>


                <label
                  class="teacher-form-field teacher-form-field-full"
                >

                  <span>
                    Correct answer
                  </span>

                  <input
                    class="teacher-quiz-question-answer"
                    type="text"
                    value="${escapeAttribute(
                      question?.correctAnswer ??
                      ""
                    )}"
                    placeholder="Enter the correct option or option index"
                  />

                </label>
              `
            : ""
        }


        ${
          type ===
          "true_false"
            ? `
                <label
                  class="teacher-form-field teacher-form-field-full"
                >

                  <span>
                    Correct answer
                  </span>

                  <select
                    class="teacher-quiz-question-answer"
                  >
                    <option
                      value="true"
                      ${
                        String(
                          question?.correctAnswer
                        ) ===
                        "true"
                          ? "selected"
                          : ""
                      }
                    >
                      True
                    </option>

                    <option
                      value="false"
                      ${
                        String(
                          question?.correctAnswer
                        ) ===
                        "false"
                          ? "selected"
                          : ""
                      }
                    >
                      False
                    </option>
                  </select>

                </label>
              `
            : ""
        }


        ${
          type ===
          "short_answer"
            ? `
                <label
                  class="teacher-form-field teacher-form-field-full"
                >

                  <span>
                    Expected answer
                  </span>

                  <input
                    class="teacher-quiz-question-answer"
                    type="text"
                    value="${escapeAttribute(
                      question?.correctAnswer ??
                      ""
                    )}"
                    placeholder="Enter the expected answer"
                  />

                </label>
              `
            : ""
        }


        <label
          class="teacher-form-field teacher-form-field-full"
        >

          <span>
            Explanation
          </span>

          <textarea
            class="teacher-quiz-question-explanation"
            rows="3"
            maxlength="3000"
            placeholder="Optional answer explanation..."
          >${escapeHtml(
            question?.explanation ||
            ""
          )}</textarea>

        </label>

      </div>

    </article>
  `;

}


/* =========================================================
   READ QUESTIONS FROM EDITOR DOM
========================================================= */

function getTeacherQuizEditorQuestions(){

  const host =
    getTeacherQuizEditorHost();


  if (
    !host
  ){

    return [];

  }


  return Array.from(
    host.querySelectorAll(
      "[data-quiz-question-editor-id]"
    )
  )
    .map(
      questionElement => {

        const type =
          safeString(
            questionElement
              .querySelector(
                ".teacher-quiz-question-type"
              )
              ?.value,
            "multiple_choice"
          );


        const question =
          safeString(
            questionElement
              .querySelector(
                ".teacher-quiz-question-text"
              )
              ?.value
          );


        const points =
          Math.max(
            0,
            safeNumber(
              questionElement
                .querySelector(
                  ".teacher-quiz-question-points"
                )
                ?.value,
              1
            )
          );


        const options =
          type ===
          "multiple_choice"
            ? safeString(
                questionElement
                  .querySelector(
                    ".teacher-quiz-question-options"
                  )
                  ?.value
              )
                .split(
                  "\n"
                )
                .map(
                  option =>
                    option.trim()
                )
                .filter(
                  Boolean
                )
            : (
                type ===
                "true_false"
                  ? [
                      "True",
                      "False"
                    ]
                  : []
              );


        let correctAnswer =
          questionElement
            .querySelector(
              ".teacher-quiz-question-answer"
            )
            ?.value ??
          "";


        if (
          type ===
          "true_false"
        ){

          correctAnswer =
            String(
              correctAnswer
            ) ===
            "true";

        }


        return {

          question,

          type,

          points,

          options,

          correctAnswer,

          explanation:
            safeString(
              questionElement
                .querySelector(
                  ".teacher-quiz-question-explanation"
                )
                ?.value
            )

        };

      }
    )
    .filter(
      item =>
        Boolean(
          item.question
        )
    );

}


/* =========================================================
   RENDER QUIZ QUESTION EDITOR
========================================================= */

function renderTeacherQuizEditorQuestions(){

  const container =
    $(
      "teacherQuizEditorQuestions"
    );


  if (
    !container
  ){

    return false;

  }


  const questions =
    getTeacherQuizDraftQuestions();


  if (
    !questions.length
  ){

    container.innerHTML = `
      <div
        class="teacher-inline-empty"
      >
        No questions yet. Add your first question.
      </div>
    `;


    return true;

  }


  container.innerHTML =
    questions
      .map(
        (
          question,
          index
        ) =>
          createTeacherQuizEditorQuestionMarkup(
            question,
            index
          )
      )
      .join(
        ""
      );


  bindTeacherQuizEditorQuestionControls();


  return true;

}


/* =========================================================
   SYNC CURRENT DOM QUESTIONS BEFORE STRUCTURAL CHANGE
========================================================= */

function syncTeacherQuizDraftQuestionsFromDom(){

  const host =
    getTeacherQuizEditorHost();


  if (
    !host ||
    !host.querySelector(
      "[data-quiz-question-editor-id]"
    )
  ){

    return;

  }


  const domQuestions =
    getTeacherQuizEditorQuestions();


  setTeacherQuizDraftQuestions(
    domQuestions
  );

}


/* =========================================================
   ADD QUIZ QUESTION
========================================================= */

function addTeacherQuizEditorQuestion(
  question = {}
){

  syncTeacherQuizDraftQuestionsFromDom();


  const questions =
    getTeacherQuizDraftQuestions();


  questions.push(
    normalizeTeacherQuizEditorQuestion({

      type:
        "multiple_choice",

      points:
        1,

      options:[
        "Option A",
        "Option B"
      ],

      correctAnswer:
        0,

      ...question

    })
  );


  teacherQuizWorkspaceState
    .draftQuestions =
    questions;


  renderTeacherQuizEditorQuestions();


  return true;

}


/* =========================================================
   REMOVE QUIZ QUESTION
========================================================= */

function removeTeacherQuizEditorQuestion(
  editorId
){

  syncTeacherQuizDraftQuestionsFromDom();


  teacherQuizWorkspaceState
    .draftQuestions =
    getTeacherQuizDraftQuestions()
      .filter(
        question =>
          safeString(
            question?.editorId
          ) !==
          safeString(
            editorId
          )
      );


  renderTeacherQuizEditorQuestions();


  return true;

}


/* =========================================================
   CHANGE QUESTION TYPE
========================================================= */

function changeTeacherQuizQuestionType(
  editorId,
  type
){

  syncTeacherQuizDraftQuestionsFromDom();


  const question =
    getTeacherQuizDraftQuestions()
      .find(
        item =>
          safeString(
            item?.editorId
          ) ===
          safeString(
            editorId
          )
      );


  if (
    !question
  ){

    return false;

  }


  question.type =
    safeString(
      type,
      "multiple_choice"
    );


  if (
    question.type ===
    "multiple_choice" &&
    !question.options.length
  ){

    question.options = [
      "Option A",
      "Option B"
    ];

    question.correctAnswer =
      0;

  }


  if (
    question.type ===
    "true_false"
  ){

    question.options = [
      "True",
      "False"
    ];

    question.correctAnswer =
      true;

  }


  if (
    question.type ===
    "short_answer"
  ){

    question.options =
      [];

    question.correctAnswer =
      "";

  }


  renderTeacherQuizEditorQuestions();


  return true;

}


/* =========================================================
   BIND QUESTION CONTROLS
========================================================= */

function bindTeacherQuizEditorQuestionControls(){

  const container =
    $(
      "teacherQuizEditorQuestions"
    );


  if (
    !container
  ){

    return;

  }


  container
    .querySelectorAll(
      "[data-quiz-question-remove]"
    )
    .forEach(
      button => {

        button.onclick =
          () => {

            removeTeacherQuizEditorQuestion(
              button.dataset
                .quizQuestionRemove
            );

          };

      }
    );


  container
    .querySelectorAll(
      ".teacher-quiz-question-type"
    )
    .forEach(
      select => {

        select.onchange =
          () => {

            const item =
              select.closest(
                "[data-quiz-question-editor-id]"
              );


            changeTeacherQuizQuestionType(
              item?.dataset
                ?.quizQuestionEditorId,
              select.value
            );

          };

      }
    );

}


/* =========================================================
   OPEN QUIZ EDITOR
========================================================= */

function openTeacherQuizEditor(
  quizId =
    ""
){

  const host =
    getTeacherQuizEditorHost();


  if (
    !host
  ){

    notifyAIFTError(
      "The Quiz editor container is missing from teacher.html.",
      {
        title:
          "Quiz editor unavailable"
      }
    );


    return false;

  }


  const normalizedQuizId =
    normalizeId(
      quizId
    );


  const quiz =
    normalizedQuizId
      ? getTeacherQuizById(
          normalizedQuizId
        )
      : null;


  if (
    normalizedQuizId &&
    !quiz
  ){

    notifyAIFTError(
      "The selected quiz is no longer available.",
      {
        title:
          "Quiz unavailable"
      }
    );


    return false;

  }


  const editing =
    Boolean(
      quiz
    );


  const selectedClassId =
    normalizeId(
      quiz?.classId?._id ||
      quiz?.classId ||
      teacherQuizWorkspaceState
        .classId ||
      state.selectedClassId
    );


  teacherQuizWorkspaceState
    .editingQuizId =
    normalizedQuizId;


  setTeacherQuizDraftQuestions(
    quiz
      ? getTeacherQuizQuestions(
          quiz
        )
      : []
  );


  host.hidden =
    false;


  host.innerHTML = `
    <section
      class="teacher-quiz-editor-panel"
    >

      <header
        class="teacher-quiz-editor-header"
      >

        <div>
          <span>
            ${
              editing
                ? "Edit quiz"
                : "New quiz"
            }
          </span>

          <h2>
            ${
              editing
                ? escapeHtml(
                    getTeacherQuizTitle(
                      quiz
                    )
                  )
                : "Create Quiz"
            }
          </h2>
        </div>


        <button
          type="button"
          class="teacher-icon-button"
          data-teacher-action="close-quiz-editor"
          aria-label="Close quiz editor"
        >
          <i
            class="fa-solid fa-xmark"
            aria-hidden="true"
          ></i>
        </button>

      </header>


      <div
        class="teacher-quiz-editor-body"
      >

        <div
          class="teacher-quiz-editor-settings"
        >

          <label
            class="teacher-form-field"
          >
            <span>
              Class
            </span>

            <select
              id="teacherQuizClassId"
              required
            >
              <option value="">
                Select class
              </option>

              ${renderTeacherQuizEditorClassOptions(
                selectedClassId
              )}
            </select>
          </label>


          <label
            class="teacher-form-field"
          >
            <span>
              Quiz title
            </span>

            <input
              id="teacherQuizTitle"
              type="text"
              maxlength="160"
              autocomplete="off"
              placeholder="Enter quiz title"
              value="${escapeAttribute(
                quiz?.title ||
                ""
              )}"
            />
          </label>


          <label
            class="teacher-form-field teacher-form-field-full"
          >
            <span>
              Instructions
            </span>

            <textarea
              id="teacherQuizDescription"
              rows="4"
              maxlength="5000"
              placeholder="Add instructions for students..."
            >${escapeHtml(
              getTeacherQuizInstructions(
                quiz ||
                {}
              )
            )}</textarea>
          </label>


          <label
            class="teacher-form-field"
          >
            <span>
              Status
            </span>

            <select
              id="teacherQuizStatus"
            >
              <option
                value="draft"
                ${
                  getTeacherQuizStatus(
                    quiz ||
                    {}
                  ) ===
                  "draft"
                    ? "selected"
                    : ""
                }
              >
                Draft
              </option>

              <option
                value="published"
                ${
                  getTeacherQuizStatus(
                    quiz ||
                    {}
                  ) ===
                  "published"
                    ? "selected"
                    : ""
                }
              >
                Published
              </option>

              <option
                value="closed"
                ${
                  getTeacherQuizStatus(
                    quiz ||
                    {}
                  ) ===
                  "closed"
                    ? "selected"
                    : ""
                }
              >
                Closed
              </option>
            </select>
          </label>


          <label
            class="teacher-form-field"
          >
            <span>
              Time limit
            </span>

            <div
              class="teacher-input-suffix"
            >
              <input
                id="teacherQuizTimeLimit"
                type="number"
                min="0"
                max="1440"
                value="${escapeAttribute(
                  getTeacherQuizTimeLimit(
                    quiz ||
                    {}
                  )
                )}"
              />

              <span>
                minutes
              </span>
            </div>
          </label>

        </div>


        <div
          class="teacher-quiz-editor-question-head"
        >

          <div>
            <span>
              QUESTIONS
            </span>

            <h3>
              Quiz Questions
            </h3>
          </div>


          <button
            type="button"
            id="teacherQuizAddQuestionButton"
            class="teacher-secondary-button"
          >
            <i
              class="fa-solid fa-plus"
              aria-hidden="true"
            ></i>

            Add question
          </button>

        </div>


        <div
          id="teacherQuizEditorQuestions"
          class="teacher-quiz-editor-questions"
        ></div>

      </div>


      <footer
        class="teacher-quiz-editor-footer"
      >

        ${
          editing
            ? `
                <button
                  type="button"
                  class="teacher-danger-button"
                  data-teacher-action="delete-quiz"
                  data-quiz-id="${escapeAttribute(
                    normalizedQuizId
                  )}"
                >
                  <i
                    class="fa-regular fa-trash-can"
                    aria-hidden="true"
                  ></i>

                  Delete quiz
                </button>
              `
            : `<span></span>`
        }


        <div
          class="teacher-quiz-editor-footer-actions"
        >

          <button
            type="button"
            class="teacher-secondary-button"
            data-teacher-action="close-quiz-editor"
          >
            Cancel
          </button>


          <button
            type="button"
            id="teacherQuizSaveButton"
            class="teacher-primary-button"
            data-teacher-action="save-quiz"
          >
            <i
              class="fa-solid fa-floppy-disk"
              aria-hidden="true"
            ></i>

            <span>
              ${
                editing
                  ? "Save Changes"
                  : "Create Quiz"
              }
            </span>
          </button>

        </div>

      </footer>

    </section>
  `;


  renderTeacherQuizEditorQuestions();


  $(
    "teacherQuizAddQuestionButton"
  )
    ?.addEventListener(
      "click",
      () => {

        addTeacherQuizEditorQuestion();

      }
    );


  /*
    New quizzes should not open as an empty unusable form.
  */

  if (
    !editing &&
    !getTeacherQuizDraftQuestions()
      .length
  ){

    addTeacherQuizEditorQuestion();

  }


  window.requestAnimationFrame(
    () => {

      host.scrollIntoView({
        behavior:
          "smooth",

        block:
          "start"
      });

    }
  );


  return true;

}


/* =========================================================
   CLOSE QUIZ EDITOR
========================================================= */

function closeTeacherQuizEditor(){

  teacherQuizWorkspaceState
    .editingQuizId =
    "";


  teacherQuizWorkspaceState
    .draftQuestions =
    [];


  teacherQuizWorkspaceState
    .saving =
    false;


  const host =
    getTeacherQuizEditorHost();


  if (
    host
  ){

    host.hidden =
      true;

    host.innerHTML =
      "";

  }


  return true;

}


/* =========================================================
   BUILD QUIZ PAYLOAD
========================================================= */

function getTeacherQuizFormPayload(){

  const classId =
    normalizeId(
      $(
        "teacherQuizClassId"
      )?.value
    );


  const title =
    safeString(
      $(
        "teacherQuizTitle"
      )?.value
    );


  const description =
    safeString(
      $(
        "teacherQuizDescription"
      )?.value
    );


  const status =
    getTeacherQuizBackendStatus(
      $(
        "teacherQuizStatus"
      )?.value
    );


  const durationMinutes =
    Math.max(
      0,
      safeInteger(
        $(
          "teacherQuizTimeLimit"
        )?.value,
        0
      )
    );


  return {

    schoolId:
      getSchoolId(),

    classId,

    teacherId:
      getTeacherId(),

    title,

    description,

    instructions:
      description,

    status,

    durationMinutes,

    timeLimit:
      durationMinutes,

    timeLimitMinutes:
      durationMinutes,

    questions:
      getTeacherQuizEditorQuestions()

  };

}


/* =========================================================
   SAVE QUIZ
========================================================= */

async function saveTeacherQuiz(){

  if (
    teacherQuizWorkspaceState
      .saving
  ){

    return false;

  }


  const payload =
    getTeacherQuizFormPayload();


  if (
    !payload.classId
  ){

    notifyAIFTWarning(
      "Please select a class.",
      {
        title:
          "Class required"
      }
    );


    return false;

  }


  if (
    !getTeacherClassById(
      payload.classId
    )
  ){

    notifyAIFTError(
      "You do not have access to the selected class.",
      {
        title:
          "Class unavailable"
      }
    );


    return false;

  }


  if (
    !payload.title
  ){

    notifyAIFTWarning(
      "Quiz title is required.",
      {
        title:
          "Title required"
      }
    );


    return false;

  }


  if (
    !payload.questions.length
  ){

    notifyAIFTWarning(
      "Add at least one question before saving the quiz.",
      {
        title:
          "Question required"
      }
    );


    return false;

  }


  const invalidMultipleChoice =
    payload.questions
      .findIndex(
        question =>
          question.type ===
            "multiple_choice" &&
          (
            question.options.length <
              2 ||
            (
              question.correctAnswer ===
                "" ||
              question.correctAnswer ===
                null ||
              question.correctAnswer ===
                undefined
            )
          )
      );


  if (
    invalidMultipleChoice >=
    0
  ){

    notifyAIFTWarning(
      `Question ${
        invalidMultipleChoice + 1
      } needs at least two options and a correct answer.`,
      {
        title:
          "Incomplete question"
      }
    );


    return false;

  }


  const quizId =
    normalizeId(
      teacherQuizWorkspaceState
        .editingQuizId
    );


  const saveButton =
    $(
      "teacherQuizSaveButton"
    );


  teacherQuizWorkspaceState
    .saving =
    true;


  if (
    saveButton
  ){

    saveButton.disabled =
      true;

    saveButton.setAttribute(
      "aria-busy",
      "true"
    );

    saveButton.innerHTML = `
      <i
        class="fa-solid fa-spinner fa-spin"
        aria-hidden="true"
      ></i>

      <span>
        Saving...
      </span>
    `;

  }


  try{

    const response =
      quizId
        ? await apiPatch(
            `/api/quizzes/${
              encodeURIComponent(
                quizId
              )
            }`,
            payload
          )
        : await apiPost(
            "/api/quizzes",
            payload
          );


    const savedQuiz =
      response?.quiz ||
      response?.data ||
      response;


    if (
      savedQuiz &&
      typeof savedQuiz ===
        "object"
    ){

      replaceTeacherQuizInState(
        savedQuiz
      );

    }else{

      await loadTeacherQuizzes();

    }


    /*
      Always reload quizzes after a mutation.

      This keeps Teacher Studio synchronized with whatever the
      backend normalized or populated.
    */

    await loadTeacherQuizzes();


    finalizeTeacherLoadedData();


    closeTeacherQuizEditor();


    renderTeacherQuizzesWorkspace();


    notifyAIFTSuccess(
      quizId
        ? "Quiz updated successfully."
        : "Quiz created successfully.",
      {
        title:
          quizId
            ? "Quiz updated"
            : "Quiz created"
      }
    );


    return true;

  }catch(
    error
  ){

    console.error(
      "saveTeacherQuiz failed:",
      error
    );


    notifyAIFTError(
      getErrorMessage(
        error,
        "AIFT could not save this quiz."
      ),
      {
        title:
          "Quiz not saved"
      }
    );


    return false;

  }finally{

    teacherQuizWorkspaceState
      .saving =
      false;


    if (
      $(
        "teacherQuizSaveButton"
      )
    ){

      const button =
        $(
          "teacherQuizSaveButton"
        );


      button.disabled =
        false;

      button.setAttribute(
        "aria-busy",
        "false"
      );

      button.innerHTML = `
        <i
          class="fa-solid fa-floppy-disk"
          aria-hidden="true"
        ></i>

        <span>
          ${
            quizId
              ? "Save Changes"
              : "Create Quiz"
          }
        </span>
      `;

    }

  }

}


/* =========================================================
   DELETE QUIZ
========================================================= */

async function deleteTeacherQuiz(
  quizId
){

  const normalizedQuizId =
    normalizeId(
      quizId ||
      teacherQuizWorkspaceState
        .editingQuizId
  );


  const quiz =
    getTeacherQuizById(
      normalizedQuizId
    );


  if (
    !quiz
  ){

    notifyAIFTError(
      "The selected quiz is no longer available.",
      {
        title:
          "Quiz unavailable"
      }
    );


    return false;

  }


  const confirmed =
    window.confirm(
      `Delete "${getTeacherQuizTitle(
        quiz
      )}"?\n\nThis action cannot be undone.`
    );


  if (
    !confirmed
  ){

    return false;

  }


  try{

    await apiDelete(
      `/api/quizzes/${
        encodeURIComponent(
          normalizedQuizId
        )
      }`
    );


    removeTeacherQuizFromState(
      normalizedQuizId
    );


    closeTeacherQuizEditor();


    renderTeacherQuizzesWorkspace();


    notifyAIFTSuccess(
      "Quiz deleted successfully.",
      {
        title:
          "Quiz deleted"
      }
    );


    return true;

  }catch(
    error
  ){

    console.error(
      "deleteTeacherQuiz failed:",
      error
    );


    notifyAIFTError(
      getErrorMessage(
        error,
        "AIFT could not delete the quiz."
      ),
      {
        title:
          "Quiz not deleted"
      }
    );


    return false;

  }

}


/* =========================================================
   PREPARE QUIZZES FOR CLASS

   Used from a class card shortcut.
========================================================= */

function prepareTeacherQuizzesClass(
  classId
){

  const classItem =
    getTeacherClassById(
      classId
    );


  if (
    !classItem
  ){

    return false;

  }


  teacherQuizWorkspaceState
    .classId =
    normalizeId(
      classId
    );

  teacherQuizWorkspaceState
    .selectedQuizId =
    "";


  return true;

}


/* =========================================================
   REFRESH QUIZZES

   Uses the class-scoped loaders from Part 2.
========================================================= */

async function refreshTeacherQuizzesWorkspace(){

  if (
    teacherQuizWorkspaceState
      .refreshing
  ){

    return false;

  }


  teacherQuizWorkspaceState
    .refreshing =
    true;


  renderTeacherQuizzesHeader();


  try{

    const results =
      await Promise.allSettled([

        loadTeacherQuizzes(),

        loadTeacherQuizSubmissions()

      ]);


    const failures =
      [];


    results.forEach(
      (
        result,
        index
      ) => {

        if (
          result.status !==
          "rejected"
        ){

          return;

        }


        const name =
          [
            "Quizzes",
            "Quiz submissions"
          ][
            index
          ];


        failures.push({
          name,
          error:
            result.reason
        });


        reportOptionalRequestError(
          name,
          result.reason
        );

      }
    );


    finalizeTeacherLoadedData();


    renderTeacherQuizzesWorkspace();


    if (
      failures.length
    ){

      notifyAIFTWarning(
        "Some quiz information could not be refreshed.",
        {
          title:
            "Quiz refresh incomplete"
        }
      );


      return false;

    }


    notifyAIFTSuccess(
      "Quizzes and student results are up to date.",
      {
        title:
          "Quizzes refreshed"
      }
    );


    return true;

  }catch(
    error
  ){

    notifyAIFTError(
      getErrorMessage(
        error,
        "Quizzes could not be refreshed."
      ),
      {
        title:
          "Refresh failed"
      }
    );


    return false;

  }finally{

    teacherQuizWorkspaceState
      .refreshing =
      false;


    renderTeacherQuizzesHeader();

  }

}


/* =========================================================
   RENDER COMPLETE QUIZZES WORKSPACE

   If the host is absent in the CURRENT teacher.html this
   function exits safely.

   It does NOT redirect to Overview.

   That is intentional: the missing HTML host is a structural
   bug that will be fixed explicitly instead of hidden.
========================================================= */

function renderTeacherQuizzesWorkspace(){

  const host =
    $(
      "teacherPageQuizzes"
    );


  if (
    !host
  ){

    return false;

  }


  renderTeacherQuizzesHeader();

  renderTeacherQuizzesSummary();

  renderTeacherQuizzesToolbar();

  renderTeacherQuizzesGrid();

  renderTeacherSelectedQuiz();


  return true;

}


/* =========================================================
   COMPATIBILITY QUIZ RENDERER
========================================================= */

function renderTeacherQuizzes(){

  return renderTeacherQuizzesWorkspace();

}


/* =========================================================
   INITIALIZE QUIZZES
========================================================= */

function initializeTeacherQuizzesWorkspace(){

  if (
    teacherQuizWorkspaceState
      .initialized
  ){

    renderTeacherQuizzesWorkspace();

    return;

  }


  teacherQuizWorkspaceState
    .initialized =
    true;


  renderTeacherQuizzesWorkspace();

}


/* =========================================================
   REFRESH QUIZ UI FROM CURRENT STATE
========================================================= */

function refreshTeacherQuizzesFromCurrentState(){

  renderTeacherQuizzesSummary();

  renderTeacherQuizzesGrid();

  renderTeacherSelectedQuiz();

}


/* =========================================================
   PART 10 COMPLETE

   BACKEND READS
   ---------------------------------------------------------
   Quiz loading remains CLASS-SCOPED through Part 2:

     GET /api/quizzes?classId=<assigned-class>

     GET /api/quizzes/submissions/list?classId=<assigned-class>

   That is deliberate because classId causes the backend to
   authorize against the real class.

   VERIFIED CRUD CONTRACT
   ---------------------------------------------------------
     POST   /api/quizzes
     PATCH  /api/quizzes/:id
     DELETE /api/quizzes/:id

   CREATE REQUIRES:
     schoolId
     classId
     title

   Backend then derives/validates the class and teacher access.

   QUIZ STATUS BACKEND VALUES:
     draft
     published
     archived

   CURRENT UI DISPLAY VALUES:
     draft
     published
     closed

   "closed" maps to backend "archived".

   CENTRAL ACTION CONTROLLER WILL LATER HANDLE:

     refresh-quizzes
       -> refreshTeacherQuizzesWorkspace()

     create-quiz
       -> quiz editor

     edit-quiz
       -> quiz editor for quizId

     quiz-results
       -> openTeacherQuizResults()

     close-quiz-results
       -> closeTeacherQuizResults()

     class-quizzes
       -> prepareTeacherQuizzesClass()
          + navigate to Quizzes

   QUESTION BANK
   ---------------------------------------------------------
   The separate current teacher.html Question Bank page is
   NOT merged into this workspace.

   Question Bank remains disabled from production boot until
   its unauthenticated backend route is hardened.
========================================================= */
/* =========================================================
   AIFT TEACHER STUDIO
   PRODUCTION REPLACEMENT
   PART 11B

   QUESTION BANK WORKSPACE
   ---------------------------------------------------------
   1. Workspace state
   2. Question normalization
   3. Ownership / management UX
   4. Search/category/difficulty/type filtering
   5. Existing filter controls
   6. Existing Question Bank list
   7. Existing Question Editor
   8. Question option editor
   9. Create / edit payload
   10. POST /api/question-bank
   11. PATCH /api/question-bank/:id
   12. DELETE /api/question-bank/:id
   13. State reconciliation
   14. Refresh lifecycle
   15. Workspace initialization

   SECURITY
   ---------------------------------------------------------
   Part 11A hardened the backend.

   The frontend does NOT send createdBy.

   Backend authentication and ownership remain authoritative.

   IMPORTANT MODEL CONTRACT
   ---------------------------------------------------------
   Current supplied Question Bank API does NOT establish:
     correctAnswer
     answer

   teacher.html currently contains #teacherQuestionAnswer.

   We DO NOT silently pretend that field persists.

   Until models/QuestionBank.js is verified/upgraded:
   - field remains visible
   - field is disabled
   - no answer field is sent to the backend

   This prevents silent data loss.
========================================================= */


/* =========================================================
   QUESTION BANK WORKSPACE STATE
========================================================= */

const teacherQuestionBankWorkspaceState = {

  search:
    "",

  category:
    "",

  difficulty:
    "",

  type:
    "",

  editingQuestionId:
    "",

  saving:
    false,

  refreshing:
    false,

  initialized:
    false

};


/* =========================================================
   QUESTION ID
========================================================= */

function getTeacherQuestionId(
  question
){

  return normalizeId(
    question?._id ||
    question?.id
  );

}


/* =========================================================
   QUESTION BY ID
========================================================= */

function getTeacherQuestionById(
  questionId
){

  const normalizedQuestionId =
    normalizeId(
      questionId
    );


  if (
    !normalizedQuestionId
  ){

    return null;

  }


  return (
    asArray(
      state.questionBank
    )
      .find(
        question =>
          sameId(
            getTeacherQuestionId(
              question
            ),
            normalizedQuestionId
          )
      ) ||
    null
  );

}


/* =========================================================
   QUESTION TITLE
========================================================= */

function getTeacherQuestionTitle(
  question
){

  return safeString(

    question?.title,

    safeString(
      question?.question,
      "Question"
    )

  );

}


/* =========================================================
   QUESTION TEXT
========================================================= */

function getTeacherQuestionText(
  question
){

  return safeString(
    question?.question
  );

}


/* =========================================================
   QUESTION TYPE
========================================================= */

function getTeacherQuestionType(
  question
){

  const type =
    safeString(
      question?.type,
      "multiple_choice"
    )
      .toLowerCase();


  if (
    [
      "multiple_choice",
      "true_false",
      "short_answer",
      "essay"
    ].includes(
      type
    )
  ){

    return type;

  }


  return "multiple_choice";

}


/* =========================================================
   QUESTION TYPE LABEL
========================================================= */

function getTeacherQuestionTypeLabel(
  value
){

  const type =
    typeof value ===
      "object"
      ? getTeacherQuestionType(
          value
        )
      : safeString(
          value
        );


  switch(
    type
  ){

    case "true_false":

      return "True / False";

    case "short_answer":

      return "Short answer";

    case "essay":

      return "Essay";

    default:

      return "Multiple choice";

  }

}


/* =========================================================
   QUESTION DIFFICULTY
========================================================= */

function getTeacherQuestionDifficulty(
  question
){

  const difficulty =
    safeString(
      question?.difficulty,
      "medium"
    )
      .toLowerCase();


  if (
    [
      "easy",
      "medium",
      "hard"
    ].includes(
      difficulty
    )
  ){

    return difficulty;

  }


  return "medium";

}


/* =========================================================
   QUESTION DIFFICULTY LABEL
========================================================= */

function getTeacherQuestionDifficultyLabel(
  question
){

  const difficulty =
    getTeacherQuestionDifficulty(
      question
    );


  return (
    difficulty
      .charAt(
        0
      )
      .toUpperCase() +
    difficulty
      .slice(
        1
      )
  );

}


/* =========================================================
   QUESTION CATEGORY
========================================================= */

function getTeacherQuestionCategory(
  question
){

  return safeString(
    question?.category,
    "General"
  );

}


/* =========================================================
   QUESTION POINTS
========================================================= */

function getTeacherQuestionPoints(
  question
){

  return Math.max(
    0,
    safeNumber(
      question?.points,
      1
    )
  );

}


/* =========================================================
   QUESTION OPTIONS
========================================================= */

function getTeacherQuestionOptions(
  question
){

  return asArray(
    question?.options
  )
    .map(
      option =>
        safeString(
          option
        )
    )
    .filter(
      Boolean
    );

}


/* =========================================================
   QUESTION TAGS
========================================================= */

function getTeacherQuestionTags(
  question
){

  return asArray(
    question?.tags
  )
    .map(
      tag =>
        safeString(
          tag
        )
    )
    .filter(
      Boolean
    );

}


/* =========================================================
   QUESTION CREATED BY
========================================================= */

function getTeacherQuestionCreatorId(
  question
){

  return normalizeId(
    question
      ?.createdBy
      ?._id ||
    question
      ?.createdBy
  );

}


/* =========================================================
   CAN CURRENT USER MANAGE QUESTION

   UX helper only.

   BACKEND remains authoritative.

   Part 11A rules:
   - admin: manage any
   - school: manage own school's questions
   - teacher: manage questions they created
========================================================= */

function canCurrentUserManageTeacherQuestion(
  question
){

  const role =
    getAuthenticatedRole();


  if (
    role ===
    "admin" ||
    role ===
    "school"
  ){

    return true;

  }


  if (
    role !==
    "teacher"
  ){

    return false;

  }


  return sameId(
    getTeacherQuestionCreatorId(
      question
    ),
    getAuthenticatedUserId()
  );

}


/* =========================================================
   QUESTION CATEGORY OPTIONS
========================================================= */

function getTeacherQuestionCategories(){

  const categories =
    new Map();


  asArray(
    state.questionBank
  )
    .forEach(
      question => {

        const category =
          getTeacherQuestionCategory(
            question
          );

        const key =
          category
            .toLowerCase();


        if (
          !categories.has(
            key
          )
        ){

          categories.set(
            key,
            category
          );

        }

      }
    );


  return Array.from(
    categories.values()
  )
    .sort(
      (
        first,
        second
      ) =>
        first.localeCompare(
          second
        )
    );

}


/* =========================================================
   FILTER QUESTION BANK
========================================================= */

function getFilteredTeacherQuestionBank(){

  const search =
    safeString(
      teacherQuestionBankWorkspaceState
        .search
    )
      .toLowerCase();

  const category =
    safeString(
      teacherQuestionBankWorkspaceState
        .category
    )
      .toLowerCase();

  const difficulty =
    safeString(
      teacherQuestionBankWorkspaceState
        .difficulty
    )
      .toLowerCase();

  const type =
    safeString(
      teacherQuestionBankWorkspaceState
        .type
    )
      .toLowerCase();


  let questions = [
    ...asArray(
      state.questionBank
    )
  ];


  /* -------------------------------------------------------
     ARCHIVED ITEMS

     Main Question Bank workspace only displays active items.
  ------------------------------------------------------- */

  questions =
    questions.filter(
      question =>
        question?.archived !==
        true
    );


  /* -------------------------------------------------------
     SEARCH
  ------------------------------------------------------- */

  if (
    search
  ){

    questions =
      questions.filter(
        question => {

          const haystack =
            [

              getTeacherQuestionTitle(
                question
              ),

              getTeacherQuestionText(
                question
              ),

              getTeacherQuestionCategory(
                question
              ),

              getTeacherQuestionTypeLabel(
                question
              ),

              ...getTeacherQuestionTags(
                question
              )

            ]
              .filter(
                Boolean
              )
              .join(
                " "
              )
              .toLowerCase();


          return haystack.includes(
            search
          );

        }
      );

  }


  /* -------------------------------------------------------
     CATEGORY
  ------------------------------------------------------- */

  if (
    category
  ){

    questions =
      questions.filter(
        question =>
          getTeacherQuestionCategory(
            question
          )
            .toLowerCase() ===
          category
      );

  }


  /* -------------------------------------------------------
     DIFFICULTY
  ------------------------------------------------------- */

  if (
    difficulty
  ){

    questions =
      questions.filter(
        question =>
          getTeacherQuestionDifficulty(
            question
          ) ===
          difficulty
      );

  }


  /* -------------------------------------------------------
     TYPE
  ------------------------------------------------------- */

  if (
    type
  ){

    questions =
      questions.filter(
        question =>
          getTeacherQuestionType(
            question
          ) ===
          type
      );

  }


  /* -------------------------------------------------------
     RECENTLY UPDATED FIRST
  ------------------------------------------------------- */

  questions.sort(
    (
      first,
      second
    ) =>
      (
        toValidDate(
          second?.updatedAt ||
          second?.createdAt
        )?.getTime() ||
        0
      ) -
      (
        toValidDate(
          first?.updatedAt ||
          first?.createdAt
        )?.getTime() ||
        0
      )
  );


  return questions;

}


/* =========================================================
   QUESTION BANK COUNT
========================================================= */

function renderTeacherQuestionBankCount(){

  const allQuestions =
    asArray(
      state.questionBank
    )
      .filter(
        question =>
          question?.archived !==
          true
      );

  const visibleQuestions =
    getFilteredTeacherQuestionBank();

  const hasFilters =
    Boolean(

      teacherQuestionBankWorkspaceState
        .search ||

      teacherQuestionBankWorkspaceState
        .category ||

      teacherQuestionBankWorkspaceState
        .difficulty ||

      teacherQuestionBankWorkspaceState
        .type

    );


  setText(

    "teacherQuestionBankCount",

    hasFilters
      ? `${visibleQuestions.length} of ${allQuestions.length} ${
          allQuestions.length ===
          1
            ? "question"
            : "questions"
        }`
      : `${allQuestions.length} ${
          allQuestions.length ===
          1
            ? "question"
            : "questions"
        }`

  );

}


/* =========================================================
   CATEGORY FILTER
========================================================= */

function renderTeacherQuestionCategoryFilter(){

  const select =
    $(
      "teacherQuestionCategoryFilter"
    );


  if (
    !select
  ){

    return;

  }


  const selectedValue =
    teacherQuestionBankWorkspaceState
      .category;

  const categories =
    getTeacherQuestionCategories();


  select.innerHTML = `
    <option value="">
      All categories
    </option>

    ${
      categories
        .map(
          category => `
            <option
              value="${escapeAttribute(category)}"
            >
              ${escapeHtml(category)}
            </option>
          `
        )
        .join(
          ""
        )
    }
  `;


  select.value =
    selectedValue;


  if (
    select.value !==
    selectedValue
  ){

    teacherQuestionBankWorkspaceState
      .category =
      "";

    select.value =
      "";

  }

}


/* =========================================================
   QUESTION FILTER STATE
========================================================= */

function renderTeacherQuestionBankFilters(){

  const search =
    $(
      "teacherQuestionSearch"
    );

  const difficulty =
    $(
      "teacherQuestionDifficultyFilter"
    );

  const type =
    $(
      "teacherQuestionTypeFilter"
    );


  if (
    search &&
    search.value !==
      teacherQuestionBankWorkspaceState
        .search
  ){

    search.value =
      teacherQuestionBankWorkspaceState
        .search;

  }


  renderTeacherQuestionCategoryFilter();


  if (
    difficulty
  ){

    difficulty.value =
      teacherQuestionBankWorkspaceState
        .difficulty;


    if (
      difficulty.value !==
      teacherQuestionBankWorkspaceState
        .difficulty
    ){

      teacherQuestionBankWorkspaceState
        .difficulty =
        "";

      difficulty.value =
        "";

    }

  }


  if (
    type
  ){

    type.value =
      teacherQuestionBankWorkspaceState
        .type;


    if (
      type.value !==
      teacherQuestionBankWorkspaceState
        .type
    ){

      teacherQuestionBankWorkspaceState
        .type =
        "";

      type.value =
        "";

    }

  }

}


/* =========================================================
   QUESTION META TAG
========================================================= */

function createTeacherQuestionMetaTag(
  icon,
  value
){

  return `
    <span>
      <i
        class="${escapeAttribute(icon)}"
        aria-hidden="true"
      ></i>

      ${escapeHtml(value)}
    </span>
  `;

}


/* =========================================================
   QUESTION BANK ITEM

   Uses the same Question Bank design family already present
   in teacher.html / existing CSS.
========================================================= */

function createTeacherQuestionBankItem(
  question
){

  const questionId =
    getTeacherQuestionId(
      question
    );

  const title =
    getTeacherQuestionTitle(
      question
    );

  const text =
    getTeacherQuestionText(
      question
    );

  const category =
    getTeacherQuestionCategory(
      question
    );

  const type =
    getTeacherQuestionType(
      question
    );

  const typeLabel =
    getTeacherQuestionTypeLabel(
      type
    );

  const difficulty =
    getTeacherQuestionDifficulty(
      question
    );

  const points =
    getTeacherQuestionPoints(
      question
    );

  const options =
    getTeacherQuestionOptions(
      question
    );

  const tags =
    getTeacherQuestionTags(
      question
    );

  const manageable =
    canCurrentUserManageTeacherQuestion(
      question
    );


  return `
    <article
      class="teacher-question-bank-item"
      data-question-id="${escapeAttribute(questionId)}"
    >

      <!-- ===============================================
           MAIN COPY
      ================================================ -->

      <div
        class="teacher-question-bank-copy"
      >

        <div
          class="teacher-question-bank-title-row"
        >

          <span
            class="teacher-question-bank-category"
          >
            ${escapeHtml(category)}
          </span>


          <span
            class="teacher-question-bank-difficulty is-${escapeAttribute(difficulty)}"
          >
            ${escapeHtml(
              getTeacherQuestionDifficultyLabel(
                question
              )
            )}
          </span>

        </div>


        <strong
          class="teacher-question-bank-title"
        >
          ${escapeHtml(title)}
        </strong>


        <p
          class="teacher-question-bank-question"
        >
          ${escapeHtml(text)}
        </p>


        ${
          options.length
            ? `
              <div
                class="teacher-question-bank-options-preview"
              >
                ${
                  options
                    .slice(
                      0,
                      4
                    )
                    .map(
                      (
                        option,
                        index
                      ) => `
                        <span>
                          ${index + 1}.
                          ${escapeHtml(option)}
                        </span>
                      `
                    )
                    .join(
                      ""
                    )
                }
              </div>
            `
            : ""
        }


        <div
          class="teacher-question-bank-meta"
        >

          ${createTeacherQuestionMetaTag(
            "fa-solid fa-list-check",
            typeLabel
          )}

          ${createTeacherQuestionMetaTag(
            "fa-solid fa-star",
            `${points} ${
              points === 1
                ? "point"
                : "points"
            }`
          )}

          ${
            tags.length
              ? createTeacherQuestionMetaTag(
                  "fa-solid fa-tags",
                  tags
                    .slice(
                      0,
                      3
                    )
                    .join(
                      ", "
                    )
                )
              : ""
          }

        </div>

      </div>


      <!-- ===============================================
           ACTIONS
      ================================================ -->

      <div
        class="teacher-question-bank-actions"
      >

        ${
          manageable
            ? `
              <button
                type="button"
                class="teacher-secondary-button"
                data-teacher-action="edit-question"
                data-question-id="${escapeAttribute(questionId)}"
              >
                <i
                  class="fa-regular fa-pen-to-square"
                  aria-hidden="true"
                ></i>

                Edit
              </button>


              <button
                type="button"
                class="teacher-icon-button teacher-danger-icon-button"
                data-teacher-action="delete-question"
                data-question-id="${escapeAttribute(questionId)}"
                aria-label="Delete ${escapeAttribute(title)}"
                title="Delete question"
              >
                <i
                  class="fa-solid fa-trash"
                  aria-hidden="true"
                ></i>
              </button>
            `
            : `
              <span
                class="teacher-question-shared-label"
                title="Shared by another teacher in your school"
              >
                <i
                  class="fa-solid fa-users"
                  aria-hidden="true"
                ></i>

                Shared
              </span>
            `
        }

      </div>

    </article>
  `;

}


/* =========================================================
   QUESTION BANK EMPTY STATE
========================================================= */

function renderTeacherQuestionBankEmptyState(
  questions
){

  const empty =
    $(
      "teacherQuestionBankEmpty"
    );


  if (
    !empty
  ){

    return;

  }


  const hasAnyQuestions =
    asArray(
      state.questionBank
    )
      .some(
        question =>
          question?.archived !==
          true
      );

  const hasResults =
    questions.length >
    0;

  const hasFilters =
    Boolean(

      teacherQuestionBankWorkspaceState
        .search ||

      teacherQuestionBankWorkspaceState
        .category ||

      teacherQuestionBankWorkspaceState
        .difficulty ||

      teacherQuestionBankWorkspaceState
        .type

    );


  empty.hidden =
    hasResults;


  if (
    hasResults
  ){

    return;

  }


  const heading =
    empty.querySelector(
      "h2"
    );

  const description =
    empty.querySelector(
      "p"
    );


  if (
    !hasAnyQuestions
  ){

    if (
      heading
    ){

      heading.textContent =
        "No questions yet";

    }


    if (
      description
    ){

      description.textContent =
        "Create reusable questions for quizzes, assignments and learning activities.";

    }


    return;

  }


  if (
    hasFilters
  ){

    if (
      heading
    ){

      heading.textContent =
        "No questions found";

    }


    if (
      description
    ){

      description.textContent =
        "No questions match the current search or filters.";

    }

  }

}


/* =========================================================
   QUESTION BANK LIST
========================================================= */

function renderTeacherQuestionBankList(){

  const container =
    $(
      "teacherQuestionBankList"
    );


  if (
    !container
  ){

    return;

  }


  const questions =
    getFilteredTeacherQuestionBank();


  renderTeacherQuestionBankCount();

  renderTeacherQuestionBankEmptyState(
    questions
  );


  if (
    !questions.length
  ){

    container.innerHTML =
      "";

    container.hidden =
      true;

    return;

  }


  container.hidden =
    false;


  container.innerHTML =
    questions
      .map(
        createTeacherQuestionBankItem
      )
      .join(
        ""
      );

}


/* =========================================================
   QUESTION TYPE USES OPTIONS
========================================================= */

function teacherQuestionTypeUsesOptions(
  type
){

  return [
    "multiple_choice",
    "true_false"
  ].includes(
    safeString(
      type
    )
  );

}


/* =========================================================
   CREATE OPTION ROW
========================================================= */

function createTeacherQuestionOptionRow(
  value = "",
  index = 0
){

  return `
    <div
      class="teacher-question-option-row"
    >

      <input
        type="text"
        class="teacher-question-option"
        placeholder="Option ${index + 1}"
        value="${escapeAttribute(value)}"
      />


      <button
        type="button"
        class="teacher-icon-button teacher-danger-icon-button"
        data-teacher-action="remove-question-option"
        aria-label="Remove option"
      >
        <i
          class="fa-solid fa-trash"
          aria-hidden="true"
        ></i>
      </button>

    </div>
  `;

}


/* =========================================================
   GET QUESTION EDITOR OPTIONS
========================================================= */

function getTeacherQuestionEditorOptions(){

  return $all(
    "#teacherQuestionOptions .teacher-question-option"
  )
    .map(
      input =>
        safeString(
          input.value
        )
    )
    .filter(
      Boolean
    );

}


/* =========================================================
   NORMALIZE OPTION PLACEHOLDERS
========================================================= */

function normalizeTeacherQuestionOptionRows(){

  const container =
    $(
      "teacherQuestionOptions"
    );


  if (
    !container
  ){

    return;

  }


  const rows =
    Array.from(
      container.querySelectorAll(
        ".teacher-question-option-row"
      )
    );


  rows.forEach(
    (
      row,
      index
    ) => {

      const input =
        row.querySelector(
          ".teacher-question-option"
        );


      if (
        input
      ){

        input.placeholder =
          `Option ${index + 1}`;

      }

    }
  );

}


/* =========================================================
   ADD OPTION
========================================================= */

function addTeacherQuestionOption(
  value = ""
){

  const container =
    $(
      "teacherQuestionOptions"
    );


  if (
    !container
  ){

    return false;

  }


  const index =
    container.querySelectorAll(
      ".teacher-question-option-row"
    ).length;


  container.insertAdjacentHTML(
    "beforeend",
    createTeacherQuestionOptionRow(
      value,
      index
    )
  );


  normalizeTeacherQuestionOptionRows();


  return true;

}


/* =========================================================
   REMOVE OPTION
========================================================= */

function removeTeacherQuestionOption(
  button
){

  const row =
    button?.closest(
      ".teacher-question-option-row"
    );


  if (
    !row
  ){

    return false;

  }


  const container =
    $(
      "teacherQuestionOptions"
    );


  const totalRows =
    container
      ?.querySelectorAll(
        ".teacher-question-option-row"
      )
      .length ||
    0;


  /*
    Multiple choice should not be left with fewer than two
    editable slots.
  */

  if (
    totalRows <=
      2 &&
    getTeacherQuestionType(
      {
        type:
          $("teacherQuestionType")
            ?.value
      }
    ) ===
      "multiple_choice"
  ){

    notifyAIFTInfo(
      "Multiple-choice questions need at least two option fields.",
      {
        title:
          "Options required"
      }
    );


    return false;

  }


  row.remove();

  normalizeTeacherQuestionOptionRows();


  return true;

}


/* =========================================================
   RENDER QUESTION EDITOR OPTIONS
========================================================= */

function renderTeacherQuestionEditorOptions(
  options = []
){

  const container =
    $(
      "teacherQuestionOptions"
    );


  if (
    !container
  ){

    return;

  }


  const values =
    asArray(
      options
    )
      .map(
        option =>
          safeString(
            option
          )
      )
      .filter(
        Boolean
      );


  const normalizedValues =
    values.length
      ? values
      : [
          "",
          ""
        ];


  container.innerHTML =
    normalizedValues
      .map(
        (
          value,
          index
        ) =>
          createTeacherQuestionOptionRow(
            value,
            index
          )
      )
      .join(
        ""
      );

}


/* =========================================================
   SYNC QUESTION TYPE UI

   Existing #teacherQuestionOptionsField stays in teacher.html.

   True/False has fixed options.

   Short answer/essay do not need option fields.

   Correct-answer persistence remains disabled until the
   QuestionBank model contract is established.
========================================================= */

function syncTeacherQuestionTypeFields(){

  const type =
    safeString(
      $(
        "teacherQuestionType"
      )?.value,
      "multiple_choice"
    );

  const optionsField =
    $(
      "teacherQuestionOptionsField"
    );

  const answerInput =
    $(
      "teacherQuestionAnswer"
    );


  if (
    optionsField
  ){

    optionsField.hidden =
      !teacherQuestionTypeUsesOptions(
        type
      );

  }


  if (
    type ===
    "true_false"
  ){

    renderTeacherQuestionEditorOptions([
      "True",
      "False"
    ]);


    $all(
      "#teacherQuestionOptions .teacher-question-option"
    )
      .forEach(
        input => {

          input.readOnly =
            true;

        }
      );

  }else if (
    type ===
    "multiple_choice"
  ){

    const options =
      getTeacherQuestionEditorOptions();


    if (
      options.length <
      2
    ){

      renderTeacherQuestionEditorOptions([
        ...options,
        ...Array(
          Math.max(
            0,
            2 -
            options.length
          )
        ).fill("")
      ]);

    }


    $all(
      "#teacherQuestionOptions .teacher-question-option"
    )
      .forEach(
        input => {

          input.readOnly =
            false;

        }
      );

  }


  /*
    Do not let a teacher enter information that appears to be
    saved when the currently established QuestionBank API does
    not persist it.
  */

  if (
    answerInput
  ){

    answerInput.value =
      "";

    answerInput.disabled =
      true;

    answerInput.placeholder =
      "Correct-answer storage will be enabled after the QuestionBank model is verified.";

    answerInput.title =
      "The current Question Bank backend contract does not yet establish a correctAnswer field.";

  }

}


/* =========================================================
   RESET QUESTION EDITOR
========================================================= */

function resetTeacherQuestionEditor(){

  teacherQuestionBankWorkspaceState
    .editingQuestionId =
    "";


  const fields = {

    teacherQuestionTitle:
      "",

    teacherQuestionText:
      "",

    teacherQuestionCategory:
      "General",

    teacherQuestionExplanation:
      "",

    teacherQuestionTags:
      ""

  };


  Object.entries(
    fields
  )
    .forEach(
      ([
        id,
        value
      ]) => {

        const element =
          $(
            id
          );


        if (
          element
        ){

          element.value =
            value;

        }

      }
    );


  const type =
    $(
      "teacherQuestionType"
    );

  const difficulty =
    $(
      "teacherQuestionDifficulty"
    );

  const points =
    $(
      "teacherQuestionPoints"
    );


  if (
    type
  ){

    type.value =
      "multiple_choice";

  }


  if (
    difficulty
  ){

    difficulty.value =
      "medium";

  }


  if (
    points
  ){

    points.value =
      "1";

  }


  renderTeacherQuestionEditorOptions([
    "",
    ""
  ]);


  syncTeacherQuestionTypeFields();


  setText(
    "teacherQuestionEditorTitle",
    "New Question"
  );

}


/* =========================================================
   POPULATE QUESTION EDITOR
========================================================= */

function populateTeacherQuestionEditor(
  question
){

  if (
    !question
  ){

    resetTeacherQuestionEditor();

    return;

  }


  teacherQuestionBankWorkspaceState
    .editingQuestionId =
    getTeacherQuestionId(
      question
    );


  const values = {

    teacherQuestionTitle:
      getTeacherQuestionTitle(
        question
      ),

    teacherQuestionText:
      getTeacherQuestionText(
        question
      ),

    teacherQuestionCategory:
      getTeacherQuestionCategory(
        question
      ),

    teacherQuestionExplanation:
      safeString(
        question?.explanation
      ),

    teacherQuestionTags:
      getTeacherQuestionTags(
        question
      ).join(
        ", "
      )

  };


  Object.entries(
    values
  )
    .forEach(
      ([
        id,
        value
      ]) => {

        const element =
          $(
            id
          );


        if (
          element
        ){

          element.value =
            value;

        }

      }
    );


  const type =
    $(
      "teacherQuestionType"
    );

  const difficulty =
    $(
      "teacherQuestionDifficulty"
    );

  const points =
    $(
      "teacherQuestionPoints"
    );


  if (
    type
  ){

    type.value =
      getTeacherQuestionType(
        question
      );

  }


  if (
    difficulty
  ){

    difficulty.value =
      getTeacherQuestionDifficulty(
        question
      );

  }


  if (
    points
  ){

    points.value =
      String(
        getTeacherQuestionPoints(
          question
        )
      );

  }


  renderTeacherQuestionEditorOptions(
    getTeacherQuestionOptions(
      question
    )
  );


  syncTeacherQuestionTypeFields();


  setText(
    "teacherQuestionEditorTitle",
    "Edit Question"
  );

}


/* =========================================================
   OPEN QUESTION EDITOR
========================================================= */

function openTeacherQuestionEditor(
  questionId = ""
){

  const editor =
    $(
      "teacherQuestionEditor"
    );


  if (
    !editor
  ){

    return false;

  }


  if (
    questionId
  ){

    const question =
      getTeacherQuestionById(
        questionId
      );


    if (
      !question
    ){

      notifyAIFTError(
        "The selected question is no longer available.",
        {
          title:
            "Question unavailable"
        }
      );


      return false;

    }


    if (
      !canCurrentUserManageTeacherQuestion(
        question
      )
    ){

      notifyAIFTError(
        "You cannot modify a question created by another teacher.",
        {
          title:
            "Question is read-only"
        }
      );


      return false;

    }


    populateTeacherQuestionEditor(
      question
    );

  }else{

    resetTeacherQuestionEditor();

  }


  editor.hidden =
    false;


  window.requestAnimationFrame(
    () => {

      $(
        "teacherQuestionTitle"
      )?.focus();

    }
  );


  return true;

}


/* =========================================================
   CLOSE QUESTION EDITOR
========================================================= */

function closeTeacherQuestionEditor(){

  const editor =
    $(
      "teacherQuestionEditor"
    );


  if (
    editor
  ){

    editor.hidden =
      true;

  }


  teacherQuestionBankWorkspaceState
    .editingQuestionId =
    "";


  return true;

}


/* =========================================================
   BUILD TAGS
========================================================= */

function getTeacherQuestionEditorTags(){

  return safeString(
    $(
      "teacherQuestionTags"
    )?.value
  )
    .split(
      ","
    )
    .map(
      tag =>
        tag.trim()
    )
    .filter(
      Boolean
    )
    .filter(
      (
        tag,
        index,
        array
      ) =>
        array
          .findIndex(
            existing =>
              existing.toLowerCase() ===
              tag.toLowerCase()
          ) ===
        index
    );

}


/* =========================================================
   QUESTION EDITOR PAYLOAD

   SECURITY:
   createdBy is intentionally NOT included.

   Part 11A sets:
     createdBy = req.user._id

   correctAnswer is intentionally NOT included because its
   persistence is not established in the current QuestionBank
   backend/model contract.
========================================================= */

function buildTeacherQuestionPayload(){

  const title =
    safeString(
      $(
        "teacherQuestionTitle"
      )?.value
    );

  const question =
    safeString(
      $(
        "teacherQuestionText"
      )?.value
    );

  const type =
    safeString(
      $(
        "teacherQuestionType"
      )?.value,
      "multiple_choice"
    );

  const difficulty =
    safeString(
      $(
        "teacherQuestionDifficulty"
      )?.value,
      "medium"
    );

  const category =
    safeString(
      $(
        "teacherQuestionCategory"
      )?.value,
      "General"
    );

  const points =
    Math.max(
      0,
      safeNumber(
        $(
          "teacherQuestionPoints"
        )?.value,
        1
      )
    );

  const explanation =
    safeString(
      $(
        "teacherQuestionExplanation"
      )?.value
    );

  let options =
    getTeacherQuestionEditorOptions();


  if (
    type ===
    "true_false"
  ){

    options = [
      "True",
      "False"
    ];

  }


  if (
    [
      "short_answer",
      "essay"
    ].includes(
      type
    )
  ){

    options =
      [];

  }


  if (
    !title
  ){

    throw new AIFTApiError(
      "Question title is required.",
      {
        code:
          "QUESTION_TITLE_REQUIRED"
      }
    );

  }


  if (
    !question
  ){

    throw new AIFTApiError(
      "Question text is required.",
      {
        code:
          "QUESTION_TEXT_REQUIRED"
      }
    );

  }


  if (
    type ===
      "multiple_choice" &&
    options.length <
      2
  ){

    throw new AIFTApiError(
      "Multiple-choice questions require at least two options.",
      {
        code:
          "QUESTION_OPTIONS_REQUIRED"
      }
    );

  }


  const schoolId =
    getSchoolId();


  if (
    !schoolId
  ){

    throw new AIFTApiError(
      "Your school could not be identified.",
      {
        code:
          "QUESTION_SCHOOL_REQUIRED"
      }
    );

  }


  return {

    schoolId,

    title,

    question,

    type,

    options,

    explanation,

    points,

    difficulty,

    bloom:
      "remember",

    category,

    tags:
      getTeacherQuestionEditorTags(),

    attachments:
      []

  };

}


/* =========================================================
   REPLACE QUESTION IN STATE
========================================================= */

function replaceTeacherQuestionInState(
  savedQuestion
){

  const questionId =
    getTeacherQuestionId(
      savedQuestion
    );


  if (
    !questionId
  ){

    return false;

  }


  const index =
    state.questionBank
      .findIndex(
        question =>
          sameId(
            getTeacherQuestionId(
              question
            ),
            questionId
          )
      );


  if (
    index >=
    0
  ){

    state.questionBank[
      index
    ] =
      savedQuestion;

  }else{

    state.questionBank.unshift(
      savedQuestion
    );

  }


  return true;

}


/* =========================================================
   REMOVE QUESTION FROM STATE
========================================================= */

function removeTeacherQuestionFromState(
  questionId
){

  const normalizedQuestionId =
    normalizeId(
      questionId
    );


  if (
    !normalizedQuestionId
  ){

    return false;

  }


  const before =
    state.questionBank.length;


  state.questionBank =
    state.questionBank
      .filter(
        question =>
          !sameId(
            getTeacherQuestionId(
              question
            ),
            normalizedQuestionId
          )
      );


  return (
    state.questionBank.length <
    before
  );

}


/* =========================================================
   SAVE QUESTION

   CREATE:
     POST /api/question-bank

   EDIT:
     PATCH /api/question-bank/:id
========================================================= */

async function saveTeacherQuestion(){

  if (
    teacherQuestionBankWorkspaceState
      .saving
  ){

    return false;

  }


  let payload;


  try{

    payload =
      buildTeacherQuestionPayload();

  }catch(
    error
  ){

    notifyAIFTError(
      getErrorMessage(
        error,
        "Please review the question fields."
      ),
      {
        title:
          "Question incomplete"
      }
    );


    return false;

  }


  const editingQuestionId =
    normalizeId(
      teacherQuestionBankWorkspaceState
        .editingQuestionId
    );


  if (
    editingQuestionId
  ){

    const currentQuestion =
      getTeacherQuestionById(
        editingQuestionId
      );


    if (
      !currentQuestion ||
      !canCurrentUserManageTeacherQuestion(
        currentQuestion
      )
    ){

      notifyAIFTError(
        "You are not allowed to update this question.",
        {
          title:
            "Question not saved"
        }
      );


      return false;

    }

  }


  teacherQuestionBankWorkspaceState
    .saving =
    true;


  const saveButton =
    $one(
      '#teacherQuestionEditor [data-teacher-action="save-question"]'
    );


  if (
    saveButton
  ){

    saveButton.disabled =
      true;

    saveButton.setAttribute(
      "aria-busy",
      "true"
    );


    saveButton.innerHTML = `
      <i
        class="fa-solid fa-spinner fa-spin"
        aria-hidden="true"
      ></i>

      Saving...
    `;

  }


  try{

    const response =
      editingQuestionId
        ? await apiPatch(
            `/api/question-bank/${encodeURIComponent(
              editingQuestionId
            )}`,
            payload
          )
        : await apiPost(
            "/api/question-bank",
            payload
          );


    const savedQuestion =
      response?.question ||
      response?.data ||
      response;


    if (
      savedQuestion &&
      getTeacherQuestionId(
        savedQuestion
      )
    ){

      replaceTeacherQuestionInState(
        savedQuestion
      );

    }else{

      await loadTeacherQuestionBank();

    }


    closeTeacherQuestionEditor();


    renderTeacherQuestionBankWorkspace();


    /*
      Quiz Question Bank integrations will read this same
      authoritative state.questionBank.
    */

    notifyAIFTSuccess(

      editingQuestionId
        ? "The question was updated."
        : "The question was added to the Question Bank.",

      {
        title:
          editingQuestionId
            ? "Question updated"
            : "Question created"
      }

    );


    return true;

  }catch(
    error
  ){

    notifyAIFTError(
      getErrorMessage(
        error,
        "AIFT could not save this question."
      ),
      {
        title:
          "Question not saved"
      }
    );


    return false;

  }finally{

    teacherQuestionBankWorkspaceState
      .saving =
      false;


    if (
      saveButton &&
      document.body.contains(
        saveButton
      )
    ){

      saveButton.disabled =
        false;

      saveButton.setAttribute(
        "aria-busy",
        "false"
      );


      saveButton.innerHTML = `
        <i
          class="fa-solid fa-floppy-disk"
          aria-hidden="true"
        ></i>

        Save Question
      `;

    }

  }

}


/* =========================================================
   DELETE QUESTION

   We require an explicit browser confirmation because this is
   destructive and the current backend performs real deletion.
========================================================= */

async function deleteTeacherQuestion(
  questionId
){

  const question =
    getTeacherQuestionById(
      questionId
    );


  if (
    !question
  ){

    notifyAIFTError(
      "The selected question is no longer available.",
      {
        title:
          "Question unavailable"
      }
    );


    return false;

  }


  if (
    !canCurrentUserManageTeacherQuestion(
      question
    )
  ){

    notifyAIFTError(
      "You are not allowed to delete this question.",
      {
        title:
          "Question protected"
      }
    );


    return false;

  }


  const confirmed =
    window.confirm(
      `Delete "${getTeacherQuestionTitle(
        question
      )}" from the Question Bank?\n\nThis action cannot be undone.`
    );


  if (
    !confirmed
  ){

    return false;

  }


  try{

    await apiDelete(
      `/api/question-bank/${encodeURIComponent(
        getTeacherQuestionId(
          question
        )
      )}`
    );


    removeTeacherQuestionFromState(
      getTeacherQuestionId(
        question
      )
    );


    renderTeacherQuestionBankWorkspace();


    notifyAIFTSuccess(
      "The question was deleted.",
      {
        title:
          "Question deleted"
      }
    );


    return true;

  }catch(
    error
  ){

    notifyAIFTError(
      getErrorMessage(
        error,
        "AIFT could not delete this question."
      ),
      {
        title:
          "Question not deleted"
      }
    );


    return false;

  }

}


/* =========================================================
   REFRESH QUESTION BANK
========================================================= */

async function refreshTeacherQuestionBankWorkspace(){

  if (
    teacherQuestionBankWorkspaceState
      .refreshing
  ){

    return false;

  }


  teacherQuestionBankWorkspaceState
    .refreshing =
    true;


  const buttons =
    $all(
      '[data-teacher-action="refresh-question-bank"]'
    );


  buttons.forEach(
    button => {

      button.disabled =
        true;

      button.setAttribute(
        "aria-busy",
        "true"
      );


      button
        .querySelector(
          "i"
        )
        ?.classList.add(
          "fa-spin"
        );

    }
  );


  try{

    const schoolId =
      getSchoolId();


    if (
      !schoolId
    ){

      throw new AIFTApiError(
        "Your school could not be identified.",
        {
          code:
            "QUESTION_BANK_SCHOOL_REQUIRED"
        }
      );

    }


    const response =
      await apiGet(
        "/api/question-bank",
        {
          query:{
            schoolId,
            archived:
              false
          }
        }
      );


    state.questionBank =
      uniqueById(
        asArray(
          response
        )
      );


    renderTeacherQuestionBankWorkspace();


    notifyAIFTSuccess(
      "The Question Bank is up to date.",
      {
        title:
          "Question Bank refreshed"
      }
    );


    return true;

  }catch(
    error
  ){

    notifyAIFTError(
      getErrorMessage(
        error,
        "The Question Bank could not be refreshed."
      ),
      {
        title:
          "Refresh failed"
      }
    );


    return false;

  }finally{

    teacherQuestionBankWorkspaceState
      .refreshing =
      false;


    buttons.forEach(
      button => {

        button.disabled =
          false;

        button.setAttribute(
          "aria-busy",
          "false"
        );


        button
          .querySelector(
            "i"
          )
          ?.classList.remove(
            "fa-spin"
          );

      }
    );

  }

}


