/* =========================================================
   RENDER COMPLETE QUESTION BANK
========================================================= */

function renderTeacherQuestionBankWorkspace(){

  renderTeacherQuestionBankFilters();

  renderTeacherQuestionBankList();


  /*
    Preserve editor state if the user is currently editing.
  */

  if (
    teacherQuestionBankWorkspaceState
      .editingQuestionId
  ){

    const question =
      getTeacherQuestionById(
        teacherQuestionBankWorkspaceState
          .editingQuestionId
      );


    if (
      !question
    ){

      closeTeacherQuestionEditor();

    }

  }

}


/* =========================================================
   INITIALIZE QUESTION BANK
========================================================= */

function initializeTeacherQuestionBankWorkspace(){

  if (
    teacherQuestionBankWorkspaceState
      .initialized
  ){

    renderTeacherQuestionBankWorkspace();

    return;

  }


  teacherQuestionBankWorkspaceState
    .initialized =
    true;


  bindTeacherQuestionBankStaticControls();

  syncTeacherQuestionTypeFields();

  renderTeacherQuestionBankWorkspace();

}


