/* =========================================================
   RESOURCE ID
========================================================= */

function getTeacherResourceId(
  resource
){

  /*
    New ClassLesson resources have a real MongoDB nested _id.

    Always prefer that ID because backend mutation endpoints use:

      /api/class-lessons/:lessonId/resources/:resourceId

    Legacy resources can still fall back to the older synthetic
    identity.
  */

  return safeString(

    resource?.resourceId ||
    resource?._id ||
    resource?.id,

    [
      normalizeId(
        resource?.lessonId
      ),

      safeString(
        resource?.url
      ),

      safeString(
        resource?.title
      )

    ]
      .filter(
        Boolean
      )
      .join(
        "::"
      )

  );

}


/* =========================================================
   RESOURCE URL
========================================================= */

function getTeacherResourceUrl(
  resource
){

  return safeString(
    resource?.url ||
    resource?.fileUrl ||
    resource?.href
  );

}


/* =========================================================
   RESOURCE TITLE
========================================================= */

function getTeacherResourceTitle(
  resource
){

  return safeString(

    resource?.title,

    safeString(
      resource?.name,
      "Learning resource"
    )

  );

}


/* =========================================================
   RESOURCE TYPE
========================================================= */

function normalizeTeacherResourceType(
  value,
  url = ""
){

  const raw =
    safeString(
      value
    )
      .toLowerCase()
      .replace(
        /[\s-]+/g,
        "_"
      );


  if (
    [
      "video",
      "image",
      "document",
      "pdf",
      "link",
      "audio",
      "file",
      "presentation",
      "spreadsheet"
    ].includes(
      raw
    )
  ){

    return raw;

  }


  const normalizedUrl =
    safeString(
      url
    )
      .toLowerCase();


  if (
    /\.pdf(?:$|\?)/i.test(
      normalizedUrl
    )
  ){

    return "pdf";

  }


  if (
    /\.(png|jpe?g|gif|webp|svg)(?:$|\?)/i.test(
      normalizedUrl
    )
  ){

    return "image";

  }


  if (
    /\.(mp4|webm|mov|m4v)(?:$|\?)/i.test(
      normalizedUrl
    )
  ){

    return "video";

  }


  if (
    /\.(mp3|wav|ogg|m4a)(?:$|\?)/i.test(
      normalizedUrl
    )
  ){

    return "audio";

  }


  if (
    /\.(ppt|pptx)(?:$|\?)/i.test(
      normalizedUrl
    )
  ){

    return "presentation";

  }


  if (
    /\.(xls|xlsx|csv)(?:$|\?)/i.test(
      normalizedUrl
    )
  ){

    return "spreadsheet";

  }


  if (
    /\.(doc|docx|txt|rtf)(?:$|\?)/i.test(
      normalizedUrl
    )
  ){

    return "document";

  }


  if (
    /^https?:\/\//i.test(
      normalizedUrl
    )
  ){

    return "link";

  }


  return "file";

}


/* =========================================================
   RESOURCE TYPE LABEL
========================================================= */

function getTeacherResourceTypeLabel(
  resource
){

  const type =
    normalizeTeacherResourceType(
      resource?.type,
      getTeacherResourceUrl(
        resource
      )
    );


  switch(
    type
  ){

    case "pdf":
      return "PDF";

    case "video":
      return "Video";

    case "image":
      return "Image";

    case "audio":
      return "Audio";

    case "presentation":
      return "Presentation";

    case "spreadsheet":
      return "Spreadsheet";

    case "document":
      return "Document";

    case "link":
      return "Link";

    default:
      return "File";

  }

}


/* =========================================================
   RESOURCE ICON
========================================================= */

function getTeacherResourceIcon(
  resource
){

  const type =
    normalizeTeacherResourceType(
      resource?.type,
      getTeacherResourceUrl(
        resource
      )
    );


  switch(
    type
  ){

    case "pdf":
      return "fa-solid fa-file-pdf";

    case "video":
      return "fa-solid fa-circle-play";

    case "image":
      return "fa-solid fa-image";

    case "audio":
      return "fa-solid fa-headphones";

    case "presentation":
      return "fa-solid fa-file-powerpoint";

    case "spreadsheet":
      return "fa-solid fa-file-excel";

    case "document":
      return "fa-solid fa-file-lines";

    case "link":
      return "fa-solid fa-link";

    default:
      return "fa-solid fa-paperclip";

  }

}

/* =========================================================
   LESSON RESOURCE NORMALIZER
   PRODUCTION UPLOAD-AWARE VERSION

   Supports:
     legacy URL-string resources
     old { title, url, type } resources
     new uploaded ClassLesson resources

   IMPORTANT
   ---------------------------------------------------------

   resourceId preserves the actual nested MongoDB _id.

   That ID is required for:
     DELETE /api/class-lessons/:lessonId/resources/:resourceId
========================================================= */

function normalizeTeacherLessonResource(
  resource,
  lesson,
  index
){

  if(
    !resource
  ){

    return null;

  }


  /* =====================================================
     LEGACY STRING RESOURCE
  ===================================================== */

  const source =
    typeof resource ===
      "string"
      ? {
          url:
            resource
        }
      : resource;


  /* =====================================================
     URL
  ===================================================== */

  const url =
    safeString(
      source?.secureUrl ||
      source?.url ||
      source?.fileUrl ||
      source?.href
    );


  if(
    !url
  ){

    return null;

  }


  /* =====================================================
     OWNERSHIP
  ===================================================== */

  const lessonId =
    normalizeId(
      lesson?._id ||
      lesson?.id
    );


  const classId =
    normalizeId(
      lesson?.classId?._id ||
      lesson?.classId
    );


  const moduleId =
    normalizeId(
      lesson?.moduleId?._id ||
      lesson?.moduleId
    );


  if(
    !lessonId ||
    !classId
  ){

    return null;

  }


  /* =====================================================
     REAL NESTED RESOURCE ID

     New resources stored in ClassLesson.resources[] receive
     their own Mongoose ObjectId automatically.
  ===================================================== */

  const resourceId =
    normalizeId(
      source?._id ||
      source?.resourceId
    );


  /* =====================================================
     TYPE
  ===================================================== */

  const type =
    normalizeTeacherResourceType(
      source?.type,
      url
    );


  /* =====================================================
     RETURN NORMALIZED RESOURCE
  ===================================================== */

  return {

    /*
      UI identity.

      Prefer the real nested MongoDB resource ID.

      Legacy resources retain a deterministic synthetic ID.
    */

    id:
      resourceId ||
      [
        lessonId,
        index,
        url
      ]
        .join(
          "::"
        ),


    resourceId:
      resourceId ||
      "",


    lessonId,


    classId,


    moduleId,


    title:
      safeString(
        source?.title ||
        source?.name ||
        source?.originalName,
        `Resource ${index + 1}`
      ),


    description:
      safeString(
        source?.description
      ),


    url,


    secureUrl:
      safeString(
        source?.secureUrl,
        url
      ),


    type,


    source:
      safeString(
        source?.source,
        resourceId
          ? "upload"
          : "link"
      )
        .toLowerCase(),


    lessonTitle:
      safeString(
        lesson?.title,
        "Lesson"
      ),


    /* ===================================================
       FILE METADATA
    =================================================== */

    originalName:
      safeString(
        source?.originalName
      ),


    mimeType:
      safeString(
        source?.mimeType
      ),


    size:
      Math.max(
        0,
        Number(
          source?.size ||
          0
        ) ||
        0
      ),


    format:
      safeString(
        source?.format
      ),


    publicId:
      safeString(
        source?.publicId
      ),


    resourceType:
      safeString(
        source?.resourceType
      ),


    width:
      Number.isFinite(
        Number(
          source?.width
        )
      )
        ? Number(
            source.width
          )
        : null,


    height:
      Number.isFinite(
        Number(
          source?.height
        )
      )
        ? Number(
            source.height
          )
        : null,


    duration:
      Number.isFinite(
        Number(
          source?.duration
        )
      )
        ? Number(
            source.duration
          )
        : null,


    uploadedBy:
      normalizeId(
        source?.uploadedBy?._id ||
        source?.uploadedBy
      ),


    uploadedAt:
      source?.uploadedAt ||
      null,


    createdAt:
      source?.createdAt ||
      source?.uploadedAt ||
      lesson?.createdAt ||
      null,


    updatedAt:
      source?.updatedAt ||
      source?.uploadedAt ||
      lesson?.updatedAt ||
      null

  };

}


/* =========================================================
   LESSON VIDEO AS RESOURCE
========================================================= */

function createTeacherLessonVideoResource(
  lesson
){

  const videoUrl =
    safeString(
      lesson?.videoUrl
    );


  if (
    !videoUrl
  ){

    return null;

  }


  const lessonId =
    normalizeId(
      lesson?._id ||
      lesson?.id
    );


  return {

    id:
      `${lessonId}::lesson-video`,

    title:
      `${safeString(
        lesson?.title,
        "Lesson"
      )} video`,

    description:
      safeString(
        lesson?.summary
      ),

    url:
      videoUrl,

    type:
      "video",

    lessonId,

    lessonTitle:
      safeString(
        lesson?.title,
        "Lesson"
      ),

    classId:
      normalizeId(
        lesson?.classId?._id ||
        lesson?.classId
      ),

    moduleId:
      normalizeId(
        lesson?.moduleId?._id ||
        lesson?.moduleId
      ),

    createdAt:
      lesson?.createdAt ||
      null,

    updatedAt:
      lesson?.updatedAt ||
      null

  };

}

/* =========================================================
   BUILD TEACHER RESOURCE COLLECTION
   PRODUCTION PERMISSION-AWARE VERSION

   SECURITY / OWNERSHIP MODEL
   ---------------------------------------------------------

   Teacher Studio may only build Resources from Classes that
   belong to the currently selected/authenticated Teacher.

   The browser filtering below is UX/data isolation only.
   Backend authorization must remain authoritative.

   School/Admin management pages may have broader visibility,
   but this Teacher Studio workspace remains scoped to the
   Teacher represented by getTeacherId().
========================================================= */

function buildTeacherResourcesFromLessons(){

  const resources =
    [];


  /* =====================================================
     AUTHORITATIVE TEACHER CLASS SCOPE
  ===================================================== */

  const allowedClassIds =
    new Set(
      getTeacherClassIds()
        .map(
          normalizeId
        )
        .filter(
          Boolean
        )
    );


  if(
    !allowedClassIds.size
  ){

    return [];

  }


  /* =====================================================
     ONLY LESSONS FROM ASSIGNED CLASSES
  ===================================================== */

  const teacherLessons =
    asArray(
      state.classLessons
    )
      .filter(
        lesson => {

          const classId =
            normalizeId(
              lesson?.classId?._id ||
              lesson?.classId
            );


          return Boolean(
            classId &&
            allowedClassIds.has(
              classId
            )
          );

        }
      );


  /* =====================================================
     BUILD RESOURCE RECORDS
  ===================================================== */

  teacherLessons.forEach(
    lesson => {

      const lessonClassId =
        normalizeId(
          lesson?.classId?._id ||
          lesson?.classId
        );


      /*
        Defensive second check.

        A malformed lesson record must never be allowed to
        create an unscoped Resource.
      */

      if(
        !lessonClassId ||
        !allowedClassIds.has(
          lessonClassId
        )
      ){

        return;

      }


      /* ===================================================
         NORMAL LESSON RESOURCES
      =================================================== */

      asArray(
        lesson?.resources
      )
        .forEach(
          (
            resource,
            index
          ) => {

            const normalized =
              normalizeTeacherLessonResource(
                resource,
                lesson,
                index
              );


            if(
              !normalized
            ){

              return;

            }


            const resourceClassId =
              normalizeId(
                normalized.classId
              );


            /*
              Never trust the child Resource class reference
              over the owning Lesson.

              Both must resolve to the Teacher's authorized
              class scope.
            */

            if(
              !resourceClassId ||
              !allowedClassIds.has(
                resourceClassId
              )
            ){

              return;

            }


            resources.push(
              normalized
            );

          }
        );


      /* ===================================================
         LESSON VIDEO

         videoUrl is also a reusable Resource.
      =================================================== */

      const lessonVideo =
        createTeacherLessonVideoResource(
          lesson
        );


      if(
        lessonVideo
      ){

        const videoClassId =
          normalizeId(
            lessonVideo.classId
          );


        if(
          videoClassId &&
          allowedClassIds.has(
            videoClassId
          )
        ){

          resources.push(
            lessonVideo
          );

        }

      }

    }
  );


  /* =====================================================
     DEDUPLICATE

     Identity:
       lessonId + resource URL
  ===================================================== */

  const seen =
    new Set();


  return resources.filter(
    resource => {

      const resourceClassId =
        normalizeId(
          resource?.classId
        );


      /*
        Final authorization gate before anything enters the
        Teacher Resources workspace.
      */

      if(
        !resourceClassId ||
        !allowedClassIds.has(
          resourceClassId
        )
      ){

        return false;

      }


      const key =
        [
          normalizeId(
            resource.lessonId
          ),

          getTeacherResourceUrl(
            resource
          )
        ]
          .join(
            "::"
          )
          .toLowerCase();


      if(
        !key ||
        seen.has(
          key
        )
      ){

        return false;

      }


      seen.add(
        key
      );


      return true;

    }
  );

}


/* =========================================================
   RESOURCE CLASS
========================================================= */

function getTeacherResourceClass(
  resource
){

  return getTeacherClassById(
    resource?.classId
  );

}


/* =========================================================
   RESOURCE CLASS NAME
========================================================= */

function getTeacherResourceClassName(
  resource
){

  const classItem =
    getTeacherResourceClass(
      resource
    );


  return safeString(

    classItem?.title ||
    classItem?.name,

    "Class"

  );

}



/* =========================================================
   FILTERED TEACHER RESOURCES
   PRODUCTION PERMISSION + FILTER ENGINE

   IMPORTANT
   ---------------------------------------------------------

   Even though Resources are already scoped while loading and
   building, this function applies one final class-ownership
   gate before anything reaches the UI.

   This protects against:
     stale frontend state
     malformed cached records
     accidental state contamination
     future loader changes
========================================================= */

function getFilteredTeacherResources(){

  const search =
    safeString(
      teacherResourcesWorkspaceState
        .search
    )
      .trim()
      .toLowerCase();


  const selectedClassId =
    normalizeId(
      teacherResourcesWorkspaceState
        .classId
    );


  const selectedType =
    safeString(
      teacherResourcesWorkspaceState
        .type,
      "all"
    )
      .trim()
      .toLowerCase();


  const sort =
    safeString(
      teacherResourcesWorkspaceState
        .sort,
      "recent"
    )
      .trim()
      .toLowerCase();


  /* =====================================================
     AUTHORITATIVE FRONTEND CLASS SCOPE
  ===================================================== */

  const allowedClassIds =
    new Set(
      getTeacherClassIds()
        .map(
          normalizeId
        )
        .filter(
          Boolean
        )
    );


  if(
    !allowedClassIds.size
  ){

    return [];

  }


  let resources =
    asArray(
      teacherResourcesWorkspaceState
        .resources
    )
      .filter(
        resource => {

          const classId =
            normalizeId(
              resource?.classId
            );


          return Boolean(
            classId &&
            allowedClassIds.has(
              classId
            )
          );

        }
      );


  /* =====================================================
     CLASS FILTER
  ===================================================== */

  if(
    selectedClassId &&
    selectedClassId !==
      "all"
  ){

    resources =
      resources.filter(
        resource =>
          sameId(
            resource?.classId,
            selectedClassId
          )
      );

  }


  /* =====================================================
     TYPE FILTER
  ===================================================== */

  if(
    selectedType !==
      "all"
  ){

    resources =
      resources.filter(
        resource =>
          normalizeTeacherResourceType(
            resource?.type,
            getTeacherResourceUrl(
              resource
            )
          ) ===
          selectedType
      );

  }


  /* =====================================================
     SEARCH
  ===================================================== */

  if(
    search
  ){

    resources =
      resources.filter(
        resource => {

          const searchableText =
            [
              getTeacherResourceTitle(
                resource
              ),

              safeString(
                resource?.description
              ),

              safeString(
                resource?.lessonTitle
              ),

              getTeacherResourceClassName(
                resource
              ),

              getTeacherResourceTypeLabel(
                resource
              ),

              safeString(
                resource?.url
              )
            ]
              .filter(
                Boolean
              )
              .join(
                " "
              )
              .toLowerCase();


          return searchableText.includes(
            search
          );

        }
      );

  }


  /* =====================================================
     SORT
  ===================================================== */

  resources.sort(
    (
      first,
      second
    ) => {

      if(
        sort ===
        "title"
      ){

        return getTeacherResourceTitle(
          first
        )
          .localeCompare(
            getTeacherResourceTitle(
              second
            ),
            undefined,
            {
              sensitivity:
                "base"
            }
          );

      }


      if(
        sort ===
        "class"
      ){

        const classComparison =
          getTeacherResourceClassName(
            first
          )
            .localeCompare(
              getTeacherResourceClassName(
                second
              ),
              undefined,
              {
                sensitivity:
                  "base"
              }
            );


        if(
          classComparison !==
          0
        ){

          return classComparison;

        }


        return getTeacherResourceTitle(
          first
        )
          .localeCompare(
            getTeacherResourceTitle(
              second
            ),
            undefined,
            {
              sensitivity:
                "base"
            }
          );

      }


      /* ===================================================
         RECENT

         updatedAt wins over createdAt.

         Stable title fallback prevents Resource cards from
         randomly jumping when timestamps are equal.
      =================================================== */

      const firstTimestamp =
        toValidDate(
          first?.updatedAt ||
          first?.createdAt
        )?.getTime() ||
        0;


      const secondTimestamp =
        toValidDate(
          second?.updatedAt ||
          second?.createdAt
        )?.getTime() ||
        0;


      if(
        secondTimestamp !==
        firstTimestamp
      ){

        return (
          secondTimestamp -
          firstTimestamp
        );

      }


      return getTeacherResourceTitle(
        first
      )
        .localeCompare(
          getTeacherResourceTitle(
            second
          ),
          undefined,
          {
            sensitivity:
              "base"
          }
        );

    }
  );


  return resources;

}

/* =========================================================
   RESOURCE SUMMARY
========================================================= */

function getTeacherResourceSummary(){

  const resources =
    asArray(
      teacherResourcesWorkspaceState
        .resources
    );


  const classIds =
    new Set(

      resources
        .map(
          resource =>
            normalizeId(
              resource?.classId
            )
        )
        .filter(
          Boolean
        )

    );


  const lessonIds =
    new Set(

      resources
        .map(
          resource =>
            normalizeId(
              resource?.lessonId
            )
        )
        .filter(
          Boolean
        )

    );


  return {

    total:
      resources.length,

    classes:
      classIds.size,

    lessons:
      lessonIds.size,

    documents:
      resources.filter(
        resource =>
          [
            "document",
            "pdf",
            "presentation",
            "spreadsheet"
          ].includes(
            normalizeTeacherResourceType(
              resource?.type,
              getTeacherResourceUrl(
                resource
              )
            )
          )
      ).length,

    media:
      resources.filter(
        resource =>
          [
            "video",
            "image",
            "audio"
          ].includes(
            normalizeTeacherResourceType(
              resource?.type,
              getTeacherResourceUrl(
                resource
              )
            )
          )
      ).length

  };

}


