/* =========================================================
   OPEN RESOURCE EDITOR FOR EXISTING RESOURCE

   Uses the same editor UI.

   No new backend endpoint is required.

   The owning lesson remains the source of truth.
========================================================= */

async function openTeacherResourceEditorForEdit(
  resource
){

  if(
    !resource
  ){

    notifyAIFTError(
      "The selected resource could not be found.",
      {
        title:
          "Resource unavailable"
      }
    );


    return false;

  }


  const lessonId =
    normalizeId(
      resource?.lessonId
    );


  const resourceId =
    normalizeId(
      resource?.resourceId ||
      resource?._id
    );


  if(
    !lessonId ||
    !resourceId
  ){

    notifyAIFTWarning(
      "This resource does not have a complete lesson identity and cannot be edited here.",
      {
        title:
          "Resource cannot be edited"
      }
    );


    return false;

  }


  /* =====================================================
     ENSURE AUTHORITATIVE LESSON DATA EXISTS
  ===================================================== */

  if(
    !asArray(
      state.classLessons
    ).length
  ){

    teacherResourcesWorkspaceState
      .loaded =
      false;


    await loadTeacherLearningResources();

  }


  const lesson =
    getTeacherResourceLessonById(
      lessonId
    );


  if(
    !lesson ||
    !canTeacherUseResourceLesson(
      lesson
    )
  ){

    notifyAIFTError(
      "The lesson containing this resource is not available in one of your assigned classes.",
      {
        title:
          "Lesson unavailable"
      }
    );


    return false;

  }


  const classId =
    getTeacherResourceLessonClassId(
      lesson
    );


  /* =====================================================
     FIND REAL NESTED RESOURCE
  ===================================================== */

  const lessonResources =
    asArray(
      lesson?.resources
    );


  const originalResource =
    lessonResources.find(
      item =>
        sameId(
          item?._id ||
          item?.id,
          resourceId
        )
    );


  if(
    !originalResource
  ){

    notifyAIFTError(
      "The original resource could not be found inside this lesson.",
      {
        title:
          "Resource unavailable"
      }
    );


    return false;

  }


  /* =====================================================
     SET EDITOR STATE
  ===================================================== */

  teacherResourceEditorState
    .open =
    true;


  teacherResourceEditorState
    .classId =
    classId;


  teacherResourceEditorState
    .lessonId =
    lessonId;


  teacherResourceEditorState
    .editing =
    true;


  teacherResourceEditorState
    .editingResourceId =
    resourceId;


  teacherResourceEditorState
    .originalResource =
    {
      ...originalResource
    };


  teacherResourceEditorState
    .file =
    null;


  teacherResourceEditorState
    .saving =
    false;


  /*
    Uploaded resources remain upload mode.

    External links remain link mode.
  */

  teacherResourceEditorState
    .mode =
    safeString(
      originalResource?.source
    ).toLowerCase() ===
    "link"
      ? "link"
      : "upload";


  renderTeacherResourceEditor();


  /* =====================================================
     PREFILL FORM AFTER RENDER
  ===================================================== */

  const titleInput =
    $(
      "teacherResourceEditorTitleInput"
    );


  if(
    titleInput
  ){

    titleInput.value =
      safeString(
        originalResource?.title
      );

  }


  const descriptionInput =
    $(
      "teacherResourceEditorDescription"
    );


  if(
    descriptionInput
  ){

    descriptionInput.value =
      safeString(
        originalResource?.description
      );

  }


  const urlInput =
    $(
      "teacherResourceEditorUrl"
    );


  if(
    urlInput &&
    teacherResourceEditorState
      .mode ===
      "link"
  ){

    urlInput.value =
      safeString(
        originalResource?.url ||
        originalResource?.secureUrl
      );

  }


  return true;

}


/* =========================================================
   OPEN RESOURCE EDITOR
========================================================= */

async function openTeacherResourceEditor(
  {
    classId =
      "",
    lessonId =
      ""
  } = {}
){

  /*
    Resources require lesson data.

    If the workspace was entered before Lessons finished
    loading, refresh the authoritative Resource/Lesson cache.
  */

  if(
    !asArray(
      state.classLessons
    ).length
  ){

    teacherResourcesWorkspaceState
      .loaded =
      false;


    await loadTeacherLearningResources();

  }


  const requestedClassId =
    normalizeId(
      classId
    );


  const requestedLessonId =
    normalizeId(
      lessonId
    );


  let finalClassId =
    requestedClassId;


  let finalLessonId =
    requestedLessonId;


  /* =====================================================
     LESSON PROVIDED
  ===================================================== */

  if(
    finalLessonId
  ){

    const lesson =
      getTeacherResourceLessonById(
        finalLessonId
      );


    if(
      !lesson ||
      !canTeacherUseResourceLesson(
        lesson
      )
    ){

      notifyAIFTError(
        "The selected lesson is not available in one of your assigned classes.",
        {
          title:
            "Lesson unavailable"
        }
      );


      return false;

    }


    finalClassId =
      getTeacherResourceLessonClassId(
        lesson
      );

  }


  /* =====================================================
     CLASS FALLBACK

     Prefer the current Resource class filter when it points
     to one real class.
  ===================================================== */

  if(
    !finalClassId &&
    teacherResourcesWorkspaceState
      .classId !==
      "all"
  ){

    finalClassId =
      normalizeId(
        teacherResourcesWorkspaceState
          .classId
      );

  }


  /* =====================================================
     VERIFY CLASS
  ===================================================== */

  if(
    finalClassId &&
    !getTeacherClassById(
      finalClassId
    )
  ){

    finalClassId =
      "";

  }


  teacherResourceEditorState
    .open =
    true;


  teacherResourceEditorState
    .classId =
    finalClassId;


  teacherResourceEditorState
    .lessonId =
    finalLessonId;


  teacherResourceEditorState
    .mode =
    "upload";


  teacherResourceEditorState
    .file =
    null;


  teacherResourceEditorState
    .saving =
    false;


  renderTeacherResourceEditor();


  return true;

}


/* =========================================================
   CLOSE RESOURCE EDITOR
========================================================= */

function closeTeacherResourceEditor(){

  resetTeacherResourceEditorState();


  const container =
    $(
      "teacherResourceEditor"
    );


  if(
    container
  ){

    container.hidden =
      true;


    container.innerHTML =
      "";

  }


  return true;

}


/* =========================================================
   RESOURCE EDITOR LESSON OPTIONS
========================================================= */

function getTeacherResourceEditorLessonOptions(){

  const classId =
    normalizeId(
      teacherResourceEditorState
        .classId
    );


  if(
    !classId
  ){

    return `
      <option value="">
        Select a class first
      </option>
    `;

  }


  const lessons =
    getTeacherResourceLessonsForClass(
      classId
    );


  if(
    !lessons.length
  ){

    return `
      <option value="">
        No lessons available in this class
      </option>
    `;

  }


  return `
    <option value="">
      Select lesson
    </option>

    ${
      lessons
        .map(
          lesson => {

            const lessonId =
              normalizeId(
                lesson?._id ||
                lesson?.id
              );


            return `
              <option
                value="${escapeAttribute(
                  lessonId
                )}"
                ${
                  sameId(
                    teacherResourceEditorState
                      .lessonId,
                    lessonId
                  )
                    ? "selected"
                    : ""
                }
              >
                ${escapeHtml(
                  safeString(
                    lesson?.title,
                    "Lesson"
                  )
                )}
              </option>
            `;

          }
        )
        .join(
          ""
        )
    }
  `;

}


