/* =========================================================
   SET RESOURCE EDITOR MODE
========================================================= */

function setTeacherResourceEditorMode(
  mode
){

  const normalizedMode =
    mode ===
    "link"
      ? "link"
      : "upload";


  teacherResourceEditorState
    .mode =
    normalizedMode;


  if(
    normalizedMode ===
    "link"
  ){

    teacherResourceEditorState
      .file =
      null;

  }


  renderTeacherResourceEditor();


  return true;

}


