/* =========================================================
   RENDER SELECTED STUDENT

   Current teacher.html does not yet contain this host.

   Final HTML cleanup will add:
     <div id="teacherSelectedStudent" hidden></div>

   directly underneath the existing Students area.
========================================================= */

function renderTeacherSelectedStudent(
  studentId =
    teacherStudentWorkspaceState
      .selectedStudentId
){

  const container =
    $(
      "teacherSelectedStudent"
    );


  if (
    !container
  ){

    /*
      Missing host is a known teacher.html compatibility issue.

      Do not throw.
      Do not redirect.
      Do not silently show Overview.
    */

    return false;

  }


  const record =
    getTeacherStudentById(
      studentId
    );


  if (
    !record
  ){

    teacherStudentWorkspaceState
      .selectedStudentId =
      "";

    container.hidden =
      true;

    container.innerHTML =
      "";


    return false;

  }


  const student =
    record.student ||
    {};

  const normalizedStudentId =
    record.id;

  const name =
    getTeacherStudentDisplayName(
      record
    );

  const email =
    getTeacherStudentEmail(
      record
    );

  const course =
    getTeacherSelectedStudentCourse(
      student
    );

  const phone =
    getTeacherSelectedStudentPhone(
      student
    );

  const avatar =
    getTeacherStudentAvatar(
      record
    );

  const classes =
    getTeacherSelectedStudentClasses(
      normalizedStudentId
    );

  const assignments =
    getTeacherSelectedStudentAssignmentTotal(
      normalizedStudentId
    );

  const submissions =
    getTeacherStudentSubmissions(
      normalizedStudentId
    ).length;

  const missing =
    getTeacherStudentMissingAssignments(
      normalizedStudentId
    ).length;

  const pending =
    getTeacherStudentPendingSubmissions(
      normalizedStudentId
    ).length;

  const submissionRate =
    getTeacherSelectedStudentSubmissionRate(
      normalizedStudentId
    );

  const attendance =
    getTeacherSelectedStudentAttendanceSummary(
      normalizedStudentId
    );

  const gradeAverage =
    getTeacherSelectedStudentAverageGrade(
      normalizedStudentId
    );

  const quizAverage =
    getTeacherSelectedStudentQuizAverage(
      normalizedStudentId
    );

  const progress =
    getTeacherSelectedStudentProgressContext(
      normalizedStudentId
    );

  const recentSubmissions =
    getTeacherSelectedStudentRecentSubmissions(
      normalizedStudentId
    );


  teacherStudentWorkspaceState
    .selectedStudentId =
    normalizedStudentId;


  container.hidden =
    false;


  container.innerHTML = `
    <section
      class="teacher-student-detail-panel"
      data-student-id="${escapeAttribute(normalizedStudentId)}"
    >

      <!-- ===============================================
           HEADER
      ================================================ -->

      <header
        class="teacher-student-detail-header"
      >

        <button
          type="button"
          class="teacher-icon-button"
          data-teacher-action="close-student-detail"
          aria-label="Close student details"
        >
          <i
            class="fa-solid fa-xmark"
            aria-hidden="true"
          ></i>
        </button>


        <img
          class="teacher-student-detail-avatar"
          src="${escapeAttribute(avatar)}"
          alt=""
          loading="lazy"
          referrerpolicy="no-referrer"
        />


        <div
          class="teacher-student-detail-identity"
        >

          <span
            class="teacher-page-eyebrow"
          >
            STUDENT
          </span>

          <h2>
            ${escapeHtml(name)}
          </h2>

          <p>
            ${escapeHtml(
              email ||
              "No email available"
            )}
          </p>


          <div
            class="teacher-student-detail-profile-meta"
          >

            ${
              course
                ? `
                  <span>
                    <i
                      class="fa-solid fa-graduation-cap"
                      aria-hidden="true"
                    ></i>

                    ${escapeHtml(course)}
                  </span>
                `
                : ""
            }


            ${
              phone
                ? `
                  <span>
                    <i
                      class="fa-solid fa-phone"
                      aria-hidden="true"
                    ></i>

                    ${escapeHtml(phone)}
                  </span>
                `
                : ""
            }

          </div>

        </div>


        <span
          class="teacher-student-status ${
            progress.category ===
            "needs-attention"
              ? "inactive"
              : "active"
          }"
        >
          ${escapeHtml(progress.label)}
        </span>

      </header>


      <!-- ===============================================
           CLASSES
      ================================================ -->

      <div
        class="teacher-student-detail-classes"
      >

        <span>
          Assigned classes
        </span>

        <div>
          ${
            classes.length
              ? classes
                  .map(
                    createTeacherSelectedStudentClassChip
                  )
                  .join(
                    ""
                  )
              : `
                  <small>
                    No assigned class.
                  </small>
                `
          }
        </div>

      </div>


      <!-- ===============================================
           METRICS
      ================================================ -->

      <div
        class="teacher-student-detail-metrics"
      >

        ${createTeacherStudentDetailMetric({
          icon:
            "fa-solid fa-chart-line",

          label:
            "Learning progress",

          value:
            progress.score ===
            null
              ? "—"
              : `${progress.score}%`,

          description:
            progress.description
        })}


        ${createTeacherStudentDetailMetric({
          icon:
            "fa-solid fa-file-circle-check",

          label:
            "Work completion",

          value:
            assignments
              ? `${submissionRate}%`
              : "—",

          description:
            assignments
              ? `${submissions} submissions across ${assignments} assigned tasks`
              : "No assignments available"
        })}


        ${createTeacherStudentDetailMetric({
          icon:
            "fa-solid fa-calendar-check",

          label:
            "Attendance",

          value:
            attendance.total
              ? `${attendance.rate}%`
              : "—",

          description:
            attendance.total
              ? `${attendance.present} present · ${attendance.late} late · ${attendance.absent} absent`
              : "No attendance records yet"
        })}


        ${createTeacherStudentDetailMetric({
          icon:
            "fa-solid fa-graduation-cap",

          label:
            "Average grade",

          value:
            gradeAverage ===
            null
              ? "—"
              : `${gradeAverage}%`,

          description:
            gradeAverage ===
            null
              ? "No reviewed numeric grades yet"
              : "Based on reviewed submissions"
        })}


        ${createTeacherStudentDetailMetric({
          icon:
            "fa-solid fa-list-check",

          label:
            "Quiz average",

          value:
            quizAverage ===
            null
              ? "—"
              : `${quizAverage}%`,

          description:
            quizAverage ===
            null
              ? "No quiz results available yet"
              : "Based on available quiz attempts"
        })}


        ${createTeacherStudentDetailMetric({
          icon:
            "fa-solid fa-triangle-exclamation",

          label:
            "Overdue work",

          value:
            String(
              missing
            ),

          description:
            missing
              ? `${missing} overdue ${
                  missing ===
                  1
                    ? "assignment"
                    : "assignments"
                }`
              : "No overdue assignments detected"
        })}

      </div>


      <!-- ===============================================
           TEACHER ACTIONS
      ================================================ -->

      <div
        class="teacher-student-detail-actions"
      >

        <button
          type="button"
          class="teacher-primary-button"
          data-teacher-action="student-work"
          data-student-id="${escapeAttribute(normalizedStudentId)}"
        >
          <i
            class="fa-regular fa-file-lines"
            aria-hidden="true"
          ></i>

          Student Work
        </button>


        <button
          type="button"
          class="teacher-secondary-button"
          data-teacher-action="student-grading"
          data-student-id="${escapeAttribute(normalizedStudentId)}"
        >
          <i
            class="fa-solid fa-pen-to-square"
            aria-hidden="true"
          ></i>

          ${
            pending
              ? `Grade ${pending}`
              : "Grading"
          }
        </button>


        <button
          type="button"
          class="teacher-secondary-button"
          data-teacher-action="student-attendance"
          data-student-id="${escapeAttribute(normalizedStudentId)}"
        >
          <i
            class="fa-solid fa-calendar-check"
            aria-hidden="true"
          ></i>

          Attendance
        </button>

      </div>


      <!-- ===============================================
           RECENT WORK
      ================================================ -->

      <section
        class="teacher-student-detail-section"
      >

        <div
          class="teacher-student-detail-section-head"
        >

          <div>

            <span
              class="teacher-page-eyebrow"
            >
              RECENT ACTIVITY
            </span>

            <h3>
              Student Work
            </h3>

          </div>


          ${
            submissions >
            recentSubmissions.length
              ? `
                <button
                  type="button"
                  class="teacher-secondary-button"
                  data-teacher-action="student-work"
                  data-student-id="${escapeAttribute(normalizedStudentId)}"
                >
                  View all
                </button>
              `
              : ""
          }

        </div>


        <div
          class="teacher-student-detail-work-list"
        >

          ${
            recentSubmissions.length
              ? recentSubmissions
                  .map(
                    createTeacherSelectedStudentSubmissionRow
                  )
                  .join(
                    ""
                  )
              : `
                  <div
                    class="teacher-inline-empty"
                  >
                    No recent student submissions.
                  </div>
                `
          }

        </div>

      </section>

    </section>
  `;


  const image =
    container.querySelector(
      ".teacher-student-detail-avatar"
    );


  if (
    image
  ){

    image.onerror =
      () => {

        image.onerror =
          null;

        image.src =
          FALLBACK_AVATAR;

      };

  }


  return true;

}


/* =========================================================
   OPEN STUDENT DETAIL
========================================================= */

function openTeacherSelectedStudent(
  studentId
){

  const record =
    getTeacherStudentById(
      studentId
    );


  if (
    !record
  ){

    notifyAIFTError(
      "The selected student is not available in your assigned classes.",
      {
        title:
          "Student unavailable"
      }
    );


    return false;

  }


  teacherStudentWorkspaceState
    .selectedStudentId =
    record.id;


  return renderTeacherSelectedStudent(
    record.id
  );

}


/* =========================================================
   CLOSE STUDENT DETAIL
========================================================= */

function closeTeacherSelectedStudent(){

  teacherStudentWorkspaceState
    .selectedStudentId =
    "";


  const container =
    $(
      "teacherSelectedStudent"
    );


  if (
    container
  ){

    container.hidden =
      true;

    container.innerHTML =
      "";

  }


  return true;

}


/* =========================================================
   PREPARE STUDENT WORK

   Submissions page has no student dropdown in current HTML,
   so we retain the selected student as explicit workspace
   context and let the central router apply it.
========================================================= */

function prepareTeacherStudentWork(
  studentId
){

  const record =
    getTeacherStudentById(
      studentId
    );


  if (
    !record
  ){

    return false;

  }


  teacherStudentWorkspaceState
    .selectedStudentId =
    record.id;


  return true;

}


/* =========================================================
   STUDENT-WORK FILTERED SUBMISSIONS

   Used by the central action controller after navigation to
   Submissions.
========================================================= */

function getTeacherSubmissionsForSelectedStudent(){

  const studentId =
    normalizeId(
      teacherStudentWorkspaceState
        .selectedStudentId
    );


  if (
    !studentId
  ){

    return getTeacherSubmissions();

  }


  return getTeacherStudentSubmissions(
    studentId
  );

}


/* =========================================================
   PREPARE STUDENT GRADING
========================================================= */

function prepareTeacherStudentGrading(
  studentId
){

  const record =
    getTeacherStudentById(
      studentId
    );


  if (
    !record
  ){

    return false;

  }


  teacherStudentWorkspaceState
    .selectedStudentId =
    record.id;


  teacherGradingWorkspaceState
    .classId =
    "";

  teacherGradingWorkspaceState
    .assignmentId =
    "";

  teacherGradingWorkspaceState
    .status =
    "submitted";

  teacherGradingWorkspaceState
    .selectedSubmissionId =
    "";


  return true;

}


/* =========================================================
   STUDENT GRADING SUBMISSIONS

   Student filtering remains a separate selection constraint
   rather than overwriting the class/assignment data model.
========================================================= */

function getTeacherSelectedStudentPendingGrading(){

  const studentId =
    normalizeId(
      teacherStudentWorkspaceState
        .selectedStudentId
    );


  if (
    !studentId
  ){

    return [];
  }


  return getTeacherStudentPendingSubmissions(
    studentId
  );

}


/* =========================================================
   PREPARE STUDENT ATTENDANCE
========================================================= */

function prepareTeacherStudentAttendance(
  studentId
){

  const record =
    getTeacherStudentById(
      studentId
    );


  if (
    !record
  ){

    return false;

  }


  const classes =
    getTeacherSelectedStudentClasses(
      studentId
    );


  teacherStudentWorkspaceState
    .selectedStudentId =
    record.id;


  teacherAttendanceWorkspaceState
    .selectedStudentId =
    record.id;


  /*
    If the student has one teacher class, selecting it is
    unambiguous.

    If they are in multiple classes, do NOT guess which class
    the teacher intends to mark.
  */

  if (
    classes.length ===
    1
  ){

    teacherAttendanceWorkspaceState
      .classId =
      normalizeId(
        classes[0]?._id ||
        classes[0]?.id
      );

  }else{

    teacherAttendanceWorkspaceState
      .classId =
      "";

  }


  return true;

}


/* =========================================================
   PREPARE STUDENTS FOR CLASS

   Used by class card -> Students.
========================================================= */

function prepareTeacherStudentsClass(
  classId
){

  const classItem =
    getTeacherClassById(
      classId
    );


  if (
    !classItem
  ){

    return false;

  }


  teacherStudentWorkspaceState
    .classId =
    normalizeId(
      classId
    );

  teacherStudentWorkspaceState
    .search =
    "";

  teacherStudentWorkspaceState
    .progress =
    "";

  teacherStudentWorkspaceState
    .selectedStudentId =
    "";


  return true;

}


/* =========================================================
   REFRESH SELECTED STUDENT

   Uses the real underlying datasets.

   Student roster comes from classes.
   Student progress depends on:
     assignments
     submissions
     attendance
     quizzes
     quiz submissions
========================================================= */

async function refreshTeacherSelectedStudent(){

  const selectedStudentId =
    normalizeId(
      teacherStudentWorkspaceState
        .selectedStudentId
    );


  if (
    !selectedStudentId
  ){

    return false;

  }


  try{

    const results =
      await Promise.allSettled([

        loadTeacherClasses(),

        loadTeacherAssignments(),

        loadTeacherSubmissions(),

        loadTeacherAttendance(),

        loadTeacherQuizzes(),

        loadTeacherQuizSubmissions()

      ]);


    results.forEach(
      (
        result,
        index
      ) => {

        if (
          result.status !==
          "rejected"
        ){

          return;

        }


        const labels = [

          "Classes",
          "Assignments",
          "Submissions",
          "Attendance",
          "Quizzes",
          "Quiz submissions"

        ];


        reportOptionalRequestError(
          labels[
            index
          ],
          result.reason
        );

      }
    );


    finalizeTeacherLoadedData();


    const record =
      getTeacherStudentById(
        selectedStudentId
      );


    if (
      !record
    ){

      closeTeacherSelectedStudent();


      notifyAIFTWarning(
        "This student is no longer enrolled in one of your assigned classes.",
        {
          title:
            "Student access changed"
        }
      );


      return false;

    }


    renderTeacherStudentsWorkspace();

    renderTeacherSelectedStudent(
      selectedStudentId
    );


    return true;

  }catch(
    error
  ){

    notifyAIFTError(
      getErrorMessage(
        error,
        "Student information could not be refreshed."
      ),
      {
        title:
          "Refresh failed"
      }
    );


    return false;

  }

}


/* =========================================================
   REFRESH STUDENT DETAIL FROM CURRENT STATE
========================================================= */

function refreshTeacherSelectedStudentFromCurrentState(){

  if (
    teacherStudentWorkspaceState
      .selectedStudentId
  ){

    renderTeacherSelectedStudent(
      teacherStudentWorkspaceState
        .selectedStudentId
    );

  }

}


