/* =========================================================
   ANALYTICS TOOLBAR CONTROLS
========================================================= */

function bindTeacherAnalyticsToolbarControls(){

  const classFilter =
    $(
      "teacherAnalyticsClassFilter"
    );

  const rangeFilter =
    $(
      "teacherAnalyticsRange"
    );


  if (
    classFilter
  ){

    classFilter.onchange =
      event => {

        teacherAnalyticsWorkspaceState
          .classId =
          normalizeId(
            event.target.value
          );


        renderTeacherAnalyticsWorkspace();

      };

  }


  if (
    rangeFilter
  ){

    rangeFilter.onchange =
      event => {

        teacherAnalyticsWorkspaceState
          .range =
          normalizeTeacherAnalyticsRange(
            event.target.value
          );


        renderTeacherAnalyticsWorkspace();

      };

  }


  $all(
    "[data-teacher-analytics-metric]"
  )
    .forEach(
      button => {

        button.onclick =
          event => {

            event.preventDefault();


            const metric =
              safeString(
                button.dataset
                  .teacherAnalyticsMetric,
                "overview"
              );


            if (
              ![
                "overview",
                "students",
                "attendance",
                "assignments"
              ].includes(
                metric
              )
            ){

              return;

            }


            teacherAnalyticsWorkspaceState
              .metric =
              metric;


            renderTeacherAnalyticsToolbar();

            renderTeacherAnalyticsContent();

          };

      }
    );

}


