/* =========================================================
   SIMPLE ANALYTICS CHART

   Uses normal DOM/CSS rather than adding a chart library.

   Existing teacher analytics styling remains authoritative.
========================================================= */

function createTeacherAnalyticsBarChart(
  {
    title,
    subtitle,
    data,
    getValue,
    getLabel,
    suffix = "",
    emptyMessage =
      "No activity is available for this period."
  }
){

  const values =
    data.map(
      item =>
        Math.max(
          0,
          safeNumber(
            getValue(
              item
            ),
            0
          )
        )
    );

  const maximum =
    Math.max(
      1,
      ...values
    );


  const hasActivity =
    values.some(
      value =>
        value >
        0
    );


  return `
    <section
      class="teacher-analytics-chart-card"
    >

      <div
        class="teacher-selected-section-head"
      >

        <div>

          <h3>
            ${escapeHtml(title)}
          </h3>

          <p>
            ${escapeHtml(subtitle)}
          </p>

        </div>

      </div>


      ${
        hasActivity
          ? `
            <div
              class="teacher-analytics-bars"
            >

              ${
                data
                  .map(
                    (
                      item,
                      index
                    ) => {

                      const value =
                        values[
                          index
                        ];

                      const height =
                        Math.max(
                          value >
                          0
                            ? 6
                            : 2,
                          Math.round(
                            (
                              value /
                              maximum
                            ) *
                            100
                          )
                        );


                      return `
                        <div
                          class="teacher-analytics-bar-column"
                          title="${escapeAttribute(
                            `${getLabel(
                              item
                            )}: ${value}${suffix}`
                          )}"
                        >

                          <span
                            class="teacher-analytics-bar-value"
                          >
                            ${
                              value
                                ? `${escapeHtml(value)}${escapeHtml(suffix)}`
                                : ""
                            }
                          </span>


                          <span
                            class="teacher-analytics-bar-track"
                          >
                            <span
                              class="teacher-analytics-bar-fill"
                              style="height:${height}%"
                            ></span>
                          </span>


                          <small>
                            ${escapeHtml(
                              getLabel(
                                item
                              )
                            )}
                          </small>

                        </div>
                      `;

                    }
                  )
                  .join(
                    ""
                  )
              }

            </div>
          `
          : `
              <div
                class="teacher-inline-empty"
              >
                ${escapeHtml(emptyMessage)}
              </div>
            `
      }

    </section>
  `;

}


