/* =========================================================
   STUDENT ANALYTICS RECORD
========================================================= */

function createTeacherAnalyticsStudentRecord(
  studentRecord
){

  const studentId =
    studentRecord.id;

  const submissions =
    getTeacherStudentSubmissions(
      studentId
    );

  const attendanceRecords =
    getTeacherStudentAttendance(
      studentId
    );

  const missing =
    getTeacherStudentMissingAssignments(
      studentId
    ).length;

  const pending =
    getTeacherStudentPendingSubmissions(
      studentId
    ).length;

  const averageGrade =
    getTeacherSelectedStudentAverageGrade(
      studentId
    );


  return {

    studentId,

    student:
      studentRecord.student,

    record:
      studentRecord,

    attendance:
      attendanceRecords.length
        ? getTeacherStudentAttendanceRate(
            studentId
          )
        : null,

    submissions:
      submissions.length,

    missing,

    pending,

    averageGrade

  };

}


/* =========================================================
   STUDENT ANALYTICS RECORDS
========================================================= */

function getTeacherAnalyticsStudentRecords(){

  return getTeacherAnalyticsStudents()
    .map(
      createTeacherAnalyticsStudentRecord
    )
    .sort(
      (
        first,
        second
      ) => {

        /*
          Students needing attention first.
        */

        const firstRisk =
          first.missing *
            10 +
          first.pending *
            2 +
          (
            first.attendance !==
              null &&
            first.attendance <
              75
              ? 5
              : 0
          );

        const secondRisk =
          second.missing *
            10 +
          second.pending *
            2 +
          (
            second.attendance !==
              null &&
            second.attendance <
              75
              ? 5
              : 0
          );


        if (
          firstRisk !==
          secondRisk
        ){

          return (
            secondRisk -
            firstRisk
          );

        }


        return getTeacherStudentDisplayName(
          first.record
        )
          .localeCompare(
            getTeacherStudentDisplayName(
              second.record
            )
          );

      }
    );

}


