/* =========================================================
   ASSIGNMENT ANALYTICS RECORD
========================================================= */

function createTeacherAnalyticsAssignmentRecord(
  assignment
){

  const assignmentId =
    normalizeId(
      assignment?._id ||
      assignment?.id
    );

  const classItem =
    getTeacherAssignmentClass(
      assignment
    );

  const expected =
    getTeacherAssignmentExpectedStudents(
      assignment
    );

  const submissions =
    getTeacherAssignmentSubmissions(
      assignmentId
    );

  const submittedStudents =
    new Set(
      submissions
        .map(
          submission =>
            getTeacherSubmissionStudentId(
              submission
            )
        )
        .filter(
          Boolean
        )
    );

  const reviewed =
    getTeacherAssignmentReviewedCount(
      assignmentId
    );

  const pending =
    getTeacherAssignmentPendingCount(
      assignmentId
    );

  const grades =
    submissions
      .map(
        submission =>
          Number(
            submission?.grade
          )
      )
      .filter(
        Number.isFinite
      );

  const averageGrade =
    grades.length
      ? clampPercentage(
          grades.reduce(
            (
              total,
              grade
            ) =>
              total +
              grade,
            0
          ) /
          grades.length
        )
      : null;


  return {

    assignmentId,

    assignment,

    classItem,

    expected,

    submitted:
      submittedStudents.size,

    reviewed,

    pending,

    completion:
      expected
        ? clampPercentage(
            (
              submittedStudents.size /
              expected
            ) *
            100
          )
        : 0,

    averageGrade,

    overdue:
      isTeacherAssignmentOverdue(
        assignment
      )

  };

}


/* =========================================================
   ASSIGNMENT ANALYTICS RECORDS
========================================================= */

function getTeacherAnalyticsAssignmentRecords(){

  return getTeacherAnalyticsAssignments()
    .map(
      createTeacherAnalyticsAssignmentRecord
    )
    .sort(
      (
        first,
        second
      ) => {

        if (
          first.overdue !==
          second.overdue
        ){

          return first.overdue
            ? -1
            : 1;

        }


        if (
          first.pending !==
          second.pending
        ){

          return (
            second.pending -
            first.pending
          );

        }


        return (
          second.completion -
          first.completion
        );

      }
    );

}


