/* =========================================================
   DEDICATED ATTENDANCE ANALYTICS
========================================================= */

function renderTeacherAnalyticsAttendanceSection(){

  const container =
    $(
      "analyticsAttendanceChart"
    );


  if (
    !container
  ){

    return;

  }


  const records =
    getTeacherAnalyticsAttendance({
      withinRange:
        true
    });

  const counts = {

    present:
      0,

    late:
      0,

    absent:
      0,

    excused:
      0

  };


  records.forEach(
    record => {

      const status =
        normalizeTeacherAttendanceStatus(
          record?.status
        );


      if (
        Object.prototype
          .hasOwnProperty
          .call(
            counts,
            status
          )
      ){

        counts[
          status
        ] +=
          1;

      }

    }
  );


  const total =
    Object.values(
      counts
    )
      .reduce(
        (
          sum,
          value
        ) =>
          sum +
          value,
        0
      );


  const daily =
    aggregateTeacherAnalyticsChartData(
      buildTeacherAnalyticsDailyData()
    );


  container.innerHTML = `
    <div
      class="teacher-analytics-main-grid"
    >

      ${createTeacherAnalyticsBarChart({
        title:
          "Attendance trend",

        subtitle:
          getTeacherAnalyticsRangeLabel(),

        data:
          daily,

        getValue:
          item =>
            item.attendanceRate ===
              null
              ? 0
              : item.attendanceRate,

        getLabel:
          item =>
            item.label,

        suffix:
          "%"
      })}


      <section
        class="teacher-analytics-chart-card"
      >

        <div
          class="teacher-selected-section-head"
        >
          <div>
            <h3>
              Attendance distribution
            </h3>

            <p>
              ${escapeHtml(
                getTeacherAnalyticsRangeLabel()
              )}
            </p>
          </div>
        </div>


        ${
          total
            ? `
              <div
                class="teacher-analytics-distribution-list"
              >

                ${
                  [
                    [
                      "Present",
                      counts.present,
                      "present"
                    ],
                    [
                      "Late",
                      counts.late,
                      "late"
                    ],
                    [
                      "Absent",
                      counts.absent,
                      "absent"
                    ],
                    [
                      "Excused",
                      counts.excused,
                      "excused"
                    ]
                  ]
                    .map(
                      ([
                        label,
                        value,
                        key
                      ]) => {

                        const percentage =
                          clampPercentage(
                            (
                              value /
                              total
                            ) *
                            100
                          );


                        return `
                          <div
                            class="teacher-analytics-distribution-row"
                          >

                            <span>
                              ${escapeHtml(label)}
                            </span>

                            <div
                              class="teacher-analytics-distribution-track"
                            >
                              <span
                                class="is-${escapeAttribute(key)}"
                                style="width:${percentage}%"
                              ></span>
                            </div>

                            <strong>
                              ${value}
                            </strong>

                          </div>
                        `;

                      }
                    )
                    .join(
                      ""
                    )
                }

              </div>
            `
            : `
                <div
                  class="teacher-inline-empty"
                >
                  No attendance records are available for this period.
                </div>
              `
        }

      </section>

    </div>
  `;

}


