/* =========================================================
   CONTENT VISIBILITY
========================================================= */

function renderTeacherAnalyticsContent(){

  const metric =
    teacherAnalyticsWorkspaceState
      .metric;


  const overview =
    $(
      "teacherAnalyticsOverview"
    );

  const students =
    $(
      "teacherAnalyticsStudentSection"
    );

  const attendance =
    $(
      "teacherAnalyticsAttendanceSection"
    );

  const assignments =
    $(
      "teacherAnalyticsAssignmentSection"
    );


  if (
    overview
  ){

    overview.hidden =
      metric !==
      "overview";

  }


  if (
    students
  ){

    students.hidden =
      metric !==
      "students";

  }


  if (
    attendance
  ){

    attendance.hidden =
      metric !==
      "attendance";

  }


  if (
    assignments
  ){

    assignments.hidden =
      metric !==
      "assignments";

  }


  switch(
    metric
  ){

    case "students":

      renderTeacherAnalyticsStudentPerformance(
        "analyticsStudentPerformance"
      );

      break;


    case "attendance":

      renderTeacherAnalyticsAttendanceSection();

      break;


    case "assignments":

      renderTeacherAnalyticsAssignmentPerformance(
        "analyticsAssignmentPerformance"
      );

      break;


    default:

      renderTeacherAnalyticsActivityChart();

      renderTeacherAnalyticsAttendanceChart();

      renderTeacherAnalyticsStudentPerformance();

      renderTeacherAnalyticsAssignmentPerformance();

      renderTeacherAnalyticsKabezya();

      break;

  }

}


/* =========================================================
   PREPARE ANALYTICS FOR CLASS
========================================================= */

function prepareTeacherAnalyticsClass(
  classId
){

  const classItem =
    getTeacherClassById(
      classId
    );


  if (
    !classItem
  ){

    return false;

  }


  teacherAnalyticsWorkspaceState
    .classId =
    normalizeId(
      classId
    );

  teacherAnalyticsWorkspaceState
    .metric =
    "overview";


  return true;

}


/* =========================================================
   REFRESH ANALYTICS

   Reuses the same operational datasets Analytics derives
   from.

   Optional failures do not destroy the whole analytics page.
========================================================= */

async function refreshTeacherAnalyticsWorkspace(){

  if (
    teacherAnalyticsWorkspaceState
      .refreshing
  ){

    return false;

  }


  teacherAnalyticsWorkspaceState
    .refreshing =
    true;


  renderTeacherAnalyticsHeader();


  try{

    const results =
      await Promise.allSettled([

        loadTeacherClasses(),

        loadTeacherAssignments(),

        loadTeacherSubmissions(),

        loadTeacherAttendance(),

        loadTeacherQuizzes(),

        loadTeacherQuizSubmissions(),

        loadTeacherSchedules()

      ]);


    const labels = [

      "Classes",
      "Assignments",
      "Submissions",
      "Attendance",
      "Quizzes",
      "Quiz submissions",
      "Schedule"

    ];


    let failed =
      0;


    results.forEach(
      (
        result,
        index
      ) => {

        if (
          result.status ===
          "rejected"
        ){

          failed +=
            1;


          reportOptionalRequestError(
            labels[
              index
            ],
            result.reason
          );

        }

      }
    );


    finalizeTeacherLoadedData();


    renderTeacherAnalyticsWorkspace();


    if (
      failed
    ){

      notifyAIFTWarning(
        `${failed} analytics data ${
          failed ===
          1
            ? "source"
            : "sources"
        } could not be refreshed. Available metrics were still updated.`,
        {
          title:
            "Analytics partially refreshed"
        }
      );


      return false;

    }


    notifyAIFTSuccess(
      "Teaching analytics are up to date.",
      {
        title:
          "Analytics refreshed"
      }
    );


    return true;

  }catch(
    error
  ){

    notifyAIFTError(
      getErrorMessage(
        error,
        "Analytics could not be refreshed."
      ),
      {
        title:
          "Refresh failed"
      }
    );


    return false;

  }finally{

    teacherAnalyticsWorkspaceState
      .refreshing =
      false;


    renderTeacherAnalyticsHeader();

  }

}


/* =========================================================
   COMPLETE ANALYTICS WORKSPACE
========================================================= */

function renderTeacherAnalyticsWorkspace(){

  renderTeacherAnalyticsHeader();

  renderTeacherAnalyticsToolbar();

  renderTeacherAnalyticsSummary();

  renderTeacherAnalyticsContent();

}


/* =========================================================
   ANALYTICS COMPATIBILITY RENDERER
========================================================= */

function renderTeacherAnalytics(){

  renderTeacherAnalyticsWorkspace();

}


/* =========================================================
   INITIALIZE ANALYTICS
========================================================= */

function initializeTeacherAnalyticsWorkspace(){

  if (
    teacherAnalyticsWorkspaceState
      .initialized
  ){

    renderTeacherAnalyticsWorkspace();

    return;

  }


  teacherAnalyticsWorkspaceState
    .initialized =
    true;


  teacherAnalyticsWorkspaceState
    .range =
    normalizeTeacherAnalyticsRange(
      teacherAnalyticsWorkspaceState
        .range
    );


  if (
    ![
      "overview",
      "students",
      "attendance",
      "assignments"
    ].includes(
      teacherAnalyticsWorkspaceState
        .metric
    )
  ){

    teacherAnalyticsWorkspaceState
      .metric =
      "overview";

  }


  renderTeacherAnalyticsWorkspace();

}


/* =========================================================
   REFRESH ANALYTICS FROM CURRENT STATE
========================================================= */

function refreshTeacherAnalyticsFromCurrentState(){

  renderTeacherAnalyticsSummary();

  renderTeacherAnalyticsContent();

}


