/* =========================================================
   SYNC KABEZYA STATE

   Other Teacher Studio sections may prepare Kabezya context
   through state.kabezya before navigating to the AI page.

   This function safely consumes that context.
========================================================= */

function syncTeacherKabezyaState(){

  if (
    !state.kabezya ||
    typeof state.kabezya !==
      "object"
  ){

    state.kabezya =
      {};

  }


  teacherKabezyaWorkspaceState.mode =
    normalizeTeacherKabezyaMode(
      state.kabezya.mode ||
      teacherKabezyaWorkspaceState.mode
    );


  teacherKabezyaWorkspaceState.classId =
    normalizeId(
      state.kabezya.classId ||
      teacherKabezyaWorkspaceState.classId
    );


  teacherKabezyaWorkspaceState.studentId =
    normalizeId(
      state.kabezya.studentId ||
      teacherKabezyaWorkspaceState.studentId
    );


  teacherKabezyaWorkspaceState.assignmentId =
    normalizeId(
      state.kabezya.assignmentId ||
      teacherKabezyaWorkspaceState.assignmentId
    );


  teacherKabezyaWorkspaceState.submissionId =
    normalizeId(
      state.kabezya.submissionId ||
      teacherKabezyaWorkspaceState.submissionId
    );


  teacherKabezyaWorkspaceState.quizId =
    normalizeId(
      state.kabezya.quizId ||
      teacherKabezyaWorkspaceState.quizId
    );


  Object.assign(
    state.kabezya,
    {
      mode:
        teacherKabezyaWorkspaceState
          .mode,

      classId:
        teacherKabezyaWorkspaceState
          .classId,

      studentId:
        teacherKabezyaWorkspaceState
          .studentId,

      assignmentId:
        teacherKabezyaWorkspaceState
          .assignmentId,

      submissionId:
        teacherKabezyaWorkspaceState
          .submissionId,

      quizId:
        teacherKabezyaWorkspaceState
          .quizId
    }
  );

}


