function getTeacherKabezyaQuiz(){

  const quizId =
    teacherKabezyaWorkspaceState
      .quizId;


  if (
    !quizId
  ){

    return null;

  }


  return getTeacherQuizById(
    quizId
  );

}


/* =========================================================
   SAFE CLASS CONTEXT

   Only teacher-visible operational information is included.

   Avoid sending unnecessary profile information.
========================================================= */

function buildTeacherKabezyaClassContext(){

  const classItem =
    getTeacherKabezyaClass();


  if (
    !classItem
  ){

    return null;

  }


  const classId =
    normalizeId(
      classItem?._id ||
      classItem?.id
    );


  const students =
    getTeacherStudentRecords()
      .filter(
        record =>
          getTeacherStudentClasses(
            record
          )
            .some(
              item =>
                sameId(
                  item?._id ||
                  item?.id,
                  classId
                )
            )
      );


  const assignments =
    getTeacherAssignments()
      .filter(
        assignment =>
          sameId(
            assignment
              ?.classId
              ?._id ||
            assignment
              ?.classId,
            classId
          )
      );


  const submissions =
    getTeacherSubmissions()
      .filter(
        submission =>
          sameId(
            getTeacherSubmissionClassId(
              submission
            ),
            classId
          )
      );


  const attendance =
    getTeacherAttendance()
      .filter(
        record =>
          sameId(
            record
              ?.classId
              ?._id ||
            record
              ?.classId,
            classId
          )
      );


  return {

    id:
      classId,

    title:
      getTeacherClassTitle(
        classItem
      ),

    subject:
      safeString(
        classItem?.subject
      ),

    code:
      safeString(
        classItem?.classCode ||
        classItem?.code
      ),

    studentCount:
      students.length,

    assignmentCount:
      assignments.length,

    submissionCount:
      submissions.length,

    attendanceRecords:
      attendance.length

  };

}


/* =========================================================
   SAFE STUDENT CONTEXT
========================================================= */

function buildTeacherKabezyaStudentContext(){

  const record =
    getTeacherKabezyaStudentRecord();


  if (
    !record
  ){

    return null;

  }


  const studentId =
    record.id;


  const attendance =
    getTeacherStudentAttendance(
      studentId
    );

  const submissions =
    getTeacherStudentSubmissions(
      studentId
    );

  const missing =
    getTeacherStudentMissingAssignments(
      studentId
    );

  const pending =
    getTeacherStudentPendingSubmissions(
      studentId
    );


  return {

    id:
      studentId,

    name:
      getTeacherStudentDisplayName(
        record
      ),

    classes:
      getTeacherStudentClasses(
        record
      )
        .map(
          classItem => ({
            id:
              normalizeId(
                classItem?._id ||
                classItem?.id
              ),

            title:
              getTeacherClassTitle(
                classItem
              )
          })
        ),

    attendanceRate:
      attendance.length
        ? getTeacherStudentAttendanceRate(
            studentId
          )
        : null,

    submissions:
      submissions.length,

    missingAssignments:
      missing.length,

    pendingReviews:
      pending.length,

    averageGrade:
      getTeacherSelectedStudentAverageGrade(
        studentId
      )

  };

}


/* =========================================================
   SAFE ASSIGNMENT CONTEXT
========================================================= */

function buildTeacherKabezyaAssignmentContext(){

  const assignment =
    getTeacherKabezyaAssignment();


  if (
    !assignment
  ){

    return null;

  }


  const assignmentId =
    normalizeId(
      assignment?._id ||
      assignment?.id
    );


  const classItem =
    getTeacherAssignmentClass(
      assignment
    );


  return {

    id:
      assignmentId,

    title:
      getTeacherAssignmentTitle(
        assignment
      ),

    description:
      safeString(
        assignment?.description ||
        assignment?.instructions
      ),

    dueDate:
      assignment?.dueDate ||
      null,

    class:
      classItem
        ? {
            id:
              normalizeId(
                classItem?._id ||
                classItem?.id
              ),

            title:
              getTeacherClassTitle(
                classItem
              )
          }
        : null,

    expectedStudents:
      getTeacherAssignmentExpectedStudents(
        assignment
      ),

    submitted:
      getTeacherAssignmentSubmissionCount(
        assignmentId
      ),

    reviewed:
      getTeacherAssignmentReviewedCount(
        assignmentId
      ),

    pending:
      getTeacherAssignmentPendingCount(
        assignmentId
      ),

    overdue:
      isTeacherAssignmentOverdue(
        assignment
      )

  };

}


/* =========================================================
   SAFE SUBMISSION CONTEXT

   Student work is included because submission-review mode
   specifically requires the teacher-authorized work.

   Existing grade/feedback may be included as context, but
   Kabezya cannot save changes itself.
========================================================= */

function buildTeacherKabezyaSubmissionContext(){

  const submission =
    getTeacherKabezyaSubmission();


  if (
    !submission
  ){

    return null;

  }


  const studentId =
    getTeacherSubmissionStudentId(
      submission
    );

  const assignmentId =
    getTeacherSubmissionAssignmentId(
      submission
    );

  const assignment =
    getTeacherAssignmentById(
      assignmentId
    );

  const studentRecord =
    getTeacherStudentRecordById(
      studentId
    );


  return {

    id:
      normalizeId(
        submission?._id ||
        submission?.id
      ),

    status:
      normalizeSubmissionStatus(
        submission?.status
      ),

    text:
      safeString(
        submission?.text
      ),

    fileUrl:
      safeString(
        submission?.fileUrl
      ),

    grade:
      submission?.grade ??
      null,

    feedback:
      safeString(
        submission?.feedback
      ),

    submittedAt:
      submission?.submittedAt ||
      submission?.createdAt ||
      null,

    student:
      studentRecord
        ? {
            id:
              studentId,

            name:
              getTeacherStudentDisplayName(
                studentRecord
              )
          }
        : {
            id:
              studentId
          },

    assignment:
      assignment
        ? {
            id:
              assignmentId,

            title:
              getTeacherAssignmentTitle(
                assignment
              ),

            description:
              safeString(
                assignment?.description ||
                assignment?.instructions
              )
          }
        : {
            id:
              assignmentId
          }

  };

}


/* =========================================================
   SAFE QUIZ CONTEXT
========================================================= */

function buildTeacherKabezyaQuizContext(){

  const quiz =
    getTeacherKabezyaQuiz();


  if (
    !quiz
  ){

    return null;

  }


  return {

    id:
      getTeacherQuizId(
        quiz
      ),

    title:
      getTeacherQuizTitle(
        quiz
      ),

    description:
      safeString(
        quiz?.description
      ),

    questionCount:
      asArray(
        quiz?.questions
      )
        .length,

    totalPoints:
      getTeacherQuizTotalPoints(
        quiz
      ),

    classId:
      getTeacherQuizClassId(
        quiz
      )

  };

}


/* =========================================================
   ANALYTICS CONTEXT

   Only use operational metrics already calculated in Part 14.
========================================================= */

function buildTeacherKabezyaAnalyticsContext(){

  if (
    typeof getTeacherAnalyticsSummary !==
      "function"
  ){

    return null;

  }


  const summary =
    getTeacherAnalyticsSummary();


  return {

    range:
      typeof getTeacherAnalyticsRangeLabel ===
        "function"
        ? getTeacherAnalyticsRangeLabel()
        : "",

    classId:
      normalizeId(
        teacherAnalyticsWorkspaceState
          ?.classId
      ),

    students:
      summary.students,

    classes:
      summary.classes,

    assignments:
      summary.assignments,

    submissions:
      summary.submissions,

    attendanceRate:
      summary.attendanceRate,

    submissionRate:
      summary.submissionRate,

    reviewRate:
      summary.reviewRate,

    quizAverage:
      summary.quizAverage,

    pendingReviews:
      summary.pendingReviews,

    overdueAssignments:
      summary.overdueAssignments

  };

}


/* =========================================================
   COMPLETE KABEZYA CONTEXT
========================================================= */

function buildTeacherKabezyaContext(){

  return {

    source:
      "teacher-studio",

    mode:
      teacherKabezyaWorkspaceState
        .mode,

    class:
      buildTeacherKabezyaClassContext(),

    student:
      buildTeacherKabezyaStudentContext(),

    assignment:
      buildTeacherKabezyaAssignmentContext(),

    submission:
      buildTeacherKabezyaSubmissionContext(),

    quiz:
      buildTeacherKabezyaQuizContext(),

    analytics:
      teacherKabezyaWorkspaceState
        .mode ===
        TEACHER_KABEZYA_MODES
          .CLASS_ANALYSIS
          ? buildTeacherKabezyaAnalyticsContext()
          : null

  };

}


/* =========================================================
   KABEZYA ENDPOINT BY MODE

   These preserve the endpoint architecture already present
   in the existing Teacher Studio implementation.
========================================================= */

function getTeacherKabezyaEndpoint(){

  switch(
    teacherKabezyaWorkspaceState
      .mode
  ){

    case TEACHER_KABEZYA_MODES
      .CLASS_ANALYSIS:

      return "/api/kabezya/teacher/analyze-class";


    case TEACHER_KABEZYA_MODES
      .STUDENT_ANALYSIS:

      return "/api/kabezya/teacher/analyze-student";


    case TEACHER_KABEZYA_MODES
      .SUBMISSION_REVIEW:

    case TEACHER_KABEZYA_MODES
      .FEEDBACK:

      return "/api/kabezya/teacher/inspect-submission";


    case TEACHER_KABEZYA_MODES
      .GENERATE_QUIZ:

      return "/api/kabezya/teacher/generate-quiz";


    case TEACHER_KABEZYA_MODES
      .GENERATE_ASSIGNMENT:

      return "/api/kabezya/teacher/generate-assignment";


    case TEACHER_KABEZYA_MODES
      .LESSON_PLAN:

      return "/api/kabezya/teacher/generate-lesson-plan";


    case TEACHER_KABEZYA_MODES
      .ASSISTANT:

    default:

      return "/api/kabezya/teacher/assistant";

  }

}


/* =========================================================
   NORMALIZE GENERATED QUESTIONS
========================================================= */

function normalizeTeacherKabezyaQuestions(
  value
){

  return asArray(
    value
  )
    .map(
      (
        question,
        index
      ) => {

        if (
          typeof question ===
          "string"
        ){

          return {

            question:
              safeString(
                question
              ),

            type:
              "short_answer",

            options:
              [],

            correctAnswer:
              "",

            explanation:
              "",

            points:
              1

          };

        }


        if (
          !question ||
          typeof question !==
            "object"
        ){

          return null;

        }


        const text =
          safeString(
            question.question ||
            question.title ||
            question.text,
            `Question ${index + 1}`
          );


        if (
          !text
        ){

          return null;

        }


        return {

          question:
            text,

          type:
            safeString(
              question.type,
              "multiple_choice"
            ),

          options:
            asArray(
              question.options
            )
              .map(
                option =>
                  safeString(
                    option
                  )
              )
              .filter(
                Boolean
              ),

          correctAnswer:
            safeString(
              question.correctAnswer ||
              question.answer
            ),

          explanation:
            safeString(
              question.explanation
            ),

          points:
            Math.max(
              0,
              safeNumber(
                question.points,
                1
              )
            )

        };

      }
    )
    .filter(
      Boolean
    );

}


/* =========================================================
   NORMALIZE KABEZYA RESPONSE
========================================================= */

function normalizeTeacherKabezyaResponse(
  response
){

  const source =
    response?.data &&
    typeof response.data ===
      "object"
      ? response.data
      : response || {};


  if (
    typeof source ===
    "string"
  ){

    return {

      message:
        source,

      content:
        source,

      feedback:
        "",

      score:
        null,

      questions:
        [],

      assignment:
        null,

      lessonPlan:
        null

    };

  }


  const message =
    safeString(
      source.message ||
      source.content ||
      source.answer ||
      source.analysis ||
      source.result ||
      source.text
    );


  const rawScore =
    source.score ??
    source.suggestedScore ??
    source.suggestedGrade ??
    null;

  const numericScore =
    rawScore ===
      null ||
    rawScore ===
      undefined ||
    rawScore ===
      ""
      ? null
      : Number(
          rawScore
        );


  return {

    message,

    content:
      message,

    feedback:
      safeString(
        source.feedback ||
        source.suggestedFeedback
      ),

    score:
      Number.isFinite(
        numericScore
      )
        ? numericScore
        : null,

    questions:
      normalizeTeacherKabezyaQuestions(
        source.questions ||
        source.quiz?.questions
      ),

    assignment:
      source.assignment &&
      typeof source.assignment ===
        "object"
        ? source.assignment
        : null,

    lessonPlan:
      source.lessonPlan ||
      source.lesson ||
      null

  };

}


/* =========================================================
   KABEZYA RESPONSE TEXT
========================================================= */

function getTeacherKabezyaResponseText(
  response
){

  if (
    !response
  ){

    return "";

  }


  if (
    typeof response ===
    "string"
  ){

    return response;

  }


  return safeString(
    response.message ||
    response.content ||
    response.feedback
  );

}


