/* =========================================================
   KABEZYA QUICK PROMPTS
========================================================= */

function getTeacherKabezyaQuickPrompts(){

  switch(
    teacherKabezyaWorkspaceState
      .mode
  ){

    case TEACHER_KABEZYA_MODES
      .CLASS_ANALYSIS:

      return [
        "Summarize the main class performance patterns.",
        "Which learning indicators may need teacher attention?",
        "Compare attendance and assignment completion."
      ];


    case TEACHER_KABEZYA_MODES
      .STUDENT_ANALYSIS:

      return [
        "Summarize this student's recent learning activity.",
        "Which areas may need teacher follow-up?",
        "Suggest supportive next steps for this student."
      ];


    case TEACHER_KABEZYA_MODES
      .SUBMISSION_REVIEW:

    case TEACHER_KABEZYA_MODES
      .FEEDBACK:

      return [
        "Review this submission and suggest constructive feedback.",
        "Identify strengths and areas for improvement.",
        "Draft concise feedback without changing the grade."
      ];


    case TEACHER_KABEZYA_MODES
      .GENERATE_QUIZ:

      return [
        "Create 5 multiple-choice questions.",
        "Create a short formative assessment.",
        "Generate questions with explanations."
      ];


    case TEACHER_KABEZYA_MODES
      .GENERATE_ASSIGNMENT:

      return [
        "Draft a practical assignment for this class.",
        "Create an assignment with clear instructions.",
        "Suggest an assignment with measurable outcomes."
      ];


    case TEACHER_KABEZYA_MODES
      .LESSON_PLAN:

      return [
        "Create a structured lesson plan.",
        "Plan a 60-minute lesson with activities.",
        "Suggest learning objectives and assessment checks."
      ];


    default:

      return [
        "What should I prioritize today?",
        "Help me plan my teaching workload.",
        "Summarize what may need my attention."
      ];

  }

}


