/* =========================================================
   PREPARE CLASS ANALYSIS
========================================================= */

function prepareTeacherKabezyaClassAnalysis(
  classId
){

  const normalized =
    normalizeId(
      classId
    );


  if (
    normalized &&
    !getTeacherClassById(
      normalized
    )
  ){

    return false;

  }


  if (
    !state.kabezya
  ){

    state.kabezya =
      {};

  }


  Object.assign(
    state.kabezya,
    {
      mode:
        TEACHER_KABEZYA_MODES
          .CLASS_ANALYSIS,

      classId:
        normalized,

      studentId:
        "",

      assignmentId:
        "",

      submissionId:
        "",

      quizId:
        ""
    }
  );


  syncTeacherKabezyaState();


  return true;

}


/* =========================================================
   PREPARE STUDENT ANALYSIS
========================================================= */

function prepareTeacherKabezyaStudentAnalysis(
  studentId
){

  const normalized =
    normalizeId(
      studentId
    );

  const record =
    getTeacherStudentRecordById(
      normalized
    );


  if (
    !record
  ){

    return false;

  }


  const classItem =
    getTeacherStudentClasses(
      record
    )[0] ||
    null;


  if (
    !state.kabezya
  ){

    state.kabezya =
      {};

  }


  Object.assign(
    state.kabezya,
    {
      mode:
        TEACHER_KABEZYA_MODES
          .STUDENT_ANALYSIS,

      studentId:
        normalized,

      classId:
        normalizeId(
          classItem?._id ||
          classItem?.id
        ),

      assignmentId:
        "",

      submissionId:
        "",

      quizId:
        ""
    }
  );


  syncTeacherKabezyaState();


  return true;

}


