/* =========================================================
   USE KABEZYA FEEDBACK SUGGESTION

   IMPORTANT:
   This only fills the grading form.

   It does NOT submit/save the review.
========================================================= */

function useTeacherKabezyaFeedbackSuggestion(){

  const response =
    teacherKabezyaWorkspaceState
      .response;


  if (
    !response?.feedback
  ){

    notifyAIFTInfo(
      "Kabezya has not prepared feedback yet.",
      {
        title:
          "No feedback draft"
      }
    );


    return false;

  }


  const submissionId =
    teacherKabezyaWorkspaceState
      .submissionId;


  if (
    !submissionId
  ){

    notifyAIFTWarning(
      "Select a student submission before applying AI feedback.",
      {
        title:
          "Submission required"
      }
    );


    return false;

  }


  teacherGradingWorkspaceState
    .selectedSubmissionId =
    submissionId;


  activateStudentStudioPage(
    "grading"
  );


  window.requestAnimationFrame(
    () => {

      renderTeacherSubmissionViewer();


      window.requestAnimationFrame(
        () => {

          const feedback =
            $(
              "teacherSubmissionFeedback"
            );


          if (
            feedback
          ){

            feedback.value =
              response.feedback;

          }


          const grade =
            $(
              "teacherSubmissionGrade"
            );


          if (
            grade &&
            response.score !==
              null &&
            response.score !==
              undefined
          ){

            grade.value =
              response.score;

          }

        }
      );

    }
  );


  return true;

}


/* =========================================================
   KABEZYA QUICK PROMPT ACTION
========================================================= */

function runTeacherKabezyaQuickPrompt(
  prompt
){

  const normalized =
    safeString(
      prompt
    );


  if (
    !normalized
  ){

    return false;

  }


  teacherKabezyaWorkspaceState
    .prompt =
    normalized;


  const input =
    $(
      "teacherKabezyaPrompt"
    );


  if (
    input
  ){

    input.value =
      normalized;

  }


  askTeacherKabezya(
    normalized
  );


  return true;

}


