/* =========================================================
   SETTINGS PROFILE
========================================================= */

function renderTeacherSettingsProfile(){

  const container =
    $(
      "teacherSettingsProfile"
    );


  if (
    !container
  ){

    return;

  }


  const teacher =
    state.me ||
    state.loggedUser ||
    {};

  const name =
    getTeacherDisplayName(
      teacher
    );

  const avatar =
    getSafeImageUrl(

      teacher?.profileImage ||
      teacher?.avatar ||
      teacher?.photoURL,

      FALLBACK_AVATAR

    );

  const email =
    safeString(
      teacher?.email
    );

  const subject =
    safeString(

      teacher?.subject ||
      teacher?.department,

      "Teacher"

    );

  const schoolName =
    safeString(

      teacher?.schoolName ||
      teacher?.school?.name ||
      state.school?.name

    );


  container.innerHTML = `
    <section
      class="teacher-settings-card"
    >

      <div
        class="teacher-settings-card-head"
      >

        <div>

          <h3>
            Teacher profile
          </h3>

          <p>
            Account information connected to your Teacher Studio.
          </p>

        </div>

      </div>


      <div
        class="teacher-settings-profile"
      >

        <img
          src="${escapeAttribute(avatar)}"
          alt=""
          loading="lazy"
          referrerpolicy="no-referrer"
        />


        <div>

          <strong>
            ${escapeHtml(name)}
          </strong>

          ${
            email
              ? `
                  <span>
                    ${escapeHtml(email)}
                  </span>
                `
              : ""
          }


          <small>
            ${escapeHtml(subject)}
          </small>


          ${
            schoolName
              ? `
                  <small>
                    ${escapeHtml(schoolName)}
                  </small>
                `
              : ""
          }

        </div>

      </div>


      <div
        class="teacher-settings-profile-actions"
      >

        <a
          href="profile.html"
          class="teacher-secondary-button"
        >
          <i
            class="fa-regular fa-user"
            aria-hidden="true"
          ></i>

          View profile
        </a>

      </div>

    </section>
  `;


  const image =
    container.querySelector(
      ".teacher-settings-profile img"
    );


  if (
    image
  ){

    image.onerror =
      () => {

        image.onerror =
          null;

        image.src =
          FALLBACK_AVATAR;

      };

  }

}


