/* =========================================================
   APPLY COMPACT MODE
========================================================= */

function applyTeacherCompactMode(){

  document.body
    .classList
    .toggle(

      "teacher-compact-mode",

      Boolean(
        teacherSettingsWorkspaceState
          .compactMode
      )

    );

}


/* =========================================================
   READ SETTINGS FORM
========================================================= */

function readTeacherSettingsForm(){

  return {

    notifications:
      Boolean(
        $(
          "teacherSettingNotifications"
        )?.checked
      ),

    emailNotifications:
      Boolean(
        $(
          "teacherSettingEmailNotifications"
        )?.checked
      ),

    gradingReminders:
      Boolean(
        $(
          "teacherSettingGradingReminders"
        )?.checked
      ),

    attendanceReminders:
      Boolean(
        $(
          "teacherSettingAttendanceReminders"
        )?.checked
      ),

    compactMode:
      Boolean(
        $(
          "teacherSettingCompactMode"
        )?.checked
      )

  };

}


/* =========================================================
   SAVE SETTINGS

   This intentionally does not make an API call because the
   old /api/users/me/preferences endpoint has not been
   established as a verified current backend contract.
========================================================= */

async function saveTeacherSettings(){

  if (
    teacherSettingsWorkspaceState
      .saving
  ){

    return false;

  }


  teacherSettingsWorkspaceState
    .saving =
    true;


  const preferences =
    readTeacherSettingsForm();


  Object.assign(
    teacherSettingsWorkspaceState,
    preferences
  );


  renderTeacherSettingsPreferences();


  try{

    const saved =
      writeTeacherDevicePreferences(
        preferences
      );


    if (
      !saved
    ){

      throw new Error(
        "Browser storage is unavailable."
      );

    }


    /*
      Keep already-loaded state.me in sync for the current
      browser session without claiming the server was changed.
    */

    if (
      state.me
    ){

      state.me.preferences = {

        ...(state.me.preferences || {}),

        ...preferences

      };

    }


    applyTeacherCompactMode();


    notifyAIFTSuccess(
      "Teacher Studio preferences were saved on this device.",
      {
        title:
          "Settings saved"
      }
    );


    return true;

  }catch(
    error
  ){

    notifyAIFTError(
      getErrorMessage(
        error,
        "Teacher Studio could not save these preferences."
      ),
      {
        title:
          "Settings not saved"
      }
    );


    return false;

  }finally{

    teacherSettingsWorkspaceState
      .saving =
      false;


    renderTeacherSettingsPreferences();

  }

}


/* =========================================================
   RESET SETTINGS
========================================================= */

function resetTeacherSettings(){

  const confirmed =
    window.confirm(
      "Reset Teacher Studio interface preferences on this device?"
    );


  if (
    !confirmed
  ){

    return false;

  }


  Object.assign(
    teacherSettingsWorkspaceState,
    TEACHER_SETTINGS_DEFAULTS
  );


  try{

    window.localStorage
      .removeItem(
        TEACHER_SETTINGS_STORAGE_KEY
      );

  }catch(
    error
  ){

    console.warn(
      "Teacher settings storage could not be cleared:",
      error
    );

  }


  applyTeacherCompactMode();

  renderTeacherSettingsPreferences();


  notifyAIFTSuccess(
    "Teacher Studio preferences were reset.",
    {
      title:
        "Settings reset"
    }
  );


  return true;

}


/* =========================================================
   SETTINGS WORKSPACE
========================================================= */

function renderTeacherSettingsWorkspace(){

  hydrateTeacherSettingsFromUser();

  renderTeacherSettingsHeader();

  renderTeacherSettingsProfile();

  renderTeacherSettingsPreferences();

  applyTeacherCompactMode();

}


/* =========================================================
   SETTINGS COMPATIBILITY
========================================================= */

function renderTeacherSettings(){

  renderTeacherSettingsWorkspace();

}


/* =========================================================
   INITIALIZE SETTINGS
========================================================= */

function initializeTeacherSettingsWorkspace(){

  if (
    teacherSettingsWorkspaceState
      .initialized
  ){

    renderTeacherSettingsWorkspace();

    return;

  }


  teacherSettingsWorkspaceState
    .initialized =
    true;


  hydrateTeacherSettingsFromUser();

  applyTeacherCompactMode();

  renderTeacherSettingsWorkspace();

}


