/* =========================================================
   SUPPORT REQUEST DATA
========================================================= */

function buildTeacherSupportRequest(){

  const name =
    safeString(
      $(
        "teacherSupportName"
      )?.value
    );

  const email =
    safeString(
      $(
        "teacherSupportEmail"
      )?.value
    );

  const topic =
    safeString(
      $(
        "teacherSupportTopic"
      )?.value
    );

  const subject =
    safeString(
      $(
        "teacherSupportSubject"
      )?.value
    );

  const message =
    safeString(
      $(
        "teacherSupportMessage"
      )?.value
    );

  const technicalDetails =
    safeString(
      $(
        "teacherSupportTechnicalDetails"
      )?.value
    );


  if (
    !name ||
    !email ||
    !topic ||
    !subject ||
    !message
  ){

    throw new AIFTApiError(
      "Please complete all required support fields.",
      {
        code:
          "SUPPORT_FIELDS_REQUIRED"
      }
    );

  }


  return {

    name,

    email,

    topic,

    subject,

    message,

    technicalDetails

  };

}


/* =========================================================
   SUPPORT REQUEST AS TEXT
========================================================= */

function formatTeacherSupportRequest(
  request
){

  const teacherId =
    getAuthenticatedUserId();

  const schoolId =
    getSchoolId();


  return [
    "AIFT Teacher Studio Support Request",
    "",
    `Name: ${request.name}`,
    `Email: ${request.email}`,
    `Topic: ${request.topic}`,
    `Subject: ${request.subject}`,
    "",
    "Issue:",
    request.message,
    "",
    request.technicalDetails
      ? [
          "Technical details:",
          request.technicalDetails,
          ""
        ].join("\n")
      : "",
    "Context:",
    `Role: Teacher`,
    teacherId
      ? `User ID: ${teacherId}`
      : "",
    schoolId
      ? `School ID: ${schoolId}`
      : "",
    `Page: ${window.location.href}`,
    `Browser: ${navigator.userAgent}`,
    `Generated: ${new Date().toISOString()}`
  ]
    .filter(
      value =>
        value !==
        ""
    )
    .join(
      "\n"
    );

}


/* =========================================================
   CLIPBOARD FALLBACK
========================================================= */

async function copyTextToTeacherClipboard(
  text
){

  if (
    navigator.clipboard &&
    typeof navigator.clipboard
      .writeText ===
      "function" &&
    window.isSecureContext
  ){

    await navigator.clipboard
      .writeText(
        text
      );


    return true;

  }


  const textarea =
    document.createElement(
      "textarea"
    );


  textarea.value =
    text;

  textarea.setAttribute(
    "readonly",
    ""
  );

  textarea.style.position =
    "fixed";

  textarea.style.opacity =
    "0";

  textarea.style.pointerEvents =
    "none";


  document.body.appendChild(
    textarea
  );


  textarea.select();


  let success =
    false;


  try{

    success =
      document.execCommand(
        "copy"
      );

  }finally{

    textarea.remove();

  }


  return success;

}


/* =========================================================
   COPY SUPPORT REQUEST

   IMPORTANT:
   This does not pretend the request was submitted.

   It prepares a clean support bundle while we verify the real
   support backend contract.
========================================================= */

async function copyTeacherSupportRequest(){

  let request;


  try{

    request =
      buildTeacherSupportRequest();

  }catch(
    error
  ){

    notifyAIFTError(
      getErrorMessage(
        error,
        "Please complete the support request."
      ),
      {
        title:
          "Support request incomplete"
      }
    );


    return false;

  }


  const text =
    formatTeacherSupportRequest(
      request
    );


  try{

    const copied =
      await copyTextToTeacherClipboard(
        text
      );


    if (
      !copied
    ){

      throw new Error(
        "Clipboard access was unavailable."
      );

    }


    notifyAIFTSuccess(
      "The support request was copied. It has not been submitted to a server.",
      {
        title:
          "Support request copied"
      }
    );


    return true;

  }catch(
    error
  ){

    notifyAIFTError(
      getErrorMessage(
        error,
        "The support request could not be copied."
      ),
      {
        title:
          "Copy failed"
      }
    );


    return false;

  }

}


