/* =========================================================
   AIFT TEACHER STUDIO
   PRODUCTION REPLACEMENT
   PART 17

   MESSAGES INTEGRATION
   ---------------------------------------------------------
   1. Messages workspace state
   2. Conversation normalization
   3. Conversation user helpers
   4. Unread calculations
   5. Search
   6. Recent conversation cards
   7. Open full messages workspace
   8. Start student conversation
   9. Messages refresh
   10. Unread badges
   11. Initialization

   ARCHITECTURE
   ---------------------------------------------------------
   Teacher Studio does NOT create a second messaging system.

   The full AIFT messaging experience remains:

     messages.html

   Teacher Studio provides:
     - recent conversations
     - unread counts
     - message search
     - direct thread shortcuts
     - student messaging shortcuts

   VERIFIED BACKEND:
   ---------------------------------------------------------
   GET  /api/messages
   GET  /api/messages/:userId
   POST /api/messages

   Full thread functionality stays in messages.html.
========================================================= */


/* =========================================================
   MESSAGES WORKSPACE STATE
========================================================= */

const teacherMessagesWorkspaceState = {

  conversations:
    [],

  search:
    "",

  loading:
    false,

  refreshing:
    false,

  loaded:
    false,

  initialized:
    false

};


/* =========================================================
   CONVERSATION ID
========================================================= */

function getTeacherConversationId(
  conversation
){

  return normalizeId(

    conversation?.conversationId ||
    conversation?._id ||
    conversation?.id

  );

}


/* =========================================================
   CONVERSATION OTHER USER
========================================================= */

function getTeacherConversationUser(
  conversation
){

  const user =
    conversation?.user;


  if (
    user &&
    typeof user ===
      "object"
  ){

    return user;

  }


  return null;

}


/* =========================================================
   CONVERSATION USER ID
========================================================= */

function getTeacherConversationUserId(
  conversation
){

  const user =
    getTeacherConversationUser(
      conversation
    );


  return normalizeId(
    user?._id ||
    user?.id
  );

}


/* =========================================================
   CONVERSATION USER NAME
========================================================= */

function getTeacherConversationUserName(
  conversation
){

  const user =
    getTeacherConversationUser(
      conversation
    );


  if (
    !user
  ){

    return "Conversation";

  }


  return safeString(

    user?.name ||
    user?.displayName ||
    user?.companyName ||
    user?.schoolName,

    "AIFT user"

  );

}


/* =========================================================
   CONVERSATION USER ROLE
========================================================= */

function getTeacherConversationUserRole(
  conversation
){

  const user =
    getTeacherConversationUser(
      conversation
    );


  const role =
    safeString(
      user?.role
    )
      .toLowerCase();


  switch(
    role
  ){

    case "student":

      return "Student";


    case "teacher":

      return "Teacher";


    case "school":

      return "School";


    case "employer":

      return "Employer";


    case "admin":

      return "Administrator";


    default:

      return role
        ? (
            role
              .charAt(
                0
              )
              .toUpperCase() +
            role.slice(
              1
            )
          )
        : "AIFT user";

  }

}


/* =========================================================
   CONVERSATION AVATAR
========================================================= */

function getTeacherConversationAvatar(
  conversation
){

  const user =
    getTeacherConversationUser(
      conversation
    );


  return getSafeImageUrl(

    user?.profileImage ||
    user?.avatar ||
    user?.logo,

    FALLBACK_AVATAR

  );

}


/* =========================================================
   CONVERSATION LAST MESSAGE
========================================================= */

function getTeacherConversationLastMessage(
  conversation
){

  return safeString(

    conversation?.lastMessage,

    "No messages yet"

  );

}


/* =========================================================
   CONVERSATION LAST DATE
========================================================= */

function getTeacherConversationLastDate(
  conversation
){

  return toValidDate(

    conversation?.lastMessageDate ||
    conversation?.updatedAt ||
    conversation?.createdAt

  );

}


/* =========================================================
   CONVERSATION UNREAD
========================================================= */

function getTeacherConversationUnreadCount(
  conversation
){

  return Math.max(
    0,
    safeInteger(

      conversation?.unreadCount ??
      conversation?.unread,

      0

    )
  );

}


/* =========================================================
   TOTAL UNREAD
========================================================= */

function getTeacherTotalUnreadMessages(){

  return teacherMessagesWorkspaceState
    .conversations
    .reduce(
      (
        total,
        conversation
      ) =>
        total +
        getTeacherConversationUnreadCount(
          conversation
        ),
      0
    );

}


/* =========================================================
   NORMALIZE CONVERSATION
========================================================= */

function normalizeTeacherConversation(
  conversation
){

  if (
    !conversation ||
    typeof conversation !==
      "object"
  ){

    return null;

  }


  const user =
    getTeacherConversationUser(
      conversation
    );


  if (
    !user
  ){

    return null;

  }


  const userId =
    normalizeId(
      user?._id ||
      user?.id
    );


  if (
    !userId
  ){

    return null;

  }


  return {

    ...conversation,

    conversationId:
      getTeacherConversationId(
        conversation
      ),

    user,

    unreadCount:
      getTeacherConversationUnreadCount(
        conversation
      )

  };

}


/* =========================================================
   LOAD CONVERSATIONS

   Verified backend:
     GET /api/messages

   Backend already scopes results to authenticated user.
========================================================= */

async function loadTeacherMessageConversations(){

  if (
    teacherMessagesWorkspaceState
      .loading
  ){

    return teacherMessagesWorkspaceState
      .conversations;

  }


  teacherMessagesWorkspaceState
    .loading =
    true;


  try{

    const response =
      await apiGet(
        "/api/messages"
      );


    teacherMessagesWorkspaceState
      .conversations =
      asArray(
        response?.conversations ||
        response?.data ||
        response
      )
        .map(
          normalizeTeacherConversation
        )
        .filter(
          Boolean
        )
        .sort(
          (
            first,
            second
          ) =>
            (
              getTeacherConversationLastDate(
                second
              )?.getTime() ||
              0
            ) -
            (
              getTeacherConversationLastDate(
                first
              )?.getTime() ||
              0
            )
        );


    teacherMessagesWorkspaceState
      .loaded =
      true;


    updateTeacherMessageUnreadBadges();


    return teacherMessagesWorkspaceState
      .conversations;

  }catch(
    error
  ){

    console.error(
      "Teacher messages load failed:",
      error
    );


    throw error;

  }finally{

    teacherMessagesWorkspaceState
      .loading =
      false;

  }

}


/* =========================================================
   FILTERED CONVERSATIONS
========================================================= */

function getFilteredTeacherConversations(){

  const search =
    safeString(
      teacherMessagesWorkspaceState
        .search
    )
      .toLowerCase();


  let conversations =
    [
      ...teacherMessagesWorkspaceState
        .conversations
    ];


  /*
    Respect archived status supplied by messaging backend.
  */

  conversations =
    conversations.filter(
      conversation =>
        conversation?.archived !==
        true
    );


  if (
    search
  ){

    conversations =
      conversations.filter(
        conversation => {

          const haystack =
            [

              getTeacherConversationUserName(
                conversation
              ),

              getTeacherConversationUserRole(
                conversation
              ),

              getTeacherConversationLastMessage(
                conversation
              ),

              safeString(
                getTeacherConversationUser(
                  conversation
                )?.headline
              ),

              safeString(
                getTeacherConversationUser(
                  conversation
                )?.profession
              )

            ]
              .filter(
                Boolean
              )
              .join(
                " "
              )
              .toLowerCase();


          return haystack.includes(
            search
          );

        }
      );

  }


  conversations.sort(
    (
      first,
      second
    ) => {

      /*
        Pinned conversations first.
      */

      if (
        Boolean(
          first?.pinned
        ) !==
        Boolean(
          second?.pinned
        )
      ){

        return first?.pinned
          ? -1
          : 1;

      }


      /*
        Then unread conversations.
      */

      const firstUnread =
        getTeacherConversationUnreadCount(
          first
        );

      const secondUnread =
        getTeacherConversationUnreadCount(
          second
        );


      if (
        Boolean(
          firstUnread
        ) !==
        Boolean(
          secondUnread
        )
      ){

        return firstUnread
          ? -1
          : 1;

      }


      /*
        Then newest.
      */

      return (
        (
          getTeacherConversationLastDate(
            second
          )?.getTime() ||
          0
        ) -
        (
          getTeacherConversationLastDate(
            first
          )?.getTime() ||
          0
        )
      );

    }
  );


  return conversations;

}


/* =========================================================
   UNREAD BADGES

   Existing HTML contains:
     #teacherUnreadSidebarCount

   Other badge IDs are updated only when present.
========================================================= */

function updateTeacherMessageUnreadBadges(){

  const count =
    getTeacherTotalUnreadMessages();


  const badgeIds = [

    "teacherUnreadSidebarCount",

    "teacherUnreadMessageCount",

    "teacherUnreadTopbarCount"

  ];


  badgeIds.forEach(
    id => {

      const badge =
        $(
          id
        );


      if (
        !badge
      ){

        return;

      }


      badge.hidden =
        count <=
        0;


      badge.textContent =
        count >
        99
          ? "99+"
          : String(
              count
            );


      badge.setAttribute(
        "aria-label",
        `${count} unread ${
          count ===
          1
            ? "message"
            : "messages"
        }`
      );

    }
  );

}


