/* =========================================================
   HIDE STARTUP LOADER
========================================================= */

function hideTeacherStudioStartupLoader(){

  const loaders = [

    $(
      "teacherStudioLoader"
    ),

    $(
      "teacherPageLoader"
    ),

    document.querySelector(
      ".teacher-studio-loader"
    )

  ]
    .filter(
      Boolean
    );


  loaders.forEach(
    element => {

      element.hidden =
        true;

      element.classList
        .add(
          "hidden"
        );

    }
  );


  document.body
    .classList
    .remove(
      "teacher-loading",
      "studio-loading"
    );

}


/* =========================================================
   SHOW STARTUP LOADER
========================================================= */

function showTeacherStudioStartupLoader(){

  document.body
    .classList
    .add(
      "teacher-loading"
    );


  const loader =

    $(
      "teacherStudioLoader"
    ) ||

    $(
      "teacherPageLoader"
    ) ||

    document.querySelector(
      ".teacher-studio-loader"
    );


  if (
    loader
  ){

    loader.hidden =
      false;

    loader.classList
      .remove(
        "hidden"
      );

  }

}


/* =========================================================
   STARTUP ERROR SCREEN
========================================================= */

function renderTeacherStudioFatalError(
  error
){

  const message =
    getErrorMessage(
      error,
      "Teacher Studio could not be initialized."
    );


  const main =

    $(
      "teacherStudioWorkspace"
    ) ||

    document.querySelector(
      ".teacher-main-content"
    ) ||

    document.querySelector(
      "main"
    );


  if (
    !main
  ){

    notifyAIFTError(
      message,
      {
        title:
          "Teacher Studio unavailable"
      }
    );


    return;

  }


  main.innerHTML = `
    <section
      class="teacher-workspace-empty teacher-startup-error"
    >

      <div
        class="teacher-workspace-empty-icon"
      >
        <i
          class="fa-solid fa-triangle-exclamation"
          aria-hidden="true"
        ></i>
      </div>


      <h2>
        Teacher Studio could not load
      </h2>


      <p>
        ${escapeHtml(message)}
      </p>


      <div
        class="teacher-startup-error-actions"
      >

        <button
          type="button"
          class="teacher-primary-button"
          onclick="window.location.reload()"
        >
          <i
            class="fa-solid fa-rotate"
            aria-hidden="true"
          ></i>

          Reload
        </button>


        <a
          href="login.html"
          class="teacher-secondary-button"
        >
          Sign in again
        </a>

      </div>

    </section>
  `;

}


